        r->>'vat_number',
        r->>'logo_url',
        r->>'admin_visible_password',
        r->>'company_email',
        r->>'company_phone',
        r->>'company_address',
        r->>'smart_pin_hash',
        r->>'admin_visible_smart_pin',
