    'app_inquiry_messages',
    'app_admin_notifications',
    'app_inquiries',
    'app_access_extensions',
    'app_plan_renewal_requests',
    'app_activity_log',
    'app_team_permissions',
    'app_permissions',
    'loan_payments',
    'installment_payments',
    'goods_sales',
    'goods_events',
    'expense_transfers',
    'expense_entries',
    'expense_topups',
    'expense_accounts',
    'bitcoin_wallets',
