    'loan_ledger_entries',
    'loans',
    'loan_payments',
    'installment_plans',
    'installment_payments',
    'goods_items',
    'goods_sales',
    'goods_events',
    'expense_accounts',
    'expense_topups',
    'expense_entries',
    'expense_transfers',
    'bitcoin_wallets',
    'app_notes',
    'app_user_prefs',
    'app_inquiries',
    'app_inquiry_messages',
    'app_admin_notifications',
    'app_access_extensions',
    'app_plan_renewal_requests',
    'app_activity_log'
  ];
