  p_tables jsonb,
  p_from uuid,
  p_to uuid
)
returns jsonb
language sql
immutable
as $$
  select case
    when p_tables is null then '{}'::jsonb
    when p_from is null or p_to is null or p_from = p_to then p_tables
    else replace(p_tables::text, p_from::text, p_to::text)::jsonb
  end;
$$;

