        settings = coalesce(r->'settings', u.settings),
        last_login_at = nullif(r->>'last_login_at', '')::timestamptz,
        created_at = coalesce(nullif(r->>'created_at', '')::timestamptz, u.created_at),
        updated_at = now(),
