-- BEGIN migrations/073_inventory_category_reorder.sql
-- ############################################################################

-- Additive: batch reorder inventory category grids by sort_order.
-- Safe for live DBs with existing users — no DROP TABLE / TRUNCATE / data wipe.
-- Updates only goods_category_config.sort_order for the current data owner.

create or replace function public.app_reorder_goods_categories(p_ordered_ids uuid[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  uid uuid := public.current_app_user_id();
  data_owner uuid;
  i int;
  cat_id uuid;
  updated_count int := 0;
begin
  if uid is null then
    raise exception 'Authentication required';
  end if;

  data_owner := coalesce(public.app_data_owner_id(), uid);

  if p_ordered_ids is null or cardinality(p_ordered_ids) = 0 then
    return jsonb_build_object('ok', true, 'updated', 0);
  end if;

  for i in 1 .. cardinality(p_ordered_ids) loop
    cat_id := p_ordered_ids[i];
    if cat_id is null then
      continue;
    end if;

    update public.goods_category_config c
    set
      sort_order = (i - 1) * 10,
      updated_at = now()
    where c.id = cat_id
      and c.owner_id in (data_owner, uid)
      and coalesce(c.is_deleted, false) = false;

    if found then
      updated_count := updated_count + 1;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'updated', updated_count);
end;
$$;

revoke all on function public.app_reorder_goods_categories(uuid[]) from public;
grant execute on function public.app_reorder_goods_categories(uuid[]) to authenticated, anon, service_role;

comment on function public.app_reorder_goods_categories(uuid[]) is
  'Sets goods_category_config.sort_order from an ordered id list for the current app data owner.';

