-- BEGIN migrations/074_sync_team_member_access_from_owner.sql
-- ############################################################################

-- Sync team-member access plan fields from the company owner account.
-- When a company owner's plan/expiry changes, all team members inherit it.

create or replace function public.app_sync_team_member_access_from_owner(p_owner_id uuid)
returns integer
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  owner public.app_users;
  n int := 0;
begin
  if p_owner_id is null then
    return 0;
  end if;

  select * into owner from public.app_users where id = p_owner_id;
  if owner is null then
    return 0;
  end if;
  -- Never treat a team member as a company owner for sync.
  if owner.team_owner_id is not null then
    return 0;
  end if;

  update public.app_users m set
    access_plan = owner.access_plan,
    trial_started_at = owner.trial_started_at,
    trial_expires_at = owner.trial_expires_at,
    access_grace_warned_at = owner.access_grace_warned_at,
    access_disabled_for_expiry_at = owner.access_disabled_for_expiry_at,
    access_last_extended_at = owner.access_last_extended_at,
    access_last_extended_until = owner.access_last_extended_until,
    access_last_extended_by = owner.access_last_extended_by,
    updated_at = now()
  where m.team_owner_id = p_owner_id
    and (
      m.access_plan is distinct from owner.access_plan
      or m.trial_started_at is distinct from owner.trial_started_at
      or m.trial_expires_at is distinct from owner.trial_expires_at
      or m.access_grace_warned_at is distinct from owner.access_grace_warned_at
      or m.access_disabled_for_expiry_at is distinct from owner.access_disabled_for_expiry_at
      or m.access_last_extended_at is distinct from owner.access_last_extended_at
      or m.access_last_extended_until is distinct from owner.access_last_extended_until
      or m.access_last_extended_by is distinct from owner.access_last_extended_by
    );

  get diagnostics n = row_count;
  return n;
end;
$$;

comment on function public.app_sync_team_member_access_from_owner(uuid) is
  'Copies company owner access_plan / trial expiry fields onto all team members.';

create or replace function public.app_users_sync_team_access_trigger()
returns trigger
language plpgsql
security definer
set search_path = public, extensions
as $$
begin
  -- Only owners (no team_owner_id) push plan changes to members.
  if new.team_owner_id is not null then
    return new;
  end if;

  if tg_op = 'UPDATE' and (
    new.access_plan is distinct from old.access_plan
    or new.trial_started_at is distinct from old.trial_started_at
    or new.trial_expires_at is distinct from old.trial_expires_at
    or new.access_grace_warned_at is distinct from old.access_grace_warned_at
    or new.access_disabled_for_expiry_at is distinct from old.access_disabled_for_expiry_at
    or new.access_last_extended_at is distinct from old.access_last_extended_at
    or new.access_last_extended_until is distinct from old.access_last_extended_until
    or new.access_last_extended_by is distinct from old.access_last_extended_by
  ) then
    perform public.app_sync_team_member_access_from_owner(new.id);
  end if;

  return new;
end;
$$;

drop trigger if exists app_users_sync_team_access_trg on public.app_users;
create trigger app_users_sync_team_access_trg
after update of
  access_plan,
  trial_started_at,
  trial_expires_at,
  access_grace_warned_at,
  access_disabled_for_expiry_at,
  access_last_extended_at,
  access_last_extended_until,
  access_last_extended_by
on public.app_users
for each row
execute function public.app_users_sync_team_access_trigger();

-- One-time backfill for existing teams.
do $$
declare
  r record;
begin
  for r in
    select distinct team_owner_id as owner_id
    from public.app_users
    where team_owner_id is not null
  loop
    perform public.app_sync_team_member_access_from_owner(r.owner_id);
  end loop;
end;
$$;

grant execute on function public.app_sync_team_member_access_from_owner(uuid) to authenticated;

