-- Keep transaction owner_id aligned with parent asset
create or replace function public.app_asset_tx_sync_owner()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  asset_owner uuid;
begin
  select owner_id into asset_owner
  from public.app_assets
  where id = new.asset_id and is_deleted = false;
  if asset_owner is null then
    raise exception 'Asset not found';
  end if;
  if not public.app_owns_or_admin(asset_owner) then
    raise exception 'Not allowed to modify this asset';
  end if;
  new.owner_id := asset_owner;
  return new;
end;
$$;

