returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  u public.app_users;
begin
  u := public.current_app_user();
  if u is null then return false; end if;
  if coalesce(u.is_protected, false) is true and u.role = 'admin' then
    return true;
  end if;
  return public.app_has_permission('assets', 'view');
end;
$$;

