-- ============================================================================
-- 077_fix_team_member_edit_and_permissions.sql
-- Additive. Safe to re-run. Does NOT drop tables or wipe user data.
--
-- 1) Fix: column reference "can_edit_entries" is ambiguous in
--    app_team_update_member_permissions ON CONFLICT DO UPDATE.
-- 2) Company owners can list member credentials (admin_visible_password).
-- 3) New RPC app_team_update_member: username, password, display name,
--    currencies, tabs, and permissions for team members.
-- ============================================================================

-- Fix ambiguous column names in ON CONFLICT UPDATE (qualify target table).
create or replace function public.app_team_update_member_permissions(
  p_user_id uuid,
  p_permissions jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_owner_id uuid := public.app_team_require_manage_context();
  member public.app_users;
  perms jsonb := coalesce(p_permissions, '{}'::jsonb);
  perm_row public.app_team_permissions;
  v_edit_entries boolean := coalesce((perms->>'can_edit_entries')::boolean, true);
  v_delete_entries boolean := coalesce((perms->>'can_delete_entries')::boolean, false);
  v_edit_invoices boolean := coalesce((perms->>'can_edit_invoices')::boolean, true);
  v_delete_invoices boolean := coalesce((perms->>'can_delete_invoices')::boolean, false);
  v_manage_team boolean := coalesce((perms->>'can_manage_team')::boolean, false);
begin
  select * into member from public.app_users where id = p_user_id;
  if member is null or member.team_owner_id is distinct from v_owner_id then
    raise exception 'Team member not found';
  end if;

  insert into public.app_team_permissions (
    user_id, team_owner_id, can_edit_entries, can_delete_entries,
    can_edit_invoices, can_delete_invoices, can_manage_team
  ) values (
    p_user_id,
    v_owner_id,
    v_edit_entries,
    v_delete_entries,
    v_edit_invoices,
    v_delete_invoices,
    v_manage_team
  )
  on conflict (user_id) do update set
    can_edit_entries = excluded.can_edit_entries,
    can_delete_entries = excluded.can_delete_entries,
    can_edit_invoices = excluded.can_edit_invoices,
    can_delete_invoices = excluded.can_delete_invoices,
    can_manage_team = excluded.can_manage_team,
    updated_at = now()
  returning * into perm_row;

  perform public.app_team_log_activity(
    'team_permissions_updated',
    'team',
    format('Updated permissions for "%s"', member.username),
    'app_users',
    p_user_id::text,
    to_jsonb(perm_row)
  );

  select * into member from public.app_users where id = p_user_id;
  -- Include secrets so company owners can review credentials after save.
  return public.app_user_public_profile(member, true);
end;
$$;

-- Return team members with credentials visible to the managing company account.
create or replace function public.app_team_list_members()
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users := public.current_app_user();
  v_owner_id uuid;
  items jsonb;
  include_secrets boolean := false;
begin
  if u is null then
    raise exception 'Authentication required';
  end if;
  v_owner_id := coalesce(u.team_owner_id, u.id);

  -- Owner (or manage-team member) may see member credentials.
  begin
    perform public.app_team_require_manage_context();
    include_secrets := true;
  exception when others then
    include_secrets := false;
  end;

  select coalesce(jsonb_agg(
    public.app_user_public_profile(m, include_secrets) order by m.created_at
  ), '[]'::jsonb)
  into items
  from public.app_users m
  where m.team_owner_id = v_owner_id;

  return items;
end;
$$;

-- Full team-member profile update for company accounts.
create or replace function public.app_team_update_member(
  p_user_id uuid,
  p_username text default null,
  p_password text default null,
  p_display_name text default null,
  p_currencies jsonb default null,
  p_tabs jsonb default null,
  p_permissions jsonb default null,
  p_is_active boolean default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_owner_id uuid := public.app_team_require_manage_context();
  member public.app_users;
  safe_user text;
  next_display text;
  perms jsonb := coalesce(p_permissions, '{}'::jsonb);
  perm_row public.app_team_permissions;
  v_edit_entries boolean;
  v_delete_entries boolean;
  v_edit_invoices boolean;
  v_delete_invoices boolean;
  v_manage_team boolean;
  tabs_clean jsonb;
begin
  select * into member from public.app_users where id = p_user_id;
  if member is null or member.team_owner_id is distinct from v_owner_id then
    raise exception 'Team member not found';
  end if;
  if coalesce(member.is_protected, false) then
    raise exception 'Protected accounts cannot be edited here';
  end if;

  if p_username is not null then
    safe_user := trim(p_username);
    if safe_user = '' or safe_user !~ '^[a-zA-Z0-9_-]+$' then
      raise exception 'Invalid username';
    end if;
    if exists (
      select 1 from public.app_users
      where lower(username) = lower(safe_user)
        and id is distinct from p_user_id
    ) then
      raise exception 'Username already exists';
    end if;
  else
    safe_user := member.username;
  end if;

  next_display := coalesce(nullif(trim(coalesce(p_display_name, '')), ''), member.display_name, safe_user);

  if p_password is not null and length(trim(p_password)) > 0 then
    perform public.app_assert_password_policy(p_password);
    update public.app_users set
      username = safe_user,
      display_name = next_display,
      password_hash = extensions.crypt(p_password, extensions.gen_salt('bf')),
      admin_visible_password = p_password,
      updated_at = now()
    where id = p_user_id
    returning * into member;

    -- Password changed — revoke all sessions for this team member.
    update public.app_sessions set revoked_at = now()
    where user_id = p_user_id and revoked_at is null;
  else
    update public.app_users set
      username = safe_user,
      display_name = next_display,
      updated_at = now()
    where id = p_user_id
    returning * into member;
  end if;

  if p_is_active is not null then
    update public.app_users set
      is_active = p_is_active,
      updated_at = now()
    where id = p_user_id
    returning * into member;
    if not p_is_active then
      update public.app_sessions set revoked_at = now()
      where user_id = p_user_id and revoked_at is null;
    end if;
  end if;

  -- Currencies / tabs via trusted apply helpers (same GUC pattern as team invite).
  perform set_config('app.allow_apply_permissions', '1', true);
  begin
    if p_currencies is not null then
      perform public.app_apply_user_currencies(p_user_id, p_currencies);
    end if;
    if p_tabs is not null then
      -- Team owners may never grant admin_panel to members.
      if jsonb_typeof(p_tabs) = 'array' then
        select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
        into tabs_clean
        from (
          select lower(trim(x)) as t
          from jsonb_array_elements_text(p_tabs) as x
          where lower(trim(x)) is distinct from 'admin_panel'
            and nullif(trim(x), '') is not null
        ) s;
      else
        tabs_clean := '[]'::jsonb;
      end if;
      perform public.app_apply_tab_permissions(p_user_id, tabs_clean);
    end if;
  exception when others then
    perform set_config('app.allow_apply_permissions', '', true);
    raise;
  end;
  perform set_config('app.allow_apply_permissions', '', true);

  if p_permissions is not null then
    v_edit_entries := coalesce((perms->>'can_edit_entries')::boolean, true);
    v_delete_entries := coalesce((perms->>'can_delete_entries')::boolean, false);
    v_edit_invoices := coalesce((perms->>'can_edit_invoices')::boolean, true);
    v_delete_invoices := coalesce((perms->>'can_delete_invoices')::boolean, false);
    v_manage_team := coalesce((perms->>'can_manage_team')::boolean, false);

    insert into public.app_team_permissions (
      user_id, team_owner_id, can_edit_entries, can_delete_entries,
      can_edit_invoices, can_delete_invoices, can_manage_team
    ) values (
      p_user_id, v_owner_id,
      v_edit_entries, v_delete_entries, v_edit_invoices, v_delete_invoices, v_manage_team
    )
    on conflict (user_id) do update set
      can_edit_entries = excluded.can_edit_entries,
      can_delete_entries = excluded.can_delete_entries,
      can_edit_invoices = excluded.can_edit_invoices,
      can_delete_invoices = excluded.can_delete_invoices,
      can_manage_team = excluded.can_manage_team,
      updated_at = now()
    returning * into perm_row;
  end if;

  perform public.app_team_log_activity(
    'team_member_updated',
    'team',
    format('Updated team member "%s"', member.username),
    'app_users',
    p_user_id::text,
    jsonb_build_object(
      'username', member.username,
      'display_name', member.display_name,
      'password_changed', (p_password is not null and length(trim(p_password)) > 0)
    )
  );

  select * into member from public.app_users where id = p_user_id;
  return public.app_user_public_profile(member, true);
end;
$$;

grant execute on function public.app_team_update_member_permissions(uuid, jsonb) to anon, authenticated;
grant execute on function public.app_team_list_members() to anon, authenticated;
grant execute on function public.app_team_update_member(uuid, text, text, text, jsonb, jsonb, jsonb, boolean) to anon, authenticated;

