-- ============================================================================
-- 078_admin_storage_management.sql
-- Additive. Safe to re-run. Does NOT drop tables or wipe user data.
--
-- Admin Disk / Storage Management: per-user estimated storage usage across
-- ledger text, domain tables, photos (wallet logos / company logos), notes,
-- assets, bitcoin wallets, and Supabase storage objects.
-- ============================================================================

create or replace function public.app_admin_storage_table_bytes(
  p_table regclass,
  p_owner_col text default 'owner_id'
)
returns table(owner_id uuid, bytes bigint)
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_table is null then
    return;
  end if;
  if not exists (
    select 1
    from pg_attribute a
    where a.attrelid = p_table
      and a.attname = p_owner_col
      and a.attnum > 0
      and not a.attisdropped
  ) then
    return;
  end if;

  return query execute format(
    'select %I::uuid as owner_id, coalesce(sum(pg_column_size(t.*)), 0)::bigint as bytes
     from %s t
     where %I is not null
     group by 1',
    p_owner_col, p_table::text, p_owner_col
  );
exception when others then
  return;
end;
$$;

revoke all on function public.app_admin_storage_table_bytes(regclass, text) from public, anon, authenticated;

create or replace function public.app_admin_storage_usage()
returns jsonb
language plpgsql
security definer
set search_path = public, extensions, storage
as $$
declare
  admin public.app_users := public.app_require_admin();
  users_json jsonb := '[]'::jsonb;
  totals jsonb;
  storage_rows jsonb := '[]'::jsonb;
begin
  -- Per-user bucket from storage.objects (company-logos / wallet photos).
  begin
    select coalesce(jsonb_agg(jsonb_build_object(
      'owner_id', uid,
      'bytes', bytes
    )), '[]'::jsonb)
    into storage_rows
    from (
      select
        nullif(split_part(o.name, '/', 1), '')::uuid as uid,
        coalesce(sum(
          coalesce((o.metadata->>'size')::bigint, octet_length(coalesce(o.name, '')), 0)
        ), 0)::bigint as bytes
      from storage.objects o
      where o.bucket_id = 'company-logos'
        and nullif(split_part(o.name, '/', 1), '') ~* '^[0-9a-f-]{36}$'
      group by 1
    ) s
    where uid is not null;
  exception when others then
    storage_rows := '[]'::jsonb;
  end;

  with
  ledger as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.loan_ledger_entries'))
  ),
  loans as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.loans'))
  ),
  payments as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.loan_payments'))
  ),
  installments as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.installment_plans'))
  ),
  goods as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.goods_items'))
  ),
  goods_events as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.goods_events'))
  ),
  goods_sales as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.goods_sales'))
  ),
  goods_brands as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.goods_brands'))
  ),
  expenses as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.expense_accounts'))
  ),
  expense_entries as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.expense_entries'))
  ),
  expense_topups as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.expense_topups'))
  ),
  notes as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.app_notes'))
  ),
  prefs as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.app_user_prefs'))
  ),
  btc as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.bitcoin_wallets'))
  ),
  assets as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.app_assets'))
  ),
  asset_tx as (
    select * from public.app_admin_storage_table_bytes(to_regclass('public.app_asset_transactions'))
  ),
  logo_profile as (
    select
      u.id as owner_id,
      (
        coalesce(octet_length(coalesce(u.logo_url, '')), 0)
        + coalesce(octet_length(coalesce(u.company_name, '')), 0)
        + coalesce(octet_length(coalesce(u.company_address, '')), 0)
        + coalesce(octet_length(coalesce(u.settings::text, '')), 0)
        + coalesce(octet_length(coalesce(u.display_name, '')), 0)
        + coalesce(octet_length(coalesce(u.username, '')), 0)
      )::bigint as bytes
    from public.app_users u
  ),
  storage_files as (
    select
      (x->>'owner_id')::uuid as owner_id,
      coalesce((x->>'bytes')::bigint, 0)::bigint as bytes
    from jsonb_array_elements(storage_rows) x
  ),
  combined as (
    select owner_id, bytes, 'ledger'::text as kind from ledger
    union all select owner_id, bytes, 'loans' from loans
    union all select owner_id, bytes, 'payments' from payments
    union all select owner_id, bytes, 'installments' from installments
    union all select owner_id, bytes, 'goods' from goods
    union all select owner_id, bytes, 'goods_events' from goods_events
    union all select owner_id, bytes, 'goods_sales' from goods_sales
    union all select owner_id, bytes, 'goods_brands' from goods_brands
    union all select owner_id, bytes, 'expenses' from expenses
    union all select owner_id, bytes, 'expense_entries' from expense_entries
    union all select owner_id, bytes, 'expense_topups' from expense_topups
    union all select owner_id, bytes, 'notes' from notes
    union all select owner_id, bytes, 'prefs' from prefs
    union all select owner_id, bytes, 'bitcoin' from btc
    union all select owner_id, bytes, 'assets' from assets
    union all select owner_id, bytes, 'asset_tx' from asset_tx
    union all select owner_id, bytes, 'profile_text' from logo_profile
    union all select owner_id, bytes, 'photos' from storage_files
  ),
  by_user_kind as (
    select owner_id, kind, sum(bytes)::bigint as bytes
    from combined
    where owner_id is not null
    group by 1, 2
  ),
  by_user as (
    select
      u.id,
      u.username,
      u.display_name,
      u.role,
      u.is_active,
      u.team_owner_id,
      coalesce(sum(k.bytes), 0)::bigint as total_bytes,
      coalesce(sum(k.bytes) filter (where k.kind in (
        'ledger','loans','payments','installments','goods','goods_events','goods_sales','goods_brands',
        'expenses','expense_entries','expense_topups','notes','prefs','bitcoin','assets','asset_tx',
        'profile_text'
      )), 0)::bigint as text_bytes,
      coalesce(sum(k.bytes) filter (where k.kind = 'photos'), 0)::bigint as photo_bytes,
      coalesce(sum(k.bytes) filter (where k.kind in ('ledger','loans','payments','installments')), 0)::bigint as ledger_bytes,
      coalesce(sum(k.bytes) filter (where k.kind in ('expenses','expense_entries','expense_topups')), 0)::bigint as expense_bytes,
      coalesce(sum(k.bytes) filter (where k.kind in ('goods','goods_events','goods_sales','goods_brands')), 0)::bigint as inventory_bytes,
      coalesce(sum(k.bytes) filter (where k.kind = 'notes'), 0)::bigint as notes_bytes,
      coalesce(sum(k.bytes) filter (where k.kind = 'bitcoin'), 0)::bigint as bitcoin_bytes,
      coalesce(sum(k.bytes) filter (where k.kind in ('assets','asset_tx')), 0)::bigint as assets_bytes,
      coalesce(sum(k.bytes) filter (where k.kind = 'profile_text'), 0)::bigint as profile_bytes
    from public.app_users u
    left join by_user_kind k on k.owner_id = u.id
    group by u.id, u.username, u.display_name, u.role, u.is_active, u.team_owner_id
  )
  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', b.id,
      'username', b.username,
      'display_name', b.display_name,
      'role', b.role,
      'is_active', b.is_active,
      'team_owner_id', b.team_owner_id,
      'total_bytes', b.total_bytes,
      'text_bytes', b.text_bytes,
      'photo_bytes', b.photo_bytes,
      'ledger_bytes', b.ledger_bytes,
      'expense_bytes', b.expense_bytes,
      'inventory_bytes', b.inventory_bytes,
      'notes_bytes', b.notes_bytes,
      'bitcoin_bytes', b.bitcoin_bytes,
      'assets_bytes', b.assets_bytes,
      'profile_bytes', b.profile_bytes
    ) order by b.total_bytes desc, b.username
  ), '[]'::jsonb)
  into users_json
  from by_user b;

  select jsonb_build_object(
    'user_count', count(*)::int,
    'total_bytes', coalesce(sum((u->>'total_bytes')::bigint), 0),
    'text_bytes', coalesce(sum((u->>'text_bytes')::bigint), 0),
    'photo_bytes', coalesce(sum((u->>'photo_bytes')::bigint), 0),
    'ledger_bytes', coalesce(sum((u->>'ledger_bytes')::bigint), 0),
    'expense_bytes', coalesce(sum((u->>'expense_bytes')::bigint), 0),
    'inventory_bytes', coalesce(sum((u->>'inventory_bytes')::bigint), 0),
    'notes_bytes', coalesce(sum((u->>'notes_bytes')::bigint), 0),
    'bitcoin_bytes', coalesce(sum((u->>'bitcoin_bytes')::bigint), 0),
    'assets_bytes', coalesce(sum((u->>'assets_bytes')::bigint), 0),
    'profile_bytes', coalesce(sum((u->>'profile_bytes')::bigint), 0)
  )
  into totals
  from jsonb_array_elements(users_json) u;

  return jsonb_build_object(
    'generated_at', now(),
    'requested_by', admin.username,
    'totals', totals,
    'users', users_json
  );
end;
$$;

