-- ============================================================================
-- 079_admin_photo_compression.sql
-- Additive. Safe to re-run. Does NOT drop tables or wipe unrelated user data.
--
-- Admin Storage Management: list a user's photo assets and replace URLs in-place
-- after client-side compression (storage objects are overwritten by the client).
-- ============================================================================

create or replace function public.app_admin_list_user_photos(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions, storage
as $$
declare
  admin public.app_users := public.app_require_admin();
  target public.app_users;
  items jsonb := '[]'::jsonb;
  storage_items jsonb := '[]'::jsonb;
  profile_url text;
begin
  if p_user_id is null then
    raise exception 'User id is required';
  end if;
  select * into target from public.app_users where id = p_user_id;
  if target is null then
    raise exception 'User not found';
  end if;

  -- Supabase storage objects under this user folder
  begin
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', 'storage:' || o.name,
      'source', 'storage',
      'ref_id', null,
      'path', o.name,
      'url', '',
      'bytes', coalesce((o.metadata->>'size')::bigint, 0),
      'label', case
        when o.name ilike '%/wallet-%' then 'Wallet photo'
        when o.name ilike '%/logo-%' then 'Company logo'
        else 'Uploaded photo'
      end,
      'mime', coalesce(o.metadata->>'mimetype', o.metadata->>'contentType', 'image/*')
    ) order by o.name), '[]'::jsonb)
    into storage_items
    from storage.objects o
    where o.bucket_id = 'company-logos'
      and o.name like (p_user_id::text || '/%');
  exception when others then
    storage_items := '[]'::jsonb;
  end;

  items := storage_items;

  profile_url := coalesce(nullif(trim(target.logo_url), ''), nullif(trim(target.settings->>'logo'), ''), '');
  if profile_url <> '' then
    items := items || jsonb_build_array(jsonb_build_object(
      'id', 'profile:' || p_user_id::text,
      'source', 'profile',
      'ref_id', p_user_id,
      'path', case
        when profile_url ~* '/storage/v1/object/(?:public/)?company-logos/' then
          coalesce(
            (regexp_match(profile_url, '/storage/v1/object/(?:public/)?company-logos/([^?#]+)'))[1],
            ''
          )
        else ''
      end,
      'url', profile_url,
      'bytes', octet_length(profile_url),
      'label', 'Profile / company logo',
      'mime', case when profile_url like 'data:image/%' then split_part(split_part(profile_url, ';', 1), ':', 2) else 'image/*' end
    ));
  end if;

  -- Expense wallet custom logos (storage URL or embedded data URL)
  if to_regclass('public.expense_accounts') is not null then
    items := items || coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', 'expense:' || ea.id::text,
        'source', 'expense_account',
        'ref_id', ea.id,
        'path', case
          when ea.custom_logo_url ~* '/storage/v1/object/(?:public/)?company-logos/' then
            coalesce(
              (regexp_match(ea.custom_logo_url, '/storage/v1/object/(?:public/)?company-logos/([^?#]+)'))[1],
              ''
            )
          else ''
        end,
        'url', ea.custom_logo_url,
        'bytes', octet_length(coalesce(ea.custom_logo_url, '')),
        'label', coalesce(nullif(trim(ea.account_name), ''), 'Wallet logo'),
        'mime', case
          when ea.custom_logo_url like 'data:image/%' then split_part(split_part(ea.custom_logo_url, ';', 1), ':', 2)
          else 'image/*'
        end
      ) order by ea.account_name, ea.id)
      from public.expense_accounts ea
      where ea.owner_id = p_user_id
        and nullif(trim(ea.custom_logo_url), '') is not null
    ), '[]'::jsonb);
  end if;

  -- Deduplicate by path (prefer first) then by exact url
  select coalesce(jsonb_agg(uniq order by uniq->>'label', uniq->>'id'), '[]'::jsonb)
  into items
  from (
    select distinct on (coalesce(nullif(e->>'path', ''), e->>'url')) e as uniq
    from jsonb_array_elements(items) e
    order by coalesce(nullif(e->>'path', ''), e->>'url'), e->>'source'
  ) d;

  return jsonb_build_object(
    'user_id', p_user_id,
    'username', target.username,
    'display_name', target.display_name,
    'photos', items,
    'requested_by', admin.username
  );
end;
$$;

create or replace function public.app_admin_replace_photo_url(
  p_user_id uuid,
  p_source text,
  p_ref_id uuid default null,
  p_old_url text default null,
  p_new_url text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  admin public.app_users := public.app_require_admin();
  target public.app_users;
  old_u text := trim(coalesce(p_old_url, ''));
  new_u text := trim(coalesce(p_new_url, ''));
  src text := lower(trim(coalesce(p_source, '')));
  n int := 0;
begin
  if p_user_id is null then
    raise exception 'User id is required';
  end if;
  if new_u = '' then
    raise exception 'Compressed photo URL is required';
  end if;
  select * into target from public.app_users where id = p_user_id;
  if target is null then
    raise exception 'User not found';
  end if;

  if src = 'profile' then
    update public.app_users
    set
      logo_url = new_u,
      settings = coalesce(settings, '{}'::jsonb) || jsonb_build_object('logo', new_u),
      updated_at = now()
    where id = p_user_id;
    get diagnostics n = row_count;
  elsif src = 'expense_account' then
    if p_ref_id is null then
      raise exception 'Expense account id is required';
    end if;
    update public.expense_accounts
    set custom_logo_url = new_u
    where id = p_ref_id
      and owner_id = p_user_id;
    get diagnostics n = row_count;
    if n = 0 then
      raise exception 'Expense account photo not found';
    end if;
    -- Keep ledger note meta in sync when old URL is known
    if old_u <> '' and to_regclass('public.loan_ledger_entries') is not null then
      update public.loan_ledger_entries
      set notes = replace(notes, '[CLOGO:' || old_u || ']', '[CLOGO:' || replace(new_u, ']', '') || ']')
      where owner_id = p_user_id
        and notes ilike '%[CLOGO:' || old_u || ']%';
    end if;
    if to_regclass('public.expense_accounts') is not null and old_u <> '' then
      update public.expense_accounts
      set notes = replace(coalesce(notes, ''), '[CLOGO:' || old_u || ']', '[CLOGO:' || replace(new_u, ']', '') || ']')
      where id = p_ref_id
        and owner_id = p_user_id
        and coalesce(notes, '') ilike '%[CLOGO:' || old_u || ']%';
    end if;
  elsif src = 'storage' then
    -- Storage object overwrite is performed by the client in-place; nothing to change in DB
    -- when the public URL/path stays the same.
    n := 1;
  else
    raise exception 'Unsupported photo source';
  end if;

  return jsonb_build_object(
    'ok', true,
    'source', src,
    'updated', n,
    'user_id', p_user_id,
    'by', admin.username
  );
end;
$$;

