  constraint goods_item_barcodes_barcode_nonempty check (length(trim(barcode)) > 0),
  constraint goods_item_barcodes_owner_group_unique unique (owner_id, group_id),
  constraint goods_item_barcodes_owner_barcode_unique unique (owner_id, barcode)
);

create index if not exists goods_item_barcodes_owner_idx
  on public.goods_item_barcodes (owner_id);

create index if not exists goods_item_barcodes_barcode_idx
  on public.goods_item_barcodes (owner_id, barcode);

