-- List barcodes for current data owner
create or replace function public.app_list_my_goods_barcodes(
  p_limit int default 5000
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner uuid := public.app_data_owner_id();
  v_limit int := greatest(1, least(coalesce(p_limit, 5000), 10000));
  rows jsonb;
begin
  if v_owner is null then
    raise exception 'Not authenticated';
  end if;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.updated_at desc), '[]'::jsonb)
  into rows
  from (
    select
      id::text as id,
      group_id::text as group_id,
      barcode,
      item_name,
      item_code,
      currency,
      unit_price,
      created_at,
      updated_at
    from public.goods_item_barcodes
    where owner_id = v_owner
    order by updated_at desc
    limit v_limit
  ) t;

  return jsonb_build_object('ok', true, 'rows', rows);
end;
$$;

grant execute on function public.app_list_my_goods_barcodes(int) to authenticated;

-- Upsert one barcode for a stock group
create or replace function public.app_upsert_goods_barcode(
  p_group_id uuid,
  p_barcode text,
  p_item_name text default null,
  p_item_code text default null,
  p_currency text default null,
  p_unit_price numeric default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner uuid := public.app_data_owner_id();
  v_code text := upper(trim(coalesce(p_barcode, '')));
  v_row public.goods_item_barcodes%rowtype;
begin
  if v_owner is null then
    raise exception 'Not authenticated';
  end if;
  if p_group_id is null then
    raise exception 'group_id required';
  end if;
  if length(v_code) < 4 then
    raise exception 'barcode too short';
  end if;

  insert into public.goods_item_barcodes as b (
    owner_id, group_id, barcode, item_name, item_code, currency, unit_price, updated_at
  ) values (
    v_owner, p_group_id, v_code, nullif(trim(coalesce(p_item_name, '')), ''),
    nullif(trim(coalesce(p_item_code, '')), ''), nullif(trim(coalesce(p_currency, '')), ''),
    p_unit_price, now()
  )
  on conflict (owner_id, group_id) do update
    set barcode = excluded.barcode,
        item_name = coalesce(excluded.item_name, b.item_name),
        item_code = coalesce(excluded.item_code, b.item_code),
        currency = coalesce(excluded.currency, b.currency),
        unit_price = coalesce(excluded.unit_price, b.unit_price),
        updated_at = now()
  returning * into v_row;

  return jsonb_build_object(
    'ok', true,
    'row', jsonb_build_object(
      'id', v_row.id::text,
      'group_id', v_row.group_id::text,
      'barcode', v_row.barcode,
      'item_name', v_row.item_name,
      'item_code', v_row.item_code,
      'currency', v_row.currency,
      'unit_price', v_row.unit_price
    )
  );
exception
  when unique_violation then
    raise exception 'Barcode already assigned to another product';
end;
$$;

grant execute on function public.app_upsert_goods_barcode(uuid, text, text, text, text, numeric) to authenticated;

-- Lookup group by barcode
create or replace function public.app_find_goods_by_barcode(
  p_barcode text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_owner uuid := public.app_data_owner_id();
  v_code text := upper(trim(coalesce(p_barcode, '')));
  v_row public.goods_item_barcodes%rowtype;
begin
  if v_owner is null then
    raise exception 'Not authenticated';
  end if;
  if length(v_code) < 4 then
    return jsonb_build_object('ok', false, 'error', 'invalid_barcode');
  end if;

  select * into v_row
  from public.goods_item_barcodes
  where owner_id = v_owner
    and barcode = v_code
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  return jsonb_build_object(
    'ok', true,
    'row', jsonb_build_object(
      'id', v_row.id::text,
      'group_id', v_row.group_id::text,
      'barcode', v_row.barcode,
      'item_name', v_row.item_name,
      'item_code', v_row.item_code,
      'currency', v_row.currency,
      'unit_price', v_row.unit_price
    )
  );
end;
$$;

grant execute on function public.app_find_goods_by_barcode(text) to authenticated;

