-- Keep history owner aligned with parent depreciation asset
create or replace function public.depreciation_history_sync_owner()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  asset_owner uuid;
begin
  select owner_id into asset_owner
  from public.depreciation_assets
  where id = new.depreciation_asset_id and is_deleted = false;
  if asset_owner is null then
    raise exception 'Depreciation asset not found';
  end if;
  if not public.app_owns_or_admin(asset_owner) then
    raise exception 'Not allowed to modify this depreciation asset';
  end if;
  new.owner_id := asset_owner;
  return new;
end;
$$;

drop trigger if exists trg_depreciation_history_sync_owner on public.depreciation_history;
create trigger trg_depreciation_history_sync_owner
  before insert or update on public.depreciation_history
  for each row execute function public.depreciation_history_sync_owner();

do $$
declare
  t text;
  tables text[] := array['depreciation_assets', 'depreciation_history'];
begin
  foreach t in array tables loop
    if exists (
      select 1 from information_schema.routines
      where routine_schema = 'public' and routine_name = 'app_team_assert_mutation'
    ) then
      execute format('drop trigger if exists trg_app_team_assert_mutation on public.%I', t);
      execute format(
        'create trigger trg_app_team_assert_mutation
           before insert or update or delete on public.%I
           for each row execute function public.app_team_assert_mutation()',
        t
      );
    end if;
  end loop;
end $$;

