-- ============================================================================
-- 084_admin_security_key.sql
-- Extra Admin Security Key gate for the default protected admin only
-- (is_protected = true AND role = admin). Additive. Safe to re-run.
-- Does NOT wipe data. Does NOT change permissions for other admins/users.
--
-- Storage: bcrypt hash + AES cipher (never plaintext). Verification is server-side.
-- Unlock sessions are bound to the current app_sessions row and revoked on logout
-- or when the Admin tab is locked again.
-- ============================================================================

create extension if not exists pgcrypto with schema extensions;

-- ── Pepper (server-only; no REST access) ─────────────────────────────────────
create table if not exists public.app_admin_security_pepper (
  id int primary key default 1 check (id = 1),
  pepper bytea not null,
  created_at timestamptz not null default now()
);

insert into public.app_admin_security_pepper (id, pepper)
select 1, extensions.gen_random_bytes(32)
where not exists (select 1 from public.app_admin_security_pepper where id = 1);

alter table public.app_admin_security_pepper enable row level security;
revoke all on table public.app_admin_security_pepper from public, anon, authenticated;

-- ── Settings (one row per protected admin who configured a key) ──────────────
create table if not exists public.app_admin_security_settings (
  user_id uuid primary key references public.app_users(id) on delete cascade,
  key_hash text not null,
  key_cipher bytea not null,
  configured_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists app_admin_security_settings_updated_idx
  on public.app_admin_security_settings (updated_at desc);

alter table public.app_admin_security_settings enable row level security;
revoke all on table public.app_admin_security_settings from public, anon, authenticated;

-- ── Unlock sessions (bound to login session) ─────────────────────────────────
create table if not exists public.app_admin_security_unlocks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.app_users(id) on delete cascade,
  session_id uuid not null references public.app_sessions(id) on delete cascade,
  unlocked_at timestamptz not null default now(),
  expires_at timestamptz not null,
  revoked_at timestamptz,
  constraint app_admin_security_unlocks_session_uniq unique (session_id)
);

create index if not exists app_admin_security_unlocks_user_idx
  on public.app_admin_security_unlocks (user_id);

create index if not exists app_admin_security_unlocks_active_idx
  on public.app_admin_security_unlocks (session_id)
  where revoked_at is null;

alter table public.app_admin_security_unlocks enable row level security;
revoke all on table public.app_admin_security_unlocks from public, anon, authenticated;

-- ── Brute-force rate limiting ────────────────────────────────────────────────
create table if not exists public.app_admin_security_attempts (
  user_id uuid primary key references public.app_users(id) on delete cascade,
  fail_count int not null default 0,
  locked_until timestamptz,
  updated_at timestamptz not null default now()
);

alter table public.app_admin_security_attempts enable row level security;
revoke all on table public.app_admin_security_attempts from public, anon, authenticated;

-- ── Helpers ──────────────────────────────────────────────────────────────────
create or replace function public.app_admin_security_get_pepper()
returns bytea
language plpgsql
stable
security definer
set search_path = public, extensions
as $$
declare
  p bytea;
begin
  select pepper into p from public.app_admin_security_pepper where id = 1;
  if p is null then
    insert into public.app_admin_security_pepper (id, pepper)
    values (1, extensions.gen_random_bytes(32))
    on conflict (id) do nothing;
    select pepper into p from public.app_admin_security_pepper where id = 1;
  end if;
  return p;
end;
$$;

revoke all on function public.app_admin_security_get_pepper() from public, anon, authenticated;

create or replace function public.app_admin_security_assert_key_format(p_key text)
returns text
language plpgsql
immutable
as $$
declare
  k text := trim(coalesce(p_key, ''));
begin
  if k !~ '^\d{15}$' then
    raise exception 'Security key must be exactly 15 digits';
  end if;
  return k;
end;
$$;

create or replace function public.app_admin_security_hash_key(p_key text)
returns text
language plpgsql
volatile
security definer
set search_path = public, extensions
as $$
begin
  return extensions.crypt(p_key, extensions.gen_salt('bf', 10));
end;
$$;

revoke all on function public.app_admin_security_hash_key(text) from public, anon, authenticated;

create or replace function public.app_admin_security_encrypt_key(p_key text)
returns bytea
language plpgsql
stable
security definer
set search_path = public, extensions
as $$
begin
  return extensions.encrypt(
    convert_to(p_key, 'UTF8'),
    public.app_admin_security_get_pepper(),
    'aes'
  );
end;
$$;

revoke all on function public.app_admin_security_encrypt_key(text) from public, anon, authenticated;

create or replace function public.app_require_protected_admin_identity()
returns public.app_users
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  u public.app_users := public.current_app_user();
begin
  if u is null then
    raise exception 'Authentication required';
  end if;
  if u.role <> 'admin' or not u.is_active or coalesce(u.is_protected, false) is not true then
    raise exception 'Protected administrator access required';
  end if;
  return u;
end;
$$;

create or replace function public.app_admin_security_key_configured(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.app_admin_security_settings s
    where s.user_id = p_user_id
      and coalesce(s.key_hash, '') <> ''
  );
$$;

create or replace function public.app_admin_security_is_unlocked_for(p_user_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  sess public.app_sessions := public.current_app_session();
  ok boolean := false;
begin
  if sess is null or p_user_id is null then
    return false;
  end if;
  if sess.user_id is distinct from p_user_id then
    return false;
  end if;
  select exists (
    select 1
    from public.app_admin_security_unlocks u
    where u.session_id = sess.id
      and u.user_id = p_user_id
      and u.revoked_at is null
      and u.expires_at > now()
  ) into ok;
  return coalesce(ok, false);
end;
$$;

create or replace function public.app_admin_security_gate(p_user_id uuid default null)
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  uid uuid := p_user_id;
  u public.app_users;
begin
  if uid is null then
    uid := public.current_app_user_id();
  end if;
  if uid is null then
    return;
  end if;
  select * into u from public.app_users where id = uid;
  if u is null then
    return;
  end if;
  -- Only the default protected admin is gated.
  if u.role <> 'admin' or coalesce(u.is_protected, false) is not true then
    return;
  end if;
  -- Backup import nested path must not deadlock on unlock.
  begin
    if public.app_import_is_authorized() then
      return;
    end if;
  exception when undefined_function then
    null;
  end;
  if not public.app_admin_security_key_configured(u.id) then
    return;
  end if;
  if public.app_admin_security_is_unlocked_for(u.id) then
    return;
  end if;
  raise exception 'Admin security key required';
end;
$$;

-- ── Patch admin gates (preserve existing behavior + add unlock check) ────────
create or replace function public.app_require_protected_admin()
returns public.app_users
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  u public.app_users := public.app_require_protected_admin_identity();
begin
  perform public.app_admin_security_gate(u.id);
  return u;
end;
$$;

create or replace function public.app_require_admin()
returns public.app_users
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  u public.app_users := public.current_app_user();
begin
  if u is null then
    raise exception 'Authentication required';
  end if;
  if not u.is_active then
    raise exception 'Administrator access required';
  end if;
  if coalesce(u.is_protected, false) is true and u.role = 'admin' then
    perform public.app_admin_security_gate(u.id);
    return u;
  end if;
  if u.role <> 'admin' then
    raise exception 'Administrator access required';
  end if;
  -- Non-protected admins: unchanged (no security-key gate).
  return u;
end;
$$;

create or replace function public.app_admin_security_clear_unlocks_for_session(p_session_id uuid)
returns void
language plpgsql
security definer
set search_path = public
