-- ── Smart PIN lockout state (no plaintext PIN stored) ───────────────────────
create table if not exists public.app_smart_pin_lockouts (
  user_id uuid primary key references public.app_users(id) on delete cascade,
  fail_streak int not null default 0
    check (fail_streak >= 0 and fail_streak <= 3),
  lock_tier int not null default 0
    check (lock_tier >= 0 and lock_tier <= 4),
  locked_until timestamptz,
  temp_disabled boolean not null default false,
  temp_disabled_at timestamptz,
  updated_at timestamptz not null default now()
);

