create or replace function public.app_smart_pin_register_failure(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  row_rec public.app_smart_pin_lockouts;
  u public.app_users;
  new_streak int;
  next_tier int;
  lock_mins int;
  lock_until timestamptz;
begin
  select * into u from public.app_users where id = p_user_id;
  if u is null then
    raise exception 'User not found';
  end if;

  row_rec := public.app_smart_pin_lockout_row(p_user_id);

  if coalesce(row_rec.temp_disabled, false) then
    raise exception 'Account temporarily disabled after Smart PIN lockout. Contact the default administrator to reopen access.';
  end if;

  if row_rec.locked_until is not null and row_rec.locked_until > now() then
    perform public.app_smart_pin_assert_usable(p_user_id);
  end if;

  -- Fresh window after a timed lock expires: streak restarts; tier is kept.
  if row_rec.locked_until is not null and row_rec.locked_until <= now() then
    update public.app_smart_pin_lockouts
    set fail_streak = 0,
        locked_until = null,
        updated_at = now()
    where user_id = p_user_id
    returning * into row_rec;
  end if;

  new_streak := least(3, coalesce(row_rec.fail_streak, 0) + 1);

  update public.app_smart_pin_lockouts
  set fail_streak = new_streak,
      updated_at = now()
  where user_id = p_user_id
  returning * into row_rec;

  if new_streak < 3 then
    return jsonb_build_object(
      'ok', false,
      'locked', false,
      'temp_disabled', false,
      'fail_streak', new_streak,
      'remaining_attempts', 3 - new_streak,
      'lock_tier', row_rec.lock_tier
    );
  end if;

  -- Third failure in this window → escalate lock tier.
  next_tier := least(4, coalesce(row_rec.lock_tier, 0) + 1);

  if next_tier >= 4 then
    update public.app_smart_pin_lockouts
    set fail_streak = 0,
        lock_tier = 4,
        locked_until = null,
        temp_disabled = true,
        temp_disabled_at = now(),
        updated_at = now()
    where user_id = p_user_id
    returning * into row_rec;

    -- Never delete data. Temporarily disable account (protected admin stays active
    -- so the default administrator cannot permanently lock themselves out of login).
    if coalesce(u.is_protected, false) is not true then
      update public.app_users
      set is_active = false,
          updated_at = now()
      where id = p_user_id;

      update public.app_sessions
      set revoked_at = now()
      where user_id = p_user_id
        and revoked_at is null;
    end if;

    return jsonb_build_object(
      'ok', false,
      'locked', false,
      'temp_disabled', true,
      'fail_streak', 0,
      'remaining_attempts', 0,
      'lock_tier', 4
    );
  end if;

  lock_mins := case next_tier
    when 1 then 3
    when 2 then 15
    else 30
  end;
  lock_until := now() + make_interval(mins => lock_mins);

  update public.app_smart_pin_lockouts
  set fail_streak = 0,
      lock_tier = next_tier,
      locked_until = lock_until,
      updated_at = now()
  where user_id = p_user_id
  returning * into row_rec;

  return jsonb_build_object(
    'ok', false,
    'locked', true,
    'temp_disabled', false,
    'fail_streak', 0,
    'remaining_attempts', 0,
    'lock_tier', next_tier,
    'locked_until', lock_until,
    'retry_after_seconds', greatest(0, ceil(extract(epoch from (lock_until - now())))),
    'lock_minutes', lock_mins
  );
end;
$$;

