    set admin_visible_smart_pin = null, updated_at = now()
    where id = u.id;
    perform public.app_smart_pin_clear_lockout(u.id);
    return jsonb_build_object('ok', true, 'enabled', false);
  end if;

  perform public.app_smart_pin_assert_usable(u.id);

  if pin !~ '^\d{4}$' and pin !~ '^\d{6}$' then
    raise exception 'Smart Pin must be exactly 4 or 6 digits';
  end if;

  if public.app_hash_smart_pin(u.username, pin) <> u.smart_pin_hash then
    fail_info := public.app_smart_pin_register_failure(u.id);
    if coalesce((fail_info->>'temp_disabled')::boolean, false) then
      return fail_info || jsonb_build_object(
        'ok', false,
        'enabled', true,
        'message', 'Account temporarily disabled after Smart PIN lockout. Contact the default administrator to reopen access.'
      );
    end if;
    if coalesce((fail_info->>'locked')::boolean, false) then
      secs := greatest(1, coalesce((fail_info->>'retry_after_seconds')::int, 0));
      mins := greatest(1, coalesce((fail_info->>'lock_minutes')::int, ceil(secs / 60.0)::int));
      return fail_info || jsonb_build_object(
        'ok', false,
        'enabled', true,
        'message', format('Too many incorrect Smart PIN attempts. Access locked for %s minute(s).', mins)
      );
    end if;
    return fail_info || jsonb_build_object(
      'ok', false,
      'enabled', true,
      'message', format(
        'Smart Pin is incorrect. %s attempt(s) remaining before lockout.',
        greatest(0, coalesce((fail_info->>'remaining_attempts')::int, 0))
      )
    );
  end if;

  update public.app_users
  set
    smart_pin_hash = null,
    admin_visible_smart_pin = null,
    updated_at = now()
  where id = u.id;

  perform public.app_smart_pin_clear_lockout(u.id);
  return jsonb_build_object('ok', true, 'enabled', false);
end;
$$;

-- ── Protected admin: reopen Smart PIN lockout (no data deletion) ────────────
create or replace function public.app_admin_reopen_smart_pin_lockout(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  admin public.app_users;
  target public.app_users;
begin
  admin := public.app_require_protected_admin();
  if admin is null or coalesce(admin.is_protected, false) is not true then
    raise exception 'Only the default administrator can reopen Smart PIN lockouts';
  end if;

  select * into target from public.app_users where id = p_user_id;
  if target is null then
    raise exception 'User not found';
  end if;

  perform public.app_smart_pin_clear_lockout(p_user_id);

  update public.app_users
  set is_active = true,
      updated_at = now()
  where id = p_user_id
    and coalesce(is_protected, false) is not true;

  -- Protected target: ensure active (identity already protected).
  if coalesce(target.is_protected, false) then
    update public.app_users
    set is_active = true,
        updated_at = now()
    where id = p_user_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'user_id', p_user_id,
    'reopened', true
  );
end;
$$;

-- Protected admin can clear own Smart PIN lockout by proving Admin Security Key
-- (avoids permanent self-lockout when is_active is kept true).
create or replace function public.app_admin_security_key_reopen_own_smart_pin(p_key text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users := public.current_app_user();
  key_text text;
  fail_info jsonb;
begin
  if u is null then
    raise exception 'Authentication required';
  end if;
  if u.role <> 'admin' or coalesce(u.is_protected, false) is not true then
    raise exception 'Only the default administrator can use this recovery path';
  end if;

  perform public.app_admin_security_assert_not_locked(u.id);

  if not public.app_admin_security_key_configured(u.id) then
    -- No admin key configured: allow protected admin to clear own PIN lockout.
    perform public.app_smart_pin_clear_lockout(u.id);
    update public.app_users set is_active = true, updated_at = now() where id = u.id;
    return jsonb_build_object('ok', true, 'reopened', true);
  end if;

  key_text := public.app_admin_security_assert_key_format(p_key);
  if not public.app_admin_security_verify_key(u.id, key_text) then
    fail_info := public.app_admin_security_register_failure(u.id);
    if coalesce((fail_info->>'locked')::boolean, false) then
      raise exception 'Too many failed attempts. Try again in % seconds.',
        greatest(1, coalesce((fail_info->>'retry_after_seconds')::int, 1));
    end if;
    raise exception 'Invalid security key. % attempt(s) remaining.',
      greatest(0, coalesce((fail_info->>'remaining_attempts')::int, 0));
  end if;

  perform public.app_admin_security_clear_failures(u.id);
  perform public.app_smart_pin_clear_lockout(u.id);
  update public.app_users set is_active = true, updated_at = now() where id = u.id;

  return jsonb_build_object('ok', true, 'reopened', true);
end;
$$;

-- When admin re-enables a user, also clear Smart PIN lockout (no data wipe).
create or replace function public.app_users_clear_smart_pin_lockout_on_enable()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'UPDATE'
     and old.is_active is distinct from true
     and new.is_active is true then
    delete from public.app_smart_pin_lockouts where user_id = new.id;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_app_users_clear_smart_pin_lockout_on_enable on public.app_users;
create trigger trg_app_users_clear_smart_pin_lockout_on_enable
  after update of is_active on public.app_users
  for each row
  execute function public.app_users_clear_smart_pin_lockout_on_enable();

-- Login/validate messaging for Smart PIN temp disable (preserve 064 behavior).
create or replace function public.app_login(
  p_username text,
  p_password text,
  p_user_agent text default null,
  p_ip text default null,
  p_remember boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users;
  token text;
  weak boolean;
  pin_disabled boolean := false;
begin
  if p_username is null or trim(p_username) = '' then
    raise exception 'Username is required';
  end if;
  if p_password is null or p_password = '' then
    raise exception 'Password is required';
  end if;

  select * into u
  from public.app_users
  where lower(username) = lower(trim(p_username))
  limit 1;

  if u is null or u.password_hash <> extensions.crypt(p_password, u.password_hash) then
    raise exception 'Invalid username or password';
  end if;

  if u.id is not null then
    perform public.app_enforce_access_expiry(u.id);
    select * into u from public.app_users where id = u.id;
  end if;

  if not u.is_active then
    select coalesce(temp_disabled, false) into pin_disabled
    from public.app_smart_pin_lockouts
    where user_id = u.id;
    if coalesce(pin_disabled, false) then
      raise exception 'Account temporarily disabled after Smart PIN lockout. Contact the default administrator to reopen access.';
    end if;
    if u.access_disabled_for_expiry_at is not null then
      raise exception 'Account is disabled because the access period expired. Contact the administrator to renew.';
    end if;
    raise exception 'Account is disabled';
  end if;

  weak := not public.app_password_meets_policy(p_password);

  token := public.app_create_session(u.id, p_user_agent, p_ip, coalesce(p_remember, true));

  update public.app_users
  set
    last_login_at = now(),
    updated_at = now(),
    password_is_weak = weak
  where id = u.id;

  select * into u from public.app_users where id = u.id;
  u.last_login_at := now();

  return jsonb_build_object(
    'session_token', token,
    'user', public.app_user_public_profile(u, false)
  );
end;
$$;

create or replace function public.app_validate_session()
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  sess public.app_sessions := public.current_app_session();
  u public.app_users;
  pin_disabled boolean := false;
begin
  if sess is null then
    raise exception 'Session expired or invalid';
  end if;

  if coalesce(sess.is_persistent, true) then
    update public.app_sessions
    set last_seen_at = now(),
        expires_at = greatest(expires_at, now() + interval '14 days')
    where id = sess.id;
  else
    update public.app_sessions
    set last_seen_at = now()
    where id = sess.id;
  end if;

  select * into u from public.app_users where id = sess.user_id;
  if u is null then
    update public.app_sessions set revoked_at = now() where id = sess.id;
    raise exception 'Account is disabled';
  end if;

  perform public.app_enforce_access_expiry(u.id);
  select * into u from public.app_users where id = u.id;

  if not u.is_active then
    update public.app_sessions set revoked_at = now() where id = sess.id and revoked_at is null;
    select coalesce(temp_disabled, false) into pin_disabled
    from public.app_smart_pin_lockouts
    where user_id = u.id;
    if coalesce(pin_disabled, false) then
      raise exception 'Account temporarily disabled after Smart PIN lockout. Contact the default administrator to reopen access.';
    end if;
    if u.access_disabled_for_expiry_at is not null then
      raise exception 'Account is disabled because the access period expired. Contact the administrator to renew.';
    end if;
    raise exception 'Account is disabled';
  end if;

  return jsonb_build_object(
    'session_token', null,
    'user', public.app_user_public_profile(u, false)
  );
end;
$$;

grant execute on function public.app_get_smart_pin_status() to anon, authenticated;
grant execute on function public.app_verify_smart_pin(text) to anon, authenticated;
grant execute on function public.app_set_smart_pin(text) to anon, authenticated;
grant execute on function public.app_clear_smart_pin(text) to anon, authenticated;
grant execute on function public.app_admin_reopen_smart_pin_lockout(uuid) to anon, authenticated;
grant execute on function public.app_admin_security_key_reopen_own_smart_pin(text) to anon, authenticated;

grant execute on function public.app_login(text, text, text, text, boolean)
  to authenticated, anon, service_role;
grant execute on function public.app_validate_session() to authenticated, anon, service_role;

