-- END migrations/085_admin_key_page_lock_and_smart_pin_lockout.sql
-- ############################################################################

-- ############################################################################
-- BEGIN migrations/086_fix_lockout_commit_on_failure.sql
-- ############################################################################

-- ============================================================================
-- 086_fix_lockout_commit_on_failure.sql
-- Additive / safe to re-run.
--
-- Bug: raising an exception after app_smart_pin_register_failure (or admin
-- security register_failure) rolled back the counter update in the same
-- transaction — so fail streak never advanced past 1 ("2 attempts remaining").
--
-- Fix: return ok=false + message for incorrect PIN/key and lockout outcomes so
-- the RPC commits. Keep raise only for hard preconditions (auth, format).
-- ============================================================================

-- ── Smart PIN verify: commit failure counters ───────────────────────────────
create or replace function public.app_verify_smart_pin(p_pin text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users := public.current_app_user();
  pin text := trim(coalesce(p_pin, ''));
  fail_info jsonb;
  mins int;
  secs int;
  remaining int;
begin
  if u is null then
    raise exception 'Authentication required';
  end if;

  if coalesce(u.smart_pin_hash, '') = '' then
    return jsonb_build_object('ok', true, 'enabled', false);
  end if;

  -- Locked / temp-disabled: no counter write, raise is safe.
  perform public.app_smart_pin_assert_usable(u.id);

  if pin !~ '^\d{4}$' and pin !~ '^\d{6}$' then
    raise exception 'Smart Pin must be exactly 4 or 6 digits';
  end if;

  if public.app_hash_smart_pin(u.username, pin) = u.smart_pin_hash then
    perform public.app_smart_pin_clear_lockout(u.id);
    return jsonb_build_object('ok', true, 'enabled', true);
  end if;

  -- IMPORTANT: return (do not raise) after registering failure so the update commits.
  fail_info := public.app_smart_pin_register_failure(u.id);

  if coalesce((fail_info->>'temp_disabled')::boolean, false) then
    return fail_info || jsonb_build_object(
      'ok', false,
      'enabled', true,
      'message', 'Account temporarily disabled after Smart PIN lockout. Contact the default administrator to reopen access.'
    );
  end if;

  if coalesce((fail_info->>'locked')::boolean, false) then
    secs := greatest(1, coalesce((fail_info->>'retry_after_seconds')::int, 0));
    mins := greatest(1, coalesce((fail_info->>'lock_minutes')::int, ceil(secs / 60.0)::int));
    return fail_info || jsonb_build_object(
      'ok', false,
      'enabled', true,
      'message', format('Too many incorrect Smart PIN attempts. Access locked for %s minute(s).', mins)
    );
  end if;

  remaining := greatest(0, coalesce((fail_info->>'remaining_attempts')::int, 0));
  return fail_info || jsonb_build_object(
    'ok', false,
    'enabled', true,
    'message', format('Smart Pin is incorrect. %s attempt(s) remaining before lockout.', remaining)
  );
end;
$$;

create or replace function public.app_clear_smart_pin(p_pin text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users := public.current_app_user();
  pin text := trim(coalesce(p_pin, ''));
  fail_info jsonb;
