    update public.app_users
    set admin_visible_smart_pin = null, updated_at = now()
    where id = u.id;
    perform public.app_smart_pin_clear_lockout(u.id);
    return jsonb_build_object('ok', true, 'enabled', false);
  end if;

  perform public.app_smart_pin_assert_usable(u.id);

  if pin !~ '^\d{4}$' and pin !~ '^\d{6}$' then
    raise exception 'Smart Pin must be exactly 4 or 6 digits';
  end if;

  if public.app_hash_smart_pin(u.username, pin) <> u.smart_pin_hash then
    fail_info := public.app_smart_pin_register_failure(u.id);

    if coalesce((fail_info->>'temp_disabled')::boolean, false) then
      return fail_info || jsonb_build_object(
        'ok', false,
        'enabled', true,
        'message', 'Account temporarily disabled after Smart PIN lockout. Contact the default administrator to reopen access.'
      );
    end if;

    if coalesce((fail_info->>'locked')::boolean, false) then
      secs := greatest(1, coalesce((fail_info->>'retry_after_seconds')::int, 0));
      mins := greatest(1, coalesce((fail_info->>'lock_minutes')::int, ceil(secs / 60.0)::int));
      return fail_info || jsonb_build_object(
        'ok', false,
        'enabled', true,
        'message', format('Too many incorrect Smart PIN attempts. Access locked for %s minute(s).', mins)
      );
    end if;

    remaining := greatest(0, coalesce((fail_info->>'remaining_attempts')::int, 0));
    return fail_info || jsonb_build_object(
      'ok', false,
      'enabled', true,
      'message', format('Smart Pin is incorrect. %s attempt(s) remaining before lockout.', remaining)
    );
  end if;

  update public.app_users
  set
    smart_pin_hash = null,
    admin_visible_smart_pin = null,
    updated_at = now()
  where id = u.id;

  perform public.app_smart_pin_clear_lockout(u.id);
  return jsonb_build_object('ok', true, 'enabled', false);
end;
$$;

-- ── Admin Security Key unlock/set: commit failure counters ──────────────────
create or replace function public.app_admin_security_key_unlock(p_key text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users := public.app_require_protected_admin_identity();
  key_text text;
  fail_info jsonb;
  unlock_info jsonb;
  remaining int;
  secs int;
begin
  if not public.app_admin_security_key_configured(u.id) then
    raise exception 'Admin security key is not configured';
  end if;

  perform public.app_admin_security_assert_not_locked(u.id);
  key_text := public.app_admin_security_assert_key_format(p_key);

  if not public.app_admin_security_verify_key(u.id, key_text) then
    fail_info := public.app_admin_security_register_failure(u.id);
    if coalesce((fail_info->>'locked')::boolean, false) then
      secs := greatest(1, coalesce((fail_info->>'retry_after_seconds')::int, 1));
      return fail_info || jsonb_build_object(
        'ok', false,
        'unlocked', false,
        'message', format('Too many failed attempts. Try again in %s seconds.', secs)
      );
    end if;
    remaining := greatest(0, coalesce((fail_info->>'remaining_attempts')::int, 0));
    return fail_info || jsonb_build_object(
      'ok', false,
      'unlocked', false,
      'message', format('Invalid security key. %s attempt(s) remaining.', remaining)
    );
  end if;

  perform public.app_admin_security_clear_failures(u.id);
  unlock_info := public.app_admin_security_issue_unlock(u.id);

  return jsonb_build_object(
    'ok', true,
    'unlocked', true,
    'expires_at', unlock_info->>'expires_at'
  );
end;
$$;

create or replace function public.app_admin_security_key_set(
  p_new_key text,
  p_current_key text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users := public.app_require_protected_admin_identity();
  configured boolean := public.app_admin_security_key_configured(u.id);
  new_key text;
  current_key text;
  unlock_info jsonb;
  fail_info jsonb;
  remaining int;
  secs int;
begin
  perform public.app_admin_security_assert_not_locked(u.id);
  new_key := public.app_admin_security_assert_key_format(p_new_key);

  if configured then
    current_key := public.app_admin_security_assert_key_format(p_current_key);
    if not public.app_admin_security_verify_key(u.id, current_key) then
      fail_info := public.app_admin_security_register_failure(u.id);
      if coalesce((fail_info->>'locked')::boolean, false) then
        secs := greatest(1, coalesce((fail_info->>'retry_after_seconds')::int, 1));
        return fail_info || jsonb_build_object(
          'ok', false,
          'message', format('Too many failed attempts. Try again in %s seconds.', secs)
        );
      end if;
      remaining := greatest(0, coalesce((fail_info->>'remaining_attempts')::int, 0));
      return fail_info || jsonb_build_object(
        'ok', false,
        'message', format('Invalid security key. %s attempt(s) remaining.', remaining)
      );
    end if;
  end if;

  insert into public.app_admin_security_settings (user_id, key_hash, key_cipher, configured_at, updated_at)
  values (
    u.id,
    public.app_admin_security_hash_key(new_key),
    public.app_admin_security_encrypt_key(new_key),
    now(),
    now()
  )
  on conflict (user_id) do update
  set key_hash = excluded.key_hash,
      key_cipher = excluded.key_cipher,
      updated_at = now();

  perform public.app_admin_security_clear_failures(u.id);
  unlock_info := public.app_admin_security_issue_unlock(u.id);

  return jsonb_build_object(
    'ok', true,
    'configured', true,
    'updated', configured,
    'unlocked', true,
    'expires_at', unlock_info->>'expires_at'
  );
end;
$$;

create or replace function public.app_admin_security_key_reopen_own_smart_pin(p_key text)
