    );
  end if;

  perform public.app_admin_security_clear_failures(u.id);
  perform public.app_smart_pin_clear_lockout(u.id);
  update public.app_users set is_active = true, updated_at = now() where id = u.id;

  return jsonb_build_object('ok', true, 'reopened', true);
end;
$$;

