-- ============================================================================
-- 087_smart_pin_lock_tiers_countdown.sql
-- Additive / safe to re-run.
-- Lock progression after each 3 wrong attempts:
--   1st → 3 min, 2nd → 5 min, 3rd → 15 min, 4th → 30 min, 5th → temp disable.
-- ============================================================================

alter table public.app_smart_pin_lockouts
  drop constraint if exists app_smart_pin_lockouts_lock_tier_check;

alter table public.app_smart_pin_lockouts
  add constraint app_smart_pin_lockouts_lock_tier_check
  check (lock_tier >= 0 and lock_tier <= 5);

create or replace function public.app_smart_pin_register_failure(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  row_rec public.app_smart_pin_lockouts;
  u public.app_users;
  new_streak int;
  next_tier int;
  lock_mins int;
  lock_until timestamptz;
begin
  select * into u from public.app_users where id = p_user_id;
  if u is null then
    raise exception 'User not found';
  end if;

  row_rec := public.app_smart_pin_lockout_row(p_user_id);

  if coalesce(row_rec.temp_disabled, false) then
    raise exception 'Account temporarily disabled after Smart PIN lockout. Contact admin on WhatsApp +92 333 900 4564 to restore access.';
  end if;

  if row_rec.locked_until is not null and row_rec.locked_until > now() then
    perform public.app_smart_pin_assert_usable(p_user_id);
  end if;

  -- Fresh window after a timed lock expires: streak restarts; tier is kept.
  if row_rec.locked_until is not null and row_rec.locked_until <= now() then
    update public.app_smart_pin_lockouts
    set fail_streak = 0,
        locked_until = null,
        updated_at = now()
    where user_id = p_user_id
    returning * into row_rec;
  end if;

  new_streak := least(3, coalesce(row_rec.fail_streak, 0) + 1);

  update public.app_smart_pin_lockouts
  set fail_streak = new_streak,
      updated_at = now()
  where user_id = p_user_id
  returning * into row_rec;

  if new_streak < 3 then
    return jsonb_build_object(
      'ok', false,
      'locked', false,
      'temp_disabled', false,
      'fail_streak', new_streak,
      'remaining_attempts', 3 - new_streak,
      'lock_tier', row_rec.lock_tier
    );
  end if;

  -- Third failure in this window → escalate lock tier.
  next_tier := least(5, coalesce(row_rec.lock_tier, 0) + 1);

  if next_tier >= 5 then
    update public.app_smart_pin_lockouts
    set fail_streak = 0,
        lock_tier = 5,
        locked_until = null,
        temp_disabled = true,
        temp_disabled_at = now(),
        updated_at = now()
    where user_id = p_user_id
    returning * into row_rec;

    -- Never delete data. Temporarily disable account (protected admin stays active).
    if coalesce(u.is_protected, false) is not true then
      update public.app_users
      set is_active = false,
          updated_at = now()
      where id = p_user_id;

      update public.app_sessions
      set revoked_at = now()
      where user_id = p_user_id
        and revoked_at is null;
    end if;

    return jsonb_build_object(
      'ok', false,
      'locked', false,
      'temp_disabled', true,
      'fail_streak', 0,
      'remaining_attempts', 0,
      'lock_tier', 5,
      'message', 'Due to too many wrong attempts, access is locked. Please contact admin to restore your access on WhatsApp +92 333 900 4564.'
    );
  end if;

  lock_mins := case next_tier
    when 1 then 3
    when 2 then 5
    when 3 then 15
    else 30
  end;
  lock_until := now() + make_interval(mins => lock_mins);

  update public.app_smart_pin_lockouts
  set fail_streak = 0,
      lock_tier = next_tier,
      locked_until = lock_until,
      updated_at = now()
  where user_id = p_user_id
  returning * into row_rec;

  return jsonb_build_object(
    'ok', false,
    'locked', true,
    'temp_disabled', false,
    'fail_streak', 0,
    'remaining_attempts', 0,
    'lock_tier', next_tier,
    'locked_until', lock_until,
    'retry_after_seconds', greatest(0, ceil(extract(epoch from (lock_until - now())))),
    'lock_minutes', lock_mins
  );
end;
$$;

revoke all on function public.app_smart_pin_register_failure(uuid) from public, anon, authenticated;

create or replace function public.app_smart_pin_assert_usable(p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  row_rec public.app_smart_pin_lockouts;
  secs int;
  mins int;
begin
  row_rec := public.app_smart_pin_lockout_row(p_user_id);

  if coalesce(row_rec.temp_disabled, false) then
    raise exception 'Due to too many wrong attempts, access is locked. Please contact admin to restore your access on WhatsApp +92 333 900 4564.';
  end if;

  if row_rec.locked_until is not null and row_rec.locked_until > now() then
    secs := greatest(1, ceil(extract(epoch from (row_rec.locked_until - now())))::int);
    mins := greatest(1, ceil(secs / 60.0)::int);
    raise exception 'Smart PIN locked. Try again in % minute(s) (% seconds).', mins, secs;
  end if;
end;
$$;

revoke all on function public.app_smart_pin_assert_usable(uuid) from public, anon, authenticated;

-- Align login messaging for Smart PIN temp disable (preserve 064/085 behavior).
create or replace function public.app_login(
  p_username text,
  p_password text,
  p_user_agent text default null,
  p_ip text default null,
  p_remember boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users;
  token text;
  weak boolean;
  pin_disabled boolean := false;
begin
  if p_username is null or trim(p_username) = '' then
    raise exception 'Username is required';
  end if;
  if p_password is null or p_password = '' then
    raise exception 'Password is required';
  end if;

  select * into u
  from public.app_users
  where lower(username) = lower(trim(p_username))
  limit 1;

  if u is null or u.password_hash <> extensions.crypt(p_password, u.password_hash) then
    raise exception 'Invalid username or password';
  end if;

  if u.id is not null then
    perform public.app_enforce_access_expiry(u.id);
    select * into u from public.app_users where id = u.id;
  end if;

  if not u.is_active then
    select coalesce(temp_disabled, false) into pin_disabled
    from public.app_smart_pin_lockouts
    where user_id = u.id;
    if coalesce(pin_disabled, false) then
      raise exception 'Due to too many wrong attempts, access is locked. Please contact admin to restore your access on WhatsApp +92 333 900 4564.';
    end if;
    if u.access_disabled_for_expiry_at is not null then
      raise exception 'Account is disabled because the access period expired. Contact the administrator to renew.';
    end if;
    raise exception 'Account is disabled';
  end if;

  weak := not public.app_password_meets_policy(p_password);

  token := public.app_create_session(u.id, p_user_agent, p_ip, coalesce(p_remember, true));

  update public.app_users
  set
    last_login_at = now(),
    updated_at = now(),
    password_is_weak = weak
  where id = u.id;

  select * into u from public.app_users where id = u.id;
  u.last_login_at := now();

  return jsonb_build_object(
    'session_token', token,
    'user', public.app_user_public_profile(u, false)
  );
end;
$$;

grant execute on function public.app_login(text, text, text, text, boolean)
  to authenticated, anon, service_role;

-- Keep verify messages aligned (still returns ok=false so counters commit).
create or replace function public.app_verify_smart_pin(p_pin text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users := public.current_app_user();
  pin text := trim(coalesce(p_pin, ''));
  fail_info jsonb;
  mins int;
  secs int;
  remaining int;
begin
  if u is null then
    raise exception 'Authentication required';
  end if;

  if coalesce(u.smart_pin_hash, '') = '' then
    return jsonb_build_object('ok', true, 'enabled', false);
  end if;

  perform public.app_smart_pin_assert_usable(u.id);

  if pin !~ '^\d{4}$' and pin !~ '^\d{6}$' then
    raise exception 'Smart Pin must be exactly 4 or 6 digits';
  end if;

  if public.app_hash_smart_pin(u.username, pin) = u.smart_pin_hash then
    perform public.app_smart_pin_clear_lockout(u.id);
    return jsonb_build_object('ok', true, 'enabled', true);
  end if;

  fail_info := public.app_smart_pin_register_failure(u.id);

  if coalesce((fail_info->>'temp_disabled')::boolean, false) then
    return fail_info || jsonb_build_object(
      'ok', false,
      'enabled', true,
      'message', 'Due to too many wrong attempts, access is locked. Please contact admin to restore your access on WhatsApp +92 333 900 4564.'
    );
  end if;

  if coalesce((fail_info->>'locked')::boolean, false) then
    secs := greatest(1, coalesce((fail_info->>'retry_after_seconds')::int, 0));
    mins := greatest(1, coalesce((fail_info->>'lock_minutes')::int, ceil(secs / 60.0)::int));
    return fail_info || jsonb_build_object(
      'ok', false,
      'enabled', true,
      'message', format('Too many incorrect Smart PIN attempts. Access locked for %s minute(s).', mins)
    );
  end if;

  remaining := greatest(0, coalesce((fail_info->>'remaining_attempts')::int, 0));
  return fail_info || jsonb_build_object(
    'ok', false,
    'enabled', true,
    'message', format('Smart Pin is incorrect. %s attempt(s) remaining before lockout.', remaining)
  );
end;
$$;

grant execute on function public.app_verify_smart_pin(text) to anon, authenticated;

