-- Admin clear PIN: wipe pin + wipe lockout so user can set a new PIN immediately.
create or replace function public.app_admin_clear_user_smart_pin(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  target public.app_users;
begin
  perform public.app_require_protected_admin();

  select * into target from public.app_users where id = p_user_id;
  if target is null then
    raise exception 'User not found';
  end if;
  if coalesce(target.is_protected, false) is true then
    raise exception 'Protected administrator Smart Pin cannot be cleared this way';
  end if;

  update public.app_users
  set
    smart_pin_hash = null,
    admin_visible_smart_pin = null,
    is_active = true,
    updated_at = now()
  where id = p_user_id
  returning * into target;

  -- Reset progressive lockout / fail streak completely.
  delete from public.app_smart_pin_lockouts where user_id = p_user_id;

  if exists (
    select 1 from information_schema.tables
    where table_schema = 'public' and table_name = 'loan_ledger_entries'
  ) then
    delete from public.loan_ledger_entries
    where owner_id = p_user_id
      and coalesce(person_name, '') = 'SYSTEM'
      and (
        coalesce(notes, '') ilike '%SECRET_PIN_HASH%'
        or coalesce(notes, '') ilike '%SMART_PIN_DISABLED%'
      );
  end if;

  return public.app_user_public_profile(target, true)
    || jsonb_build_object(
      'smart_pin_hash', '',
      'smart_pin_enabled', false,
      'admin_visible_smart_pin', '',
      'smart_pin_lockout_cleared', true
    );
end;
$$;

-- Reopen also fully deletes lockout row (fresh start).
create or replace function public.app_admin_reopen_smart_pin_lockout(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  admin public.app_users;
  target public.app_users;
begin
  admin := public.app_require_protected_admin();
  if admin is null or coalesce(admin.is_protected, false) is not true then
    raise exception 'Only the default administrator can reopen Smart PIN lockouts';
  end if;

  select * into target from public.app_users where id = p_user_id;
  if target is null then
    raise exception 'User not found';
  end if;

  delete from public.app_smart_pin_lockouts where user_id = p_user_id;

  update public.app_users
  set is_active = true,
      updated_at = now()
  where id = p_user_id;

  return jsonb_build_object(
    'ok', true,
    'user_id', p_user_id,
    'reopened', true
  );
end;
$$;

-- Heal any protected-admin permanent PIN lockouts already stored.
update public.app_smart_pin_lockouts l
set
  temp_disabled = false,
  temp_disabled_at = null,
  lock_tier = 0,
  fail_streak = 0,
  updated_at = now()
from public.app_users u
where l.user_id = u.id
  and coalesce(u.is_protected, false) is true
  and coalesce(u.role, '') = 'admin'
  and coalesce(l.temp_disabled, false) is true;

