-- ============================================================================
-- 090_site_analytics.sql
-- Additive / safe to re-run.
-- Site analytics (visits, sessions, pageviews, events) for admin Analytics overlay.
-- Does not DROP existing user/domain tables.
-- ============================================================================

create extension if not exists pgcrypto with schema extensions;

-- ── Sessions ─────────────────────────────────────────────────────────────────

create table if not exists public.app_site_analytics_sessions (
  id uuid primary key default gen_random_uuid(),
  session_key text not null unique,
  visitor_key text not null,
  started_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  duration_seconds integer not null default 0
    check (duration_seconds >= 0 and duration_seconds <= 86400),
  landing_path text not null default '/',
  exit_path text,
  referrer text not null default '',
  traffic_source text not null default 'direct'
    check (traffic_source in ('direct', 'search', 'referral', 'social', 'campaign')),
  utm_source text,
  utm_medium text,
  utm_campaign text,
  device_type text not null default 'desktop'
    check (device_type in ('mobile', 'tablet', 'desktop')),
  browser text not null default '',
  os text not null default '',
  page_views integer not null default 0 check (page_views >= 0),
  event_count integer not null default 0 check (event_count >= 0),
  is_bounce boolean not null default true,
  app_user_id uuid references public.app_users(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists app_site_analytics_sessions_started_idx
  on public.app_site_analytics_sessions (started_at desc);
create index if not exists app_site_analytics_sessions_visitor_idx
  on public.app_site_analytics_sessions (visitor_key, started_at desc);
create index if not exists app_site_analytics_sessions_source_idx
  on public.app_site_analytics_sessions (traffic_source, started_at desc);
create index if not exists app_site_analytics_sessions_device_idx
  on public.app_site_analytics_sessions (device_type, started_at desc);

-- ── Page views ───────────────────────────────────────────────────────────────

create table if not exists public.app_site_analytics_pageviews (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.app_site_analytics_sessions(id) on delete cascade,
  visitor_key text not null,
  path text not null,
  title text not null default '',
  viewed_at timestamptz not null default now()
);

create index if not exists app_site_analytics_pageviews_viewed_idx
  on public.app_site_analytics_pageviews (viewed_at desc);
create index if not exists app_site_analytics_pageviews_path_idx
  on public.app_site_analytics_pageviews (path, viewed_at desc);
create index if not exists app_site_analytics_pageviews_session_idx
  on public.app_site_analytics_pageviews (session_id, viewed_at desc);

-- ── Interaction events ───────────────────────────────────────────────────────

create table if not exists public.app_site_analytics_events (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.app_site_analytics_sessions(id) on delete cascade,
  visitor_key text not null,
  event_name text not null,
  event_label text not null default '',
  path text not null default '',
  meta jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists app_site_analytics_events_created_idx
  on public.app_site_analytics_events (created_at desc);
create index if not exists app_site_analytics_events_name_idx
  on public.app_site_analytics_events (event_name, created_at desc);

-- ── Daily rollups ────────────────────────────────────────────────────────────

create table if not exists public.app_site_analytics_daily (
  day date primary key,
  sessions integer not null default 0,
  pageviews integer not null default 0,
  events integer not null default 0,
  total_duration_seconds bigint not null default 0,
  bounce_sessions integer not null default 0,
  device_mobile integer not null default 0,
  device_tablet integer not null default 0,
  device_desktop integer not null default 0,
  source_direct integer not null default 0,
  source_search integer not null default 0,
  source_referral integer not null default 0,
  source_social integer not null default 0,
  source_campaign integer not null default 0
);

create table if not exists public.app_site_analytics_visitor_days (
  day date not null,
  visitor_key text not null,
  primary key (day, visitor_key)
);

create table if not exists public.app_site_analytics_path_daily (
  day date not null,
  path text not null,
  views integer not null default 0,
  primary key (day, path)
);

create index if not exists app_site_analytics_path_daily_views_idx
  on public.app_site_analytics_path_daily (day, views desc);

-- RLS: deny direct table access — RPCs only
alter table public.app_site_analytics_sessions enable row level security;
alter table public.app_site_analytics_pageviews enable row level security;
alter table public.app_site_analytics_events enable row level security;
alter table public.app_site_analytics_daily enable row level security;
alter table public.app_site_analytics_visitor_days enable row level security;
alter table public.app_site_analytics_path_daily enable row level security;

drop policy if exists app_site_analytics_sessions_deny on public.app_site_analytics_sessions;
create policy app_site_analytics_sessions_deny
  on public.app_site_analytics_sessions for all to anon, authenticated
