drop policy if exists app_site_analytics_pageviews_deny on public.app_site_analytics_pageviews;
create policy app_site_analytics_pageviews_deny
  on public.app_site_analytics_pageviews for all to anon, authenticated
  using (false) with check (false);

drop policy if exists app_site_analytics_events_deny on public.app_site_analytics_events;
create policy app_site_analytics_events_deny
  on public.app_site_analytics_events for all to anon, authenticated
  using (false) with check (false);

drop policy if exists app_site_analytics_daily_deny on public.app_site_analytics_daily;
create policy app_site_analytics_daily_deny
  on public.app_site_analytics_daily for all to anon, authenticated
  using (false) with check (false);

drop policy if exists app_site_analytics_visitor_days_deny on public.app_site_analytics_visitor_days;
create policy app_site_analytics_visitor_days_deny
  on public.app_site_analytics_visitor_days for all to anon, authenticated
  using (false) with check (false);

drop policy if exists app_site_analytics_path_daily_deny on public.app_site_analytics_path_daily;
create policy app_site_analytics_path_daily_deny
  on public.app_site_analytics_path_daily for all to anon, authenticated
  using (false) with check (false);

-- ── Helpers ──────────────────────────────────────────────────────────────────

create or replace function public.app_site_analytics_classify_source(
  p_referrer text,
  p_utm_source text default null,
  p_utm_medium text default null
)
returns text
language plpgsql
immutable
as $$
declare
  ref text := lower(trim(coalesce(p_referrer, '')));
  utm_s text := lower(trim(coalesce(p_utm_source, '')));
  utm_m text := lower(trim(coalesce(p_utm_medium, '')));
  host text := '';
begin
  if utm_s <> '' or utm_m <> '' then
    if utm_m in ('cpc', 'ppc', 'paid', 'paidsearch', 'display', 'email', 'affiliate')
       or utm_s <> '' then
      return 'campaign';
    end if;
  end if;

  if ref = '' then
    return 'direct';
  end if;

  begin
    host := lower(split_part(split_part(ref, '://', 2), '/', 1));
  exception when others then
    host := '';
  end;

  if host = '' then
    return 'direct';
  end if;

  if host like '%google.%'
     or host like '%bing.%'
     or host like '%yahoo.%'
     or host like '%duckduckgo.%'
     or host like '%baidu.%'
     or host like '%yandex.%' then
    return 'search';
  end if;

  if host like '%facebook.%'
     or host like '%instagram.%'
     or host like '%twitter.%'
     or host like '%x.com%'
     or host like '%linkedin.%'
     or host like '%t.co%'
     or host like '%youtube.%'
     or host like '%tiktok.%'
     or host like '%whatsapp.%' then
    return 'social';
  end if;

  if host like '%triplem.vip%' or host like '%localhost%' then
    return 'direct';
  end if;

  return 'referral';
end;
$$;

create or replace function public.app_site_analytics_ensure_daily(p_day date)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.app_site_analytics_daily (day)
  values (p_day)
  on conflict (day) do nothing;
end;
$$;

-- ── Public ingest (batched, rate-limited) ────────────────────────────────────

create or replace function public.app_site_analytics_ingest(p_payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_key text := left(trim(coalesce(payload->>'visitor_key', '')), 64);
  s_key text := left(trim(coalesce(payload->>'session_key', '')), 64);
  path_raw text := left(trim(coalesce(payload->>'path', '/')), 240);
  title_raw text := left(trim(coalesce(payload->>'title', '')), 160);
  ref_raw text := left(trim(coalesce(payload->>'referrer', '')), 500);
  device_raw text := lower(trim(coalesce(payload->>'device_type', 'desktop')));
  browser_raw text := left(trim(coalesce(payload->>'browser', '')), 64);
  os_raw text := left(trim(coalesce(payload->>'os', '')), 64);
  utm_s text := left(nullif(trim(coalesce(payload->>'utm_source', '')), ''), 80);
  utm_m text := left(nullif(trim(coalesce(payload->>'utm_medium', '')), ''), 80);
  utm_c text := left(nullif(trim(coalesce(payload->>'utm_campaign', '')), ''), 80);
  dur int := greatest(0, least(coalesce((payload->>'duration_seconds')::int, 0), 86400));
  want_pageview boolean := coalesce((payload->>'pageview')::boolean, false);
  heartbeat boolean := coalesce((payload->>'heartbeat')::boolean, false);
  events jsonb := coalesce(payload->'events', '[]'::jsonb);
  event_item jsonb;
  event_name text;
  event_label text;
  events_added int := 0;
  sess public.app_site_analytics_sessions;
  is_new boolean := false;
  day_local date := (timezone('utc', now()))::date;
  source text;
  app_uid uuid := null;
  recent_pv int := 0;
begin
  if v_key is null or v_key = '' or char_length(v_key) < 8 then
    raise exception 'Invalid visitor';
  end if;
  if s_key is null or s_key = '' or char_length(s_key) < 8 then
    raise exception 'Invalid session';
  end if;
  if path_raw is null or path_raw = '' then
    path_raw := '/';
  end if;
  if device_raw not in ('mobile', 'tablet', 'desktop') then
    device_raw := 'desktop';
  end if;
  if jsonb_typeof(events) <> 'array' then
    events := '[]'::jsonb;
  end if;
  if jsonb_array_length(events) > 25 then
    events := (
      select coalesce(jsonb_agg(value), '[]'::jsonb)
      from (
        select value from jsonb_array_elements(events) with ordinality as t(value, ord)
        where ord <= 25
      ) x
    );
  end if;

  begin
    app_uid := public.current_app_user_id();
  exception when others then
    app_uid := null;
  end;

  select * into sess
  from public.app_site_analytics_sessions
  where session_key = s_key;

  if sess.id is null then
    source := public.app_site_analytics_classify_source(ref_raw, utm_s, utm_m);
    insert into public.app_site_analytics_sessions (
      session_key, visitor_key, landing_path, exit_path, referrer, traffic_source,
      utm_source, utm_medium, utm_campaign, device_type, browser, os,
      duration_seconds, page_views, event_count, is_bounce, app_user_id
    ) values (
      s_key, v_key, path_raw, path_raw, coalesce(ref_raw, ''), source,
      utm_s, utm_m, utm_c, device_raw, browser_raw, os_raw,
      dur, 0, 0, true, app_uid
    )
    returning * into sess;
    is_new := true;

    perform public.app_site_analytics_ensure_daily(day_local);
    update public.app_site_analytics_daily d
    set
      sessions = d.sessions + 1,
      bounce_sessions = d.bounce_sessions + 1,
      device_mobile = d.device_mobile + case when device_raw = 'mobile' then 1 else 0 end,
      device_tablet = d.device_tablet + case when device_raw = 'tablet' then 1 else 0 end,
      device_desktop = d.device_desktop + case when device_raw = 'desktop' then 1 else 0 end,
      source_direct = d.source_direct + case when source = 'direct' then 1 else 0 end,
      source_search = d.source_search + case when source = 'search' then 1 else 0 end,
      source_referral = d.source_referral + case when source = 'referral' then 1 else 0 end,
      source_social = d.source_social + case when source = 'social' then 1 else 0 end,
      source_campaign = d.source_campaign + case when source = 'campaign' then 1 else 0 end
    where d.day = day_local;

    insert into public.app_site_analytics_visitor_days (day, visitor_key)
    values (day_local, v_key)
    on conflict do nothing;
  end if;

  -- Soft rate limit: max ~120 pageviews / session / hour
  if want_pageview then
    select count(*)::int into recent_pv
    from public.app_site_analytics_pageviews
    where session_id = sess.id
      and viewed_at > now() - interval '1 hour';
    if recent_pv >= 120 then
      want_pageview := false;
    end if;
  end if;

  if want_pageview then
    insert into public.app_site_analytics_pageviews (session_id, visitor_key, path, title)
    values (sess.id, v_key, path_raw, title_raw);

    update public.app_site_analytics_sessions s
    set
      page_views = s.page_views + 1,
      exit_path = path_raw,
      last_seen_at = now(),
      duration_seconds = greatest(s.duration_seconds, dur),
      is_bounce = case when (s.page_views + 1) > 1 then false else s.is_bounce end,
      app_user_id = coalesce(app_uid, s.app_user_id),
      browser = case when browser_raw <> '' then browser_raw else s.browser end,
      os = case when os_raw <> '' then os_raw else s.os end,
      device_type = device_raw
    where s.id = sess.id
    returning * into sess;

    perform public.app_site_analytics_ensure_daily(day_local);
    update public.app_site_analytics_daily d
    set
      pageviews = d.pageviews + 1,
      bounce_sessions = greatest(0, d.bounce_sessions - case when sess.page_views = 2 then 1 else 0 end)
    where d.day = day_local;

    insert into public.app_site_analytics_path_daily (day, path, views)
    values (day_local, path_raw, 1)
    on conflict (day, path) do update
      set views = public.app_site_analytics_path_daily.views + 1;
  elsif heartbeat or dur > 0 then
    update public.app_site_analytics_sessions s
    set
      last_seen_at = now(),
      duration_seconds = greatest(s.duration_seconds, dur),
      exit_path = coalesce(nullif(path_raw, ''), s.exit_path),
      app_user_id = coalesce(app_uid, s.app_user_id)
    where s.id = sess.id
    returning * into sess;
  end if;

  for event_item in
    select value from jsonb_array_elements(events)
  loop
    event_name := left(trim(coalesce(event_item->>'name', event_item->>'event_name', '')), 64);
    event_label := left(trim(coalesce(event_item->>'label', event_item->>'event_label', '')), 160);
    if event_name = '' then
      continue;
    end if;
    insert into public.app_site_analytics_events (
      session_id, visitor_key, event_name, event_label, path, meta
    ) values (
      sess.id,
      v_key,
      event_name,
      event_label,
      left(trim(coalesce(event_item->>'path', path_raw)), 240),
      coalesce(event_item->'meta', '{}'::jsonb)
    );
    events_added := events_added + 1;
  end loop;

  if events_added > 0 then
    update public.app_site_analytics_sessions s
    set
      event_count = s.event_count + events_added,
      last_seen_at = now(),
      duration_seconds = greatest(s.duration_seconds, dur),
      is_bounce = false
    where s.id = sess.id
    returning * into sess;

    perform public.app_site_analytics_ensure_daily(day_local);
    update public.app_site_analytics_daily d
    set events = d.events + events_added
    where d.day = day_local;
  end if;

  return jsonb_build_object(
    'ok', true,
    'session_id', sess.id,
    'is_new_session', is_new,
    'page_views', sess.page_views,
    'events_added', events_added
  );
end;
$$;

-- ── Admin dashboard summary ──────────────────────────────────────────────────

create or replace function public.app_admin_analytics_summary(p_range text default '7d')
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  admin public.app_users;
  rng text := lower(trim(coalesce(p_range, '7d')));
  since timestamptz;
  until_ts timestamptz := now();
  days int := 7;
  totals jsonb;
  series jsonb := '[]'::jsonb;
  devices jsonb;
  sources jsonb;
  top_pages jsonb := '[]'::jsonb;
  top_events jsonb := '[]'::jsonb;
  timeline jsonb := '[]'::jsonb;
  browsers jsonb := '[]'::jsonb;
  avg_dur numeric := 0;
  unique_visitors int := 0;
  visits int := 0;
  pageviews int := 0;
  events_n int := 0;
begin
  admin := public.app_require_admin();

  if rng not in ('today', '1d', '7d', '30d', '90d', 'all') then
    rng := '7d';
  end if;
  if rng in ('today', '1d') then
    since := date_trunc('day', now());
    days := 1;
  elsif rng = '30d' then
    since := now() - interval '30 days';
    days := 30;
  elsif rng = '90d' then
    since := now() - interval '90 days';
    days := 90;
  elsif rng = 'all' then
    since := timestamptz '2020-01-01';
    days := 3650;
  else
    since := now() - interval '7 days';
    days := 7;
  end if;

  select
    count(*)::int,
    coalesce(sum(page_views), 0)::int,
    coalesce(sum(event_count), 0)::int,
    coalesce(avg(nullif(duration_seconds, 0)), 0)
  into visits, pageviews, events_n, avg_dur
  from public.app_site_analytics_sessions
  where started_at >= since and started_at <= until_ts;

  select count(distinct visitor_key)::int into unique_visitors
  from public.app_site_analytics_sessions
  where started_at >= since and started_at <= until_ts;

  totals := jsonb_build_object(
    'visits', visits,
    'unique_visitors', unique_visitors,
    'pageviews', pageviews,
    'events', events_n,
    'avg_session_seconds', round(coalesce(avg_dur, 0))::int,
    'range', rng,
    'since', since,
    'generated_at', now()
  );

  select coalesce(jsonb_agg(jsonb_build_object(
    'day', d.day,
    'sessions', d.sessions,
    'pageviews', d.pageviews,
    'events', d.events,
    'unique_visitors', coalesce(v.uv, 0)
  ) order by d.day), '[]'::jsonb)
  into series
  from public.app_site_analytics_daily d
  left join lateral (
    select count(*)::int as uv
    from public.app_site_analytics_visitor_days vd
    where vd.day = d.day
  ) v on true
  where d.day >= since::date
    and d.day <= until_ts::date;

  select jsonb_build_object(
    'mobile', coalesce(sum(case when device_type = 'mobile' then 1 else 0 end), 0),
    'tablet', coalesce(sum(case when device_type = 'tablet' then 1 else 0 end), 0),
    'desktop', coalesce(sum(case when device_type = 'desktop' then 1 else 0 end), 0)
  )
  into devices
  from public.app_site_analytics_sessions
  where started_at >= since and started_at <= until_ts;

  select jsonb_build_object(
    'direct', coalesce(sum(case when traffic_source = 'direct' then 1 else 0 end), 0),
    'search', coalesce(sum(case when traffic_source = 'search' then 1 else 0 end), 0),
    'referral', coalesce(sum(case when traffic_source = 'referral' then 1 else 0 end), 0),
    'social', coalesce(sum(case when traffic_source = 'social' then 1 else 0 end), 0),
    'campaign', coalesce(sum(case when traffic_source = 'campaign' then 1 else 0 end), 0)
  )
  into sources
  from public.app_site_analytics_sessions
  where started_at >= since and started_at <= until_ts;

  select coalesce(jsonb_agg(jsonb_build_object('path', path, 'views', views) order by views desc), '[]'::jsonb)
  into top_pages
  from (
    select path, sum(views)::int as views
    from public.app_site_analytics_path_daily
    where day >= since::date and day <= until_ts::date
    group by path
    order by sum(views) desc
    limit 12
  ) t;

  select coalesce(jsonb_agg(jsonb_build_object(
    'name', event_name,
    'label', event_label,
    'count', cnt
  ) order by cnt desc), '[]'::jsonb)
  into top_events
  from (
    select event_name, event_label, count(*)::int as cnt
    from public.app_site_analytics_events
    where created_at >= since and created_at <= until_ts
    group by event_name, event_label
    order by count(*) desc
    limit 12
  ) e;

  select coalesce(jsonb_agg(jsonb_build_object('browser', browser, 'count', cnt) order by cnt desc), '[]'::jsonb)
  into browsers
  from (
    select nullif(browser, '') as browser, count(*)::int as cnt
    from public.app_site_analytics_sessions
    where started_at >= since and started_at <= until_ts
      and nullif(browser, '') is not null
    group by browser
    order by count(*) desc
    limit 8
  ) b;

  select coalesce(jsonb_agg(row_obj order by sort_at desc), '[]'::jsonb)
  into timeline
  from (
    select row_obj, sort_at
    from (
      (
        select
          jsonb_build_object(
            'kind', 'pageview',
            'label', path,
            'detail', title,
            'at', viewed_at,
            'device', null,
            'source', null
          ) as row_obj,
          viewed_at as sort_at
        from public.app_site_analytics_pageviews
        where viewed_at >= since
        order by viewed_at desc
        limit 30
      )
      union all
      (
        select
          jsonb_build_object(
            'kind', 'event',
            'label', event_name,
            'detail', event_label,
            'at', created_at,
            'device', null,
            'source', null
          ) as row_obj,
          created_at as sort_at
        from public.app_site_analytics_events
        where created_at >= since
        order by created_at desc
        limit 30
      )
      union all
      (
        select
          jsonb_build_object(
            'kind', 'session',
            'label', 'Visit',
            'detail', landing_path,
            'at', started_at,
            'device', device_type,
            'source', traffic_source
          ) as row_obj,
          started_at as sort_at
        from public.app_site_analytics_sessions
        where started_at >= since
        order by started_at desc
        limit 30
      )
    ) merged
    order by sort_at desc
    limit 40
  ) u;

  return jsonb_build_object(
    'ok', true,
    'totals', totals,
    'series', coalesce(series, '[]'::jsonb),
    'devices', coalesce(devices, '{}'::jsonb),
    'sources', coalesce(sources, '{}'::jsonb),
    'top_pages', coalesce(top_pages, '[]'::jsonb),
    'top_events', coalesce(top_events, '[]'::jsonb),
    'browsers', coalesce(browsers, '[]'::jsonb),
    'timeline', coalesce(timeline, '[]'::jsonb),
    'days', days
  );
end;
$$;

