-- ============================================================================
-- 091_analytics_storage_cleanup.sql
-- Additive / safe to re-run.
-- Admin Analytics Storage stats + cleanup for site analytics tables only.
-- Does NOT touch user/domain ledger data.
-- ============================================================================

create or replace function public.app_admin_analytics_storage_stats()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  admin public.app_users := public.app_require_admin();
  sessions_n bigint := 0;
  pageviews_n bigint := 0;
  events_n bigint := 0;
  daily_n bigint := 0;
  visitor_days_n bigint := 0;
  path_daily_n bigint := 0;
  records_n bigint := 0;
  analytics_bytes bigint := 0;
  db_bytes bigint := 0;
  pct numeric := 0;
begin
  perform admin;

  begin
    select count(*) into sessions_n from public.app_site_analytics_sessions;
  exception when undefined_table then sessions_n := 0;
  end;
  begin
    select count(*) into pageviews_n from public.app_site_analytics_pageviews;
  exception when undefined_table then pageviews_n := 0;
  end;
  begin
    select count(*) into events_n from public.app_site_analytics_events;
  exception when undefined_table then events_n := 0;
  end;
  begin
    select count(*) into daily_n from public.app_site_analytics_daily;
  exception when undefined_table then daily_n := 0;
  end;
  begin
    select count(*) into visitor_days_n from public.app_site_analytics_visitor_days;
  exception when undefined_table then visitor_days_n := 0;
  end;
  begin
    select count(*) into path_daily_n from public.app_site_analytics_path_daily;
  exception when undefined_table then path_daily_n := 0;
  end;

  records_n := sessions_n + pageviews_n + events_n + daily_n + visitor_days_n + path_daily_n;

  begin
    analytics_bytes :=
      coalesce(pg_total_relation_size('public.app_site_analytics_sessions'::regclass), 0)
      + coalesce(pg_total_relation_size('public.app_site_analytics_pageviews'::regclass), 0)
      + coalesce(pg_total_relation_size('public.app_site_analytics_events'::regclass), 0)
      + coalesce(pg_total_relation_size('public.app_site_analytics_daily'::regclass), 0)
      + coalesce(pg_total_relation_size('public.app_site_analytics_visitor_days'::regclass), 0)
      + coalesce(pg_total_relation_size('public.app_site_analytics_path_daily'::regclass), 0);
  exception when others then
    analytics_bytes := 0;
  end;

  begin
    db_bytes := pg_database_size(current_database());
  exception when others then
    db_bytes := 0;
  end;

  if db_bytes > 0 then
    pct := round((analytics_bytes::numeric / db_bytes::numeric) * 100, 2);
  end if;

  return jsonb_build_object(
    'ok', true,
    'records', records_n,
    'bytes', analytics_bytes,
    'db_bytes', db_bytes,
    'percent', pct,
    'breakdown', jsonb_build_object(
      'sessions', sessions_n,
      'pageviews', pageviews_n,
      'events', events_n,
      'daily', daily_n,
      'visitor_days', visitor_days_n,
      'path_daily', path_daily_n
    ),
    'generated_at', now()
  );
end;
$$;

create or replace function public.app_admin_analytics_storage_cleanup(p_older_than_days int default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  admin public.app_users := public.app_require_admin();
  days int := p_older_than_days;
  cutoff timestamptz;
  cutoff_day date;
  del_pageviews bigint := 0;
  del_events bigint := 0;
  del_sessions bigint := 0;
  del_daily bigint := 0;
  del_visitor_days bigint := 0;
  del_path_daily bigint := 0;
  n bigint;
begin
  perform admin;

  -- null / 0 / negative => wipe all analytics tables only
  if days is null or days <= 0 then
    begin
      delete from public.app_site_analytics_pageviews;
      get diagnostics n = row_count; del_pageviews := n;
    exception when undefined_table then del_pageviews := 0;
    end;
    begin
      delete from public.app_site_analytics_events;
      get diagnostics n = row_count; del_events := n;
    exception when undefined_table then del_events := 0;
    end;
    begin
      delete from public.app_site_analytics_sessions;
      get diagnostics n = row_count; del_sessions := n;
    exception when undefined_table then del_sessions := 0;
    end;
    begin
      delete from public.app_site_analytics_daily;
      get diagnostics n = row_count; del_daily := n;
    exception when undefined_table then del_daily := 0;
    end;
    begin
      delete from public.app_site_analytics_visitor_days;
      get diagnostics n = row_count; del_visitor_days := n;
    exception when undefined_table then del_visitor_days := 0;
    end;
    begin
      delete from public.app_site_analytics_path_daily;
      get diagnostics n = row_count; del_path_daily := n;
    exception when undefined_table then del_path_daily := 0;
    end;
  else
    if days not in (3, 7, 14, 30) then
      raise exception 'Unsupported cleanup window. Use 3, 7, 14, 30, or all.';
    end if;
    cutoff := now() - make_interval(days => days);
    cutoff_day := (timezone('utc', now()))::date - days;

    begin
      delete from public.app_site_analytics_pageviews
      where viewed_at < cutoff;
      get diagnostics n = row_count; del_pageviews := n;
    exception when undefined_table then del_pageviews := 0;
    end;

    begin
      delete from public.app_site_analytics_events
      where created_at < cutoff;
      get diagnostics n = row_count; del_events := n;
    exception when undefined_table then del_events := 0;
    end;

    begin
      delete from public.app_site_analytics_sessions
      where started_at < cutoff;
      get diagnostics n = row_count; del_sessions := n;
    exception when undefined_table then del_sessions := 0;
    end;

    begin
      delete from public.app_site_analytics_daily
      where day < cutoff_day;
      get diagnostics n = row_count; del_daily := n;
    exception when undefined_table then del_daily := 0;
    end;

    begin
      delete from public.app_site_analytics_visitor_days
      where day < cutoff_day;
      get diagnostics n = row_count; del_visitor_days := n;
    exception when undefined_table then del_visitor_days := 0;
    end;

    begin
      delete from public.app_site_analytics_path_daily
      where day < cutoff_day;
      get diagnostics n = row_count; del_path_daily := n;
    exception when undefined_table then del_path_daily := 0;
    end;
  end if;

  return jsonb_build_object(
    'ok', true,
    'older_than_days', days,
    'deleted', jsonb_build_object(
      'sessions', del_sessions,
      'pageviews', del_pageviews,
      'events', del_events,
      'daily', del_daily,
      'visitor_days', del_visitor_days,
      'path_daily', del_path_daily,
      'total', del_sessions + del_pageviews + del_events + del_daily + del_visitor_days + del_path_daily
    ),
    'stats', public.app_admin_analytics_storage_stats()
  );
end;
$$;

grant execute on function public.app_admin_analytics_storage_stats() to anon, authenticated;
grant execute on function public.app_admin_analytics_storage_cleanup(int) to anon, authenticated;

