-- Safe numeric reader for the application's bracket metadata tags.
create or replace function public.app_meta_numeric(p_notes text, p_key text, p_default numeric default 0)
returns numeric
language sql
immutable
as $fn$
  select case
    when public.app_note_meta_value(coalesce(p_notes, ''), p_key)
         ~ '^[-+]?[0-9]+([.][0-9]+)?$'
      then public.app_note_meta_value(coalesce(p_notes, ''), p_key)::numeric
    else coalesce(p_default, 0)
  end
$fn$;

-- Expense activity with real offset pagination (the original RPC remains intact).
create or replace function public.app_list_my_expense_activity_page(
  p_from date default null,
  p_to date default null,
  p_search text default null,
  p_group_id text default null,
  p_limit int default 250,
  p_offset int default 0
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  caller_id uuid := public.current_app_user_id();
  data_owner uuid := public.app_data_owner_id();
  lim int := greatest(1, least(coalesce(p_limit, 250), 500));
  off_n int := greatest(0, coalesce(p_offset, 0));
  q text := lower(trim(coalesce(p_search, '')));
  gid uuid := null;
  payload jsonb := '[]'::jsonb;
  has_more boolean := false;
begin
  if caller_id is null or data_owner is null then raise exception 'Authentication required'; end if;
  if not public.app_has_permission('expenses', 'view') then raise exception 'Expenses access required'; end if;
  if nullif(trim(coalesce(p_group_id, '')), '') is not null then
    begin gid := trim(p_group_id)::uuid; exception when others then gid := null; end;
  end if;

  with activity as (
    select t.id, t.group_id::text as group_id, t.account_name, t.currency,
      t.amount, t.topup_date as activity_date, t.notes, t.created_at, t.updated_at,
      'TOPUP'::text as row_type, ''::text as item_name, ''::text as expense_type,
      a.account_type
    from public.expense_topups t
    join public.expense_accounts a on a.group_id = t.group_id and a.owner_id = data_owner
    where t.owner_id = data_owner and not coalesce(t.is_deleted, false)
      and not coalesce(a.is_deleted, false)
      and (gid is null or t.group_id = gid)
      and (p_from is null or t.topup_date >= p_from)
      and (p_to is null or t.topup_date <= p_to)
      and (q = '' or lower(coalesce(t.account_name, '')) like '%' || q || '%'
        or lower(coalesce(t.notes, '')) like '%' || q || '%'
        or lower(coalesce(a.account_type, '')) like '%' || q || '%'
        or 'topup' like '%' || q || '%')
    union all
    select e.id, e.group_id::text, e.account_name, e.currency,
      e.amount, e.expense_date, e.notes, e.created_at, e.updated_at,
      'EXPENSE'::text, coalesce(e.item_name, ''), coalesce(e.expense_type, 'Other'),
      a.account_type
    from public.expense_entries e
    join public.expense_accounts a on a.group_id = e.group_id and a.owner_id = data_owner
    where e.owner_id = data_owner and not coalesce(e.is_deleted, false)
      and not coalesce(a.is_deleted, false)
      and (gid is null or e.group_id = gid)
      and (p_from is null or e.expense_date >= p_from)
      and (p_to is null or e.expense_date <= p_to)
      and (q = '' or lower(coalesce(e.account_name, '')) like '%' || q || '%'
        or lower(coalesce(e.item_name, '')) like '%' || q || '%'
        or lower(coalesce(e.expense_type, '')) like '%' || q || '%'
        or lower(coalesce(e.notes, '')) like '%' || q || '%'
        or lower(coalesce(a.account_type, '')) like '%' || q || '%')
  ), page as (
    select * from activity
    order by activity_date desc nulls last, created_at desc, id desc
    offset off_n limit lim + 1
  ), numbered as (
    select page.*, row_number() over (order by activity_date desc nulls last, created_at desc, id desc) as page_row
    from page
  )
  select
    coalesce(jsonb_agg(to_jsonb(numbered) - 'page_row' order by activity_date desc nulls last, created_at desc, id desc)
      filter (where page_row <= lim), '[]'::jsonb),
    coalesce(bool_or(page_row > lim), false)
  into payload, has_more
  from numbered;

  return jsonb_build_object('ok', true, 'items', payload, 'has_more', has_more,
    'limit', lim, 'offset', off_n);
end
$fn$;

-- Inventory cards with real offset pagination and lightweight per-item totals.
create or replace function public.app_list_my_inventory_summaries_page(
  p_search text default null,
  p_brand text default null,
  p_item_type text default null,
  p_status text default null,
  p_limit int default 250,
  p_offset int default 0
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  caller_id uuid := public.current_app_user_id();
  data_owner uuid := public.app_data_owner_id();
  lim int := greatest(1, least(coalesce(p_limit, 250), 500));
  off_n int := greatest(0, coalesce(p_offset, 0));
  q text := lower(trim(coalesce(p_search, '')));
  brand_q text := lower(trim(coalesce(p_brand, '')));
  type_q text := lower(trim(coalesce(p_item_type, '')));
  status_q text := lower(trim(coalesce(p_status, '')));
  payload jsonb := '[]'::jsonb;
  has_more boolean := false;
begin
  if caller_id is null or data_owner is null then raise exception 'Authentication required'; end if;
  if not public.app_has_permission('inventory', 'view') then raise exception 'Inventory access required'; end if;

  with item_rows as (
    select gi.id, gi.group_id::text as group_id, gi.item_name, gi.currency,
      gi.unit_actual_price, gi.bought_qty, gi.total_actual_price, gi.bought_date,
      gi.item_code, gi.notes, gi.brand, gi.variant_label, gi.brand_id, gi.variant_id,
      coalesce(nullif(gi.product_line, ''), public.app_note_meta_value(gi.notes, 'PLINE'), '') as product_line,
      gi.product_line_id,
      coalesce(nullif(gi.category_slug, ''), public.app_note_meta_value(gi.notes, 'CSLUG'), '') as category_slug,
      coalesce(nullif(gi.item_category, ''), public.app_note_meta_value(gi.notes, 'UCAT'), 'count') as item_category,
      coalesce(nullif(gi.quantity_unit, ''), public.app_note_meta_value(gi.notes, 'UOM'), 'item') as quantity_unit,
      coalesce(nullif(gi.sell_by, ''), nullif(public.app_note_meta_value(gi.notes, 'SELLBY'), '')) as sell_by,
      coalesce(gi.bottle_size_qty, public.app_meta_numeric(gi.notes, 'BSIZE', null)) as bottle_size_qty,
      coalesce(nullif(gi.bottle_size_unit, ''), nullif(public.app_note_meta_value(gi.notes, 'BUNIT'), '')) as bottle_size_unit,
      coalesce(nullif(public.app_note_meta_value(gi.notes, 'ITYPE'), ''), 'General') as item_type,
      coalesce(nullif(public.app_note_meta_value(gi.notes, 'IDESC'), ''), '') as item_description,
      public.app_meta_numeric(gi.notes, 'USP', 0) as unit_sold_price,
      coalesce(s.sold_qty, 0)::numeric as sold_qty,
      coalesce(s.sold_total, 0)::numeric as sold_total,
      greatest(gi.bought_qty - coalesce(s.sold_qty, 0), 0)::numeric as remaining_qty,
      case when greatest(gi.bought_qty - coalesce(s.sold_qty, 0), 0) <= 0.00000001 then 'Sold'
        when coalesce(s.sold_qty, 0) > 0 then 'Partial' else 'In Stock' end as stock_status,
      gi.created_at, gi.updated_at
    from public.goods_items gi
    left join lateral (
      select coalesce(sum(gs.sold_qty), 0) sold_qty, coalesce(sum(gs.total_sold_price), 0) sold_total
      from public.goods_sales gs
      where gs.owner_id = data_owner and gs.group_id = gi.group_id and not coalesce(gs.is_deleted, false)
    ) s on true
    where gi.owner_id = data_owner and not coalesce(gi.is_deleted, false)
      and (q = '' or lower(coalesce(gi.item_name, '')) like '%' || q || '%'
        or lower(coalesce(gi.brand, '')) like '%' || q || '%'
        or lower(coalesce(gi.variant_label, '')) like '%' || q || '%'
        or lower(coalesce(gi.product_line, '')) like '%' || q || '%'
        or lower(coalesce(gi.item_code, '')) like '%' || q || '%'
        or lower(coalesce(gi.notes, '')) like '%' || q || '%')
      and (brand_q = '' or brand_q = 'all' or lower(coalesce(gi.brand, '')) = brand_q)
      and (type_q = '' or type_q = 'all'
        or lower(coalesce(public.app_note_meta_value(gi.notes, 'ITYPE'), 'general')) = type_q)
      and (status_q = '' or status_q = 'all'
        or (status_q in ('open','in stock','instock') and greatest(gi.bought_qty - coalesce(s.sold_qty,0),0) > 0.00000001)
        or (status_q in ('closed','sold') and greatest(gi.bought_qty - coalesce(s.sold_qty,0),0) <= 0.00000001)
        or (status_q in ('lowstock','low stock') and gi.bought_qty > 0
          and greatest(gi.bought_qty - coalesce(s.sold_qty,0),0) > 0.00000001
          and greatest(gi.bought_qty - coalesce(s.sold_qty,0),0) / gi.bought_qty <= 0.15))
  ), page as (
    select * from item_rows order by bought_date desc nulls last, item_name, id
    offset off_n limit lim + 1
  ), numbered as (
    select page.*, row_number() over (order by bought_date desc nulls last, item_name, id) page_row from page
  )
  select coalesce(jsonb_agg(to_jsonb(numbered) - 'page_row' order by bought_date desc nulls last, item_name, id)
      filter (where page_row <= lim), '[]'::jsonb),
    coalesce(bool_or(page_row > lim), false)
  into payload, has_more from numbered;

  return jsonb_build_object('ok', true, 'items', payload, 'has_more', has_more,
    'limit', lim, 'offset', off_n);
end
$fn$;

-- Asset cards use one row per asset plus six numeric aggregates, never history.
create or replace function public.app_list_my_asset_summaries(p_limit int default 5000)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  caller_id uuid := public.current_app_user_id();
  data_owner uuid := public.app_data_owner_id();
  lim int := greatest(1, least(coalesce(p_limit, 5000), 5000));
  payload jsonb := '[]'::jsonb;
begin
  if caller_id is null or data_owner is null then raise exception 'Authentication required'; end if;
  if not public.app_can_use_assets() then raise exception 'Asset Management access required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'asset', to_jsonb(x) - 'maintenance' - 'repair' - 'operating' - 'other_expense' - 'additional_investment' - 'revenue',
    'summary', jsonb_build_object(
      'maintenance', x.maintenance, 'repair', x.repair, 'operating', x.operating,
      'other_expense', x.other_expense, 'additional_investment', x.additional_investment,
      'revenue', x.revenue
    )) order by x.purchase_date desc, x.name, x.id), '[]'::jsonb)
  into payload
  from (
    select a.*,
      coalesce(sum(abs(t.amount)) filter (where t.tx_type = 'maintenance'), 0) maintenance,
      coalesce(sum(abs(t.amount)) filter (where t.tx_type = 'repair'), 0) repair,
      coalesce(sum(abs(t.amount)) filter (where t.tx_type = 'operating'), 0) operating,
      coalesce(sum(abs(t.amount)) filter (where t.tx_type = 'other_expense'), 0) other_expense,
      coalesce(sum(abs(t.amount)) filter (where t.tx_type = 'additional_investment'), 0) additional_investment,
      coalesce(sum(abs(t.amount)) filter (where t.tx_type = 'revenue'), 0) revenue
    from public.app_assets a
    left join public.app_asset_transactions t on t.asset_id = a.id and t.owner_id = data_owner
      and not coalesce(t.is_deleted, false)
    where a.owner_id = data_owner and not coalesce(a.is_deleted, false)
    group by a.id
    order by a.purchase_date desc, a.name, a.id
    limit lim
  ) x;
  return jsonb_build_object('ok', true, 'items', payload);
end
$fn$;

-- Exact plan status helper used by the Dashboard aggregation. It follows the
-- application's FIFO payment behavior and honours explicit IALLOC allocations.
create or replace function public.app_installment_plan_status(p_group_id uuid, p_owner_id uuid)
returns text
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  plan public.installment_plans%rowtype;
  pay record;
  slots numeric[];
  slot_count int;
  base_amount numeric;
  last_amount numeric;
  down_amount numeric;
  financed numeric;
  start_on date;
  remaining numeric;
  allocation text;
  part text;
  part_index int;
  part_amount numeric;
  i int;
  take_amount numeric;
  paid_any numeric := 0;
  overdue_any boolean := false;
begin
  select * into plan from public.installment_plans
  where group_id = p_group_id and owner_id = p_owner_id and not coalesce(is_deleted, false);
  if not found then return 'Open'; end if;
  slot_count := greatest(1, coalesce(plan.installment_count, public.app_meta_numeric(plan.notes, 'ICNT', 1)::int));
  down_amount := greatest(0, least(plan.principal_amount,
    coalesce(plan.down_payment_amount, public.app_meta_numeric(plan.notes, 'IDOWN', 0))));
  financed := greatest(0, coalesce(plan.financed_amount, plan.principal_amount - down_amount));
  base_amount := coalesce(nullif(plan.installment_amount, 0), financed / slot_count);
  last_amount := coalesce(nullif(public.app_meta_numeric(plan.notes, 'ILAST', 0), 0),
    greatest(0, financed - base_amount * (slot_count - 1)));
  start_on := coalesce(nullif((plan.meta->>'scheduleStart'), '')::date,
    nullif(public.app_note_meta_value(plan.notes, 'ISTART'), '')::date, plan.loan_date);
  slots := array_fill(base_amount, array[slot_count]);
  slots[slot_count] := last_amount;

  for pay in
    select * from public.installment_payments
    where group_id = p_group_id and owner_id = p_owner_id and not coalesce(is_deleted, false)
    order by payment_date, created_at, id
  loop
    if lower(coalesce(pay.meta->>'paymentType', public.app_note_meta_value(pay.notes, 'IPTYPE'), '')) = 'down_payment' then
      continue;
    end if;
    remaining := greatest(0, pay.payment_amount);
    paid_any := paid_any + remaining;
    allocation := coalesce(pay.meta->>'allocation', public.app_note_meta_value(pay.notes, 'IALLOC'), '');
    if allocation <> '' then
      foreach part in array regexp_split_to_array(allocation, '[|]') loop
        begin
          part_index := split_part(part, ':', 1)::int;
          part_amount := split_part(part, ':', 2)::numeric;
        exception when others then
          part_index := 0; part_amount := 0;
        end;
        if part_index between 1 and slot_count and remaining > 0 and part_amount > 0 then
          take_amount := least(slots[part_index], part_amount, remaining);
          slots[part_index] := greatest(0, slots[part_index] - take_amount);
          remaining := greatest(0, remaining - take_amount);
        end if;
      end loop;
    end if;
    if remaining > 0 then
      for i in 1..slot_count loop
        exit when remaining <= 0.00000001;
        take_amount := least(slots[i], remaining);
        slots[i] := greatest(0, slots[i] - take_amount);
        remaining := greatest(0, remaining - take_amount);
      end loop;
    end if;
  end loop;

  if (select coalesce(sum(v), 0) from unnest(slots) v) <= 0.00000001 then return 'Closed'; end if;
  for i in 1..slot_count loop
    if (start_on + make_interval(months => i - 1))::date < current_date and slots[i] > 0.00000001 then
      overdue_any := true; exit;
    end if;
  end loop;
  if overdue_any then return 'Overdue'; end if;
  if paid_any > 0 or down_amount > 0 then return 'Partial'; end if;
  return 'Open';
end
$fn$;

-- One authoritative, lightweight response for all Dashboard cards and charts.
create or replace function public.app_get_my_dashboard_summary()
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  caller_id uuid := public.current_app_user_id();
  data_owner uuid := public.app_data_owner_id();
  expense_rows jsonb := '[]'::jsonb; expense_months jsonb := '[]'::jsonb;
  inventory_rows jsonb := '[]'::jsonb; inventory_months jsonb := '[]'::jsonb;
  loan_rows jsonb := '[]'::jsonb; loan_months jsonb := '[]'::jsonb;
  installment_rows jsonb := '[]'::jsonb; installment_months jsonb := '[]'::jsonb;
  asset_rows jsonb := '[]'::jsonb; asset_months jsonb := '[]'::jsonb; top_assets jsonb := '[]'::jsonb;
begin
  if caller_id is null or data_owner is null then raise exception 'Authentication required'; end if;

  if public.app_has_permission('expenses', 'view') then
    with topups as (
      select group_id, sum(amount) amount from public.expense_topups
      where owner_id = data_owner and not coalesce(is_deleted, false) group by group_id
    ), spends as (
      select group_id, sum(amount) amount from public.expense_entries
      where owner_id = data_owner and not coalesce(is_deleted, false) group by group_id
    ), wallet as (
      select a.currency, a.group_id, a.opening_balance,
        coalesce(t.amount, 0) topup_total, coalesce(s.amount, 0) spend_total,
        a.opening_balance + coalesce(t.amount, 0) - coalesce(s.amount, 0) balance
      from public.expense_accounts a left join topups t using(group_id) left join spends s using(group_id)
      where a.owner_id = data_owner and not coalesce(a.is_deleted, false)
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency), '[]'::jsonb) into expense_rows
    from (select currency, count(*) wallets, count(*) filter(where balance > 0) active_wallets,
      sum(opening_balance) opening_total, sum(topup_total) topup_total,
      sum(spend_total) spend_total, sum(balance) balance_total from wallet group by currency) x;

    with flow as (
      select currency, to_char(account_date, 'YYYY-MM') AS "month", opening_balance topup, 0::numeric spend
      from public.expense_accounts where owner_id = data_owner and not coalesce(is_deleted, false)
      union all select currency, to_char(topup_date, 'YYYY-MM'), amount, 0
      from public.expense_topups where owner_id = data_owner and not coalesce(is_deleted, false)
      union all select currency, to_char(expense_date, 'YYYY-MM'), 0, amount
      from public.expense_entries where owner_id = data_owner and not coalesce(is_deleted, false)
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency, x."month"), '[]'::jsonb) into expense_months
    from (select currency, "month", sum(topup) topup, sum(spend) spend from flow group by currency, "month") x;
  end if;

  if public.app_has_permission('inventory', 'view') then
    with purchase_events as (
      select group_id, sum(coalesce(qty, public.app_meta_numeric(notes, 'BQTY', 0))) qty,
        sum(coalesce(amount, 0)) gross, sum(coalesce(nullif(public.app_meta_numeric(notes, 'NET', 0), 0), amount, 0)) net
      from public.goods_events where owner_id = data_owner and not coalesce(is_deleted, false)
        and upper(coalesce(tx_type, '')) = 'PURCHASE' group by group_id
    ), sales as (
      select group_id, sum(sold_qty) sold_qty, sum(total_sold_price) sold_total,
        sum(coalesce(nullif(public.app_meta_numeric(notes, 'NET', 0), 0), total_sold_price)) sold_net,
        sum(least(total_sold_price, greatest(0, case
          when public.app_note_meta_value(notes, 'PAID') <> '' then public.app_meta_numeric(notes, 'PAID', 0)
          when public.app_note_meta_value(notes, 'BAL') <> '' then total_sold_price - public.app_meta_numeric(notes, 'BAL', 0)
          else total_sold_price end))) initial_paid,
        max(sold_date) latest_sold_date
      from public.goods_sales where owner_id = data_owner and not coalesce(is_deleted, false) group by group_id
    ), settlements as (
      select group_id, sum(coalesce(amount, 0)) paid
      from public.goods_events where owner_id = data_owner and not coalesce(is_deleted, false)
        and upper(coalesce(tx_type, '')) = 'SETTLEMENT' group by group_id
    ), items as (
      select gi.currency, gi.group_id,
        gi.bought_qty + coalesce(pe.qty, 0) bought_qty,
        gi.total_actual_price + coalesce(pe.gross, 0) purchase_total,
        case when gi.bought_qty + coalesce(pe.qty, 0) > 0
          then (coalesce(nullif(public.app_meta_numeric(gi.notes, 'NET', 0), 0), gi.total_actual_price) + coalesce(pe.net, 0))
            / (gi.bought_qty + coalesce(pe.qty, 0)) else 0 end unit_cost,
        coalesce(s.sold_qty, 0) sold_qty, coalesce(s.sold_total, 0) sold_total,
        coalesce(s.sold_net, 0) sold_net, coalesce(s.initial_paid, 0) + coalesce(st.paid, 0) raw_paid,
        s.latest_sold_date
      from public.goods_items gi left join purchase_events pe using(group_id)
      left join sales s using(group_id) left join settlements st using(group_id)
      where gi.owner_id = data_owner and not coalesce(gi.is_deleted, false)
    ), final as (
      select *, greatest(bought_qty - sold_qty, 0) remaining_qty,
        least(sold_total, raw_paid) paid_total,
        sold_net - unit_cost * sold_qty profit_loss
      from items
    ), customers as (
      select currency, count(distinct customer_name) customer_count from (
        select currency, nullif(trim(public.app_note_meta_value(notes, 'CUST')), '') customer_name
        from public.goods_sales where owner_id = data_owner and not coalesce(is_deleted, false)
        union all
        select currency, nullif(trim(public.app_note_meta_value(notes, 'CUST')), '')
        from public.goods_events where owner_id = data_owner and not coalesce(is_deleted, false)
          and upper(coalesce(tx_type, '')) = 'CUSTOMER'
      ) c where customer_name is not null group by currency
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency), '[]'::jsonb) into inventory_rows
    from (select f.currency, count(*) items,
      count(*) filter(where remaining_qty > 0.00000001 and not (bought_qty > 0 and remaining_qty / bought_qty <= 0.15)) in_stock,
      count(*) filter(where remaining_qty > 0.00000001 and bought_qty > 0 and remaining_qty / bought_qty <= 0.15) low_stock,
      count(*) filter(where remaining_qty <= 0.00000001) sold_out,
      trim(to_char(sum(remaining_qty), 'FM999999999999990.########')) stock_qty_label,
      sum(unit_cost * remaining_qty) stock_value, sum(purchase_total) purchase_total,
      sum(sold_total) sales_total, sum(paid_total) paid_total,
      sum(greatest(profit_loss, 0)) profit_total, sum(abs(least(profit_loss, 0))) loss_total,
      sum(greatest(sold_total - paid_total, 0)) outstanding_total,
      count(*) filter(where sold_total - paid_total > 0.00000001) outstanding_count,
      coalesce(max(c.customer_count), 0) customer_count
      from final f left join customers c using(currency) group by f.currency) x;

    with purchase_flow as (
      select currency, to_char(bought_date, 'YYYY-MM') AS "month", total_actual_price purchase, 0::numeric sales, 0::numeric profit
      from public.goods_items where owner_id = data_owner and not coalesce(is_deleted, false)
      union all select currency, to_char(event_date, 'YYYY-MM'), coalesce(amount, 0), 0, 0
      from public.goods_events where owner_id = data_owner and not coalesce(is_deleted, false)
        and upper(coalesce(tx_type, '')) = 'PURCHASE'
      union all select currency, to_char(sold_date, 'YYYY-MM'), 0, total_sold_price,
        coalesce(nullif(public.app_meta_numeric(notes, 'NET', 0), 0), total_sold_price)
      from public.goods_sales where owner_id = data_owner and not coalesce(is_deleted, false)
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency, x."month"), '[]'::jsonb) into inventory_months
    from (select currency, "month", sum(purchase) purchase, sum(sales) sales,
      sum(profit) - sum(purchase) profit from purchase_flow group by currency, "month") x;
  end if;

  if public.app_has_permission('loans', 'view') then
    with principals as (
      select direction, person_name, currency, sum(principal_amount) principal
      from public.loans where owner_id = data_owner and not coalesce(is_deleted, false)
      group by direction, person_name, currency
    ), payments as (
      select l.direction, l.person_name, l.currency, sum(p.payment_amount) paid
      from public.loans l join public.loan_payments p on p.group_id = l.group_id and p.owner_id = data_owner
      where l.owner_id = data_owner and not coalesce(l.is_deleted, false) and not coalesce(p.is_deleted, false)
      group by l.direction, l.person_name, l.currency
    ), people as (
      select p.*, coalesce(y.paid, 0) paid, greatest(p.principal - coalesce(y.paid, 0), 0) remaining,
        case when p.principal - coalesce(y.paid, 0) <= 0.00000001 then 'Closed'
          when coalesce(y.paid, 0) > 0 then 'Partial' else 'Open' end status
      from principals p left join payments y using(direction, person_name, currency)
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency), '[]'::jsonb) into loan_rows
    from (select currency, count(*) people,
      count(*) filter(where direction='given') given_count, count(*) filter(where direction='taken') taken_count,
      sum(principal) filter(where direction='given') given_principal,
      sum(paid) filter(where direction='given') given_paid,
      sum(remaining) filter(where direction='given') given_open,
      sum(principal) filter(where direction='taken') taken_principal,
      sum(paid) filter(where direction='taken') taken_paid,
      sum(remaining) filter(where direction='taken') taken_open,
      count(*) filter(where status='Open') status_open,
      count(*) filter(where status='Partial') status_partial,
      count(*) filter(where status='Closed') status_closed
      from people group by currency) x;

    with flow as (
      select currency, to_char(loan_date, 'YYYY-MM') AS "month",
        case when direction='given' then principal_amount else 0 end "givenOut",
        0::numeric "givenIn", case when direction='taken' then principal_amount else 0 end "takenIn", 0::numeric "takenOut"
      from public.loans where owner_id=data_owner and not coalesce(is_deleted,false)
      union all select l.currency, to_char(p.payment_date, 'YYYY-MM'), 0,
        case when l.direction='given' then p.payment_amount else 0 end, 0,
        case when l.direction='taken' then p.payment_amount else 0 end
      from public.loan_payments p join public.loans l on l.group_id=p.group_id and l.owner_id=data_owner
      where p.owner_id=data_owner and not coalesce(p.is_deleted,false) and not coalesce(l.is_deleted,false)
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency,x."month"),'[]'::jsonb) into loan_months
    from (select currency,"month",sum("givenOut") "givenOut",sum("givenIn") "givenIn",
      sum("takenIn") "takenIn",sum("takenOut") "takenOut" from flow group by currency,"month") x;
  end if;

  if public.app_has_permission('installments', 'view') then
    with paid as (
      select group_id, sum(payment_amount) paid from public.installment_payments
      where owner_id=data_owner and not coalesce(is_deleted,false) group by group_id
    ), plans as (
      select p.currency,p.group_id,p.principal_amount principal,coalesce(y.paid,0) paid,
        greatest(p.principal_amount-coalesce(y.paid,0),0) remaining,
        public.app_installment_plan_status(p.group_id,data_owner) status
      from public.installment_plans p left join paid y using(group_id)
      where p.owner_id=data_owner and not coalesce(p.is_deleted,false)
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency),'[]'::jsonb) into installment_rows
    from (select currency,count(*) plans,
      count(*) filter(where status in ('Open','Partial')) active,
      count(*) filter(where status='Overdue') overdue,
      count(*) filter(where status='Closed') completed,
      sum(principal) principal,sum(paid) paid,sum(remaining) remaining,
      count(*) filter(where status='Open') status_open,
      count(*) filter(where status='Partial') status_partial,
      count(*) filter(where status='Overdue') status_overdue,
      count(*) filter(where status='Closed') status_closed from plans group by currency) x;

    with flow as (
      select currency,to_char(loan_date,'YYYY-MM') AS "month",principal_amount principal,0::numeric paid
      from public.installment_plans where owner_id=data_owner and not coalesce(is_deleted,false)
      union all select currency,to_char(payment_date,'YYYY-MM'),0,payment_amount
      from public.installment_payments where owner_id=data_owner and not coalesce(is_deleted,false)
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency,x."month"),'[]'::jsonb) into installment_months
    from (select currency,"month",sum(principal) principal,sum(paid) paid from flow group by currency,"month") x;
  end if;

  if public.app_can_use_assets() then
    with tx as (
      select asset_id,
        coalesce(sum(abs(amount)) filter(where tx_type='maintenance'),0) maintenance,
        coalesce(sum(abs(amount)) filter(where tx_type='repair'),0) repair,
        coalesce(sum(abs(amount)) filter(where tx_type='operating'),0) operating,
        coalesce(sum(abs(amount)) filter(where tx_type='other_expense'),0) other_expense,
        coalesce(sum(abs(amount)) filter(where tx_type='additional_investment'),0) additional_investment,
        coalesce(sum(abs(amount)) filter(where tx_type='revenue'),0) revenue
      from public.app_asset_transactions where owner_id=data_owner and not coalesce(is_deleted,false) group by asset_id
    ), asset_calc as (
      select a.*,coalesce(t.maintenance,0) maintenance,coalesce(t.repair,0) repair,
        coalesce(t.operating,0) operating,coalesce(t.other_expense,0) other_expense,
        coalesce(t.additional_investment,0) additional_investment,coalesce(t.revenue,0) revenue,
        coalesce(t.maintenance,0)+coalesce(t.repair,0)+coalesce(t.operating,0)+coalesce(t.other_expense,0)+
          coalesce(t.additional_investment,0)+case when a.status in ('sold','disposed') then abs(coalesce(a.sale_costs,0)) else 0 end invested_spent,
        case when a.status='sold' then abs(coalesce(a.sale_price,0)) else 0 end sale_value
      from public.app_assets a left join tx t on t.asset_id=a.id
      where a.owner_id=data_owner and not coalesce(a.is_deleted,false)
    ), dep as (
      select currency,
        sum(greatest(0,purchase_price-least(salvage_value,purchase_price)) /
          greatest(1,round(useful_life_years*12)) * least(greatest(1,round(useful_life_years*12)),
          greatest(0,(extract(year from age(date_trunc('month',case when status in ('sold','disposed') and disposal_date is not null then least(current_date,disposal_date) else current_date end),date_trunc('month',purchase_date)))::int*12 +
          extract(month from age(date_trunc('month',case when status in ('sold','disposed') and disposal_date is not null then least(current_date,disposal_date) else current_date end),date_trunc('month',purchase_date)))::int+1)))) accumulated,
        sum(purchase_price) purchase
      from public.depreciation_assets where owner_id=data_owner and not coalesce(is_deleted,false) group by currency
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency),'[]'::jsonb) into asset_rows
    from (select a.currency,count(*) assets,count(*) filter(where a.status='active') active,
      count(*) filter(where a.status='sold') sold,count(*) filter(where a.status='disposed') disposed,
      sum(a.purchase_price) purchase,sum(a.invested_spent) invested,sum(a.revenue) revenue,
      sum(a.sale_value) sale,sum(a.revenue+a.sale_value-a.purchase_price-a.invested_spent) net,
      sum(a.maintenance) maintenance,sum(a.repair) repair,sum(a.operating) operating,
      sum(a.other_expense) other_expense,sum(a.additional_investment) additional_investment,
      sum(case when a.status in ('sold','disposed') then abs(coalesce(a.sale_costs,0)) else 0 end) sale_costs,
      greatest(0,coalesce(max(d.purchase),0)-coalesce(max(d.accumulated),0)) depreciation_book_value,
      coalesce(max(d.accumulated),0) accumulated_depreciation
      from asset_calc a left join dep d using(currency) group by a.currency) x;

    with flow as (
      select a.currency,to_char(t.tx_date,'YYYY-MM') AS "month",
        case when t.tx_type='revenue' then abs(t.amount) else 0 end revenue,
        case when t.tx_type<>'revenue' then abs(t.amount) else 0 end expense
      from public.app_asset_transactions t join public.app_assets a on a.id=t.asset_id and a.owner_id=data_owner
      where t.owner_id=data_owner and not coalesce(t.is_deleted,false) and not coalesce(a.is_deleted,false)
    )
    select coalesce(jsonb_agg(to_jsonb(x) order by x.currency,x."month"),'[]'::jsonb) into asset_months
    from (select currency,"month",sum(revenue) revenue,sum(expense) expense from flow group by currency,"month") x;

    with tx as (
      select asset_id,sum(abs(amount)) filter(where tx_type='revenue') revenue,
        sum(abs(amount)) filter(where tx_type<>'revenue') expense
      from public.app_asset_transactions where owner_id=data_owner and not coalesce(is_deleted,false) group by asset_id
    ), ranked as (
      select a.id,a.name,a.asset_type,a.asset_type_other,a.status,a.currency,
        coalesce(t.expense,0)+case when a.status in ('sold','disposed') then abs(coalesce(a.sale_costs,0)) else 0 end invested_spent,
        coalesce(t.revenue,0) revenue,
        coalesce(t.revenue,0)+case when a.status='sold' then abs(coalesce(a.sale_price,0)) else 0 end-
          abs(a.purchase_price)-coalesce(t.expense,0)-case when a.status in ('sold','disposed') then abs(coalesce(a.sale_costs,0)) else 0 end net
      from public.app_assets a left join tx t on t.asset_id=a.id
      where a.owner_id=data_owner and not coalesce(a.is_deleted,false)
      order by abs(coalesce(t.revenue,0)-abs(a.purchase_price)-coalesce(t.expense,0)) desc limit 12
    )
    select coalesce(jsonb_agg(to_jsonb(ranked) order by abs(net) desc),'[]'::jsonb) into top_assets from ranked;
  end if;

  return jsonb_build_object('ok',true,'generated_at',now(),'sections',jsonb_build_object(
    'expenses',jsonb_build_object('rows',expense_rows,'months',expense_months),
    'inventory',jsonb_build_object('rows',inventory_rows,'months',inventory_months),
    'loans',jsonb_build_object('rows',loan_rows,'months',loan_months),
    'installments',jsonb_build_object('rows',installment_rows,'months',installment_months),
    'assets',jsonb_build_object('rows',asset_rows,'months',asset_months,'top_assets',top_assets)
  ));
end
$fn$;

grant execute on function public.app_meta_numeric(text,text,numeric) to anon, authenticated, service_role;
grant execute on function public.app_list_my_expense_activity_page(date,date,text,text,int,int) to anon, authenticated, service_role;
grant execute on function public.app_list_my_inventory_summaries_page(text,text,text,text,int,int) to anon, authenticated, service_role;
grant execute on function public.app_list_my_asset_summaries(int) to anon, authenticated, service_role;
grant execute on function public.app_installment_plan_status(uuid,uuid) to anon, authenticated, service_role;
grant execute on function public.app_get_my_dashboard_summary() to anon, authenticated, service_role;

