-- ############################################################################
-- BEGIN migrations/093_security_hardening_session_login_rpc.sql
-- ############################################################################

-- ============================================================================
-- 093_security_hardening_session_login_rpc.sql
-- Security hardening for custom sessions and authentication RPC boundaries.
--
-- LIVE-DATABASE SAFETY
--   * Additive / forward-only. Safe to re-run.
--   * Does NOT delete, truncate, purge, rename, or rewrite existing user data.
--   * Does NOT revoke existing legitimate sessions.
--   * Does NOT change wallets, expenses, inventory, loans, assets, messages,
--     notes, team data, settings, passwords, Smart PINs, or access plans.
--   * Creates one isolated security-metadata table for failed-login throttling.
--   * Existing login / trial signup / Remember Me UX remains unchanged.
--
-- Fixes / hardening
--   1) Prevent direct app_create_session RPC use by anon/authenticated callers.
--   2) Add an internal transaction-local authorization guard to session minting.
--   3) Add server-side failed-login throttling without storing raw IP/username.
--   4) Stop app_user_public_profile from returning the raw Smart PIN hash.
--   5) Revoke unnecessary direct access to internal SECURITY DEFINER helpers.
--   6) Stop future Admin Security Key updates from storing a reversible key copy.
--      Existing rows are intentionally left untouched to obey no-data-change.
-- ============================================================================

create extension if not exists pgcrypto with schema extensions;

-- ── 1) Request/network fingerprint helper (hash only; no raw IP persistence) ─
create or replace function public.app_request_network_fingerprint(p_fallback_ip text default null)
returns text
language plpgsql
stable
security definer
set search_path = public, extensions
as $$
declare
  raw_headers text;
  headers jsonb := '{}'::jsonb;
  candidate text;
begin
  begin
    raw_headers := nullif(current_setting('request.headers', true), '');
    if raw_headers is not null then
      headers := raw_headers::jsonb;
    end if;
  exception when others then
    headers := '{}'::jsonb;
  end;

  candidate := nullif(trim(coalesce(
    nullif(headers->>'cf-connecting-ip', ''),
    nullif(split_part(coalesce(headers->>'x-forwarded-for', ''), ',', 1), ''),
    nullif(headers->>'x-real-ip', ''),
    nullif(p_fallback_ip, ''),
    ''
  )), '');

  if candidate is null then
    return null;
  end if;

  return encode(extensions.digest(lower(candidate), 'sha256'), 'hex');
end;
$$;

revoke all on function public.app_request_network_fingerprint(text)
  from public, anon, authenticated;

-- ── 2) Login throttle state (security metadata only) ────────────────────────
create table if not exists public.app_login_throttle (
  scope_key text primary key,
  scope_type text not null check (scope_type in ('account', 'network')),
  fail_count integer not null default 0 check (fail_count >= 0),
  window_started_at timestamptz not null default now(),
  locked_until timestamptz,
  updated_at timestamptz not null default now()
);

create index if not exists app_login_throttle_updated_idx
  on public.app_login_throttle (updated_at desc);

alter table public.app_login_throttle enable row level security;
revoke all on table public.app_login_throttle from public, anon, authenticated;

create or replace function public.app_login_throttle_scope_key(p_scope text, p_value text)
returns text
language sql
immutable
set search_path = public, extensions
as $$
  select lower(trim(coalesce(p_scope, ''))) || ':' ||
         encode(extensions.digest(coalesce(p_value, ''), 'sha256'), 'hex');
$$;

create or replace function public.app_login_throttle_is_locked(p_scope_key text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((
    select t.locked_until > now()
    from public.app_login_throttle t
    where t.scope_key = p_scope_key
  ), false);
$$;

create or replace function public.app_login_throttle_register_failure(
  p_scope_key text,
  p_scope_type text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  row_rec public.app_login_throttle;
  threshold_count integer;
  window_length interval;
  lock_length interval;
  next_count integer;
begin
  if p_scope_key is null or trim(p_scope_key) = '' then
    return;
  end if;
  if p_scope_type not in ('account', 'network') then
    return;
  end if;

  -- Account threshold protects legacy/weak credentials while remaining generous
  -- enough that ordinary users do not encounter the limiter. Network threshold
  -- is higher to avoid penalising shared offices / NAT connections.
  if p_scope_type = 'account' then
    threshold_count := 20;
    window_length := interval '15 minutes';
    lock_length := interval '15 minutes';
  else
    threshold_count := 30;
    window_length := interval '15 minutes';
    lock_length := interval '15 minutes';
  end if;

  insert into public.app_login_throttle (
    scope_key, scope_type, fail_count, window_started_at, locked_until, updated_at
  ) values (
    p_scope_key, p_scope_type, 0, now(), null, now()
  )
  on conflict (scope_key) do nothing;

  select * into row_rec
  from public.app_login_throttle
  where scope_key = p_scope_key
  for update;

  if row_rec.locked_until is not null and row_rec.locked_until > now() then
    update public.app_login_throttle
    set updated_at = now()
    where scope_key = p_scope_key;
    return;
  end if;

  if row_rec.window_started_at < now() - window_length then
    next_count := 1;
    update public.app_login_throttle
    set fail_count = next_count,
        window_started_at = now(),
        locked_until = null,
        updated_at = now()
    where scope_key = p_scope_key;
  else
    next_count := coalesce(row_rec.fail_count, 0) + 1;
    update public.app_login_throttle
    set fail_count = next_count,
        locked_until = case
          when next_count >= threshold_count then now() + lock_length
          else null
        end,
        updated_at = now()
    where scope_key = p_scope_key;
  end if;
end;
$$;

create or replace function public.app_login_throttle_reset(p_scope_key text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_scope_key is null or trim(p_scope_key) = '' then
    return;
  end if;

  -- Reset in place; intentionally no DELETE so this migration/workflow never
  -- removes existing records.
  update public.app_login_throttle
  set fail_count = 0,
      window_started_at = now(),
      locked_until = null,
      updated_at = now()
  where scope_key = p_scope_key;
end;
$$;

revoke all on function public.app_login_throttle_scope_key(text, text)
  from public, anon, authenticated;
revoke all on function public.app_login_throttle_is_locked(text)
  from public, anon, authenticated;
revoke all on function public.app_login_throttle_register_failure(text, text)
  from public, anon, authenticated;
revoke all on function public.app_login_throttle_reset(text)
  from public, anon, authenticated;

-- ── 3) Session minting: internal authorization guard + least privilege ───────
create or replace function public.app_session_create_authorized()
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  flag text;
  jwt_role text;
  claims jsonb := '{}'::jsonb;
begin
  begin
    flag := nullif(current_setting('app.session_create_authorized', true), '');
  exception when others then
    flag := null;
  end;

  if flag = '1' then
    return true;
  end if;

  -- Preserve trusted service-role maintenance capability without exposing the
  -- function to browser anon/authenticated roles.
  begin
    jwt_role := nullif(current_setting('request.jwt.claim.role', true), '');
  exception when others then
    jwt_role := null;
  end;

  if jwt_role = 'service_role' then
    return true;
  end if;

  begin
    claims := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  exception when others then
    claims := '{}'::jsonb;
  end;

  return coalesce(claims->>'role', '') = 'service_role';
end;
$$;

revoke all on function public.app_session_create_authorized()
  from public, anon, authenticated;

create or replace function public.app_create_session(
  p_user_id uuid,
  p_user_agent text default null,
  p_ip text default null,
  p_remember boolean default true
)
returns text
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  raw_token text;
  persistent boolean := coalesce(p_remember, true);
  sess_ttl interval := case when coalesce(p_remember, true)
    then interval '14 days'
    else interval '12 hours'
  end;
  target_active boolean;
begin
  if not public.app_session_create_authorized() then
    raise exception 'Session creation is restricted';
  end if;

  select u.is_active into target_active
  from public.app_users u
  where u.id = p_user_id;

  if target_active is distinct from true then
    raise exception 'Cannot create a session for an inactive or missing account';
  end if;

  raw_token := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.app_sessions (
    user_id, token_hash, expires_at, user_agent, ip_text, is_persistent
  )
  values (
    p_user_id,
    public.app_hash_token(raw_token),
    now() + sess_ttl,
    left(coalesce(p_user_agent, ''), 500),
    left(coalesce(p_ip, ''), 100),
    persistent
  );
  return raw_token;
end;
$$;

-- The central fix: browsers must never be able to mint a session directly.
revoke all on function public.app_create_session(uuid, text, text, boolean)
  from public, anon, authenticated;
grant execute on function public.app_create_session(uuid, text, text, boolean)
  to service_role;

-- ── 4) Login: preserve UX + Remember Me while adding server throttling ───────
create or replace function public.app_login(
  p_username text,
  p_password text,
  p_user_agent text default null,
  p_ip text default null,
  p_remember boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  u public.app_users;
  token text;
  weak boolean;
  pin_disabled boolean := false;
  normalized_username text;
  network_fp text;
  account_scope_key text;
  network_scope_key text;
begin
  if p_username is null or trim(p_username) = '' then
    raise exception 'Username is required';
  end if;
  if p_password is null or p_password = '' then
    raise exception 'Password is required';
  end if;

  normalized_username := lower(trim(p_username));
  account_scope_key := public.app_login_throttle_scope_key('account', normalized_username);
  network_fp := public.app_request_network_fingerprint(p_ip);
  if network_fp is not null then
    network_scope_key := public.app_login_throttle_scope_key('network', network_fp);
  end if;

  -- Do not disclose whether the limiter, username, or password failed.
  if public.app_login_throttle_is_locked(account_scope_key)
     or (network_scope_key is not null and public.app_login_throttle_is_locked(network_scope_key)) then
    -- Return instead of RAISE so throttle state commits, while asking PostgREST
    -- to keep the historical HTTP error behaviour for existing clients.
    perform set_config('response.status', '400', true);
    return jsonb_build_object('ok', false, 'error', 'Invalid username or password');
  end if;

  select * into u
  from public.app_users
  where lower(username) = normalized_username
  limit 1;

  if u is null then
    if network_scope_key is not null then
      perform public.app_login_throttle_register_failure(network_scope_key, 'network');
    end if;
    perform set_config('response.status', '400', true);
    return jsonb_build_object('ok', false, 'error', 'Invalid username or password');
  end if;

  if u.password_hash <> extensions.crypt(p_password, u.password_hash) then
    perform public.app_login_throttle_register_failure(account_scope_key, 'account');
    if network_scope_key is not null then
      perform public.app_login_throttle_register_failure(network_scope_key, 'network');
    end if;
    perform set_config('response.status', '400', true);
    return jsonb_build_object('ok', false, 'error', 'Invalid username or password');
  end if;

  -- Correct password clears only security counters; it never changes user data.
  perform public.app_login_throttle_reset(account_scope_key);
  if network_scope_key is not null then
    perform public.app_login_throttle_reset(network_scope_key);
  end if;

  if u.id is not null then
    perform public.app_enforce_access_expiry(u.id);
    select * into u from public.app_users where id = u.id;
  end if;

  if not u.is_active then
    select coalesce(temp_disabled, false) into pin_disabled
    from public.app_smart_pin_lockouts
    where user_id = u.id;
    if coalesce(pin_disabled, false) then
      raise exception 'Due to too many wrong attempts, access is locked. Please contact admin to restore your access on WhatsApp +92 333 900 4564.';
    end if;
    if u.access_disabled_for_expiry_at is not null then
      raise exception 'Account is disabled because the access period expired. Contact the administrator to renew.';
    end if;
    raise exception 'Account is disabled';
  end if;

  weak := not public.app_password_meets_policy(p_password);

  perform set_config('app.session_create_authorized', '1', true);
  token := public.app_create_session(u.id, p_user_agent, p_ip, coalesce(p_remember, true));
  perform set_config('app.session_create_authorized', '0', true);

  update public.app_users
  set
    last_login_at = now(),
    updated_at = now(),
    password_is_weak = weak
  where id = u.id;

  select * into u from public.app_users where id = u.id;
  u.last_login_at := now();

  return jsonb_build_object(
    'session_token', token,
    'user', public.app_user_public_profile(u, false)
  );
end;
$$;

revoke all on function public.app_login(text, text, text, text, boolean) from public;
grant execute on function public.app_login(text, text, text, text, boolean)
  to authenticated, anon, service_role;

-- ── 5) Trial signup remains identical; authorize its nested session mint ─────
do $patch_trial_session_guard$
declare
  fn_oid oid;
  def text;
  original_call text := 'token := public.app_create_session(new_user.id, p_user_agent, p_ip);';
  guarded_call text := 'perform set_config(''app.session_create_authorized'', ''1'', true);' || E'\n  ' ||
                       'token := public.app_create_session(new_user.id, p_user_agent, p_ip);' || E'\n  ' ||
                       'perform set_config(''app.session_create_authorized'', ''0'', true);';
begin
  select p.oid into fn_oid
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname = 'app_trial_signup'
  order by p.pronargs desc
  limit 1;

  if fn_oid is null then
    raise exception 'app_trial_signup not found; migration order is incomplete';
  end if;

  def := pg_get_functiondef(fn_oid);
  if def ilike '%app.session_create_authorized%' then
    raise notice 'app_trial_signup already has the session-creation guard';
    return;
  end if;

  if position(original_call in def) = 0 then
    raise exception 'Could not safely patch app_trial_signup session creation; unexpected function definition';
  end if;

  def := replace(def, original_call, guarded_call);
  execute def;
end;
$patch_trial_session_guard$;

-- ── 6) Profile hardening: never return raw Smart PIN verifier to clients ─────
do $patch_profile_pin_hash$
declare
  fn_oid oid;
  def text;
  unsafe_fragment text := $frag$'smart_pin_hash', coalesce(u.smart_pin_hash, '')$frag$;
  safe_fragment text := $frag$'smart_pin_hash', ''$frag$;
begin
  select p.oid into fn_oid
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.proname = 'app_user_public_profile'
    and pg_get_function_identity_arguments(p.oid) = 'u app_users, p_include_admin_secrets boolean'
  limit 1;

  if fn_oid is null then
    raise exception 'app_user_public_profile(app_users, boolean) not found; migration order is incomplete';
  end if;

  def := pg_get_functiondef(fn_oid);

  if position(unsafe_fragment in def) > 0 then
    def := replace(def, unsafe_fragment, safe_fragment);
    execute def;
  elsif def ilike '%''smart_pin_hash'', ''''%' then
    raise notice 'app_user_public_profile already hides smart_pin_hash';
  else
    raise exception 'Could not safely patch app_user_public_profile; unexpected smart_pin_hash output';
  end if;
end;
$patch_profile_pin_hash$;

-- Keep this helper internal even if an earlier migration granted it.
revoke all on function public.app_user_public_profile(public.app_users, boolean)
  from public, anon, authenticated;

-- ── 7) Reduce direct RPC surface for internal SECURITY DEFINER helpers ───────
-- All public entry RPCs continue to call these as the function owner.
