-- ============================================================================
-- 094_expense_item_history_accuracy.sql
-- Triplem VIP expense-history accuracy hardening (additive, read-only).
--
-- Purpose:
--   * return exact per-item transaction counts/totals for the selected history
--     range without forcing the browser to download every expense row;
--   * page the complete history for one item on demand when the user expands it.
--
-- Safety:
--   * creates/replaces read-only RPC functions only;
--   * does not INSERT, UPDATE, DELETE, TRUNCATE, DROP, rename, or rewrite any
--     user/business row, table, column, session, setting, wallet, or transaction;
--   * preserves the existing owner isolation and Expenses view permission gate.
-- ============================================================================

create or replace function public.app_list_my_expense_item_summaries(
  p_from date default null,
  p_to date default null,
  p_search text default null,
  p_group_id text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  caller_id uuid := public.current_app_user_id();
  data_owner uuid := public.app_data_owner_id();
  q text := lower(trim(coalesce(p_search, '')));
  gid uuid := null;
  payload jsonb := '[]'::jsonb;
begin
  if caller_id is null or data_owner is null then
    raise exception 'Authentication required';
  end if;
  if not public.app_has_permission('expenses', 'view') then
    raise exception 'Expenses access required';
  end if;

  if nullif(trim(coalesce(p_group_id, '')), '') is not null then
    begin
      gid := trim(p_group_id)::uuid;
    exception when others then
      gid := null;
    end;
  end if;

  with filtered as (
    select
      e.id,
      e.group_id,
      e.account_name,
      e.currency,
      e.amount,
      e.expense_date,
      e.notes,
      e.created_at,
      coalesce(
        nullif(trim(e.item_name), ''),
        nullif(trim(public.app_note_meta_value(e.notes, 'ITEM')), '')
      ) as item_name,
      coalesce(
        nullif(trim(e.expense_type), ''),
        nullif(trim(public.app_note_meta_value(e.notes, 'XTYPE')), ''),
        'Other'
      ) as expense_type,
      a.account_type
    from public.expense_entries e
    join public.expense_accounts a
      on a.group_id = e.group_id
     and a.owner_id = data_owner
    where e.owner_id = data_owner
      and not coalesce(e.is_deleted, false)
      and not coalesce(a.is_deleted, false)
      and (gid is null or e.group_id = gid)
      and (p_from is null or e.expense_date >= p_from)
      and (p_to is null or e.expense_date <= p_to)
      and coalesce(
        nullif(trim(e.item_name), ''),
        nullif(trim(public.app_note_meta_value(e.notes, 'ITEM')), '')
      ) is not null
      and (
        q = ''
        or lower(coalesce(e.account_name, '')) like '%' || q || '%'
        or lower(coalesce(nullif(trim(e.item_name), ''), nullif(trim(public.app_note_meta_value(e.notes, 'ITEM')), ''), '')) like '%' || q || '%'
        or lower(coalesce(nullif(trim(e.expense_type), ''), nullif(trim(public.app_note_meta_value(e.notes, 'XTYPE')), ''), '')) like '%' || q || '%'
        or lower(coalesce(e.notes, '')) like '%' || q || '%'
        or lower(coalesce(a.account_type, '')) like '%' || q || '%'
      )
  ), enriched as (
    select
      filtered.*,
      case
        when lower(coalesce(public.app_note_meta_value(notes, 'VATP'), '')) in ('0','false','no','off') then 0::numeric
        when public.app_note_meta_value(notes, 'VATA') ~ '^[-+]?[0-9]+([.][0-9]+)?$'
          then public.app_meta_numeric(notes, 'VATA', 0)
        when public.app_meta_numeric(notes, 'VATR', 0) > 0
          then round((amount * public.app_meta_numeric(notes, 'VATR', 0)) /
                     (100 + public.app_meta_numeric(notes, 'VATR', 0)), 2)
        else 0::numeric
      end as tax_amount
    from filtered
  ), grouped as (
    select
      currency,
      lower(item_name) as normalized_item,
      (array_agg(item_name order by expense_date desc nulls last, created_at desc, id desc))[1] as item_name,
      (array_agg(expense_type order by expense_date desc nulls last, created_at desc, id desc))[1] as expense_type,
      count(*)::bigint as transaction_count,
      coalesce(sum(amount), 0)::numeric as total_amount,
      coalesce(sum(tax_amount), 0)::numeric as tax_total,
      coalesce(sum(amount - tax_amount), 0)::numeric as net_total,
      max(expense_date) as latest_date
    from enriched
    group by currency, lower(item_name)
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'item_name', item_name,
        'expense_type', expense_type,
        'currency', currency,
        'transaction_count', transaction_count,
        'total_amount', total_amount,
        'tax_total', tax_total,
        'net_total', net_total,
        'latest_date', latest_date
      )
      order by total_amount desc, lower(item_name), currency
    ),
    '[]'::jsonb
  )
  into payload
  from grouped;

  return jsonb_build_object('ok', true, 'items', payload);
end
$fn$;

revoke all on function public.app_list_my_expense_item_summaries(date,date,text,text) from public;
grant execute on function public.app_list_my_expense_item_summaries(date,date,text,text)
  to anon, authenticated, service_role;


create or replace function public.app_list_my_expense_item_history_page(
  p_item_name text,
  p_currency text,
  p_from date default null,
  p_to date default null,
  p_search text default null,
  p_group_id text default null,
  p_limit int default 500,
  p_offset int default 0
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  caller_id uuid := public.current_app_user_id();
  data_owner uuid := public.app_data_owner_id();
  wanted_item text := lower(trim(coalesce(p_item_name, '')));
  wanted_currency text := trim(coalesce(p_currency, ''));
  q text := lower(trim(coalesce(p_search, '')));
  gid uuid := null;
  lim int := greatest(1, least(coalesce(p_limit, 500), 500));
  off_n int := greatest(0, coalesce(p_offset, 0));
  payload jsonb := '[]'::jsonb;
  has_more boolean := false;
begin
  if caller_id is null or data_owner is null then
    raise exception 'Authentication required';
  end if;
  if not public.app_has_permission('expenses', 'view') then
    raise exception 'Expenses access required';
  end if;
  if wanted_item = '' or wanted_currency = '' then
    return jsonb_build_object('ok', true, 'items', '[]'::jsonb, 'has_more', false, 'limit', lim, 'offset', off_n);
  end if;

  if nullif(trim(coalesce(p_group_id, '')), '') is not null then
    begin
      gid := trim(p_group_id)::uuid;
    exception when others then
      gid := null;
    end;
  end if;

  with matching as (
    select
      e.id,
      e.group_id::text as group_id,
      e.account_name,
      e.currency,
      e.amount,
      e.expense_date as activity_date,
      e.notes,
      e.created_at,
      e.updated_at,
      'EXPENSE'::text as row_type,
      coalesce(
        nullif(trim(e.item_name), ''),
        nullif(trim(public.app_note_meta_value(e.notes, 'ITEM')), ''),
        ''
      ) as item_name,
      coalesce(
        nullif(trim(e.expense_type), ''),
        nullif(trim(public.app_note_meta_value(e.notes, 'XTYPE')), ''),
        'Other'
      ) as expense_type,
      a.account_type
    from public.expense_entries e
    join public.expense_accounts a
      on a.group_id = e.group_id
     and a.owner_id = data_owner
    where e.owner_id = data_owner
      and not coalesce(e.is_deleted, false)
      and not coalesce(a.is_deleted, false)
      and (gid is null or e.group_id = gid)
      and e.currency = wanted_currency
      and lower(coalesce(
        nullif(trim(e.item_name), ''),
        nullif(trim(public.app_note_meta_value(e.notes, 'ITEM')), ''),
        ''
      )) = wanted_item
      and (p_from is null or e.expense_date >= p_from)
      and (p_to is null or e.expense_date <= p_to)
      and (
        q = ''
        or lower(coalesce(e.account_name, '')) like '%' || q || '%'
        or lower(coalesce(nullif(trim(e.item_name), ''), nullif(trim(public.app_note_meta_value(e.notes, 'ITEM')), ''), '')) like '%' || q || '%'
        or lower(coalesce(nullif(trim(e.expense_type), ''), nullif(trim(public.app_note_meta_value(e.notes, 'XTYPE')), ''), '')) like '%' || q || '%'
        or lower(coalesce(e.notes, '')) like '%' || q || '%'
        or lower(coalesce(a.account_type, '')) like '%' || q || '%'
      )
  ), page as (
    select *
    from matching
    order by activity_date desc nulls last, created_at desc, id desc
    offset off_n
    limit lim + 1
  ), numbered as (
    select page.*,
      row_number() over (order by activity_date desc nulls last, created_at desc, id desc) as page_row
    from page
  )
  select
    coalesce(
      jsonb_agg(to_jsonb(numbered) - 'page_row' order by activity_date desc nulls last, created_at desc, id desc)
        filter (where page_row <= lim),
      '[]'::jsonb
    ),
    coalesce(bool_or(page_row > lim), false)
  into payload, has_more
  from numbered;

  return jsonb_build_object(
    'ok', true,
    'items', payload,
    'has_more', has_more,
    'limit', lim,
    'offset', off_n
  );
end
$fn$;

revoke all on function public.app_list_my_expense_item_history_page(text,text,date,date,text,text,int,int) from public;
grant execute on function public.app_list_my_expense_item_history_page(text,text,date,date,text,text,int,int)
  to anon, authenticated, service_role;

