-- 095_expense_global_smart_search.sql
-- Global, owner-scoped Expenses search without changing any existing data.
-- Search deliberately ignores the UI date-range while text is present; ordinary
-- browsing continues to use the selected date range in the client.
-- This migration only creates/replaces read-only helper/RPC functions.

create or replace function public.app_expense_search_matches(
  p_haystack text,
  p_query text
)
returns boolean
language sql
immutable
set search_path = public
as $fn$
  select case
    when btrim(coalesce(p_query, '')) = '' then true
    else not exists (
      select 1
      from unnest(
        regexp_split_to_array(
          lower(replace(btrim(coalesce(p_query, '')), ',', '')),
          E'\\s+'
        )
      ) as token
      where token <> ''
        and lower(replace(coalesce(p_haystack, ''), ',', '')) not like '%' || token || '%'
    )
  end
$fn$;

revoke all on function public.app_expense_search_matches(text,text) from public, anon, authenticated, service_role;

create or replace function public.app_list_my_expense_activity_page(
  p_from date default null,
