      and (p_to is null or t.topup_date <= p_to)
      and public.app_expense_search_matches(
        concat_ws(' ',
          'topup money added income deposit',
          t.account_name,
          a.account_type,
          t.currency,
          t.amount::text,
          t.topup_date::text,
          t.notes
        ),
        p_search
      )
    union all
    select e.id, e.group_id::text, e.account_name, e.currency,
      e.amount, e.expense_date, e.notes, e.created_at, e.updated_at,
      'EXPENSE'::text,
      coalesce(nullif(trim(e.item_name), ''), nullif(trim(public.app_note_meta_value(e.notes, 'ITEM')), ''), ''),
      coalesce(nullif(trim(e.expense_type), ''), nullif(trim(public.app_note_meta_value(e.notes, 'XTYPE')), ''), 'Other'),
      a.account_type
    from public.expense_entries e
    join public.expense_accounts a on a.group_id = e.group_id and a.owner_id = data_owner
    where e.owner_id = data_owner and not coalesce(e.is_deleted, false)
      and not coalesce(a.is_deleted, false)
      and (gid is null or e.group_id = gid)
      and (p_from is null or e.expense_date >= p_from)
      and (p_to is null or e.expense_date <= p_to)
      and public.app_expense_search_matches(
        concat_ws(' ',
          'expense spent payment transaction',
          e.account_name,
          a.account_type,
          e.currency,
          e.amount::text,
          e.expense_date::text,
          coalesce(nullif(trim(e.item_name), ''), nullif(trim(public.app_note_meta_value(e.notes, 'ITEM')), ''), ''),
          coalesce(nullif(trim(e.expense_type), ''), nullif(trim(public.app_note_meta_value(e.notes, 'XTYPE')), ''), 'Other'),
          e.notes
        ),
        p_search
      )
  ), page as (
    select * from activity
    order by activity_date desc nulls last, created_at desc, id desc
    offset off_n limit lim + 1
  ), numbered as (
    select page.*, row_number() over (order by activity_date desc nulls last, created_at desc, id desc) as page_row
    from page
  )
  select
    coalesce(jsonb_agg(to_jsonb(numbered) - 'page_row' order by activity_date desc nulls last, created_at desc, id desc)
      filter (where page_row <= lim), '[]'::jsonb),
    coalesce(bool_or(page_row > lim), false)
  into payload, has_more
  from numbered;

  return jsonb_build_object('ok', true, 'items', payload, 'has_more', has_more,
    'limit', lim, 'offset', off_n);
end
$fn$;

