-- ============================================================================
-- 096_free_signup_pro_payment_approvals.sql
-- Free signup + Pro bank-transfer approval workflow.
--
-- LIVE-DATABASE SAFETY
--   * Additive / forward-only. Safe after 095.
--   * Does NOT delete, truncate, rename, or rewrite any existing user/business data.
--   * Does NOT alter existing users, admins, sessions, wallets, expenses, inventory,
--     teams, credentials, access periods, or historical subscriptions when installed.
--   * New account/payment mutations occur only when a NEW signup is submitted or an
--     authenticated administrator explicitly resolves that new request later.
-- ============================================================================

create extension if not exists pgcrypto with schema extensions;

-- Allow the dedicated paid-signup notification kind.
alter table public.app_admin_notifications
  drop constraint if exists app_admin_notifications_kind_check;
alter table public.app_admin_notifications
  add constraint app_admin_notifications_kind_check
  check (kind in (
    'trial_signup','inquiry','system','renewal_request','access_expiry_warning',
    'access_auto_disabled','subscription_payment'
  ));

create table if not exists public.app_subscription_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.app_users(id) on delete cascade,
  account_type text not null check (account_type in ('individual','company')),
  billing_period text not null check (billing_period in ('monthly','yearly')),
  billing_currency text not null check (billing_currency in ('AED','SAR','PKR','USD')),
  base_amount numeric(18,2) not null check (base_amount >= 0),
  team_enabled boolean not null default false,
  team_seats integer not null default 0 check (team_seats between 0 and 50),
  team_unit_amount numeric(18,2) not null default 0 check (team_unit_amount >= 0),
  team_amount numeric(18,2) not null default 0 check (team_amount >= 0),
  total_amount numeric(18,2) not null check (total_amount >= 0),
  payment_bank text not null check (payment_bank in ('hbl','enbd')),
  receipt_name text not null,
  receipt_mime text not null check (receipt_mime in ('image/png','image/jpeg','image/webp','application/pdf')),
  receipt_bytes bytea not null,
  status text not null default 'pending' check (status in ('pending','approved','declined','cancelled')),
  admin_action text,
  admin_note text,
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  resolved_by uuid references public.app_users(id) on delete set null,
  constraint app_subscription_receipt_size check (octet_length(receipt_bytes) between 1 and 5242880)
);

create index if not exists app_subscription_requests_user_created_idx
  on public.app_subscription_requests(user_id, created_at desc);
create index if not exists app_subscription_requests_status_created_idx
  on public.app_subscription_requests(status, created_at desc);
create unique index if not exists app_subscription_requests_one_pending_per_user
  on public.app_subscription_requests(user_id) where status = 'pending';

alter table public.app_subscription_requests enable row level security;
revoke all on table public.app_subscription_requests from public, anon, authenticated;
drop policy if exists app_subscription_requests_deny_all on public.app_subscription_requests;
create policy app_subscription_requests_deny_all
  on public.app_subscription_requests for all to anon, authenticated
  using (false) with check (false);

-- Small signup-abuse ledger. Stores a SHA-256 network fingerprint only, never raw IP.
create table if not exists public.app_public_signup_throttle (
  scope_key text primary key,
  signup_count integer not null default 0 check (signup_count >= 0),
  window_started_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.app_public_signup_throttle enable row level security;
revoke all on table public.app_public_signup_throttle from public, anon, authenticated;

create or replace function public.app_subscription_price(
  p_period text,
  p_currency text,
  p_team_seats integer default 0
)
returns jsonb
language plpgsql
immutable
set search_path = public
as $fn$
declare
  period text := lower(trim(coalesce(p_period,'')));
  cur text := upper(trim(coalesce(p_currency,'')));
  seats int := greatest(0, least(coalesce(p_team_seats,0), 50));
  base numeric(18,2);
  unit numeric(18,2) := 0;
begin
  if period not in ('monthly','yearly') then raise exception 'Invalid billing period'; end if;
  if cur not in ('AED','SAR','PKR','USD') then raise exception 'Invalid billing currency'; end if;

  base := case
    when period='monthly' and cur='AED' then 49
    when period='monthly' and cur='SAR' then 49
    when period='monthly' and cur='PKR' then 1799
    when period='monthly' and cur='USD' then 13.99
    when period='yearly' and cur='AED' then 449
    when period='yearly' and cur='SAR' then 449
    when period='yearly' and cur='PKR' then 19999
    when period='yearly' and cur='USD' then 149
  end;

  unit := case
    when period='monthly' and cur='AED' then 10
    when period='monthly' and cur='SAR' then 10
    when period='monthly' and cur='PKR' then 75
    when period='monthly' and cur='USD' then 4
    when period='yearly' and cur='AED' then 80
    when period='yearly' and cur='SAR' then 80
    when period='yearly' and cur='PKR' then 7000
    when period='yearly' and cur='USD' then 40
  end;

  return jsonb_build_object(
    'base_amount', base,
    'team_unit_amount', unit,
    'team_amount', round(unit * seats, 2),
    'total_amount', round(base + (unit * seats), 2),
    'team_seats', seats
  );
end
$fn$;
revoke all on function public.app_subscription_price(text,text,integer) from public, anon, authenticated;

create or replace function public.app_signup_throttle_assert_and_register(p_ip text default null)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
declare
  fp text := public.app_request_network_fingerprint(p_ip);
  k text;
  r public.app_public_signup_throttle;
begin
  if fp is null then return; end if;
  k := 'signup:' || fp;
  select * into r from public.app_public_signup_throttle where scope_key=k for update;
  if r is null then
    insert into public.app_public_signup_throttle(scope_key,signup_count,window_started_at,updated_at)
    values(k,1,now(),now());
    return;
  end if;
  if r.window_started_at < now() - interval '1 hour' then
    update public.app_public_signup_throttle
      set signup_count=1, window_started_at=now(), updated_at=now() where scope_key=k;
    return;
  end if;
  if r.signup_count >= 5 then
    raise exception 'Too many sign-up attempts from this network. Please try again later.';
  end if;
  update public.app_public_signup_throttle
    set signup_count=signup_count+1, updated_at=now() where scope_key=k;
end
$fn$;
revoke all on function public.app_signup_throttle_assert_and_register(text) from public, anon, authenticated;

create or replace function public.app_signup_v2(
  p_plan text,
  p_account_type text,
  p_username text,
  p_password text,
  p_display_name text,
  p_company_name text default null,
  p_company_email text default null,
  p_company_phone text default null,
  p_company_address text default null,
  p_vat_number text default null,
  p_logo_url text default null,
  p_currencies jsonb default '["AED"]'::jsonb,
  p_billing_currency text default 'AED',
  p_team_enabled boolean default false,
  p_team_seats integer default 0,
  p_payment_bank text default null,
  p_receipt_name text default null,
  p_receipt_mime text default null,
  p_receipt_base64 text default null,
  p_user_agent text default null,
  p_ip text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  plan text := lower(trim(coalesce(p_plan,'free')));
  acct text := lower(trim(coalesce(p_account_type,'individual')));
  safe_user text := trim(coalesce(p_username,''));
  billing_cur text := upper(trim(coalesce(p_billing_currency,'AED')));
  is_paid boolean;
  is_company boolean;
  team_on boolean;
  seats int;
  org_id uuid;
  new_user public.app_users;
  settings_obj jsonb;
  tabs jsonb;
  base_tabs text[] := array['dashboard','expenses','inventory','loans','installments','notes','reports','currency_settings'];
  cleaned text[] := array[]::text[];
  item jsonb;
  cur text;
  has_btc boolean := false;
  price jsonb;
  req public.app_subscription_requests;
  receipt bytea;
  sig text;
  token text;
  expires_at timestamptz := now() + interval '14 days';
  v_email text := nullif(trim(coalesce(p_company_email,'')),'');
  v_phone text := nullif(trim(coalesce(p_company_phone,'')),'');
  v_address text := nullif(trim(coalesce(p_company_address,'')),'');
  v_company text := nullif(trim(coalesce(p_company_name,'')),'');
  v_vat text := nullif(trim(coalesce(p_vat_number,'')),'');
  v_logo text := nullif(trim(coalesce(p_logo_url,'')),'');
begin
  if plan not in ('free','monthly','yearly') then raise exception 'Choose Free 14 Days, Pro Monthly, or Pro Yearly'; end if;
  if acct not in ('individual','company') then raise exception 'Choose Individual or Company'; end if;
  is_paid := plan in ('monthly','yearly');
  is_company := acct='company';
  team_on := is_company and coalesce(p_team_enabled,false);
  seats := case when team_on then greatest(1, least(coalesce(p_team_seats,1),50)) else 0 end;

  if safe_user !~ '^[a-zA-Z0-9_-]+$' or length(safe_user)<3 then
    raise exception 'Username must be at least 3 characters and use only letters, numbers, underscores, or hyphens.';
  end if;
  perform public.app_assert_password_policy(p_password);
  if nullif(trim(coalesce(p_display_name,'')),'') is null then raise exception 'Name is required'; end if;
  if v_email is null or v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'A valid email address is required'; end if;
  if v_phone is null or length(v_phone)<6 then raise exception 'A valid mobile number is required'; end if;
  if is_company and v_company is null then raise exception 'Company name is required'; end if;
  if is_company and v_address is null then raise exception 'Company address is required'; end if;
  if exists(select 1 from public.app_users where lower(username)=lower(safe_user)) then raise exception 'Username already exists. Please choose another.'; end if;

  if p_currencies is null or jsonb_typeof(p_currencies)<>'array' then raise exception 'Select at least one currency'; end if;
  for item in select * from jsonb_array_elements(p_currencies) loop
    cur := upper(trim(both '"' from item::text));
    if cur = any(array['AED','SAR','PKR','USD','BTC']) and not(cur=any(cleaned)) then cleaned:=array_append(cleaned,cur); end if;
  end loop;
  if coalesce(array_length(cleaned,1),0)<1 then raise exception 'Select at least one currency'; end if;
  if billing_cur not in ('AED','SAR','PKR','USD') then raise exception 'Choose AED, SAR, PKR, or USD as billing currency'; end if;
  if not billing_cur=any(cleaned) then cleaned:=array_prepend(billing_cur,cleaned); end if;
  has_btc := 'BTC'=any(cleaned);
  tabs := to_jsonb(case when has_btc then base_tabs || array['bitcoin'] else base_tabs end);

  if is_paid then
    if lower(trim(coalesce(p_payment_bank,''))) not in ('hbl','enbd') then raise exception 'Choose a bank transfer account'; end if;
    if p_receipt_mime not in ('image/png','image/jpeg','image/webp','application/pdf') then raise exception 'Receipt must be PNG, JPG, WebP, or PDF'; end if;
    if nullif(trim(coalesce(p_receipt_base64,'')),'') is null then raise exception 'Attach your payment receipt'; end if;
    begin receipt := decode(regexp_replace(p_receipt_base64,E'\\s','','g'),'base64');
    exception when others then raise exception 'Payment receipt could not be read'; end;
    if octet_length(receipt)>5242880 then raise exception 'Payment receipt must be 5MB or smaller'; end if;
    sig := lower(encode(substring(receipt from 1 for 16),'hex'));
    if p_receipt_mime='image/png' and left(sig,16)<>'89504e470d0a1a0a' then raise exception 'Invalid PNG receipt'; end if;
    if p_receipt_mime='image/jpeg' and left(sig,6)<>'ffd8ff' then raise exception 'Invalid JPEG receipt'; end if;
    if p_receipt_mime='image/webp' and not(left(sig,8)='52494646' and substring(sig from 17 for 8)='57454250') then raise exception 'Invalid WebP receipt'; end if;
    if p_receipt_mime='application/pdf' and left(sig,8)<>'25504446' then raise exception 'Invalid PDF receipt'; end if;
    price := public.app_subscription_price(plan,billing_cur,seats);
  end if;

  perform public.app_signup_throttle_assert_and_register(p_ip);

  select organization_id into org_id from public.app_users where is_protected=true order by created_at limit 1;
  if org_id is null then select organization_id into org_id from public.app_users where role='admin' order by created_at limit 1; end if;
  if org_id is null then insert into public.app_organizations(name) values('Triple M') returning id into org_id; end if;

  settings_obj := jsonb_build_object(
    'Currency',to_jsonb(cleaned),'Tabs',tabs,'BitcoinAccess',case when has_btc then 'both' else 'none' end,
    'Company',coalesce(v_company,''),'TRN',coalesce(v_vat,''),'logo',coalesce(v_logo,''),
    'email',v_email,'Email',v_email,'Mobile',v_phone,'Phone',v_phone,
    'Address',coalesce(v_address,''),'address',coalesce(v_address,''),
    'Name',trim(p_display_name),'SignupPlan',plan,'AccountType',acct,
    'BillingCurrency',billing_cur,'PaymentApprovalPending',is_paid
  );

  insert into public.app_users(
    organization_id,username,password_hash,admin_visible_password,display_name,role,is_protected,is_active,
    must_change_password,settings,company_name,vat_number,logo_url,company_email,company_phone,company_address,
    access_plan,trial_started_at,trial_expires_at,allow_team_members,max_team_members
  ) values(
    org_id,safe_user,extensions.crypt(p_password,extensions.gen_salt('bf')),null,trim(p_display_name),'user',false,true,
    false,settings_obj,case when is_company then v_company else null end,case when is_company then v_vat else null end,
    v_logo,v_email,v_phone,v_address,'trial',now(),expires_at,team_on,case when team_on then seats else 3 end
  ) returning * into new_user;

  perform public.app_apply_user_currencies(new_user.id,to_jsonb(cleaned));
  perform public.app_apply_tab_permissions(new_user.id,tabs);
  update public.app_permissions set allowed=false where user_id=new_user.id and module='admin_panel';

  if is_paid then
    insert into public.app_subscription_requests(
      user_id,account_type,billing_period,billing_currency,base_amount,team_enabled,team_seats,
      team_unit_amount,team_amount,total_amount,payment_bank,receipt_name,receipt_mime,receipt_bytes
    ) values(
      new_user.id,acct,plan,billing_cur,(price->>'base_amount')::numeric,team_on,seats,
      (price->>'team_unit_amount')::numeric,(price->>'team_amount')::numeric,(price->>'total_amount')::numeric,
      lower(trim(p_payment_bank)),left(coalesce(nullif(trim(p_receipt_name),''),'receipt'),200),p_receipt_mime,receipt
    ) returning * into req;

    perform public.app_notify_admins(
      'subscription_payment','Pro payment awaiting approval',
      format('%s (@%s) submitted %s %s payment of %s %s%s.',trim(p_display_name),safe_user,
        case when plan='monthly' then 'Pro Monthly' else 'Pro Yearly' end,
        upper(req.payment_bank),trim(to_char(req.total_amount,'FM999999999990.00')),billing_cur,
        case when team_on then format(' including %s team seat(s)',seats) else '' end),
      new_user.id,null,
      jsonb_build_object('request_id',req.id,'plan',plan,'amount',req.total_amount,'currency',billing_cur,
        'payment_bank',req.payment_bank,'team_enabled',team_on,'team_seats',seats)
    );
  end if;

  perform set_config('app.session_create_authorized','1',true);
  token := public.app_create_session(new_user.id,p_user_agent,p_ip,true);
  perform set_config('app.session_create_authorized','0',true);
  update public.app_users set last_login_at=now(),updated_at=now() where id=new_user.id;
  select * into new_user from public.app_users where id=new_user.id;

  return jsonb_build_object('ok',true,'session_token',token,'user',public.app_user_public_profile(new_user,false),
    'subscription',case when is_paid then jsonb_build_object('id',req.id,'status','pending','plan',plan,
      'currency',billing_cur,'amount',req.total_amount) else jsonb_build_object('status','free_trial') end);
end
$fn$;

revoke all on function public.app_signup_v2(text,text,text,text,text,text,text,text,text,text,text,jsonb,text,boolean,integer,text,text,text,text,text,text) from public;
grant execute on function public.app_signup_v2(text,text,text,text,text,text,text,text,text,text,text,jsonb,text,boolean,integer,text,text,text,text,text,text)
  to anon, authenticated, service_role;

-- Existing trial trigger remains useful for Free signups, but paid signups get the
-- richer payment notification instead of a duplicate generic trial notification.
create or replace function public.app_on_trial_user_created()
returns trigger
language plpgsql
security definer
set search_path = public
as $fn$
begin
  if tg_op='INSERT' and coalesce(new.access_plan,'')='trial' and coalesce(new.role,'user')<>'admin'
     and lower(coalesce(new.settings->>'SignupPlan','free'))='free' then
    perform public.app_notify_admins('trial_signup','New free account',
      format('User "%s"%s started a 14-day free workspace.',coalesce(new.username,'unknown'),
        case when nullif(trim(coalesce(new.display_name,'')),'') is not null and trim(new.display_name)<>coalesce(new.username,'')
          then format(' (%s)',trim(new.display_name)) else '' end),
      new.id,null,jsonb_build_object('username',new.username,'display_name',new.display_name,'company_name',new.company_name,
        'company_email',new.company_email,'company_phone',new.company_phone,'trial_expires_at',new.trial_expires_at));
  end if;
  return new;
end
$fn$;

create or replace function public.app_my_subscription_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  uid uuid := public.current_app_user_id();
  r public.app_subscription_requests;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into r from public.app_subscription_requests where user_id=uid order by created_at desc limit 1;
  if r is null then return jsonb_build_object('ok',true,'has_request',false); end if;
  return jsonb_build_object('ok',true,'has_request',true,'id',r.id,'status',r.status,'plan',r.billing_period,
    'currency',r.billing_currency,'amount',r.total_amount,'team_enabled',r.team_enabled,'team_seats',r.team_seats,
    'payment_bank',r.payment_bank,'created_at',r.created_at,'resolved_at',r.resolved_at,'admin_action',r.admin_action,
    'admin_note',coalesce(r.admin_note,''));
end
$fn$;
revoke all on function public.app_my_subscription_status() from public;
grant execute on function public.app_my_subscription_status() to anon, authenticated, service_role;

create or replace function public.app_admin_list_subscription_requests(p_status text default 'pending', p_limit int default 100)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  s text := lower(trim(coalesce(p_status,'pending')));
  lim int := greatest(1,least(coalesce(p_limit,100),250));
begin
  perform public.app_require_admin();
  return coalesce((select jsonb_agg(x order by x.created_at desc) from (
    select r.id,r.user_id,u.username,u.display_name,u.company_name,u.company_email,u.company_phone,
      r.account_type,r.billing_period,r.billing_currency,r.base_amount,r.team_enabled,r.team_seats,
      r.team_unit_amount,r.team_amount,r.total_amount,r.payment_bank,r.receipt_name,r.receipt_mime,
      r.status,r.admin_action,r.admin_note,r.created_at,r.resolved_at
    from public.app_subscription_requests r join public.app_users u on u.id=r.user_id
    where s='all' or r.status=s order by r.created_at desc limit lim
  ) x),'[]'::jsonb);
end
$fn$;
revoke all on function public.app_admin_list_subscription_requests(text,integer) from public;
grant execute on function public.app_admin_list_subscription_requests(text,integer) to anon, authenticated, service_role;

create or replace function public.app_admin_get_subscription_receipt(p_request_id uuid)
returns jsonb
language plpgsql
stable
