create or replace function public.app_admin_resolve_subscription_request(
  p_request_id uuid,
  p_action text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  admin public.app_users := public.app_require_admin();
  r public.app_subscription_requests;
  action text := lower(trim(coalesce(p_action,'')));
  expiry timestamptz;
begin
  select * into r from public.app_subscription_requests where id=p_request_id for update;
  if r is null then raise exception 'Payment request not found'; end if;
  if r.status<>'pending' then raise exception 'This payment request has already been resolved'; end if;
  if action not in ('approve','decline','decline_disable','grant_trial','grant_month','grant_3_months','grant_6_months','grant_year','grant_unlimited','delete') then
    raise exception 'Invalid approval action';
  end if;

  if action='delete' then
    perform public.app_admin_delete_user(r.user_id);
    return jsonb_build_object('ok',true,'action','delete','user_id',r.user_id);
  end if;

  if action='approve' then
    expiry := case when r.billing_period='monthly' then now()+interval '2 months' else now()+interval '14 months' end;
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=expiry,
      access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,
      settings=coalesce(settings,'{}'::jsonb)||jsonb_build_object('PaymentApprovalPending',false,'ApprovedPlan',r.billing_period),updated_at=now()
    where id=r.user_id;
  elsif action='grant_trial' then
    update public.app_users set access_plan='trial',trial_started_at=now(),trial_expires_at=now()+interval '14 days',
      access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,updated_at=now() where id=r.user_id;
  elsif action='grant_month' then
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=now()+interval '30 days',
      access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,updated_at=now() where id=r.user_id;
  elsif action='grant_3_months' then
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=now()+interval '90 days',
      access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,updated_at=now() where id=r.user_id;
  elsif action='grant_6_months' then
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=now()+interval '180 days',
      access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,updated_at=now() where id=r.user_id;
  elsif action='grant_year' then
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=now()+interval '365 days',
      access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,updated_at=now() where id=r.user_id;
  elsif action='grant_unlimited' then
    update public.app_users set access_plan='full',trial_started_at=null,trial_expires_at=null,
      access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,updated_at=now() where id=r.user_id;
  elsif action='decline_disable' then
    update public.app_users set is_active=false,updated_at=now() where id=r.user_id;
  end if;

  update public.app_subscription_requests set
    status=case when action='approve' then 'approved' else 'declined' end,
    admin_action=action,admin_note=nullif(trim(coalesce(p_note,'')),''),resolved_at=now(),resolved_by=admin.id
  where id=r.id;

  update public.app_admin_notifications set is_read=true,read_at=coalesce(read_at,now()),read_by=coalesce(read_by,admin.id)
  where kind='subscription_payment' and coalesce(payload->>'request_id','')=r.id::text;

  return jsonb_build_object('ok',true,'action',action,'user_id',r.user_id,'expires_at',expiry);
end
$fn$;
revoke all on function public.app_admin_resolve_subscription_request(uuid,text,text) from public;
grant execute on function public.app_admin_resolve_subscription_request(uuid,text,text) to anon, authenticated, service_role;

-- Internal helpers must not be browser-callable directly.
revoke all on function public.app_notify_admins(text,text,text,uuid,uuid,jsonb) from public, anon, authenticated;
revoke all on function public.app_signup_throttle_assert_and_register(text) from public, anon, authenticated;

notify pgrst, 'reload schema';

-- ############################################################################
-- END migrations/096_free_signup_pro_payment_approvals.sql
-- ############################################################################

-- ############################################################################
-- BEGIN migrations/097_subscription_lifecycle_and_plan_portal.sql
-- ############################################################################

-- ============================================================================
-- 097_subscription_lifecycle_and_plan_portal.sql
-- Subscription lifecycle corrections + self-service Pro plan portal.
--
-- LIVE-DATABASE SAFETY
--   * Forward-only after 096.
--   * Does NOT UPDATE, DELETE, TRUNCATE, or rewrite any existing user/business
--     row when this migration is installed.
--   * Existing users, sessions, wallets, expenses, inventory, messages, teams,
--     credentials, access dates, and existing subscription rows are preserved.
--   * DML below exists only inside RPCs and runs later after an explicit NEW
--     signup, user plan request, or administrator action.
-- ============================================================================

create extension if not exists pgcrypto with schema extensions;

-- Add lifecycle metadata without rewriting historical rows.
alter table public.app_subscription_requests
  add column if not exists request_context text,
  add column if not exists previous_access_plan text,
  add column if not exists previous_expires_at timestamptz,
  add column if not exists current_expires_at timestamptz,
  add column if not exists proposed_expires_at timestamptz,
  add column if not exists promotion_months integer,
  add column if not exists receipt_deleted_at timestamptz,
  add column if not exists receipt_deleted_by uuid references public.app_users(id) on delete set null;

-- A receipt may be explicitly erased by an administrator after review.
alter table public.app_subscription_requests
  alter column receipt_bytes drop not null;

alter table public.app_subscription_requests
  drop constraint if exists app_subscription_receipt_size;
alter table public.app_subscription_requests
  add constraint app_subscription_receipt_size
  check (receipt_bytes is null or octet_length(receipt_bytes) between 1 and 5242880);

-- Internal projection for pending subscription state. Historical 096 pending
-- requests have NULL lifecycle metadata and are interpreted as signup requests.
create or replace function public.app_subscription_pending_projection(p_user_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  r public.app_subscription_requests;
  ctx text;
  promo int;
  paid_months int;
  base_at timestamptz;
  proposed timestamptz;
begin
  if p_user_id is null then return null; end if;
  select * into r
  from public.app_subscription_requests
  where user_id=p_user_id and status='pending'
  order by created_at desc
  limit 1;
  if r is null then return null; end if;

  ctx := coalesce(nullif(trim(r.request_context),''),'signup');
  paid_months := case when r.billing_period='yearly' then 12 else 1 end;
  promo := coalesce(r.promotion_months,
    case when ctx='signup' then case when r.billing_period='yearly' then 2 else 1 end else 0 end);
  base_at := case
    when ctx='signup' then r.created_at
    else greatest(coalesce(r.current_expires_at, r.created_at), r.created_at)
  end;
  proposed := coalesce(r.proposed_expires_at, base_at + make_interval(months => paid_months + promo));

  return jsonb_build_object(
    'id',r.id,'status',r.status,'request_context',ctx,'billing_period',r.billing_period,
    'billing_currency',r.billing_currency,'total_amount',r.total_amount,
    'team_enabled',r.team_enabled,'team_seats',r.team_seats,
    'promotion_months',promo,'created_at',r.created_at,
    'current_expires_at',coalesce(r.current_expires_at,r.previous_expires_at),
    'proposed_expires_at',proposed,'payment_bank',r.payment_bank,
    'receipt_name',r.receipt_name,'receipt_exists',r.receipt_bytes is not null
  );
end
$fn$;
revoke all on function public.app_subscription_pending_projection(uuid) from public, anon, authenticated;

-- Access flags: paid signup pending approval is a provisional Pro state, not a
-- free-trial state. This is computed dynamically, so 096 rows are not rewritten.
create or replace function public.app_user_access_flags(u public.app_users)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, extensions
as $fn$
declare
  plan text := coalesce(nullif(trim(u.access_plan), ''), 'full');
  expires_at timestamptz := u.trial_expires_at;
  pending jsonb := public.app_subscription_pending_projection(u.id);
  pending_ctx text := coalesce(pending->>'request_context','');
  pending_signup boolean := pending is not null and pending_ctx='signup';
  has_period boolean := false;
  expired boolean := false;
  active_period boolean := false;
  days_left numeric := null;
  days_past numeric := 0;
  grace_active boolean := false;
  grace_days_left numeric := null;
  lock_active boolean := false;
  lock_days_left numeric := null;
  should_disable boolean := false;
  disable_at timestamptz := null;
  lock_at timestamptz := null;
  unlimited boolean := false;
  grace_days constant numeric := 3;
  lock_days constant numeric := 1;
begin
  if coalesce(u.is_protected, false) then
    return jsonb_build_object(
      'access_plan','full','trial_started_at',u.trial_started_at,'trial_expires_at',null,
      'is_trial',false,'trial_active',false,'trial_expired',false,
      'period_active',false,'period_expired',false,'trial_days_remaining',null,
      'has_access_period',false,'unlimited_access',true,'days_past_expiry',0,
      'grace_active',false,'grace_days_left',null,'lock_active',false,'lock_days_left',null,
      'lock_starts_at',null,'should_auto_disable',false,'access_disable_at',null,
      'access_grace_warned_at',u.access_grace_warned_at,
      'access_disabled_for_expiry_at',u.access_disabled_for_expiry_at,
      'data_access_allowed',true,'payment_approval_pending',false
    );
  end if;

  -- Historical paid signups created by 096 were stored as trial rows. Present
  -- them as provisional Pro without mutating those rows during migration.
  if pending_signup then
    plan := 'full';
    expires_at := coalesce((pending->>'proposed_expires_at')::timestamptz, u.trial_expires_at);
  end if;

  if plan='trial' then has_period := true;
  elsif expires_at is not null then has_period := true;
  else unlimited := true;
  end if;

  if has_period then
    if expires_at is null or expires_at <= now() then
      expired := true;
      if expires_at is not null then
        days_past := greatest(0, ceil(extract(epoch from (now()-expires_at))/86400.0));
        lock_at := expires_at + make_interval(days=>grace_days::int);
        disable_at := expires_at + make_interval(days=>(grace_days+lock_days)::int);
        grace_active := days_past < grace_days;
        if grace_active then grace_days_left := greatest(0,grace_days-days_past); end if;
        lock_active := (not grace_active) and days_past < (grace_days+lock_days);
        if lock_active then lock_days_left := greatest(0,(grace_days+lock_days)-days_past); end if;
        should_disable := days_past >= (grace_days+lock_days);
      else
        days_past := grace_days+lock_days; should_disable := true;
      end if;
    else
      active_period := true;
      days_left := greatest(0,ceil(extract(epoch from (expires_at-now()))/86400.0));
      lock_at := expires_at + make_interval(days=>grace_days::int);
      disable_at := expires_at + make_interval(days=>(grace_days+lock_days)::int);
    end if;
  end if;

  -- A pending paid signup remains reviewable and usable until the admin resolves
  -- it. The request's proposed Pro expiry is authoritative for presentation.
  if pending_signup then
    expired := false; grace_active := false; lock_active := false; should_disable := false;
    days_past := 0; grace_days_left := null; lock_days_left := null; lock_at := null; disable_at := null;
    active_period := true; has_period := true; unlimited := false;
    if expires_at is not null then
      days_left := greatest(0,ceil(extract(epoch from (expires_at-now()))/86400.0));
    end if;
  end if;

  return jsonb_build_object(
    'access_plan',plan,'trial_started_at',u.trial_started_at,'trial_expires_at',expires_at,
    'is_trial',plan='trial','trial_active',active_period and plan='trial','trial_expired',expired and plan='trial',
    'period_active',active_period,'period_expired',expired,'trial_days_remaining',days_left,
    'has_access_period',has_period,'unlimited_access',unlimited,'days_past_expiry',days_past,
    'grace_active',grace_active,'grace_days_left',grace_days_left,'lock_active',lock_active,
    'lock_days_left',lock_days_left,'lock_starts_at',lock_at,'should_auto_disable',should_disable,
    'access_disable_at',disable_at,'access_grace_warned_at',u.access_grace_warned_at,
    'access_disabled_for_expiry_at',u.access_disabled_for_expiry_at,
    'data_access_allowed',unlimited or active_period or grace_active or pending_signup,
    'payment_approval_pending',pending is not null,
    'subscription_request_id',case when pending is null then null else pending->>'id' end,
    'subscription_request_context',case when pending is null then null else pending_ctx end,
    'subscription_billing_period',case when pending is null then null else pending->>'billing_period' end,
    'subscription_proposed_expires_at',case when pending is null then null else pending->>'proposed_expires_at' end,
    'subscription_promotion_months',case when pending is null then 0 else coalesce((pending->>'promotion_months')::int,0) end
  );
end
$fn$;
revoke all on function public.app_user_access_flags(public.app_users) from public, anon, authenticated;

-- Shared secure receipt validation helper.
create or replace function public.app_subscription_decode_receipt(
  p_receipt_mime text,
  p_receipt_base64 text
)
returns bytea
language plpgsql
immutable
set search_path = public
as $fn$
declare
  receipt bytea;
  sig text;
begin
  if p_receipt_mime not in ('image/png','image/jpeg','image/webp','application/pdf') then
    raise exception 'Receipt must be PNG, JPG, WebP, or PDF';
  end if;
  if nullif(trim(coalesce(p_receipt_base64,'')),'') is null then
    raise exception 'Attach your payment receipt';
  end if;
  begin
    receipt := decode(regexp_replace(p_receipt_base64,E'\\s','','g'),'base64');
  exception when others then
    raise exception 'Payment receipt could not be read';
  end;
  if octet_length(receipt)>5242880 then raise exception 'Payment receipt must be 5MB or smaller'; end if;
  if octet_length(receipt)<4 then raise exception 'Payment receipt is invalid'; end if;
  sig := lower(encode(substring(receipt from 1 for 16),'hex'));
  if p_receipt_mime='image/png' and left(sig,16)<>'89504e470d0a1a0a' then raise exception 'Invalid PNG receipt'; end if;
  if p_receipt_mime='image/jpeg' and left(sig,6)<>'ffd8ff' then raise exception 'Invalid JPEG receipt'; end if;
  if p_receipt_mime='image/webp' and not(left(sig,8)='52494646' and substring(sig from 17 for 8)='57454250') then raise exception 'Invalid WebP receipt'; end if;
  if p_receipt_mime='application/pdf' and left(sig,8)<>'25504446' then raise exception 'Invalid PDF receipt'; end if;
  return receipt;
end
$fn$;
revoke all on function public.app_subscription_decode_receipt(text,text) from public, anon, authenticated;

-- Updated public signup. Free remains a real 14-day trial. Paid signups receive
-- provisional Pro access and calculated expiry immediately while approval waits.
create or replace function public.app_signup_v2(
  p_plan text,
  p_account_type text,
  p_username text,
  p_password text,
  p_display_name text,
  p_company_name text default null,
  p_company_email text default null,
  p_company_phone text default null,
  p_company_address text default null,
  p_vat_number text default null,
  p_logo_url text default null,
  p_currencies jsonb default '["AED"]'::jsonb,
  p_billing_currency text default 'AED',
  p_team_enabled boolean default false,
  p_team_seats integer default 0,
  p_payment_bank text default null,
  p_receipt_name text default null,
  p_receipt_mime text default null,
  p_receipt_base64 text default null,
  p_user_agent text default null,
  p_ip text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  plan text := lower(trim(coalesce(p_plan,'free')));
  acct text := lower(trim(coalesce(p_account_type,'individual')));
  safe_user text := trim(coalesce(p_username,''));
  billing_cur text := upper(trim(coalesce(p_billing_currency,'AED')));
  is_paid boolean; is_company boolean; team_on boolean; seats int;
  org_id uuid; new_user public.app_users; settings_obj jsonb; tabs jsonb;
  base_tabs text[] := array['dashboard','expenses','inventory','loans','installments','notes','reports','currency_settings'];
  cleaned text[] := array[]::text[]; item jsonb; cur text; has_btc boolean := false;
  price jsonb; req public.app_subscription_requests; receipt bytea; token text;
  started_at timestamptz := now(); expires_at timestamptz;
  promo int; paid_months int;
  v_email text := nullif(trim(coalesce(p_company_email,'')),'');
  v_phone text := nullif(trim(coalesce(p_company_phone,'')),'');
  v_address text := nullif(trim(coalesce(p_company_address,'')),'');
  v_company text := nullif(trim(coalesce(p_company_name,'')),'');
  v_vat text := nullif(trim(coalesce(p_vat_number,'')),'');
  v_logo text := nullif(trim(coalesce(p_logo_url,'')),'');
begin
  if plan not in ('free','monthly','yearly') then raise exception 'Choose Free 14 Days, Pro Monthly, or Pro Yearly'; end if;
  if acct not in ('individual','company') then raise exception 'Choose Individual or Company'; end if;
  is_paid := plan in ('monthly','yearly'); is_company := acct='company';
  team_on := is_company and coalesce(p_team_enabled,false);
  seats := case when team_on then greatest(1,least(coalesce(p_team_seats,1),50)) else 0 end;
  if safe_user !~ '^[a-zA-Z0-9_-]+$' or length(safe_user)<3 then raise exception 'Username must be at least 3 characters and use only letters, numbers, underscores, or hyphens.'; end if;
  perform public.app_assert_password_policy(p_password);
  if nullif(trim(coalesce(p_display_name,'')),'') is null then raise exception 'Name is required'; end if;
  if v_email is null or v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'A valid email address is required'; end if;
  if v_phone is null or length(v_phone)<6 then raise exception 'A valid mobile number is required'; end if;
  if is_company and v_company is null then raise exception 'Company name is required'; end if;
  if is_company and v_address is null then raise exception 'Company address is required'; end if;
  if exists(select 1 from public.app_users where lower(username)=lower(safe_user)) then raise exception 'Username already exists. Please choose another.'; end if;

  if p_currencies is null or jsonb_typeof(p_currencies)<>'array' then raise exception 'Select at least one currency'; end if;
  for item in select * from jsonb_array_elements(p_currencies) loop
    cur := upper(trim(both '"' from item::text));
    if cur=any(array['AED','SAR','PKR','USD','BTC']) and not(cur=any(cleaned)) then cleaned:=array_append(cleaned,cur); end if;
  end loop;
  if coalesce(array_length(cleaned,1),0)<1 then raise exception 'Select at least one currency'; end if;
  if billing_cur not in ('AED','SAR','PKR','USD') then raise exception 'Choose AED, SAR, PKR, or USD as billing currency'; end if;
  if not billing_cur=any(cleaned) then cleaned:=array_prepend(billing_cur,cleaned); end if;
  has_btc := 'BTC'=any(cleaned);
  tabs := to_jsonb(case when has_btc then base_tabs||array['bitcoin'] else base_tabs end);

  if is_paid then
    if lower(trim(coalesce(p_payment_bank,''))) not in ('hbl','enbd') then raise exception 'Choose a bank transfer account'; end if;
    receipt := public.app_subscription_decode_receipt(p_receipt_mime,p_receipt_base64);
    price := public.app_subscription_price(plan,billing_cur,seats);
    promo := case when plan='yearly' then 2 else 1 end;
    paid_months := case when plan='yearly' then 12 else 1 end;
    expires_at := started_at + make_interval(months=>paid_months+promo);
  else
    promo := 0; paid_months := 0; expires_at := started_at + interval '14 days';
  end if;

  perform public.app_signup_throttle_assert_and_register(p_ip);
  select organization_id into org_id from public.app_users where is_protected=true order by created_at limit 1;
  if org_id is null then select organization_id into org_id from public.app_users where role='admin' order by created_at limit 1; end if;
  if org_id is null then insert into public.app_organizations(name) values('Triple M') returning id into org_id; end if;

  settings_obj := jsonb_build_object(
    'Currency',to_jsonb(cleaned),'Tabs',tabs,'BitcoinAccess',case when has_btc then 'both' else 'none' end,
    'Company',coalesce(v_company,''),'TRN',coalesce(v_vat,''),'logo',coalesce(v_logo,''),
    'email',v_email,'Email',v_email,'Mobile',v_phone,'Phone',v_phone,
    'Address',coalesce(v_address,''),'address',coalesce(v_address,''),'Name',trim(p_display_name),
    'SignupPlan',plan,'AccountType',acct,'BillingCurrency',billing_cur,'PaymentApprovalPending',is_paid
  );

  insert into public.app_users(
    organization_id,username,password_hash,admin_visible_password,display_name,role,is_protected,is_active,
    must_change_password,settings,company_name,vat_number,logo_url,company_email,company_phone,company_address,
    access_plan,trial_started_at,trial_expires_at,allow_team_members,max_team_members
  ) values(
    org_id,safe_user,extensions.crypt(p_password,extensions.gen_salt('bf')),null,trim(p_display_name),'user',false,true,
    false,settings_obj,case when is_company then v_company else null end,case when is_company then v_vat else null end,
    v_logo,v_email,v_phone,v_address,case when is_paid then 'full' else 'trial' end,started_at,expires_at,
    team_on,case when team_on then seats else 3 end
  ) returning * into new_user;

  perform public.app_apply_user_currencies(new_user.id,to_jsonb(cleaned));
  perform public.app_apply_tab_permissions(new_user.id,tabs);
  update public.app_permissions set allowed=false where user_id=new_user.id and module='admin_panel';

  if is_paid then
    insert into public.app_subscription_requests(
      user_id,account_type,billing_period,billing_currency,base_amount,team_enabled,team_seats,
      team_unit_amount,team_amount,total_amount,payment_bank,receipt_name,receipt_mime,receipt_bytes,
      request_context,previous_access_plan,previous_expires_at,current_expires_at,proposed_expires_at,promotion_months
    ) values(
      new_user.id,acct,plan,billing_cur,(price->>'base_amount')::numeric,team_on,seats,
      (price->>'team_unit_amount')::numeric,(price->>'team_amount')::numeric,(price->>'total_amount')::numeric,
      lower(trim(p_payment_bank)),left(coalesce(nullif(trim(p_receipt_name),''),'receipt'),200),p_receipt_mime,receipt,
      'signup','trial',started_at+interval '14 days',null,expires_at,promo
    ) returning * into req;

    perform public.app_notify_admins(
      'subscription_payment','Pro payment awaiting approval',
      format('%s (@%s) submitted %s payment of %s %s. Receipt attached.%s',trim(p_display_name),safe_user,
        case when plan='monthly' then 'Pro Monthly' else 'Pro Yearly' end,
        trim(to_char(req.total_amount,'FM999999999990.00')),billing_cur,
        case when team_on then format(' %s paid team seat(s).',seats) else '' end),
      new_user.id,null,
      jsonb_build_object('request_id',req.id,'request_context','signup','plan',plan,'amount',req.total_amount,
        'currency',billing_cur,'payment_bank',req.payment_bank,'team_enabled',team_on,'team_seats',seats,
        'receipt_name',req.receipt_name,'receipt_attached',true,'promotion_months',promo,'proposed_expires_at',expires_at)
    );
  end if;

  perform set_config('app.session_create_authorized','1',true);
  token := public.app_create_session(new_user.id,p_user_agent,p_ip,true);
  perform set_config('app.session_create_authorized','0',true);
  update public.app_users set last_login_at=now(),updated_at=now() where id=new_user.id;
  select * into new_user from public.app_users where id=new_user.id;

  return jsonb_build_object('ok',true,'session_token',token,'user',public.app_user_public_profile(new_user,false),
    'subscription',case when is_paid then jsonb_build_object('id',req.id,'status','pending','plan',plan,
      'currency',billing_cur,'amount',req.total_amount,'promotion_months',promo,'proposed_expires_at',expires_at)
      else jsonb_build_object('status','free_trial') end);
end
$fn$;
revoke all on function public.app_signup_v2(text,text,text,text,text,text,text,text,text,text,text,jsonb,text,boolean,integer,text,text,text,text,text,text) from public;
grant execute on function public.app_signup_v2(text,text,text,text,text,text,text,text,text,text,text,jsonb,text,boolean,integer,text,text,text,text,text,text) to anon, authenticated, service_role;

-- Self-service Pro upgrade / extension for any non-protected main account.
create or replace function public.app_request_pro_subscription(
  p_period text,
  p_billing_currency text,
  p_payment_bank text,
  p_receipt_name text,
  p_receipt_mime text,
  p_receipt_base64 text
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  uid uuid := public.current_app_user_id();
  u public.app_users; period text := lower(trim(coalesce(p_period,'')));
  cur text := upper(trim(coalesce(p_billing_currency,'AED')));
  bank text := lower(trim(coalesce(p_payment_bank,'')));
  seats int := 0; acct text; price jsonb; receipt bytea; req public.app_subscription_requests;
  promo_available boolean; promo int; paid_months int; base_at timestamptz; proposed timestamptz;
  previous_plan text; previous_expiry timestamptz;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into u from public.app_users where id=uid for update;
  if u is null or not u.is_active then raise exception 'Authentication required'; end if;
  if u.is_protected then raise exception 'Protected administrator does not need a paid plan'; end if;
  if u.team_owner_id is not null then raise exception 'Team member plans are managed by the company main account'; end if;
  if period not in ('monthly','yearly') then raise exception 'Choose Pro Monthly or Pro Yearly'; end if;
  if cur not in ('AED','SAR','PKR','USD') then raise exception 'Choose AED, SAR, PKR, or USD'; end if;
  if bank not in ('hbl','enbd') then raise exception 'Choose a bank transfer account'; end if;
  if exists(select 1 from public.app_subscription_requests where user_id=uid and status='pending') then
    raise exception 'A payment approval is already pending for this account';
  end if;

  receipt := public.app_subscription_decode_receipt(p_receipt_mime,p_receipt_base64);
  acct := case when nullif(trim(coalesce(u.company_name,'')),'') is not null or lower(coalesce(u.settings->>'AccountType',''))='company' then 'company' else 'individual' end;
  if acct='company' and coalesce(u.allow_team_members,false) then seats := greatest(1,least(coalesce(u.max_team_members,1),50)); end if;
  price := public.app_subscription_price(period,cur,seats);
  promo_available := not exists(select 1 from public.app_subscription_requests where user_id=uid and status='approved' and admin_action='approve');
  promo := case when promo_available then case when period='yearly' then 2 else 1 end else 0 end;
  paid_months := case when period='yearly' then 12 else 1 end;
  previous_plan := coalesce(nullif(trim(u.access_plan),''),'full'); previous_expiry := u.trial_expires_at;
  base_at := greatest(now(),coalesce(previous_expiry,now()));
  proposed := base_at + make_interval(months=>paid_months+promo);

  insert into public.app_subscription_requests(
    user_id,account_type,billing_period,billing_currency,base_amount,team_enabled,team_seats,
    team_unit_amount,team_amount,total_amount,payment_bank,receipt_name,receipt_mime,receipt_bytes,
    request_context,previous_access_plan,previous_expires_at,current_expires_at,proposed_expires_at,promotion_months
  ) values(
    uid,acct,period,cur,(price->>'base_amount')::numeric,seats>0,seats,
    (price->>'team_unit_amount')::numeric,(price->>'team_amount')::numeric,(price->>'total_amount')::numeric,
    bank,left(coalesce(nullif(trim(p_receipt_name),''),'receipt'),200),p_receipt_mime,receipt,
    'renewal',previous_plan,previous_expiry,previous_expiry,proposed,promo
  ) returning * into req;

  -- A free-trial account becomes provisional Pro immediately while its payment
  -- is reviewed. Existing Pro accounts keep their current access until approval.
  if previous_plan='trial' then
    update public.app_users set access_plan='full',trial_started_at=coalesce(trial_started_at,now()),trial_expires_at=proposed,
      settings=coalesce(settings,'{}'::jsonb)||jsonb_build_object('PaymentApprovalPending',true,'BillingCurrency',cur),updated_at=now()
    where id=uid;
  else
    update public.app_users set settings=coalesce(settings,'{}'::jsonb)||jsonb_build_object('PaymentApprovalPending',true,'BillingCurrency',cur),updated_at=now() where id=uid;
  end if;

  perform public.app_notify_admins(
    'subscription_payment','Pro payment awaiting approval',
    format('%s (@%s) submitted %s payment of %s %s for plan %s. Receipt attached.',
      coalesce(nullif(trim(u.display_name),''),u.username),u.username,
      upper(bank),trim(to_char(req.total_amount,'FM999999999990.00')),cur,
      case when period='yearly' then 'extension (yearly)' else 'extension (monthly)' end),
    uid,null,
    jsonb_build_object('request_id',req.id,'request_context','renewal','plan',period,'amount',req.total_amount,
      'currency',cur,'payment_bank',bank,'team_enabled',seats>0,'team_seats',seats,'receipt_name',req.receipt_name,
      'receipt_attached',true,'promotion_months',promo,'proposed_expires_at',proposed,'current_expires_at',previous_expiry)
  );

  return jsonb_build_object('ok',true,'request',jsonb_build_object(
    'id',req.id,'status','pending','plan',period,'currency',cur,'amount',req.total_amount,
    'promotion_months',promo,'proposed_expires_at',proposed,'team_seats',seats,'receipt_attached',true));
end
$fn$;
revoke all on function public.app_request_pro_subscription(text,text,text,text,text,text) from public;
grant execute on function public.app_request_pro_subscription(text,text,text,text,text,text) to anon, authenticated, service_role;

-- Complete account-side plan status for the Plan & Subscription overlay.
create or replace function public.app_my_subscription_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  uid uuid := public.current_app_user_id();
  u public.app_users; r public.app_subscription_requests; flags jsonb; projection jsonb;
  used_promo boolean; seats int; acct text; approved_period text;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into u from public.app_users where id=uid;
  if u is null then raise exception 'Authentication required'; end if;
  flags := public.app_user_access_flags(u);
  projection := public.app_subscription_pending_projection(uid);
  select * into r from public.app_subscription_requests where user_id=uid order by created_at desc limit 1;
  used_promo := exists(select 1 from public.app_subscription_requests where user_id=uid and status='approved' and admin_action='approve');
  select billing_period into approved_period from public.app_subscription_requests
  where user_id=uid and status='approved' and admin_action='approve'
  order by resolved_at desc nulls last, created_at desc limit 1;
  acct := case when u.team_owner_id is not null then 'team_member' when nullif(trim(coalesce(u.company_name,'')),'') is not null or lower(coalesce(u.settings->>'AccountType',''))='company' then 'company' else 'individual' end;
  seats := case when acct='company' and coalesce(u.allow_team_members,false) then greatest(1,least(coalesce(u.max_team_members,1),50)) else 0 end;

  return jsonb_build_object(
    'ok',true,'has_request',r is not null,'pending',projection is not null,
    'status',case when projection is not null then 'pending' when r is null then null else r.status end,
    'id',case when projection is not null then projection->>'id' when r is null then null else r.id::text end,
    'plan',case when projection is not null then projection->>'billing_period' when r is null then null else r.billing_period end,
    'currency',case when projection is not null then projection->>'billing_currency' when r is null then null else r.billing_currency end,
    'amount',case when projection is not null then (projection->>'total_amount')::numeric when r is null then null else r.total_amount end,
    'team_enabled',seats>0,'team_seats',seats,'account_type',acct,'current_paid_period',approved_period,
    'payment_bank',case when projection is not null then projection->>'payment_bank' when r is null then null else r.payment_bank end,
    'receipt_name',case when projection is not null then projection->>'receipt_name' when r is null then null else r.receipt_name end,
    'receipt_exists',case when projection is not null then coalesce((projection->>'receipt_exists')::boolean,false) when r is null then false else r.receipt_bytes is not null end,
    'request_context',case when projection is not null then projection->>'request_context' when r is null then null else coalesce(r.request_context,'signup') end,
    'promotion_available',not used_promo,'promotion_months',case when projection is not null then coalesce((projection->>'promotion_months')::int,0) when r is null then 0 else coalesce(r.promotion_months,0) end,
    'proposed_expires_at',case when projection is not null then projection->>'proposed_expires_at' when r is null then null else r.proposed_expires_at::text end,
    'created_at',case when projection is not null then projection->>'created_at' when r is null then null else r.created_at::text end,
    'resolved_at',case when r is null then null else r.resolved_at end,'admin_action',case when r is null then null else r.admin_action end,
    'admin_note',case when r is null then '' else coalesce(r.admin_note,'') end,
    'access',flags
  );
end
$fn$;
revoke all on function public.app_my_subscription_status() from public;
grant execute on function public.app_my_subscription_status() to anon, authenticated, service_role;

create or replace function public.app_admin_list_subscription_requests(p_status text default 'pending', p_limit int default 100)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare s text := lower(trim(coalesce(p_status,'pending'))); lim int := greatest(1,least(coalesce(p_limit,100),250));
begin
  perform public.app_require_admin();
  return coalesce((select jsonb_agg(x order by x.created_at desc) from (
    select r.id,r.user_id,u.username,u.display_name,u.company_name,u.company_email,u.company_phone,
      r.account_type,r.billing_period,r.billing_currency,r.base_amount,r.team_enabled,r.team_seats,
      r.team_unit_amount,r.team_amount,r.total_amount,r.payment_bank,r.receipt_name,r.receipt_mime,
      (r.receipt_bytes is not null) receipt_exists,r.receipt_deleted_at,
      r.status,r.admin_action,r.admin_note,r.created_at,r.resolved_at,
      coalesce(r.request_context,'signup') request_context,r.previous_access_plan,r.previous_expires_at,
      r.current_expires_at,r.proposed_expires_at,r.promotion_months
    from public.app_subscription_requests r join public.app_users u on u.id=r.user_id
    where s='all' or r.status=s order by r.created_at desc limit lim
  ) x),'[]'::jsonb);
end
$fn$;
revoke all on function public.app_admin_list_subscription_requests(text,integer) from public;
grant execute on function public.app_admin_list_subscription_requests(text,integer) to anon, authenticated, service_role;

create or replace function public.app_admin_get_subscription_request(p_request_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare x jsonb;
begin
  perform public.app_require_admin();
  select to_jsonb(q) into x from (
    select r.id,r.user_id,u.username,u.display_name,u.company_name,u.company_email,u.company_phone,
      r.account_type,r.billing_period,r.billing_currency,r.base_amount,r.team_enabled,r.team_seats,
      r.team_unit_amount,r.team_amount,r.total_amount,r.payment_bank,r.receipt_name,r.receipt_mime,
      (r.receipt_bytes is not null) receipt_exists,r.receipt_deleted_at,r.status,r.admin_action,r.admin_note,
      r.created_at,r.resolved_at,coalesce(r.request_context,'signup') request_context,
      r.previous_access_plan,r.previous_expires_at,r.current_expires_at,
      coalesce(r.proposed_expires_at,(public.app_subscription_pending_projection(r.user_id)->>'proposed_expires_at')::timestamptz) proposed_expires_at,
      coalesce(r.promotion_months,(public.app_subscription_pending_projection(r.user_id)->>'promotion_months')::int,0) promotion_months
    from public.app_subscription_requests r join public.app_users u on u.id=r.user_id where r.id=p_request_id
  ) q;
  if x is null then raise exception 'Payment request not found'; end if;
  return x;
end
$fn$;
revoke all on function public.app_admin_get_subscription_request(uuid) from public;
grant execute on function public.app_admin_get_subscription_request(uuid) to anon, authenticated, service_role;

create or replace function public.app_admin_get_subscription_receipt(p_request_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare r public.app_subscription_requests;
begin
  perform public.app_require_admin();
  select * into r from public.app_subscription_requests where id=p_request_id;
  if r is null then raise exception 'Payment request not found'; end if;
  if r.receipt_bytes is null then raise exception 'This payment receipt has been deleted'; end if;
  return jsonb_build_object('id',r.id,'name',r.receipt_name,'mime',r.receipt_mime,'base64',encode(r.receipt_bytes,'base64'));
end
$fn$;
revoke all on function public.app_admin_get_subscription_receipt(uuid) from public;
grant execute on function public.app_admin_get_subscription_receipt(uuid) to anon, authenticated, service_role;

create or replace function public.app_admin_delete_subscription_receipt(p_request_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare admin public.app_users := public.app_require_admin(); r public.app_subscription_requests;
begin
  select * into r from public.app_subscription_requests where id=p_request_id for update;
  if r is null then raise exception 'Payment request not found'; end if;
  if r.receipt_bytes is null then return jsonb_build_object('ok',true,'already_deleted',true); end if;
  update public.app_subscription_requests set receipt_bytes=null,receipt_deleted_at=now(),receipt_deleted_by=admin.id where id=p_request_id;
  return jsonb_build_object('ok',true,'deleted',true,'request_id',p_request_id);
end
$fn$;
revoke all on function public.app_admin_delete_subscription_receipt(uuid) from public;
grant execute on function public.app_admin_delete_subscription_receipt(uuid) to anon, authenticated, service_role;

create or replace function public.app_subscription_notify_user(
  p_user_id uuid,p_request_id uuid,p_title text,p_body text,p_event text,p_payload jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
declare dedupe text := 'subscription:'||coalesce(p_request_id::text,'none')||':'||coalesce(p_event,'update');
begin
  if p_user_id is null then return; end if;
  if exists(select 1 from public.app_user_notifications where owner_id=p_user_id and dedupe_key=dedupe) then return; end if;
  insert into public.app_user_notifications(owner_id,kind,title,body,payload,dedupe_key)
  values(p_user_id,'system',coalesce(nullif(trim(p_title),''),'Subscription update'),coalesce(p_body,''),
    coalesce(p_payload,'{}'::jsonb)||jsonb_build_object('type','subscription_'||coalesce(p_event,'update'),'request_id',p_request_id),dedupe);
end
$fn$;
revoke all on function public.app_subscription_notify_user(uuid,uuid,text,text,text,jsonb) from public, anon, authenticated;

-- Admin resolution now preserves/extends the correct period and notifies the user.
create or replace function public.app_admin_resolve_subscription_request(
  p_request_id uuid,
  p_action text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  admin public.app_users := public.app_require_admin();
  r public.app_subscription_requests; u public.app_users;
  action text := lower(trim(coalesce(p_action,''))); ctx text; promo int; paid_months int;
  proposed timestamptz; base_at timestamptz; final_status text; note_text text := nullif(trim(coalesce(p_note,'')),'');
begin
  select * into r from public.app_subscription_requests where id=p_request_id for update;
  if r is null then raise exception 'Payment request not found'; end if;
  if r.status<>'pending' then raise exception 'This payment request has already been resolved'; end if;
  if action not in ('approve','decline','decline_disable','grant_trial','grant_month','grant_3_months','grant_6_months','grant_year','grant_unlimited','delete') then raise exception 'Invalid approval action'; end if;
  select * into u from public.app_users where id=r.user_id;
  if u is null then raise exception 'User not found'; end if;
  ctx := coalesce(nullif(trim(r.request_context),''),'signup');

  if action='delete' then
    perform public.app_admin_delete_user(r.user_id);
    return jsonb_build_object('ok',true,'action','delete','user_id',r.user_id);
  end if;

  paid_months := case when r.billing_period='yearly' then 12 else 1 end;
  promo := coalesce(r.promotion_months,
    case when not exists(select 1 from public.app_subscription_requests z where z.user_id=r.user_id and z.id<>r.id and z.status='approved' and z.admin_action='approve')
      then case when r.billing_period='yearly' then 2 else 1 end else 0 end);
  base_at := case when ctx='signup' then r.created_at else greatest(coalesce(r.current_expires_at,r.previous_expires_at,r.created_at),r.created_at) end;
  proposed := coalesce(r.proposed_expires_at,base_at+make_interval(months=>paid_months+promo));

  if action='approve' then
    update public.app_users set access_plan='full',trial_started_at=coalesce(trial_started_at,r.created_at),trial_expires_at=proposed,
      access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,
      settings=(coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending')||jsonb_build_object('ApprovedPlan',r.billing_period,'BillingCurrency',r.billing_currency),updated_at=now()
    where id=r.user_id;
    final_status := 'approved';
    perform public.app_subscription_notify_user(r.user_id,r.id,'Pro subscription approved',
      format('Your %s payment was approved. Pro access is active until %s.',case when r.billing_period='yearly' then 'yearly' else 'monthly' end,to_char(proposed,'YYYY-MM-DD HH24:MI TZ')),
      'approved',jsonb_build_object('plan',r.billing_period,'expires_at',proposed,'promotion_months',promo,'admin_note',note_text));
  elsif action='decline' then
    if ctx='signup' then
      update public.app_users set access_plan='trial',trial_started_at=coalesce(trial_started_at,r.created_at),
        trial_expires_at=r.created_at+interval '14 days',settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now()
      where id=r.user_id;
      perform public.app_subscription_notify_user(r.user_id,r.id,'Pro payment not approved',
        'Your payment was not received or could not be verified. The provisional Pro subscription was revoked; your free trial remains subject to its original 14-day period.',
        'declined',jsonb_build_object('plan',r.billing_period,'admin_note',note_text));
    else
      update public.app_users set access_plan=coalesce(r.previous_access_plan,access_plan),trial_expires_at=r.previous_expires_at,
        settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now() where id=r.user_id;
      perform public.app_subscription_notify_user(r.user_id,r.id,'Pro extension declined',
        'Your payment was not received or could not be verified. The requested Pro extension was not applied; your existing plan remains unchanged.',
        'declined',jsonb_build_object('plan',r.billing_period,'admin_note',note_text));
    end if;
    final_status := 'declined';
  elsif action='decline_disable' then
    update public.app_users set is_active=false,settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now() where id=r.user_id;
    perform public.app_subscription_notify_user(r.user_id,r.id,'Pro payment declined',
      'Your payment was not received or could not be verified, and the account was disabled by the administrator.',
      'declined',jsonb_build_object('plan',r.billing_period,'admin_note',note_text));
    final_status := 'declined';
  elsif action='grant_trial' then
    update public.app_users set access_plan='trial',trial_started_at=now(),trial_expires_at=now()+interval '14 days',access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now() where id=r.user_id;
    final_status := 'approved'; proposed := now()+interval '14 days';
  elsif action='grant_month' then
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=now()+interval '30 days',access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now() where id=r.user_id;
    final_status := 'approved'; proposed := now()+interval '30 days';
  elsif action='grant_3_months' then
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=now()+interval '90 days',access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now() where id=r.user_id;
    final_status := 'approved'; proposed := now()+interval '90 days';
  elsif action='grant_6_months' then
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=now()+interval '180 days',access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now() where id=r.user_id;
    final_status := 'approved'; proposed := now()+interval '180 days';
  elsif action='grant_year' then
    update public.app_users set access_plan='full',trial_started_at=now(),trial_expires_at=now()+interval '365 days',access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now() where id=r.user_id;
    final_status := 'approved'; proposed := now()+interval '365 days';
  elsif action='grant_unlimited' then
    update public.app_users set access_plan='full',trial_started_at=null,trial_expires_at=null,access_grace_warned_at=null,access_disabled_for_expiry_at=null,is_active=true,settings=coalesce(settings,'{}'::jsonb)-'PaymentApprovalPending',updated_at=now() where id=r.user_id;
    final_status := 'approved'; proposed := null;
  end if;

  if action like 'grant_%' then
    perform public.app_subscription_notify_user(r.user_id,r.id,'Plan access updated',
      case when action='grant_unlimited' then 'The administrator approved unlimited access for your account.' else format('The administrator updated your account access. New expiry: %s.',to_char(proposed,'YYYY-MM-DD HH24:MI TZ')) end,
      'approved',jsonb_build_object('admin_action',action,'expires_at',proposed,'admin_note',note_text));
  end if;

  update public.app_subscription_requests set status=final_status,admin_action=action,admin_note=note_text,resolved_at=now(),resolved_by=admin.id,
    proposed_expires_at=coalesce(app_subscription_requests.proposed_expires_at,proposed),promotion_months=coalesce(app_subscription_requests.promotion_months,promo)
  where id=r.id;

  update public.app_admin_notifications set is_read=true,read_at=coalesce(read_at,now()),read_by=coalesce(read_by,admin.id)
  where kind='subscription_payment' and coalesce(payload->>'request_id','')=r.id::text;

  return jsonb_build_object('ok',true,'action',action,'user_id',r.user_id,'status',final_status,'expires_at',proposed,'promotion_months',promo);
end
$fn$;
revoke all on function public.app_admin_resolve_subscription_request(uuid,text,text) from public;
grant execute on function public.app_admin_resolve_subscription_request(uuid,text,text) to anon, authenticated, service_role;

