-- ============================================================================
-- 098_subscription_receipt_archive_and_details.sql
-- Subscription receipt archive + user-safe request detail RPCs.
--
-- LIVE-DATABASE SAFETY
--   * Forward-only after 097.
--   * Installation does NOT insert, update, delete, truncate, rename, or rewrite
--     any existing user, financial, subscription, receipt, or business row.
--   * Receipt deletion occurs ONLY when a protected administrator explicitly
--     invokes the deletion RPC after deployment.
-- ============================================================================

-- Paginated administrator receipt archive. No receipt bytes are returned here.
create or replace function public.app_admin_list_subscription_receipts(
  p_limit integer default 100,
  p_offset integer default 0,
  p_receipt_state text default 'all'
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  lim integer := greatest(1, least(coalesce(p_limit,100), 250));
  off integer := greatest(0, coalesce(p_offset,0));
  filter_state text := lower(trim(coalesce(p_receipt_state,'all')));
  total_rows integer;
  available_rows integer;
  rows_json jsonb;
begin
  perform public.app_require_admin();
  if filter_state not in ('all','available','deleted') then
    raise exception 'Invalid receipt filter';
  end if;

  select count(*)::integer,
         count(*) filter (where r.receipt_bytes is not null)::integer
    into total_rows, available_rows
  from public.app_subscription_requests r
  where filter_state='all'
     or (filter_state='available' and r.receipt_bytes is not null)
     or (filter_state='deleted' and r.receipt_bytes is null);

  select coalesce(jsonb_agg(to_jsonb(q) order by q.created_at desc),'[]'::jsonb)
    into rows_json
  from (
    select r.id,r.user_id,u.username,u.display_name,u.company_name,
      r.account_type,r.billing_period,r.billing_currency,r.total_amount,
      r.payment_bank,r.receipt_name,r.receipt_mime,
      (r.receipt_bytes is not null) receipt_exists,
      r.receipt_deleted_at,r.status,r.admin_action,r.admin_note,
      r.created_at,r.resolved_at,coalesce(r.request_context,'signup') request_context,
      r.proposed_expires_at,r.promotion_months
    from public.app_subscription_requests r
    join public.app_users u on u.id=r.user_id
    where filter_state='all'
       or (filter_state='available' and r.receipt_bytes is not null)
       or (filter_state='deleted' and r.receipt_bytes is null)
    order by r.created_at desc
    limit lim offset off
  ) q;

  return jsonb_build_object(
    'ok',true,
    'rows',rows_json,
    'total',coalesce(total_rows,0),
    'available',coalesce(available_rows,0),
    'offset',off,
    'limit',lim,
    'has_more',off + jsonb_array_length(rows_json) < coalesce(total_rows,0)
  );
end
$fn$;
revoke all on function public.app_admin_list_subscription_receipts(integer,integer,text) from public;
grant execute on function public.app_admin_list_subscription_receipts(integer,integer,text) to anon, authenticated, service_role;

-- Explicit administrator-only receipt purge. Defining this function is
-- non-destructive; rows change only after a later intentional RPC invocation.
create or replace function public.app_admin_delete_subscription_receipts(
  p_request_ids uuid[] default null,
  p_delete_all boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  admin public.app_users := public.app_require_admin();
  ids uuid[] := coalesce(p_request_ids, array[]::uuid[]);
  changed integer := 0;
begin
  if coalesce(p_delete_all,false) then
    update public.app_subscription_requests
       set receipt_bytes=null,
           receipt_deleted_at=now(),
           receipt_deleted_by=admin.id
     where receipt_bytes is not null;
    get diagnostics changed = row_count;
    return jsonb_build_object('ok',true,'deleted',changed,'scope','all');
  end if;

  if coalesce(array_length(ids,1),0)=0 then
    raise exception 'Select at least one receipt';
  end if;
  if array_length(ids,1) > 250 then
    raise exception 'A maximum of 250 receipts can be deleted at once';
  end if;

  update public.app_subscription_requests
     set receipt_bytes=null,
         receipt_deleted_at=now(),
         receipt_deleted_by=admin.id
   where id=any(ids)
     and receipt_bytes is not null;
  get diagnostics changed = row_count;
  return jsonb_build_object('ok',true,'deleted',changed,'scope','selected');
end
$fn$;
revoke all on function public.app_admin_delete_subscription_receipts(uuid[],boolean) from public;
grant execute on function public.app_admin_delete_subscription_receipts(uuid[],boolean) to anon, authenticated, service_role;

-- Safe request details for the signed-in owner. This lets subscription
-- notifications open as detailed overlays without exposing receipt bytes.
create or replace function public.app_my_subscription_request_details(p_request_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  uid uuid := public.current_app_user_id();
  r public.app_subscription_requests;
  u public.app_users;
  flags jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into r
  from public.app_subscription_requests
  where id=p_request_id and user_id=uid;
  if r is null then raise exception 'Subscription request not found'; end if;
  select * into u from public.app_users where id=uid;
  flags := case when u is null then '{}'::jsonb else public.app_user_access_flags(u) end;

  return jsonb_build_object(
    'ok',true,'id',r.id,'status',r.status,
    'request_context',coalesce(r.request_context,'signup'),
    'plan',r.billing_period,'currency',r.billing_currency,'amount',r.total_amount,
    'account_type',r.account_type,'team_enabled',r.team_enabled,'team_seats',r.team_seats,
    'payment_bank',r.payment_bank,'receipt_name',r.receipt_name,
    'receipt_exists',r.receipt_bytes is not null,
    'promotion_months',coalesce(r.promotion_months,0),
    'previous_access_plan',r.previous_access_plan,'previous_expires_at',r.previous_expires_at,
    'current_expires_at',r.current_expires_at,'proposed_expires_at',r.proposed_expires_at,
    'created_at',r.created_at,'resolved_at',r.resolved_at,
    'admin_action',r.admin_action,'admin_note',coalesce(r.admin_note,''),
    'access',flags
  );
end
$fn$;
revoke all on function public.app_my_subscription_request_details(uuid) from public;
grant execute on function public.app_my_subscription_request_details(uuid) to anon, authenticated, service_role;

