create extension if not exists pgcrypto with schema extensions;

-- Ephemeral capability record for a landing visitor. The raw token is returned
-- once to the browser; only its SHA-256 hash is persisted server-side.
create table if not exists public.app_live_chat_guest_access (
  inquiry_id uuid primary key references public.app_inquiries(id) on delete cascade,
  token_hash text not null unique,
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  last_guest_message_at timestamptz,
  guest_message_count integer not null default 1 check (guest_message_count between 0 and 250)
);

create index if not exists app_live_chat_guest_access_expires_idx
  on public.app_live_chat_guest_access(expires_at);

alter table public.app_live_chat_guest_access enable row level security;
revoke all on table public.app_live_chat_guest_access from public, anon, authenticated;
drop policy if exists app_live_chat_guest_access_deny_all on public.app_live_chat_guest_access;
create policy app_live_chat_guest_access_deny_all
  on public.app_live_chat_guest_access for all to anon, authenticated
  using (false) with check (false);

-- Lightweight abuse ledger keyed by a one-way email fingerprint. It contains no
-- raw email/contact information and is not readable through PostgREST.
create table if not exists public.app_live_chat_start_throttle (
  scope_hash text primary key,
  starts integer not null default 0 check (starts >= 0),
  window_started_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.app_live_chat_start_throttle enable row level security;
revoke all on table public.app_live_chat_start_throttle from public, anon, authenticated;
drop policy if exists app_live_chat_start_throttle_deny_all on public.app_live_chat_start_throttle;
create policy app_live_chat_start_throttle_deny_all
  on public.app_live_chat_start_throttle for all to anon, authenticated
  using (false) with check (false);

create or replace function public.app_live_chat_availability()
returns jsonb
language plpgsql
stable
set search_path = public
as $fn$
declare
  gst_now timestamp := timezone('Asia/Dubai', now());
  hr integer := extract(hour from gst_now)::integer;
  is_open boolean := (hr >= 10 and hr < 17);
begin
  return jsonb_build_object(
    'timezone','GST',
    'timezone_name','Gulf Standard Time',
    'hours_label','10:00 AM – 5:00 PM GST',
    'is_open',is_open,
    'status_label',case when is_open then 'Support is online' else 'Support is currently offline' end,
    'wait_label',case when is_open then 'Typical response: within 15–30 minutes' else 'Replies resume from 10:00 AM GST' end,
    'server_time_gst',to_char(gst_now,'YYYY-MM-DD HH24:MI:SS')
  );
end
$fn$;
revoke all on function public.app_live_chat_availability() from public;
grant execute on function public.app_live_chat_availability() to anon, authenticated, service_role;

create or replace function public.app_live_chat_assert_start_limit(p_email text)
returns void
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  normalized text := lower(trim(coalesce(p_email,'')));
  key_hash text;
  row public.app_live_chat_start_throttle;
begin
  if normalized = '' then return; end if;
  key_hash := encode(extensions.digest('triplem-live-chat:' || normalized,'sha256'),'hex');
  select * into row from public.app_live_chat_start_throttle where scope_hash=key_hash for update;
  if row is null then
    insert into public.app_live_chat_start_throttle(scope_hash,starts,window_started_at,updated_at)
    values(key_hash,1,now(),now());
    return;
  end if;
  if row.window_started_at < now() - interval '2 hours' then
    update public.app_live_chat_start_throttle
       set starts=1,window_started_at=now(),updated_at=now()
     where scope_hash=key_hash;
    return;
  end if;
  if row.starts >= 6 then
    raise exception 'Too many live chat sessions were started recently. Please continue your existing chat or try again later.';
  end if;
  update public.app_live_chat_start_throttle set starts=starts+1,updated_at=now() where scope_hash=key_hash;
end
$fn$;
revoke all on function public.app_live_chat_assert_start_limit(text) from public, anon, authenticated;

create or replace function public.app_live_chat_validate_guest(
  p_inquiry_id uuid,
  p_guest_token text
)
returns public.app_live_chat_guest_access
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access;
  supplied_hash text;
begin
  if p_inquiry_id is null or nullif(trim(coalesce(p_guest_token,'')),'') is null then
    raise exception 'Live chat session is unavailable';
  end if;
  supplied_hash := public.app_hash_token(trim(p_guest_token));
  select * into access_row
    from public.app_live_chat_guest_access
   where inquiry_id=p_inquiry_id and token_hash=supplied_hash;
  if access_row is null then raise exception 'Live chat session is unavailable'; end if;
  if access_row.expires_at <= now() then raise exception 'This live chat session has expired'; end if;
  return access_row;
end
$fn$;
revoke all on function public.app_live_chat_validate_guest(uuid,text) from public, anon, authenticated;

create or replace function public.app_public_live_chat_start(
  p_name text,
  p_mobile text,
  p_email text,
  p_message text
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  v_name text := trim(coalesce(p_name,''));
  v_mobile text := trim(coalesce(p_mobile,''));
  v_email text := lower(trim(coalesce(p_email,'')));
  v_msg text := trim(coalesce(p_message,''));
  inquiry_row public.app_inquiries;
  raw_token text;
  expires timestamptz := now() + interval '2 hours';
  availability jsonb := public.app_live_chat_availability();
  auto_text text;
  messages jsonb;
begin
  if char_length(v_name) < 2 then raise exception 'Please enter your full name'; end if;
  if char_length(v_mobile) < 6 then raise exception 'Please enter a valid contact number'; end if;
  if v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email address'; end if;
  if char_length(v_msg) < 1 then raise exception 'Please write a message'; end if;
  if char_length(v_msg) > 4000 then raise exception 'Message is too long (max 4000 characters)'; end if;

  perform public.app_live_chat_assert_start_limit(v_email);

  insert into public.app_inquiries(
    sender_id,subject,body,status,source,guest_name,guest_email,guest_phone,
    last_message_at,user_last_read_at
  ) values(
    null,'Live Chat Support',v_msg,'open','landing',v_name,v_email,v_mobile,now(),now()
  ) returning * into inquiry_row;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(inquiry_row.id,'guest',null,v_msg);

  auto_text := case when coalesce((availability->>'is_open')::boolean,false) then
    'Thank you, ' || v_name || '. You are connected to Triplem VIP Support. Our live support hours are 10:00 AM to 5:00 PM Gulf Standard Time. We are currently online; typical response time is within 15–30 minutes depending on the queue.'
  else
    'Thank you, ' || v_name || '. Your message has been recorded. Triplem VIP Live Chat Support operates from 10:00 AM to 5:00 PM Gulf Standard Time. Support is currently offline; an administrator will respond during the next support window.'
  end;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,created_at)
  values(inquiry_row.id,'admin',null,auto_text,clock_timestamp()+interval '1 millisecond');

  update public.app_inquiries set last_message_at=now(),updated_at=now() where id=inquiry_row.id
  returning * into inquiry_row;

  raw_token := encode(extensions.gen_random_bytes(32),'hex');
  insert into public.app_live_chat_guest_access(
    inquiry_id,token_hash,expires_at,last_guest_message_at,guest_message_count
  ) values(
    inquiry_row.id,public.app_hash_token(raw_token),expires,now(),1
  );

  perform public.app_notify_admins(
    'inquiry','New live chat',
    format('%s started a live support chat: %s',v_name,left(v_msg,180)),
    null,inquiry_row.id,
    jsonb_build_object('source','live_chat','guest_name',v_name,'guest_email',v_email,'guest_phone',v_mobile,'expires_at',expires)
  );

  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb)
    into messages
    from public.app_inquiry_messages m where m.inquiry_id=inquiry_row.id;

  return jsonb_build_object(
    'ok',true,'inquiry_id',inquiry_row.id,'guest_token',raw_token,'expires_at',expires,
    'availability',availability,'inquiry',public.app_inquiry_public_row(inquiry_row),'messages',messages
  );
end
$fn$;
revoke all on function public.app_public_live_chat_start(text,text,text,text) from public;
grant execute on function public.app_public_live_chat_start(text,text,text,text) to anon, authenticated, service_role;

create or replace function public.app_public_live_chat_thread(
  p_inquiry_id uuid,
  p_guest_token text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access;
  inquiry_row public.app_inquiries;
  messages jsonb := '[]'::jsonb;
begin
  access_row := public.app_live_chat_validate_guest(p_inquiry_id,p_guest_token);
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;
  if inquiry_row is null or inquiry_row.subject <> 'Live Chat Support' then raise exception 'Live chat session is unavailable'; end if;

  update public.app_inquiries set user_last_read_at=now(),updated_at=now() where id=p_inquiry_id
  returning * into inquiry_row;

  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb)
    into messages
    from public.app_inquiry_messages m
   where m.inquiry_id=p_inquiry_id;

  return jsonb_build_object(
    'ok',true,'expires_at',access_row.expires_at,'availability',public.app_live_chat_availability(),
    'inquiry',public.app_inquiry_public_row(inquiry_row),'messages',messages
  );
end
$fn$;
revoke all on function public.app_public_live_chat_thread(uuid,text) from public;
grant execute on function public.app_public_live_chat_thread(uuid,text) to anon, authenticated, service_role;

create or replace function public.app_public_live_chat_reply(
  p_inquiry_id uuid,
  p_guest_token text,
  p_body text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access;
  inquiry_row public.app_inquiries;
  msg text := trim(coalesce(p_body,''));
  new_msg public.app_inquiry_messages;
begin
  if char_length(msg) < 1 then raise exception 'Please write a message'; end if;
  if char_length(msg) > 4000 then raise exception 'Message is too long (max 4000 characters)'; end if;
  access_row := public.app_live_chat_validate_guest(p_inquiry_id,p_guest_token);
  if access_row.guest_message_count >= 250 then raise exception 'This live chat has reached its message limit'; end if;
  if access_row.last_guest_message_at is not null and access_row.last_guest_message_at > now() - interval '500 milliseconds' then
    raise exception 'Please wait a moment before sending another message';
  end if;

  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id for update;
  if inquiry_row is null or inquiry_row.subject <> 'Live Chat Support' then raise exception 'Live chat session is unavailable'; end if;
  if inquiry_row.status='archived' then raise exception 'This conversation has been closed'; end if;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(p_inquiry_id,'guest',null,msg) returning * into new_msg;

  update public.app_inquiries
     set body=msg,status='open',last_message_at=now(),user_last_read_at=now(),updated_at=now()
   where id=p_inquiry_id returning * into inquiry_row;

  update public.app_live_chat_guest_access
     set last_guest_message_at=now(),guest_message_count=guest_message_count+1
   where inquiry_id=p_inquiry_id;

  perform public.app_notify_admins(
    'inquiry','Live chat reply',left(msg,220),null,p_inquiry_id,
    jsonb_build_object('source','live_chat','guest_name',inquiry_row.guest_name,'guest_email',inquiry_row.guest_email,'guest_phone',inquiry_row.guest_phone)
  );

  return jsonb_build_object('ok',true,'message',public.app_message_public_row(new_msg),'inquiry',public.app_inquiry_public_row(inquiry_row));
end
$fn$;
revoke all on function public.app_public_live_chat_reply(uuid,text,text) from public;
grant execute on function public.app_public_live_chat_reply(uuid,text,text) to anon, authenticated, service_role;

-- Remove the historical 10-character minimum from authenticated user messages.
-- Existing rows are untouched; this only changes validation for future messages.
create or replace function public.app_submit_inquiry(
  p_subject text,
  p_body text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  uid uuid := public.current_app_user_id();
  u public.app_users;
  subj text := trim(coalesce(p_subject, ''));
  msg text := trim(coalesce(p_body, ''));
  row public.app_inquiries;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into u from public.app_users where id = uid;
  if u is null or not u.is_active then raise exception 'Authentication required'; end if;
  if char_length(subj) < 3 then raise exception 'Subject must be at least 3 characters'; end if;
  if char_length(subj) > 160 then raise exception 'Subject is too long (max 160 characters)'; end if;
  if char_length(msg) < 1 then raise exception 'Please write a message'; end if;
  if char_length(msg) > 4000 then raise exception 'Message is too long (max 4000 characters)'; end if;

  insert into public.app_inquiries(
    sender_id,subject,body,status,source,guest_name,guest_email,guest_phone,last_message_at,user_last_read_at
  ) values(
    uid,subj,msg,'open','app',coalesce(u.display_name,u.username),u.company_email,u.company_phone,now(),now()
  ) returning * into row;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(row.id,'user',uid,msg);

  perform public.app_notify_admins(
    'inquiry','New inquiry',format('"%s" from %s',subj,coalesce(u.display_name,u.username)),uid,row.id,
    jsonb_build_object('subject',subj,'username',u.username,'display_name',u.display_name,'source','app')
  );
  return public.app_inquiry_public_row(row);
end
$fn$;
revoke all on function public.app_submit_inquiry(text,text) from public;
grant execute on function public.app_submit_inquiry(text,text) to anon, authenticated, service_role;

-- The landing Request Access form receives the same flexible message rule.
create or replace function public.app_public_request_access(
  p_name text,
  p_mobile text,
  p_email text,
  p_message text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  v_name text := trim(coalesce(p_name, ''));
  v_mobile text := trim(coalesce(p_mobile, ''));
  v_email text := lower(trim(coalesce(p_email, '')));
  v_msg text := trim(coalesce(p_message, ''));
  row public.app_inquiries;
begin
  if char_length(v_name) < 2 then raise exception 'Please enter your full name'; end if;
  if char_length(v_mobile) < 6 then raise exception 'Please enter a valid mobile / WhatsApp number'; end if;
  if v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email address'; end if;
  if char_length(v_msg) < 1 then raise exception 'Please write a message'; end if;
  if char_length(v_msg) > 4000 then raise exception 'Message is too long'; end if;

  insert into public.app_inquiries(sender_id,subject,body,status,source,guest_name,guest_email,guest_phone,last_message_at)
  values(null,'Request Access',v_msg,'open','landing',v_name,v_email,v_mobile,now()) returning * into row;
  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(row.id,'guest',null,v_msg);
  perform public.app_notify_admins(
    'inquiry','New access request',format('%s (%s) requested access',v_name,v_email),null,row.id,
    jsonb_build_object('source','landing','guest_name',v_name,'guest_email',v_email,'guest_phone',v_mobile)
  );
  return jsonb_build_object('ok',true,'inquiry_id',row.id,'message','Your request was sent to the administrator.');
end
