create or replace function public.app_admin_live_chat_agent_settings()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  admin public.app_users := public.app_require_admin();
  items jsonb := '[]'::jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',u.id,
    'username',u.username,
    'display_name',coalesce(u.display_name,u.username),
    'role',u.role,
    'is_active',u.is_active,
    'enabled',coalesce(a.enabled,false)
  ) order by lower(coalesce(u.display_name,u.username))),'[]'::jsonb)
  into items
  from public.app_users u
  left join public.app_live_chat_agents a on a.user_id=u.id
  where u.id is distinct from admin.id
    and coalesce(u.is_active,false) is true;
  return jsonb_build_object('ok',true,'items',items);
end
$fn$;
revoke all on function public.app_admin_live_chat_agent_settings() from public;
grant execute on function public.app_admin_live_chat_agent_settings() to anon, authenticated, service_role;

create or replace function public.app_admin_set_live_chat_agents(p_user_ids uuid[] default '{}'::uuid[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  admin public.app_users := public.app_require_admin();
  uid uuid;
  requested uuid[] := coalesce(p_user_ids,'{}'::uuid[]);
  enabled_count int := 0;
begin
  foreach uid in array requested loop
    if not exists(select 1 from public.app_users where id=uid and is_active=true) then
      raise exception 'One selected live-chat agent is unavailable';
    end if;
  end loop;

  insert into public.app_live_chat_agents(user_id,enabled,assigned_by,created_at,updated_at)
  select u.id,(u.id=any(requested)),admin.id,now(),now()
  from public.app_users u
  where u.id is distinct from admin.id and u.is_active=true
  on conflict(user_id) do update set
    enabled=excluded.enabled,
    assigned_by=excluded.assigned_by,
    updated_at=now();

  update public.app_live_chat_agents a
     set enabled=false,assigned_by=admin.id,updated_at=now()
   where a.user_id<>all(requested)
     and not exists(select 1 from public.app_users u where u.id=a.user_id and u.is_active=true);

  select count(*)::int into enabled_count
  from public.app_live_chat_agents a
  join public.app_users u on u.id=a.user_id and u.is_active=true
  where a.enabled=true;

  return jsonb_build_object('ok',true,'enabled_count',enabled_count);
end
$fn$;
revoke all on function public.app_admin_set_live_chat_agents(uuid[]) from public;
grant execute on function public.app_admin_set_live_chat_agents(uuid[]) to anon, authenticated, service_role;

create or replace function public.app_live_chat_notify_available_agents(p_inquiry_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $fn$
declare
  i public.app_inquiries;
  expiry timestamptz;
  n int := 0;
begin
  select * into i from public.app_inquiries where id=p_inquiry_id;
  if i is null or lower(coalesce(i.subject,''))<>'live chat support' then return 0; end if;
  select expires_at into expiry from public.app_live_chat_guest_access where inquiry_id=p_inquiry_id;

  insert into public.app_user_notifications(owner_id,kind,title,body,payload,dedupe_key)
  select a.user_id,'system','Live chat waiting',
    format('%s is waiting for Triplem VIP Live Support. Accept the chat to begin assisting them.',coalesce(nullif(trim(i.guest_name),''),'A visitor')),
    jsonb_build_object(
      'type','live_chat_assignment',
      'inquiry_id',i.id,
      'guest_name',coalesce(i.guest_name,''),
      'guest_email',coalesce(i.guest_email,''),
      'guest_phone',coalesce(i.guest_phone,''),
      'message',left(coalesce(i.body,''),220),
      'expires_at',expiry
    ),
    'live-chat-assignment:'||i.id::text||':'||a.user_id::text
  from public.app_live_chat_agents a
  join public.app_users u on u.id=a.user_id
  where a.enabled=true and u.is_active=true
  on conflict(owner_id,dedupe_key) where dedupe_key is not null do nothing;
  get diagnostics n = row_count;
  return n;
end
$fn$;
revoke all on function public.app_live_chat_notify_available_agents(uuid) from public, anon, authenticated;

create or replace function public.app_live_chat_accept_assignment(p_inquiry_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  uid uuid := public.current_app_user_id();
  u public.app_users;
  route public.app_live_chat_routes;
  inquiry_row public.app_inquiries;
  expiry timestamptz;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into u from public.app_users where id=uid;
  if u is null or not u.is_active then raise exception 'Authentication required'; end if;
  if not exists(select 1 from public.app_live_chat_agents where user_id=uid and enabled=true) then
    raise exception 'You are not assigned to Live Chat Support';
  end if;

  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id for update;
  if route is null then raise exception 'Live chat assignment is unavailable'; end if;
  if route.status='closed' then raise exception 'This live chat has already ended'; end if;
  if route.status='accepted' and route.assigned_user_id is distinct from uid then
    raise exception 'This live chat has already been accepted by another support agent';
  end if;
  select expires_at into expiry from public.app_live_chat_guest_access where inquiry_id=p_inquiry_id;
  if expiry is null or expiry<=now() then raise exception 'This live chat has expired'; end if;

  update public.app_live_chat_routes
     set assigned_user_id=uid,status='accepted',accepted_at=coalesce(accepted_at,now()),updated_at=now()
   where inquiry_id=p_inquiry_id
   returning * into route;

  update public.app_user_notifications
     set is_read=true,read_at=coalesce(read_at,now())
   where kind='system'
     and payload->>'type'='live_chat_assignment'
     and payload->>'inquiry_id'=p_inquiry_id::text;

  update public.app_inquiries
     set admin_last_read_at=now(),status=case when status='open' then 'read' else status end,updated_at=now()
   where id=p_inquiry_id returning * into inquiry_row;

  return jsonb_build_object('ok',true,'accepted',true,'inquiry',public.app_inquiry_public_row(inquiry_row));
end
$fn$;
revoke all on function public.app_live_chat_accept_assignment(uuid) from public;
grant execute on function public.app_live_chat_accept_assignment(uuid) to anon, authenticated, service_role;

create or replace function public.app_live_chat_agent_end(p_inquiry_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  uid uuid := public.current_app_user_id();
  route public.app_live_chat_routes;
  m public.app_inquiry_messages;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id for update;
  if route is null or route.status<>'accepted' or route.assigned_user_id is distinct from uid then
    raise exception 'This live chat is not assigned to you';
  end if;
  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(p_inquiry_id,'admin',null,'This live chat has been closed. If you need further assistance, you can start a new chat and our support team will be happy to help.') returning * into m;
  update public.app_live_chat_routes set status='closed',closed_at=now(),updated_at=now() where inquiry_id=p_inquiry_id;
  update public.app_inquiries set status='archived',last_message_at=now(),updated_at=now() where id=p_inquiry_id;
  return jsonb_build_object('ok',true,'closed',true,'message',public.app_message_public_row(m));
end
$fn$;
revoke all on function public.app_live_chat_agent_end(uuid) from public;
grant execute on function public.app_live_chat_agent_end(uuid) to anon, authenticated, service_role;

create or replace function public.app_live_chat_maybe_idle_followup(p_inquiry_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  route public.app_live_chat_routes;
  human_msg public.app_inquiry_messages;
  guest_at timestamptz;
  st public.app_live_chat_idle_state;
  elapsed interval;
  new_msg public.app_inquiry_messages;
  inserted boolean := false;
  closed boolean := false;
begin
  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id;
  if route is null or route.status='closed' then return jsonb_build_object('inserted',false,'closed',route.status='closed'); end if;

  select * into human_msg
  from public.app_inquiry_messages
  where inquiry_id=p_inquiry_id and sender_role='admin' and sender_id is not null
  order by created_at desc limit 1;
  if human_msg is null then return jsonb_build_object('inserted',false,'closed',false); end if;

  select max(created_at) into guest_at
  from public.app_inquiry_messages
  where inquiry_id=p_inquiry_id and sender_role='guest';
  if guest_at is not null and guest_at>human_msg.created_at then
    return jsonb_build_object('inserted',false,'closed',false);
  end if;

  insert into public.app_live_chat_idle_state(inquiry_id,watched_message_id,updated_at)
  values(p_inquiry_id,human_msg.id,now())
  on conflict(inquiry_id) do update set
    watched_message_id=case when app_live_chat_idle_state.watched_message_id is distinct from excluded.watched_message_id then excluded.watched_message_id else app_live_chat_idle_state.watched_message_id end,
    first_reminder_at=case when app_live_chat_idle_state.watched_message_id is distinct from excluded.watched_message_id then null else app_live_chat_idle_state.first_reminder_at end,
    second_reminder_at=case when app_live_chat_idle_state.watched_message_id is distinct from excluded.watched_message_id then null else app_live_chat_idle_state.second_reminder_at end,
    auto_closed_at=case when app_live_chat_idle_state.watched_message_id is distinct from excluded.watched_message_id then null else app_live_chat_idle_state.auto_closed_at end,
    updated_at=now();
  select * into st from public.app_live_chat_idle_state where inquiry_id=p_inquiry_id for update;
  elapsed := now()-human_msg.created_at;

  if elapsed>=interval '9 minutes' and st.auto_closed_at is null then
    insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
    values(p_inquiry_id,'admin',null,'This live chat has now closed due to inactivity. If you still need assistance, please start a new chat and we will be glad to continue helping you.') returning * into new_msg;
    update public.app_live_chat_idle_state set auto_closed_at=now(),updated_at=now() where inquiry_id=p_inquiry_id;
    update public.app_live_chat_routes set status='closed',closed_at=now(),updated_at=now() where inquiry_id=p_inquiry_id;
    update public.app_inquiries set status='archived',last_message_at=now(),updated_at=now() where id=p_inquiry_id;
    inserted:=true; closed:=true;
  elsif elapsed>=interval '7 minutes' and st.second_reminder_at is null then
    insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
    values(p_inquiry_id,'admin',null,'We have not heard back from you yet. This live chat may close automatically in about 2 minutes due to inactivity. If there is anything else we can help you with, please send a reply and we will continue assisting you.') returning * into new_msg;
    update public.app_live_chat_idle_state set second_reminder_at=now(),updated_at=now() where inquiry_id=p_inquiry_id;
    update public.app_inquiries set last_message_at=now(),updated_at=now() where id=p_inquiry_id;
    inserted:=true;
  elsif elapsed>=interval '5 minutes' and st.first_reminder_at is null then
    insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
    values(p_inquiry_id,'admin',null,'Just checking in. Are you still with us? If you need a moment, no problem. Reply whenever you are ready and we will continue assisting you.') returning * into new_msg;
    update public.app_live_chat_idle_state set first_reminder_at=now(),updated_at=now() where inquiry_id=p_inquiry_id;
    update public.app_inquiries set last_message_at=now(),updated_at=now() where id=p_inquiry_id;
    inserted:=true;
  end if;
  return jsonb_build_object('inserted',inserted,'closed',closed);
end
$fn$;
revoke all on function public.app_live_chat_maybe_idle_followup(uuid) from public, anon, authenticated;

create or replace function public.app_inquiry_public_row(i public.app_inquiries)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  sender public.app_users;
  assigned public.app_users;
  route public.app_live_chat_routes;
  msg_count int := 0;
  last_preview text := '';
  last_role text := null;
  unread_admin int := 0;
  unread_user int := 0;
begin
  if i.sender_id is not null then select * into sender from public.app_users where id=i.sender_id; end if;
  select * into route from public.app_live_chat_routes where inquiry_id=i.id;
  if route.assigned_user_id is not null then select * into assigned from public.app_users where id=route.assigned_user_id; end if;
  select count(*)::int into msg_count from public.app_inquiry_messages m where m.inquiry_id=i.id;
  select m.body,m.sender_role into last_preview,last_role from public.app_inquiry_messages m where m.inquiry_id=i.id order by m.created_at desc limit 1;
  if last_preview is null then last_preview:=i.body; end if;
  select count(*)::int into unread_admin from public.app_inquiry_messages m where m.inquiry_id=i.id and m.sender_role in ('user','guest') and (i.admin_last_read_at is null or m.created_at>i.admin_last_read_at);
  select count(*)::int into unread_user from public.app_inquiry_messages m where m.inquiry_id=i.id and m.sender_role='admin' and (i.user_last_read_at is null or m.created_at>i.user_last_read_at);
  return jsonb_build_object(
    'id',i.id,'sender_id',i.sender_id,'sender_username',coalesce(sender.username,''),
    'sender_display_name',coalesce(nullif(trim(coalesce(i.guest_name,'')),''),sender.display_name,sender.username,'Guest'),
    'sender_email',coalesce(nullif(trim(coalesce(i.guest_email,'')),''),sender.company_email,''),
    'sender_phone',coalesce(nullif(trim(coalesce(i.guest_phone,'')),''),sender.company_phone,''),
    'sender_company',coalesce(sender.company_name,''),'guest_name',coalesce(i.guest_name,''),'guest_email',coalesce(i.guest_email,''),'guest_phone',coalesce(i.guest_phone,''),
    'source',coalesce(i.source,'app'),'subject',i.subject,'body',i.body,'status',i.status,'admin_note',coalesce(i.admin_note,''),
    'message_count',msg_count,'last_message_preview',left(coalesce(last_preview,''),180),'last_message_role',last_role,
    'last_message_at',coalesce(i.last_message_at,i.updated_at,i.created_at),'unread_for_admin',unread_admin,'unread_for_user',unread_user,
    'support_assignment_status',coalesce(route.status,''),'support_assigned_to',route.assigned_user_id,
    'support_assigned_username',coalesce(assigned.username,''),'support_assigned_name',coalesce(assigned.display_name,assigned.username,''),
    'created_at',i.created_at,'updated_at',i.updated_at,'read_at',i.read_at
  );
end
$fn$;

create or replace function public.app_public_live_chat_start(p_name text,p_mobile text,p_email text,p_message text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  v_name text:=trim(coalesce(p_name,'')); v_mobile text:=trim(coalesce(p_mobile,'')); v_email text:=lower(trim(coalesce(p_email,''))); v_msg text:=trim(coalesce(p_message,''));
  inquiry_row public.app_inquiries; raw_token text; expires timestamptz:=now()+interval '2 hours'; availability jsonb:=public.app_live_chat_availability(); auto_text text; messages jsonb; agent_notices int:=0;
begin
  if char_length(v_name)<2 then raise exception 'Please enter your full name'; end if;
  if char_length(v_mobile)<6 then raise exception 'Please enter a valid contact number'; end if;
  if v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email address'; end if;
  if char_length(v_msg)<1 then raise exception 'Please write a message'; end if;
  if char_length(v_msg)>4000 then raise exception 'Message is too long (max 4000 characters)'; end if;
  perform public.app_live_chat_assert_start_limit(v_email);
  insert into public.app_inquiries(sender_id,subject,body,status,source,guest_name,guest_email,guest_phone,last_message_at,user_last_read_at)
  values(null,'Live Chat Support',v_msg,'open','landing',v_name,v_email,v_mobile,now(),now()) returning * into inquiry_row;
  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body) values(inquiry_row.id,'guest',null,v_msg);
  auto_text:=case when coalesce((availability->>'is_open')::boolean,false) then
    'Thank you, '||v_name||'. You are connected to Triplem VIP Support. Our live support hours are 10:00 AM to 5:00 PM Gulf Standard Time. We are currently online; a support representative will respond as soon as possible.'
  else 'Thank you, '||v_name||'. Your message has been recorded. Triplem VIP Live Chat Support operates from 10:00 AM to 5:00 PM Gulf Standard Time. Support is currently offline; a representative will respond during the next support window.' end;
  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,created_at) values(inquiry_row.id,'admin',null,auto_text,clock_timestamp()+interval '1 millisecond');
  update public.app_inquiries set last_message_at=now(),updated_at=now() where id=inquiry_row.id returning * into inquiry_row;
  raw_token:=encode(extensions.gen_random_bytes(32),'hex');
  insert into public.app_live_chat_guest_access(inquiry_id,token_hash,expires_at,last_guest_message_at,guest_message_count)
  values(inquiry_row.id,public.app_hash_token(raw_token),expires,now(),1);
  insert into public.app_live_chat_routes(inquiry_id,status,created_at,updated_at) values(inquiry_row.id,'pending',now(),now()) on conflict(inquiry_id) do nothing;
  agent_notices:=public.app_live_chat_notify_available_agents(inquiry_row.id);
  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb) into messages from public.app_inquiry_messages m where m.inquiry_id=inquiry_row.id;
  return jsonb_build_object('ok',true,'inquiry_id',inquiry_row.id,'guest_token',raw_token,'expires_at',expires,'availability',availability,'inquiry',public.app_inquiry_public_row(inquiry_row),'messages',messages,'support_queue',agent_notices);
end
$fn$;
revoke all on function public.app_public_live_chat_start(text,text,text,text) from public;
grant execute on function public.app_public_live_chat_start(text,text,text,text) to anon,authenticated,service_role;

create or replace function public.app_public_live_chat_thread(p_inquiry_id uuid,p_guest_token text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access; inquiry_row public.app_inquiries; route public.app_live_chat_routes; messages jsonb:='[]'::jsonb; idle jsonb;
begin
  access_row:=public.app_live_chat_validate_guest(p_inquiry_id,p_guest_token);
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;
  if inquiry_row is null or inquiry_row.subject<>'Live Chat Support' then raise exception 'Live chat session is unavailable'; end if;
  insert into public.app_live_chat_routes(inquiry_id,status,created_at,updated_at)
  values(p_inquiry_id,'pending',now(),now())
  on conflict(inquiry_id) do nothing;
  if found then perform public.app_live_chat_notify_available_agents(p_inquiry_id); end if;
  idle:=public.app_live_chat_maybe_idle_followup(p_inquiry_id);
  update public.app_inquiries set user_last_read_at=now(),updated_at=now() where id=p_inquiry_id returning * into inquiry_row;
  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id;
  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb) into messages from public.app_inquiry_messages m where m.inquiry_id=p_inquiry_id;
  return jsonb_build_object('ok',true,'expires_at',access_row.expires_at,'availability',public.app_live_chat_availability(),'inquiry',public.app_inquiry_public_row(inquiry_row),'messages',messages,'chat_closed',coalesce(route.status='closed',inquiry_row.status='archived'));
end
$fn$;
revoke all on function public.app_public_live_chat_thread(uuid,text) from public;
grant execute on function public.app_public_live_chat_thread(uuid,text) to anon,authenticated,service_role;

create or replace function public.app_public_live_chat_reply(p_inquiry_id uuid,p_guest_token text,p_body text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access; inquiry_row public.app_inquiries; route public.app_live_chat_routes; msg text:=trim(coalesce(p_body,'')); new_msg public.app_inquiry_messages;
begin
  if char_length(msg)<1 then raise exception 'Please write a message'; end if;
  if char_length(msg)>4000 then raise exception 'Message is too long (max 4000 characters)'; end if;
  access_row:=public.app_live_chat_validate_guest(p_inquiry_id,p_guest_token);
  if access_row.guest_message_count>=250 then raise exception 'This live chat has reached its message limit'; end if;
  if access_row.last_guest_message_at is not null and access_row.last_guest_message_at>now()-interval '500 milliseconds' then raise exception 'Please wait a moment before sending another message'; end if;
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id for update;
  if inquiry_row is null or inquiry_row.subject<>'Live Chat Support' then raise exception 'Live chat session is unavailable'; end if;
  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id;
  if inquiry_row.status='archived' or route.status='closed' then raise exception 'This live chat has ended. Please start a new chat if you still need help.'; end if;
  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body) values(p_inquiry_id,'guest',null,msg) returning * into new_msg;
  update public.app_inquiries set body=msg,status=case when route.status='accepted' then 'read' else 'open' end,last_message_at=now(),user_last_read_at=now(),updated_at=now() where id=p_inquiry_id returning * into inquiry_row;
  update public.app_live_chat_guest_access set last_guest_message_at=now(),guest_message_count=guest_message_count+1 where inquiry_id=p_inquiry_id;
  return jsonb_build_object('ok',true,'message',public.app_message_public_row(new_msg),'inquiry',public.app_inquiry_public_row(inquiry_row));
end
$fn$;
revoke all on function public.app_public_live_chat_reply(uuid,text,text) from public;
grant execute on function public.app_public_live_chat_reply(uuid,text,text) to anon,authenticated,service_role;

create or replace function public.app_list_my_inquiries()
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare uid uuid:=public.current_app_user_id(); items jsonb:='[]'::jsonb;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select coalesce(jsonb_agg(public.app_inquiry_public_row(i) order by coalesce(i.last_message_at,i.created_at) desc),'[]'::jsonb) into items
  from public.app_inquiries i
  where i.sender_id=uid or exists(select 1 from public.app_live_chat_routes r where r.inquiry_id=i.id and r.status='accepted' and r.assigned_user_id=uid);
  return jsonb_build_object('items',items);
end
$fn$;

create or replace function public.app_admin_list_inquiries(p_status text default null,p_limit int default 100)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare items jsonb:='[]'::jsonb; lim int:=greatest(1,least(coalesce(p_limit,100),300)); st text:=nullif(trim(coalesce(p_status,'')),'');
begin
  perform public.app_require_admin_comms();
  select coalesce(jsonb_agg(public.app_inquiry_public_row(i) order by coalesce(i.last_message_at,i.created_at) desc),'[]'::jsonb) into items
  from (
    select * from public.app_inquiries q
    where (st is null or q.status=st)
      and not exists(select 1 from public.app_live_chat_routes r where r.inquiry_id=q.id and r.status='accepted' and r.assigned_user_id is not null)
    order by coalesce(q.last_message_at,q.created_at) desc limit lim
  ) i;
  return jsonb_build_object('items',items);
end
$fn$;

create or replace function public.app_get_inquiry_thread(p_inquiry_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  uid uuid:=public.current_app_user_id(); u public.app_users; row public.app_inquiries; route public.app_live_chat_routes; msgs jsonb:='[]'::jsonb; is_admin boolean:=false; is_support boolean:=false;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into u from public.app_users where id=uid;
  if u is null or not u.is_active then raise exception 'Authentication required'; end if;
  is_admin:=(u.role='admin' and u.is_active);
  select * into row from public.app_inquiries where id=p_inquiry_id;
  if row is null then raise exception 'Conversation not found'; end if;
  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id;
  is_support:=coalesce(route.status='accepted' and route.assigned_user_id=uid,false);
  if not is_admin and not is_support and row.sender_id is distinct from uid then raise exception 'Access denied'; end if;
  if is_admin or is_support then
    update public.app_inquiries set admin_last_read_at=now(),status=case when status='open' then 'read' else status end,read_at=coalesce(read_at,now()),read_by=coalesce(read_by,uid),updated_at=now() where id=p_inquiry_id returning * into row;
    if is_admin then update public.app_admin_notifications set is_read=true,read_at=coalesce(read_at,now()),read_by=uid where related_inquiry_id=p_inquiry_id and is_read=false; end if;
  else
    update public.app_inquiries set user_last_read_at=now(),updated_at=now() where id=p_inquiry_id returning * into row;
  end if;
  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb) into msgs from public.app_inquiry_messages m where m.inquiry_id=p_inquiry_id;
  return jsonb_build_object(
    'inquiry',public.app_inquiry_public_row(row),
    'messages',msgs,
    'can_reply',(
      is_support
      or (is_admin and not coalesce(route.status='accepted' and route.assigned_user_id is not null,true))
      or (row.sender_id=uid and row.source='app' and row.status<>'archived')
    )
  );
end
$fn$;

create or replace function public.app_reply_inquiry(p_inquiry_id uuid,p_body text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  uid uuid:=public.current_app_user_id(); u public.app_users; row public.app_inquiries; route public.app_live_chat_routes; msg text:=trim(coalesce(p_body,'')); new_msg public.app_inquiry_messages; role text; is_admin boolean:=false; is_support boolean:=false;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into u from public.app_users where id=uid;
  if u is null or not u.is_active then raise exception 'Authentication required'; end if;
  is_admin:=(u.role='admin');
  if char_length(msg)<1 then raise exception 'Please write a reply'; end if;
  if char_length(msg)>4000 then raise exception 'Reply is too long'; end if;
  select * into row from public.app_inquiries where id=p_inquiry_id for update;
  if row is null then raise exception 'Conversation not found'; end if;
  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id;
  is_support:=coalesce(route.status='accepted' and route.assigned_user_id=uid,false);
  if is_admin and coalesce(route.status='accepted' and route.assigned_user_id is not null,false) and not is_support then
    raise exception 'This live chat has been transferred to its assigned support agent';
  end if;
  if is_admin or is_support then role:='admin';
  elsif row.sender_id=uid and row.source='app' then role:='user';
  else raise exception 'You cannot reply to this conversation'; end if;
  if row.status='archived' and not is_admin then raise exception 'This conversation is closed'; end if;
  if row.sender_id is null and not is_admin and not is_support then raise exception 'Access denied'; end if;
  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body) values(p_inquiry_id,role,uid,msg) returning * into new_msg;
  update public.app_inquiries set last_message_at=now(),updated_at=now(),status=case when (is_admin or is_support) and status='archived' then status when is_admin or is_support then 'read' else 'open' end,
    admin_last_read_at=case when is_admin or is_support then now() else admin_last_read_at end,
    user_last_read_at=case when not is_admin and not is_support then now() else user_last_read_at end,
    body=case when role in ('user','guest') then msg else body end
  where id=p_inquiry_id returning * into row;
  if not is_admin and not is_support then perform public.app_notify_admins('inquiry','New reply',format('Reply on "%s" from %s',row.subject,coalesce(u.display_name,u.username)),uid,row.id,jsonb_build_object('subject',row.subject,'reply',true)); end if;
  return jsonb_build_object('ok',true,'message',public.app_message_public_row(new_msg),'inquiry',public.app_inquiry_public_row(row));
end
$fn$;

create or replace function public.app_messaging_sync_state()
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  uid uuid:=public.current_app_user_id(); u public.app_users; is_admin boolean:=false; notif_count int:=0; inquiry_unread int:=0; user_unread int:=0; user_notif_unread int:=0; inquiry_count int:=0; open_count int:=0; message_total bigint:=0; latest_msg_at timestamptz; latest_updated_at timestamptz; latest_notif_at timestamptz; latest_user_notif_at timestamptz; fp text;
begin
  if uid is null then raise exception 'Authentication required'; end if;
  select * into u from public.app_users where id=uid;
  if u is null or not u.is_active then raise exception 'Authentication required'; end if;
  is_admin:=(u.role='admin' and coalesce(u.access_plan,'full')<>'trial');
  select count(*)::int,max(created_at) into user_notif_unread,latest_user_notif_at from public.app_user_notifications where owner_id=uid and is_read=false;
  if latest_user_notif_at is null then select max(created_at) into latest_user_notif_at from public.app_user_notifications where owner_id=uid; end if;

  if is_admin then
    select count(*)::int into notif_count from public.app_admin_notifications n where n.is_read=false and not(coalesce(n.payload->>'source','')='live_chat');
    select max(created_at) into latest_notif_at from public.app_admin_notifications n where not(coalesce(n.payload->>'source','')='live_chat');
    select count(*)::int into inquiry_unread from public.app_inquiries i
    where not exists(select 1 from public.app_live_chat_routes r where r.inquiry_id=i.id and r.status='accepted' and r.assigned_user_id is not null)
      and (exists(select 1 from public.app_inquiry_messages m where m.inquiry_id=i.id and m.sender_role in ('user','guest') and (i.admin_last_read_at is null or m.created_at>i.admin_last_read_at)) or i.status='open');
    select count(*)::int,count(*) filter(where i.status='open')::int,max(coalesce(i.last_message_at,i.updated_at,i.created_at)),max(i.updated_at)
    into inquiry_count,open_count,latest_msg_at,latest_updated_at from public.app_inquiries i
    where not exists(select 1 from public.app_live_chat_routes r where r.inquiry_id=i.id and r.status='accepted' and r.assigned_user_id is not null);
    select count(*)::bigint into message_total from public.app_inquiry_messages m join public.app_inquiries i on i.id=m.inquiry_id
    where not exists(select 1 from public.app_live_chat_routes r where r.inquiry_id=i.id and r.status='accepted' and r.assigned_user_id is not null);
    fp:=format('a|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s',notif_count,inquiry_unread,inquiry_count,open_count,coalesce(message_total,0),coalesce(extract(epoch from latest_msg_at)::bigint,0),coalesce(extract(epoch from latest_updated_at)::bigint,0),coalesce(extract(epoch from latest_notif_at)::bigint,0),user_notif_unread,coalesce(extract(epoch from latest_user_notif_at)::bigint,0));
    return jsonb_build_object('role','admin','fingerprint',fp,'notifications',notif_count+user_notif_unread,'admin_notifications',notif_count,'user_notifications',user_notif_unread,'inquiries',inquiry_unread,'inquiry_count',inquiry_count,'open_count',open_count,'message_total',coalesce(message_total,0),'latest_message_at',latest_msg_at,'latest_notification_at',greatest(latest_notif_at,latest_user_notif_at));
  end if;

  select count(*)::int,max(coalesce(i.last_message_at,i.updated_at,i.created_at)),max(i.updated_at) into inquiry_count,latest_msg_at,latest_updated_at
  from public.app_inquiries i where i.sender_id=uid or exists(select 1 from public.app_live_chat_routes r where r.inquiry_id=i.id and r.status='accepted' and r.assigned_user_id=uid);
  select count(*)::bigint into message_total from public.app_inquiry_messages m join public.app_inquiries i on i.id=m.inquiry_id
  where i.sender_id=uid or exists(select 1 from public.app_live_chat_routes r where r.inquiry_id=i.id and r.status='accepted' and r.assigned_user_id=uid);
  select coalesce(sum(x.c),0)::int into user_unread from (
    select count(*)::int c from public.app_inquiries i join public.app_inquiry_messages m on m.inquiry_id=i.id
      where i.sender_id=uid and m.sender_role='admin' and (i.user_last_read_at is null or m.created_at>i.user_last_read_at)
    union all
    select count(*)::int c from public.app_inquiries i join public.app_live_chat_routes r on r.inquiry_id=i.id join public.app_inquiry_messages m on m.inquiry_id=i.id
      where r.status='accepted' and r.assigned_user_id=uid and m.sender_role='guest' and (i.admin_last_read_at is null or m.created_at>i.admin_last_read_at)
  ) x;
  fp:=format('u|%s|%s|%s|%s|%s|%s|%s',user_unread,inquiry_count,coalesce(message_total,0),coalesce(extract(epoch from latest_msg_at)::bigint,0),coalesce(extract(epoch from latest_updated_at)::bigint,0),user_notif_unread,coalesce(extract(epoch from latest_user_notif_at)::bigint,0));
  return jsonb_build_object('role','user','fingerprint',fp,'notifications',user_notif_unread,'user_notifications',user_notif_unread,'inquiries',user_unread,'user_unread',user_unread,'inquiry_count',inquiry_count,'message_total',coalesce(message_total,0),'latest_message_at',latest_msg_at,'latest_notification_at',latest_user_notif_at);
end
$fn$;

