-- ============================================================================
-- 111_live_chat_ai_context_confidence_and_mobile_polish.sql
-- Triplem VIP zero-cost Live Chat AI: richer intent understanding, guarded
-- contextual composition, repeated-uncertainty handoff, and learning disclosure.
--
-- LIVE-DATABASE SAFETY
--   * Run after 110.
--   * Adds only one non-destructive AI-state counter and replaces AI functions.
--   * Existing users, financial records, subscriptions, messages, credentials,
--     business records and historical Live Chat transcripts are not deleted or
--     rewritten by installation.
--   * No paid/metred AI API, external inference endpoint, downloaded browser
--     model, API key, Edge AI service, or third-party LLM is introduced.
-- ============================================================================

alter table public.app_live_chat_ai_state
  add column if not exists uncertainty_streak integer not null default 0;

comment on column public.app_live_chat_ai_state.uncertainty_streak is
  'Consecutive AI turns that genuinely need clarification. Reset after a confidently understood visitor question; used only for safe automatic human handoff while Live Support is online.';

-- Strengthen the public-chat confidentiality boundary. The assistant may explain
-- public security principles, but never implementation secrets, privileged data,
-- credentials, internal database/API details, or security bypass information.
create or replace function public.app_live_chat_ai_confidential_request(p_message text)
returns boolean
language plpgsql
immutable
set search_path = public
as $fn$
declare
  q text := lower(regexp_replace(trim(coalesce(p_message,'')),'\s+',' ','g'));
begin
  if q='' then return false; end if;

  return
    q ~ '((show|give|reveal|share|expose|print|dump|send|provide|list|disclose|tell me|what is|what are).{0,90}(source code|codebase|repository|repo|api key|anon key|secret key|service role|service_role|jwt secret|environment variable|env file|database schema|table name|column name|rpc name|sql function|stored procedure|migration sql|supabase url|admin password|smart pin|session token|guest token|credential|password hash|pepper|encryption key|private key|internal endpoint|internal api))'
    or q ~ '(vulnerabilit|security weakness|security flaw|exploit|bypass|sql injection|xss|csrf|privilege escalation|break into|circumvent security|disable security|hack triplem|hack the app)'
    or q ~ '(how|ways?|method|steps?).{0,45}(bypass|hack|exploit|break into|circumvent|evade).{0,70}(triplem|admin|login|auth|security|database|account|rls)'
    or q ~ '(internal|private|hidden).{0,40}(architecture|endpoint|api|database|schema|implementation|security configuration|rls|policy|function|migration)'
    or q ~ '(service role|jwt secret|rls policy|row level security policy|password hash|database dump|schema dump|admin token|session token).{0,80}(show|give|reveal|share|provide|list|tell|how|what)';
end
$fn$;
revoke all on function public.app_live_chat_ai_confidential_request(text) from public, anon, authenticated;

-- Verified public knowledge fragments. This remains deliberately bounded to facts
-- already represented by the product and public site, preventing hallucinated
-- integrations or capabilities while allowing more natural response composition.
create or replace function public.app_live_chat_ai_feature_summary(p_intent text)
returns text
language plpgsql
immutable
set search_path = public
as $fn$
begin
  return case lower(trim(coalesce(p_intent,'')))
    when 'overview' then 'Triplem VIP is a private accounting and operations workspace that keeps wallets, money movement, inventory, loans, installments, assets, documents and reporting connected in one account-isolated interface.'
    when 'setup' then 'A practical setup is to create your Individual or Company workspace, add the wallets/accounts you actually use, then record transactions and enable only the operational sections you need.'
    when 'dashboard' then 'The dashboard brings key balances and operating figures together so you can review the workspace before opening a detailed wallet, transaction, inventory, loan, installment or asset history.'
    when 'business_value' then 'Its practical value is reducing scattered spreadsheets and duplicate cross-checking by keeping related balances, stock, obligations, documents and history in one structured workspace.'
    when 'wallets' then 'Wallets separate cash, bank, card, crypto or custom money accounts by balance and currency, with traceable top-ups, transfers, expenses and wallet-level history.'
    when 'expenses' then 'Expense records preserve the wallet, currency, date, category, description and transaction history needed to understand spending later, with search and supported edit/delete workflows.'
    when 'income' then 'Income and incoming money can be reflected through the supported transaction and wallet workflows so balances and related histories remain connected instead of being tracked separately.'
    when 'currency' then 'Multi-currency wallets preserve the currency context of different cash, bank, card or other accounts instead of forcing every balance into one undifferentiated currency.'
    when 'inventory' then 'Inventory connects stock, brands, variants, barcodes, customers, sales, balances and invoice-related workflows so product movement and its financial context stay together.'
    when 'sales' then 'Sales workflows connect sold inventory, customers, receipts or invoices, balances and relevant profit records inside the same workspace.'
    when 'customers' then 'Customer records are used with supported inventory and sales workflows to keep sales, outstanding balances and related documents easier to follow.'
    when 'loans' then 'Loans track money given or taken, repayments, remaining balance, currency, dates and settlement history in one place.'
    when 'installments' then 'Installments track financed amounts, down payments, due schedules, reminders and payment history.'
    when 'assets' then 'Assets can track vehicles, property, equipment or investments with purchase value, costs, revenue, sale/disposal details and profit/loss views where supported.'
    when 'invoices' then 'Triplem VIP can produce professional downloadable documents for supported sales invoices, receipts, statements and finance records using the data already held in the workspace.'
    when 'reports' then 'Reports turn connected workspace records into downloadable statements, summaries and financial documents so information is easier to review or share.'
    when 'notes' then 'Notes and reminders keep operational follow-ups close to the finance workspace while remaining private to the appropriate account context.'
    when 'bitcoin' then 'Bitcoin tools cover wallet/address and send/receive workflows; sensitive key material is treated as a browser-side concern and is never requested or disclosed in public AI chat.'
    when 'company_team' then 'Company workspaces support business identity, branding and controlled team-member access around the owner workspace.'
    when 'platforms' then 'Triplem VIP is browser-based and responsive across modern desktop, phone and tablet use.'
    when 'personalization' then 'Themes, company branding and wallet visuals personalize the workspace without changing the underlying financial structure.'
    when 'security' then 'Triplem VIP uses isolated private workspaces and server-side access controls. Public AI chat does not expose credentials, private records or implementation-sensitive security details.'
    when 'continuity' then 'Supported export, backup and reconnect workflows help preserve continuity. Missing private records are reviewed by human support rather than guessed about in public AI chat.'
    when 'demo' then 'The public Demo previews supported workflows before signup, while the free trial lets you test the real workspace with your own realistic records.'
    when 'smart_pin' then 'Smart PIN adds an extra confirmation layer for protected actions. Account-specific PIN access problems are handled by human support.'
    when 'import_backup' then 'Supported sections provide import, export or backup-oriented workflows using the formats actually offered by the product.'
    when 'payment_method' then 'Pro subscriptions use Triplem VIP''s bank-transfer and receipt-verification workflow. A private payment status or receipt decision requires human review.'
    when 'support' then 'AI support is available continuously, while human Live Support operates 10:00 AM to 5:00 PM Gulf Standard Time.'
    when 'founder' then 'Triplem VIP was created by Nadeem Shahzad Fida around practical finance, accounts, inventory, loans, assets, documents and reporting needs.'
    else null
  end;
end
$fn$;
revoke all on function public.app_live_chat_ai_feature_summary(text) from public, anon, authenticated;

-- Multi-signal deterministic intent engine. It separates topic from question
-- shape, scores multiple plausible intentions, uses only short local chat context,
-- and composes a concise answer instead of returning one generic canned phrase.
create or replace function public.app_live_chat_ai_answer(
  p_message text,
  p_guest_name text,
  p_previous_intent text,
  p_previous_message text
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  q text := lower(regexp_replace(trim(coalesce(p_message,'')),'\s+',' ','g'));
  q_words text;
  previous_intent text := lower(trim(coalesce(p_previous_intent,'')));
  previous_words text := lower(regexp_replace(trim(coalesce(p_previous_message,'')),'\s+',' ','g'));
  guest text := coalesce(nullif(trim(coalesce(p_guest_name,'')),''),'there');
  brand_related boolean := false;
  followup boolean := false;
  explicit_capability_question boolean := false;
  unverified_feature boolean := false;
  question_kind text := 'direct';
  scores jsonb;
  primary_intent text;
  secondary_intent text;
  primary_score int := 0;
  secondary_score int := 0;
  score_margin int := 0;
  confidence numeric(5,4) := 0.6000;
  answer text := '';
  secondary_text text := null;
  needs_clarification boolean := false;
  reason text := null;
  monthly_aed text;
  monthly_sar text;
  monthly_pkr text;
  monthly_usd text;
  yearly_aed text;
  yearly_sar text;
  yearly_pkr text;
  yearly_usd text;

  s_overview int := 0;
  s_setup int := 0;
  s_dashboard int := 0;
  s_business int := 0;
  s_pricing int := 0;
  s_trial int := 0;
  s_wallets int := 0;
  s_expenses int := 0;
  s_income int := 0;
  s_currency int := 0;
  s_inventory int := 0;
  s_sales int := 0;
  s_customers int := 0;
  s_loans int := 0;
  s_installments int := 0;
  s_assets int := 0;
  s_invoices int := 0;
  s_reports int := 0;
  s_notes int := 0;
  s_bitcoin int := 0;
  s_team int := 0;
  s_platforms int := 0;
  s_personalization int := 0;
  s_security int := 0;
  s_continuity int := 0;
  s_demo int := 0;
  s_smart_pin int := 0;
  s_import int := 0;
  s_payment int := 0;
  s_support int := 0;
  s_founder int := 0;
begin
  q := replace(replace(replace(q,'’',''''),'“','"'),'”','"');
  q_words := regexp_replace(q,'[^a-z0-9%+./'' -]+',' ','g');
  q_words := regexp_replace(q_words,'\s+',' ','g');
  q_words := replace(replace(replace(replace(q_words,'tripplem','triplem'),'triple m','triplem'),'tripleem','triplem'),'instalment','installment');
  previous_words := regexp_replace(previous_words,'[^a-z0-9%+./'' -]+',' ','g');
  previous_words := regexp_replace(previous_words,'\s+',' ','g');

  if q_words='' then
    return jsonb_build_object('intent','triplem_clarify','question_kind','clarify','confidence',0.3000,'handoff',false,'handoff_reason',null,'needs_clarification',true,'response','Please type the Triplem VIP question or workflow you want help with.');
  end if;

  -- Immediate human and sensitive-account cases retain the established secure path.
  if public.app_live_chat_ai_human_requested(q) then
    return jsonb_build_object('intent','human_handoff','question_kind','handoff','confidence',1.0000,'handoff',true,'handoff_reason','visitor_requested','needs_clarification',false,'response','Certainly. I have paused AI replies and placed this chat in the human-support queue. A real Triplem VIP support agent will continue from here.');
  end if;

  reason:=public.app_live_chat_ai_sensitive_handoff_reason(q);
  if reason is not null then
    answer:=case reason
      when 'account_access' then 'For your privacy, login, password or Smart PIN account issues need a real support agent. I have transferred this chat securely.'
      when 'payment_review' then 'A real support agent needs to verify account-specific payments, receipts, approvals, refunds or charges. I have transferred this chat securely.'
      when 'account_data' then 'I cannot inspect private workspace records in public AI chat. I have transferred your case to a real support agent.'
      when 'security' then 'Account-security incidents need human review rather than an automated guess. I have transferred this chat to a real support agent.'
      when 'technical_issue' then 'That appears to be a specific product issue that needs your exact case checked. I have transferred this chat to a real support agent.'
      else 'That account action needs a real Triplem VIP support agent. I have transferred this chat securely.'
    end;
    return jsonb_build_object('intent','protected_handoff','question_kind','protected','confidence',0.9950,'handoff',true,'handoff_reason',reason,'needs_clarification',false,'response',answer);
  end if;

  if public.app_live_chat_ai_private_data_request(q) then
    return jsonb_build_object('intent','privacy_guard','question_kind','privacy','confidence',1.0000,'handoff',false,'handoff_reason',null,'needs_clarification',false,'response','I cannot access or disclose another user''s private data, messages, credentials or financial records. I can explain public Triplem VIP features, or a human agent can help with your own account.');
  end if;

  if public.app_live_chat_ai_confidential_request(q) then
    return jsonb_build_object('intent','confidentiality_guard','question_kind','security','confidence',1.0000,'handoff',false,'handoff_reason',null,'needs_clarification',false,'response','I can explain Triplem VIP''s public security principles, but I cannot disclose source code, credentials, database/API internals, private records, vulnerabilities or bypass methods. A legitimate security concern can be escalated to a human agent.');
  end if;

  if q_words ~ '(ignore|forget|override).*(instruction|rules|scope|previous)|system prompt|jailbreak|act as|pretend to be' then
    return jsonb_build_object('intent','scope_guard','question_kind','security','confidence',0.9950,'handoff',false,'handoff_reason',null,'needs_clarification',false,'response','I cannot override the Triplem VIP support, privacy or security boundaries. I can still help with verified product features, plans, setup, trial or human support.');
  end if;

  if q_words ~ '(are you|r u|is this).*(ai|bot|robot|human)|who are you|your identity' then
    return jsonb_build_object('intent','ai_identity','question_kind','identity','confidence',0.9950,'handoff',false,'handoff_reason',null,'needs_clarification',false,'response','I am the Triplem VIP AI Assistant, not a human agent. I generate answers from verified Triplem VIP product knowledge and can transfer you to a real agent when needed.');
  end if;

  if q_words ~ '^(hello|hi|hey|salam|assalam|good morning|good afternoon|good evening)( there| triplem| team)?[.! ]*$' then
    return jsonb_build_object('intent','greeting','question_kind','greeting','confidence',0.9700,'handoff',false,'handoff_reason',null,'needs_clarification',false,'response','Hello, '||guest||'. Ask me how Triplem VIP works, what it can manage, pricing, the free trial, or how it could fit your workflow.');
  end if;

  brand_related := q_words ~ '(triplem|vip|wallet|expense|income|inventory|stock|sale|customer|loan|installment|asset|bitcoin|btc|invoice|receipt|report|trial|subscription|smart pin|team|workspace|dashboard|live support|finance|accounting|bookkeeping|currency|backup|theme|note|reminder)';
  followup := char_length(q_words)<=180 and previous_intent<>'' and (
      q_words ~ '^(and |also |what about |how about )?(it|this|that|those|they|them|tell me more|more|more details|explain|explain more|how|why|how does it work|how does that work|can it|does it|is it|what about that|what about it|monthly|yearly|annual|price|cost|team|members?|yes|no|okay|ok)[ ?.!]*$'
      or q_words ~ '^(can|does|is|how|what|why) (it|this|that)( |$)'
      or q_words ~ '^(and|also|then|so) (how|what|can|does|is)( |$)'
    );

  explicit_capability_question := q_words ~ '(^| )(can|could|does|do|is|are|have|has|support|supports|offer|offers|include|includes)( |.* )(it|triplem|vip|this|that)|(^| )(can i|can we|do you have|does it have|is there|will it)( | )';
  unverified_feature := q_words ~ '(payroll|salary processing|tax filing|vat filing|automatic bank feed|bank sync|bank synchronization|crm|customer relationship management|e.?commerce integration|shopify|woocommerce|point of sale|(^| )pos( |$)|public api|open api|api integration|direct bank integration|automatic reconciliation)';

  if q_words ~ '(^| )(how do i|how can i|how to|steps|step by step|set up|setup|get started|start using|begin using|where do i start)( |$)' then question_kind:='howto';
  elsif q_words ~ '(compare|comparison|versus|(^| )vs( |$)|better than|difference between|instead of)' then question_kind:='comparison';
  elsif q_words ~ '(^| )(why|benefit|advantage|worth|useful|good for|suitable|fit)( |$)' then question_kind:='benefit';
  elsif explicit_capability_question then question_kind:='capability';
  elsif q_words ~ '(^| )(what is|what does|tell me about|explain|describe)( |$)' then question_kind:='explain';
  elsif q_words ~ '(^| )(price|pricing|cost|how much|monthly|yearly|annual|fee|charges)( |$)' then question_kind:='pricing';
  end if;

  if unverified_feature and explicit_capability_question then
    return jsonb_build_object('intent','unverified_capability','question_kind',question_kind,'confidence',0.9600,'handoff',false,'handoff_reason',null,'needs_clarification',false,'response','I cannot verify that as a current Triplem VIP feature, so I will not guess. Tell me the outcome you need and I can map it to verified features, or a human agent can confirm the requirement.');
  end if;

  -- Topic scoring. Specific operational nouns and action phrases outweigh broad
  -- words such as finance or product, while natural question forms add context.
  if q_words ~ '(triplem|vip)' then s_overview:=s_overview+3; s_business:=s_business+1; end if;
  if q_words ~ '(how.*(triplem|it|this).*(work|works|working|operate|function)|how it works|workflow|what is triplem|what does triplem|about triplem|overview|what can it do|what do i get|what is included|feature|features|capabilit|what.*manage)' then s_overview:=s_overview+11; end if;
  if q_words ~ '(set up|setup|get started|start using|begin using|where do i start|first step|initial setup|new account.*start)' then s_setup:=s_setup+12; end if;
  if q_words ~ '(dashboard|home screen|overview screen|summary screen|at a glance|main screen)' then s_dashboard:=s_dashboard+11; end if;
  if q_words ~ '(why triplem|why.*use|benefit|business value|replace.*(excel|spreadsheet|sheet)|instead of.*(excel|spreadsheet)|manage.*business|manage.*finance|accounting|bookkeeping|money management|financial management|all in one|one place|suitable|good for|fit.*business|for my business|for a business|for my company|for a company|small business|personal use|individual use|compare|comparison|versus|(^| )vs( |$)|retail|trading|rental|service business|shop owner|store owner)' then s_business:=s_business+10; end if;
  if q_words ~ '(price|pricing|cost|how much|monthly|yearly|annual|subscription|pro plan|charges|fee)' then s_pricing:=s_pricing+12; end if;
  if q_words ~ '(free trial|trial|try it|test it|sign up|signup|register|create.*account|card required|credit card|need.*card|is (it|this) free|free plan)' then s_trial:=s_trial+12; end if;
  if q_words ~ '(wallet|cash account|bank account|card account|top.?up|transfer money|money transfer|account balance)' then s_wallets:=s_wallets+11; end if;
  if q_words ~ '(expense|spending|transaction history|search transaction|expense category|record transaction|purchase expense)' then s_expenses:=s_expenses+11; end if;
  if q_words ~ '(^| )(income|earning|money received|receive money|incoming money|cash in)( |$)' then s_income:=s_income+10; end if;
  if q_words ~ '(multi.?currency|different currenc|currency|aed|sar|pkr|usd|exchange currency)' then s_currency:=s_currency+10; end if;
  if q_words ~ '(inventory|stock|product|brand|variant|barcode|goods|low stock|purchased stock)' then s_inventory:=s_inventory+11; end if;
  if q_words ~ '(^| )(sale|sales|selling|sold|sell product|sales receipt|profit record)( |$)' then s_sales:=s_sales+11; end if;
  if q_words ~ '(customer|client balance|customer balance|outstanding invoice|customer statement)' then s_customers:=s_customers+10; end if;
  if q_words ~ '(^| )loan(s)?( |$)|borrow|lent|lending|repayment|money given|money taken' then s_loans:=s_loans+11; end if;
  if q_words ~ '(installment|payment schedule|down payment|due payment|due schedule|financed amount)' then s_installments:=s_installments+11; end if;
  if q_words ~ '(^| )asset(s)?( |$)|depreciation|sale.*asset|dispose.*asset|vehicle asset|property asset|equipment asset|investment asset' then s_assets:=s_assets+11; end if;
  if q_words ~ '(invoice|receipt|customer statement|sales invoice|make.*invoice|create.*invoice|generate.*invoice|pdf invoice)' then s_invoices:=s_invoices+12; end if;
  if q_words ~ '(report|statement|pdf|export|download|summary document|financial summary)' then s_reports:=s_reports+10; end if;
  if q_words ~ '(note|notes|reminder|remind me|notification.*note)' then s_notes:=s_notes+10; end if;
  if q_words ~ '(bitcoin|btc|crypto|receive bitcoin|send bitcoin|blockchain)' then s_bitcoin:=s_bitcoin+11; end if;
  if q_words ~ '(team|team member|staff|employee|company account|business account|company branding|logo|trn|member access|seat|permission)' then s_team:=s_team+10; end if;
  if q_words ~ '(mobile|iphone|ios|android|desktop|browser|phone|tablet|responsive|platform|device)' then s_platforms:=s_platforms+10; end if;
  if q_words ~ '(theme|dark mode|navy|pink|green|appearance|personalize|customize|personalization|colour|color|branding)' then s_personalization:=s_personalization+10; end if;
  if q_words ~ '(secure|security|privacy|private|data protection|isolated|account protection|safe|trust|protect.*data)' then s_security:=s_security+11; end if;
  if q_words ~ '(backup|offline|internet|connection|sync|export my data|continuity|reconnect|data recovery)' then s_continuity:=s_continuity+9; end if;
  if q_words ~ '(demo|walkthrough|preview|see.*before|try.*demo)' then s_demo:=s_demo+11; end if;
  if q_words ~ '(smart pin|smartpin)' then s_smart_pin:=s_smart_pin+12; end if;
  if q_words ~ '(import|csv|json backup|backup file|move.*data|migration from)' then s_import:=s_import+10; end if;
  if q_words ~ '(payment method|how.*pay|pay.*(pro|subscription|plan)|bank transfer|upload.*receipt|subscription.*receipt)' then s_payment:=s_payment+12; end if;
  if q_words ~ '(support hour|support time|when.*support|live support|contact|email support|whatsapp|help desk|agent)' then s_support:=s_support+10; end if;
  if q_words ~ '(founder|nadeem|who made|who built|creator|owner)' then s_founder:=s_founder+11; end if;

  -- Action-aware boosts make natural questions such as "How can I track customer
  -- dues?" or "Can I make an invoice after a sale?" land on the useful workflow.
  if q_words ~ '(track|record|manage|view|see|check).*(wallet|balance|cash|bank)' then s_wallets:=s_wallets+4; end if;
  if q_words ~ '(track|record|manage|view|see|check).*(expense|spending|transaction)' then s_expenses:=s_expenses+4; end if;
  if q_words ~ '(track|record|manage|view|see|check).*(income|earning|money received)' then s_income:=s_income+4; end if;
  if q_words ~ '(track|record|manage|view|see|check).*(stock|inventory|product|barcode)' then s_inventory:=s_inventory+4; end if;
  if q_words ~ '(sell|sale|invoice|receipt).*(stock|inventory|product|customer)|customer.*(sale|invoice|balance)' then s_sales:=s_sales+4; s_customers:=s_customers+3; end if;
  if q_words ~ '(track|manage|record|repay).*(loan|repayment)' then s_loans:=s_loans+4; end if;
  if q_words ~ '(track|manage|record|pay).*(installment|due|schedule)' then s_installments:=s_installments+4; end if;
  if q_words ~ '(track|manage|record|sell).*(asset|depreciation|property|vehicle|equipment)' then s_assets:=s_assets+4; end if;
  if q_words ~ '(create|make|generate|download).*(invoice|receipt)' then s_invoices:=s_invoices+5; end if;
  if q_words ~ '(create|make|generate|download|view).*(report|statement|summary)' then s_reports:=s_reports+4; end if;
  if q_words ~ '(team|employee|staff).*(access|use|login|permission)' then s_team:=s_team+4; end if;
  if q_words ~ '(first|start|setup|set up).*(wallet|account|business|company|workspace)' then s_setup:=s_setup+4; end if;

  -- Short conversational follow-ups use recent local context, never an external
  -- service. The current turn still dominates, preventing topic drift.
  if followup then
    case previous_intent
      when 'overview' then s_overview:=s_overview+10;
      when 'setup' then s_setup:=s_setup+10;
      when 'dashboard' then s_dashboard:=s_dashboard+10;
      when 'business_value' then s_business:=s_business+10;
      when 'pricing' then s_pricing:=s_pricing+10;
      when 'trial_signup' then s_trial:=s_trial+10;
      when 'wallets' then s_wallets:=s_wallets+10;
      when 'expenses' then s_expenses:=s_expenses+10;
      when 'income' then s_income:=s_income+10;
      when 'currency' then s_currency:=s_currency+10;
      when 'inventory' then s_inventory:=s_inventory+10;
      when 'sales' then s_sales:=s_sales+10;
      when 'customers' then s_customers:=s_customers+10;
      when 'loans' then s_loans:=s_loans+10;
      when 'installments' then s_installments:=s_installments+10;
      when 'assets' then s_assets:=s_assets+10;
      when 'invoices' then s_invoices:=s_invoices+10;
      when 'reports' then s_reports:=s_reports+10;
      when 'notes' then s_notes:=s_notes+10;
      when 'bitcoin' then s_bitcoin:=s_bitcoin+10;
      when 'company_team' then s_team:=s_team+10;
      when 'platforms' then s_platforms:=s_platforms+10;
      when 'personalization' then s_personalization:=s_personalization+10;
      when 'security' then s_security:=s_security+10;
      when 'continuity' then s_continuity:=s_continuity+10;
      when 'demo' then s_demo:=s_demo+10;
      when 'smart_pin' then s_smart_pin:=s_smart_pin+10;
      when 'import_backup' then s_import:=s_import+10;
      when 'payment_method' then s_payment:=s_payment+10;
      when 'support' then s_support:=s_support+10;
      when 'founder' then s_founder:=s_founder+10;
      else s_overview:=s_overview;
    end case;

    if previous_words ~ '(invoice|receipt)' then s_invoices:=s_invoices+2; end if;
    if previous_words ~ '(inventory|stock|product|sale)' then s_inventory:=s_inventory+2; end if;
    if previous_words ~ '(price|monthly|yearly|subscription)' then s_pricing:=s_pricing+2; end if;
  end if;

  scores:=jsonb_build_object(
    'overview',s_overview,'setup',s_setup,'dashboard',s_dashboard,'business_value',s_business,
    'pricing',s_pricing,'trial_signup',s_trial,'wallets',s_wallets,'expenses',s_expenses,
    'income',s_income,'currency',s_currency,'inventory',s_inventory,'sales',s_sales,
    'customers',s_customers,'loans',s_loans,'installments',s_installments,'assets',s_assets,
    'invoices',s_invoices,'reports',s_reports,'notes',s_notes,'bitcoin',s_bitcoin,
    'company_team',s_team,'platforms',s_platforms,'personalization',s_personalization,
    'security',s_security,'continuity',s_continuity,'demo',s_demo,'smart_pin',s_smart_pin,
    'import_backup',s_import,'payment_method',s_payment,'support',s_support,'founder',s_founder
  );

  select e.key,e.value::int into primary_intent,primary_score
    from jsonb_each_text(scores) e
    order by e.value::int desc, e.key asc limit 1;
  select e.key,e.value::int into secondary_intent,secondary_score
    from jsonb_each_text(scores) e
    where e.key<>primary_intent
    order by e.value::int desc, e.key asc limit 1;

  score_margin:=coalesce(primary_score,0)-coalesce(secondary_score,0);

  if coalesce(primary_score,0)<6 then
    needs_clarification:=true;
    if brand_related or followup then
      answer:='I want to answer the right Triplem VIP question. Are you asking how to do something, whether a feature is available, or which part of your workflow you want to manage?';
      return jsonb_build_object('intent','triplem_clarify','question_kind','clarify','confidence',0.6200,'handoff',false,'handoff_reason',null,'needs_clarification',true,'response',answer);
    else
      answer:='I am here for Triplem VIP product and support questions. If your question relates to your business or finance workflow, tell me what you want to manage and I will map it to the verified features.';
      return jsonb_build_object('intent','scope','question_kind','scope','confidence',0.7600,'handoff',false,'handoff_reason',null,'needs_clarification',false,'response',answer);
    end if;
  end if;

  confidence:=least(0.9950,0.6900+(least(primary_score,22)::numeric/80)+(least(greatest(score_margin,0),10)::numeric/100));

  -- Question-aware response composition. These answers intentionally remain short
  -- enough for Live Chat while explaining the actual workflow behind the topic.
  if primary_intent='overview' then
    if question_kind='howto' or q_words ~ '(how.*work|workflow|operate|function)' then
      answer:='You create the workspace and wallets you use, then record money movement and operational activity such as expenses, stock, loans, installments or assets. Triplem VIP keeps the related balances, histories, documents and reports connected instead of making you reconcile separate records.';
    elsif question_kind='benefit' or question_kind='comparison' then
      answer:='Triplem VIP is most useful when wallets, expenses, inventory, obligations, assets and documents would otherwise sit in separate sheets or apps. It keeps those records connected and easier to trace from one workspace.';
    else
      answer:=public.app_live_chat_ai_feature_summary('overview');
    end if;
  elsif primary_intent='setup' then
    answer:='Start with the real accounts you use: create your Individual or Company workspace, add cash/bank/card wallets and currencies, then record your normal transactions. After that, add inventory, loans, installments or assets only where your workflow needs them.';
  elsif primary_intent='dashboard' then
    answer:='The dashboard is the review layer: it gives you a concise view of key workspace figures, while the detailed sections hold the underlying transactions, stock, loans, installments and assets. Open a section when you need the full history or action controls.';
  elsif primary_intent='business_value' then
    if q_words ~ '(retail|shop|store|trading)' then
      answer:='For a retail or trading workflow, Triplem VIP can keep wallets, expenses, inventory, customers, sales, invoices and reports in one workspace. The 14-day free trial is the best way to test it against your actual daily process with no card required.';
    elsif q_words ~ '(rental|service business|services)' then
      answer:='For a service or rental-style business, Triplem VIP is useful when you need money records, expenses, assets, customer documents, loans or reports kept together. Test the exact workflow free for 14 days before choosing a Pro plan.';
    elsif question_kind='comparison' and q_words ~ '(excel|spreadsheet|sheet)' then
      answer:='Spreadsheets store cells; Triplem VIP is designed around connected records. A wallet transaction can remain tied to its history and reporting context, while inventory, loans, installments, assets and documents have their own structured workflows.';
    else
      answer:=public.app_live_chat_ai_feature_summary('business_value')||' The full workspace can be tested free for 14 days with no card.';
    end if;
  elsif primary_intent='pricing' then
    monthly_aed:=coalesce(public.app_subscription_price('monthly','AED',0)->>'base_amount','49.00');
    monthly_sar:=coalesce(public.app_subscription_price('monthly','SAR',0)->>'base_amount','49.00');
    monthly_pkr:=coalesce(public.app_subscription_price('monthly','PKR',0)->>'base_amount','1799.00');
    monthly_usd:=coalesce(public.app_subscription_price('monthly','USD',0)->>'base_amount','13.99');
    yearly_aed:=coalesce(public.app_subscription_price('yearly','AED',0)->>'base_amount','449.00');
    yearly_sar:=coalesce(public.app_subscription_price('yearly','SAR',0)->>'base_amount','449.00');
    yearly_pkr:=coalesce(public.app_subscription_price('yearly','PKR',0)->>'base_amount','19999.00');
    yearly_usd:=coalesce(public.app_subscription_price('yearly','USD',0)->>'base_amount','149.00');
    if q_words ~ '(yearly|annual)' and q_words !~ '(monthly)' then
      answer:=format('Pro Yearly is AED %s, SAR %s, PKR %s or USD %s. The full 14-day trial is available first with no card.',yearly_aed,yearly_sar,yearly_pkr,yearly_usd);
    elsif q_words ~ '(monthly)' and q_words !~ '(yearly|annual)' then
      answer:=format('Pro Monthly is AED %s, SAR %s, PKR %s or USD %s. The full 14-day trial is available first with no card.',monthly_aed,monthly_sar,monthly_pkr,monthly_usd);
    else
      answer:=format('Pro Monthly is AED %s / SAR %s / PKR %s / USD %s. Pro Yearly is AED %s / SAR %s / PKR %s / USD %s. You can test the full workspace free for 14 days with no card.',monthly_aed,monthly_sar,monthly_pkr,monthly_usd,yearly_aed,yearly_sar,yearly_pkr,yearly_usd);
    end if;
  elsif primary_intent='trial_signup' then
    answer:='The free trial gives you the full Triplem VIP workspace for 14 days with no card required. Create an Individual or Company account, test your normal workflow, then choose Pro Monthly or Pro Yearly only if it fits.';
  elsif primary_intent='wallets' then
    if question_kind='howto' then answer:='Create a wallet for each real cash, bank, card, crypto or custom account, choose its currency, then record top-ups, transfers and expenses against the correct wallet. That keeps each balance and its transaction history traceable.';
    else answer:=public.app_live_chat_ai_feature_summary('wallets'); end if;
  elsif primary_intent='expenses' then
    if question_kind='howto' then answer:='Record the expense against the correct wallet with its amount, currency, date, category and description. Triplem VIP keeps it in transaction history so you can search, review and use the record in reporting.';
    else answer:=public.app_live_chat_ai_feature_summary('expenses'); end if;
  elsif primary_intent='income' then
    answer:=public.app_live_chat_ai_feature_summary('income');
  elsif primary_intent='currency' then
    answer:=public.app_live_chat_ai_feature_summary('currency');
  elsif primary_intent='inventory' then
    if question_kind='howto' then answer:='Build the stock catalogue first, then record purchases and sales against the relevant products, variants and customers. Triplem VIP keeps stock movement, sales context, balances and invoice-related records connected.';
    else answer:=public.app_live_chat_ai_feature_summary('inventory'); end if;
  elsif primary_intent='sales' then
    answer:=public.app_live_chat_ai_feature_summary('sales');
  elsif primary_intent='customers' then
    answer:=public.app_live_chat_ai_feature_summary('customers');
  elsif primary_intent='loans' then
    if question_kind='howto' then answer:='Create the loan as money given or taken, record each repayment against it, and Triplem VIP keeps the remaining balance and settlement history visible in the same record.';
    else answer:=public.app_live_chat_ai_feature_summary('loans'); end if;
  elsif primary_intent='installments' then
    if question_kind='howto' then answer:='Create the installment plan with the financed amount, down payment and due schedule, then record payments as they occur. The plan keeps due amounts, reminders and payment history together.';
    else answer:=public.app_live_chat_ai_feature_summary('installments'); end if;
  elsif primary_intent='assets' then
    if question_kind='howto' then answer:='Add the asset with its purchase details, then record supported costs, revenue and later sale or disposal activity. Triplem VIP keeps the asset history and profit/loss context together where supported.';
    else answer:=public.app_live_chat_ai_feature_summary('assets'); end if;
  elsif primary_intent='invoices' then
    if q_words ~ '(inventory|sale|customer)' then answer:='Yes. Supported sales and customer workflows can produce professional downloadable invoices or receipts from the related workspace data, keeping the document connected to the underlying transaction context.';
    else answer:=public.app_live_chat_ai_feature_summary('invoices'); end if;
  elsif primary_intent='reports' then
    answer:=public.app_live_chat_ai_feature_summary('reports');
  elsif primary_intent='payment_method' then
    answer:=public.app_live_chat_ai_feature_summary('payment_method')||' I can explain the process, but I cannot inspect a private receipt or payment status here.';
  elsif primary_intent='support' then
    answer:=public.app_live_chat_ai_feature_summary('support')||' Ask for a real agent at any time and I will pause AI replies.';
  elsif primary_intent='security' then
    answer:=public.app_live_chat_ai_feature_summary('security')||' For an account-specific security concern, I will transfer you to a real agent instead of guessing.';
  elsif primary_intent='founder' then
    answer:=public.app_live_chat_ai_feature_summary('founder');
  elsif primary_intent='demo' then
    answer:=public.app_live_chat_ai_feature_summary('demo')||' The full trial is free for 14 days with no card.';
  else
    answer:=public.app_live_chat_ai_feature_summary(primary_intent);
    if answer is null then
      answer:='I understand the Triplem VIP topic, but I do not have enough verified detail to answer that precisely without guessing.';
      needs_clarification:=true;
      confidence:=least(confidence,0.7000);
    elsif question_kind='capability' and primary_intent not in ('security','support','founder','continuity','import_backup') then
      answer:='Yes. '||answer;
    end if;
  end if;

  -- Include one genuinely strong secondary topic only when the visitor combined
  -- two needs. This creates useful compound answers without producing long lists.
  if secondary_score>=9 and secondary_intent<>primary_intent and score_margin<=6 then
    if secondary_intent='pricing' then
      secondary_text:='If you also want pricing, I can give the current Monthly and Yearly amounts.';
    elsif secondary_intent='trial_signup' then
      secondary_text:='You can test the full workspace free for 14 days with no card.';
    elsif secondary_intent='invoices' and primary_intent in ('inventory','sales','customers') then
      secondary_text:='Supported sales/customer records can also feed professional invoice or receipt documents.';
    elsif secondary_intent='reports' and primary_intent not in ('invoices','pricing','trial_signup') then
      secondary_text:='The related records can also be used in supported statements or reports.';
    elsif secondary_intent not in ('overview','business_value','security','support','founder') then
      secondary_text:=public.app_live_chat_ai_feature_summary(secondary_intent);
    end if;
  end if;

  if secondary_text is not null and position(lower(secondary_text) in lower(answer))=0 then
    answer:=trim(answer)||' '||trim(secondary_text);
  end if;

  -- Keep answers conversationally compact. Live Support should clarify, not write
  -- an article, even when the question contains two related intents.
  if char_length(answer)>760 then answer:=left(answer,757)||'...'; end if;

  return jsonb_build_object(
    'intent',primary_intent,
    'secondary_intent',case when secondary_score>=9 and score_margin<=6 then secondary_intent else null end,
    'question_kind',question_kind,
    'confidence',confidence,
    'handoff',false,
    'handoff_reason',null,
    'needs_clarification',needs_clarification,
    'response',answer
  );
end
$fn$;
revoke all on function public.app_live_chat_ai_answer(text,text,text,text) from public, anon, authenticated;

-- Preserve compatibility signatures used by earlier deployments and helpers.
create or replace function public.app_live_chat_ai_answer(
  p_message text,
  p_guest_name text,
  p_previous_intent text
)
returns jsonb
language sql
stable
security definer
set search_path = public
as $fn$
  select public.app_live_chat_ai_answer(p_message,p_guest_name,p_previous_intent,null::text)
$fn$;
revoke all on function public.app_live_chat_ai_answer(text,text,text) from public, anon, authenticated;

create or replace function public.app_live_chat_ai_answer(
  p_message text,
  p_guest_name text default null
)
returns jsonb
language sql
stable
security definer
set search_path = public
as $fn$
  select public.app_live_chat_ai_answer(p_message,p_guest_name,null::text,null::text)
$fn$;
revoke all on function public.app_live_chat_ai_answer(text,text) from public, anon, authenticated;

-- Process up to three recent visitor turns as local context, record consecutive
-- genuine uncertainty, and automatically hand off after two unclear AI turns when
-- human Live Support is currently open. Outside support hours, AI keeps helping
-- rather than creating a misleading immediate-human expectation.
create or replace function public.app_live_chat_ai_process(
  p_inquiry_id uuid,
  p_message text,
  p_guest_name text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  decision jsonb;
  ai_msg public.app_inquiry_messages;
  next_mode text;
  notices int := 0;
  h_reason text;
  intent text;
  confidence numeric(5,4);
  response_text text;
  inquiry_row public.app_inquiries;
  route_row public.app_live_chat_routes;
  current_ai public.app_live_chat_ai_state;
  recent_guest_context text := null;
  availability jsonb;
  support_open boolean := false;
  needs_clarification boolean := false;
  next_uncertainty integer := 0;
begin
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;
  if inquiry_row is null or coalesce(inquiry_row.source,'')<>'landing' or lower(coalesce(inquiry_row.subject,''))<>'live chat support' then
    raise exception 'Live chat session is unavailable';
  end if;

  select * into route_row from public.app_live_chat_routes where inquiry_id=p_inquiry_id for update;
  if route_row.status='accepted' and route_row.assigned_user_id is not null then
    return jsonb_build_object('ok',true,'mode','human','handoff',false,'support_queue',0,'message',null);
  end if;
  if route_row.status='closed' or inquiry_row.status='archived' then
    return jsonb_build_object('ok',true,'mode','closed','handoff',false,'support_queue',0,'message',null);
  end if;

  select * into current_ai from public.app_live_chat_ai_state where inquiry_id=p_inquiry_id for update;
  if current_ai.inquiry_id is not null and current_ai.mode<>'ai' then
    return jsonb_build_object('ok',true,'mode',current_ai.mode,'handoff',(current_ai.mode='human_pending'),'support_queue',0,'message',null);
  end if;

  select string_agg(x.body,' | ' order by x.created_at) into recent_guest_context
  from (
    select m.body,m.created_at
      from public.app_inquiry_messages m
     where m.inquiry_id=p_inquiry_id and m.sender_role='guest'
     order by m.created_at desc
     offset 1 limit 3
  ) x;

  decision:=public.app_live_chat_ai_answer(
    p_message,
    p_guest_name,
    case when current_ai.inquiry_id is not null then current_ai.last_intent else null end,
    recent_guest_context
  );

  h_reason:=nullif(decision->>'handoff_reason','');
  intent:=coalesce(nullif(decision->>'intent',''),'scope');
  confidence:=coalesce((decision->>'confidence')::numeric,0.5000);
  response_text:=trim(coalesce(decision->>'response',''));
  needs_clarification:=coalesce((decision->>'needs_clarification')::boolean,false);

  availability:=public.app_live_chat_availability();
  support_open:=coalesce((availability->>'is_open')::boolean,false);
  next_uncertainty:=case
    when needs_clarification then least(9,coalesce(current_ai.uncertainty_streak,0)+1)
    else 0
  end;

  -- Explicit/sensitive handoff from the decision always wins. Otherwise two
  -- consecutive genuine misunderstandings hand off automatically only while a
  -- real agent can reasonably accept the chat now.
  if coalesce((decision->>'handoff')::boolean,false) then
    next_mode:='human_pending';
  elsif needs_clarification and next_uncertainty>=2 and support_open then
    next_mode:='human_pending';
    h_reason:='ai_uncertain_repeated';
    response_text:='I may be missing what you need. Rather than keep you repeating yourself, I have transferred this chat to a real Triplem VIP support agent who can continue with you.';
  else
    next_mode:='ai';
    if needs_clarification and next_uncertainty>=2 and not support_open then
      response_text:=trim(response_text)||' Human Live Support is currently offline and resumes at 10:00 AM GST; you can still ask me another way in the meantime.';
    end if;
  end if;

  -- New-chat disclosure is intentionally short, transparent and shown only once.
  if current_ai.inquiry_id is null then
    response_text:='I am Triplem VIP''s AI Assistant. I am still learning, so I may occasionally make mistakes and will avoid guessing. '||response_text;
  end if;

  insert into public.app_live_chat_ai_state(
    inquiry_id,mode,last_intent,last_confidence,last_ai_message_at,
    human_requested_at,human_reason,uncertainty_streak,created_at,updated_at
  ) values(
    p_inquiry_id,next_mode,intent,confidence,now(),
    case when next_mode='human_pending' then now() else null end,
    case when next_mode='human_pending' then coalesce(h_reason,'visitor_requested') else null end,
    next_uncertainty,now(),now()
  )
  on conflict(inquiry_id) do update set
    mode=excluded.mode,
    last_intent=excluded.last_intent,
    last_confidence=excluded.last_confidence,
    last_ai_message_at=excluded.last_ai_message_at,
    human_requested_at=case when excluded.mode='human_pending' then coalesce(app_live_chat_ai_state.human_requested_at,excluded.human_requested_at) else app_live_chat_ai_state.human_requested_at end,
    human_reason=case when excluded.mode='human_pending' then excluded.human_reason else app_live_chat_ai_state.human_reason end,
    uncertainty_streak=excluded.uncertainty_streak,
    updated_at=now();

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,support_actor,created_at)
  values(p_inquiry_id,'admin',null,response_text,'ai',clock_timestamp()+interval '1 millisecond')
  returning * into ai_msg;

  update public.app_inquiries
     set last_message_at=now(),updated_at=now(),
         status=case when next_mode='human_pending' then 'open' else status end
   where id=p_inquiry_id;

  if next_mode='human_pending' then
    notices:=public.app_live_chat_notify_available_agents(p_inquiry_id);
  end if;

  return jsonb_build_object(
    'ok',true,
    'mode',next_mode,
    'intent',intent,
    'secondary_intent',decision->>'secondary_intent',
    'question_kind',decision->>'question_kind',
    'confidence',confidence,
    'needs_clarification',needs_clarification,
    'uncertainty_streak',next_uncertainty,
    'handoff',(next_mode='human_pending'),
    'handoff_reason',case when next_mode='human_pending' then coalesce(h_reason,'visitor_requested') else null end,
    'support_queue',notices,
    'message',public.app_message_public_row(ai_msg)
  );
end
$fn$;
revoke all on function public.app_live_chat_ai_process(uuid,text,text) from public, anon, authenticated;

-- ############################################################################
-- END migrations/111_live_chat_ai_context_confidence_and_mobile_polish.sql
-- ############################################################################

-- ############################################################################
-- BEGIN migrations/112_live_chat_neural_semantic_ai.sql
-- ############################################################################

-- ============================================================================
-- 112_live_chat_neural_semantic_ai.sql
-- Triplem VIP Live Support: real on-device neural semantic understanding.
--
-- ARCHITECTURE
--   * Browser: Hugging Face Transformers.js + quantized MiniLM sentence
--     transformer classifies the visitor's own question semantically.
--   * Database: remains authoritative for public product facts, prices,
--     subscription workflow, privacy/security policy and human handoff.
--   * No paid AI API, API key, metered inference endpoint or private workspace
--     data is supplied to the browser model.
--
-- LIVE-DATABASE SAFETY
--   * Run after 111.
--   * Adds only nullable AI telemetry columns and new/replaced functions.
--   * No DELETE, TRUNCATE, DROP TABLE, DROP COLUMN or installation-time UPDATE.
--   * Existing users, financial records, subscriptions and historical messages
--     are not rewritten by installation.
-- ============================================================================

alter table public.app_live_chat_ai_state
  add column if not exists last_ai_engine text,
  add column if not exists last_ai_model text;

comment on column public.app_live_chat_ai_state.last_ai_engine is
  'Last support understanding engine used for this chat, e.g. transformers_js_minilm or grounded_fallback.';
comment on column public.app_live_chat_ai_state.last_ai_model is
  'Public model identifier supplied by the visitor client when neural semantic intent understanding was used. Never contains credentials or user data.';

create or replace function public.app_live_chat_ai_semantic_intent_allowed(p_intent text)
returns boolean
language sql
immutable
set search_path = public
as $fn$
  select lower(trim(coalesce(p_intent,''))) = any(array[
    'overview','business_value','setup','dashboard','pricing','payment_method','trial_signup',
    'wallets','expenses','income','currency','inventory','sales','customers','invoices',
    'reports','loans','installments','assets','notes','bitcoin','company_team','platforms',
    'personalization','security','continuity','demo','smart_pin','import_backup','support','founder'
  ]::text[])
$fn$;
revoke all on function public.app_live_chat_ai_semantic_intent_allowed(text) from public, anon, authenticated;

create or replace function public.app_live_chat_ai_safe_score(p_value text)
returns numeric
language plpgsql
immutable
set search_path = public
as $fn$
declare
  v text := trim(coalesce(p_value,''));
  n numeric;
begin
  if v !~ '^[0-9]+([.][0-9]+)?$' then return 0; end if;
  begin n:=v::numeric; exception when others then return 0; end;
  return greatest(0::numeric,least(1::numeric,n));
end
$fn$;
revoke all on function public.app_live_chat_ai_safe_score(text) from public, anon, authenticated;

create or replace function public.app_live_chat_ai_semantic_prompt(
  p_intent text,
  p_original_message text
)
returns text
language plpgsql
immutable
set search_path = public
as $fn$
declare
  i text := lower(trim(coalesce(p_intent,'')));
  q text := lower(trim(coalesce(p_original_message,'')));
begin
  return case i
    when 'overview' then 'How does Triplem VIP work, what is it for, and what can it manage?'
    when 'business_value' then 'Who is Triplem VIP for and how can it help a business or individual manage finance and operations?'
    when 'setup' then 'How do I get started and set up Triplem VIP?'
    when 'dashboard' then 'What does the Triplem VIP dashboard show and how is it used?'
    when 'pricing' then case
      when q ~ '(yearly|annual)' and q !~ '(monthly)' then 'What is the current Triplem VIP Pro Yearly price?'
      when q ~ '(monthly)' and q !~ '(yearly|annual)' then 'What is the current Triplem VIP Pro Monthly price?'
      else 'What are the current Triplem VIP plans and prices for Pro Monthly and Pro Yearly?'
    end
    when 'payment_method' then 'How do I subscribe, activate or renew Triplem VIP Pro Monthly or Pro Yearly and how does payment work?'
    when 'trial_signup' then 'How do I start the Triplem VIP 14-day free trial and create an account?'
    when 'wallets' then 'How do Triplem VIP wallets, cash accounts, bank accounts, balances, top-ups and transfers work?'
    when 'expenses' then 'How do I record, track and review expenses in Triplem VIP?'
    when 'income' then 'How does Triplem VIP track income and money received?'
    when 'currency' then 'How does Triplem VIP handle multiple currencies?'
    when 'inventory' then 'How does Triplem VIP manage inventory, stock, products, brands, variants and barcodes?'
    when 'sales' then 'How do sales work in Triplem VIP?'
    when 'customers' then 'How does Triplem VIP manage customers and customer balances?'
    when 'invoices' then 'Can Triplem VIP create invoices and receipts and how does that workflow work?'
    when 'reports' then 'What reports, statements, PDF documents and exports can Triplem VIP produce?'
    when 'loans' then 'How does Triplem VIP manage loans, lending and repayments?'
    when 'installments' then 'How does Triplem VIP manage installment plans, dues and payment schedules?'
    when 'assets' then 'How does Triplem VIP manage assets, costs, revenue, depreciation and disposal?'
    when 'notes' then 'How do notes and reminders work in Triplem VIP?'
    when 'bitcoin' then 'What verified Bitcoin tools are available in Triplem VIP?'
    when 'company_team' then 'How do Company workspaces, team members and permissions work in Triplem VIP?'
    when 'platforms' then 'Does Triplem VIP work on mobile, iPhone, Android, tablet and desktop browsers?'
    when 'personalization' then 'How can Triplem VIP themes, logos, branding and appearance be personalized?'
    when 'security' then 'What public security and privacy protections does Triplem VIP use?'
    when 'continuity' then 'What backup, export, reconnect and continuity workflows does Triplem VIP support?'
    when 'demo' then 'How can I see the Triplem VIP demo before signing up?'
    when 'smart_pin' then 'What is Triplem VIP Smart PIN and how is it used?'
    when 'import_backup' then 'What import, export and backup workflows does Triplem VIP support?'
    when 'support' then 'When is Triplem VIP human Live Support available and how do I reach an agent?'
    when 'founder' then 'Who created Triplem VIP and who is its founder?'
    else p_original_message
  end;
end
$fn$;
revoke all on function public.app_live_chat_ai_semantic_prompt(text,text) from public, anon, authenticated;

-- Neural semantic classification is a hint, not a security boundary. Every
-- protected request is evaluated by the existing server-side guard first.
create or replace function public.app_live_chat_ai_semantic_answer(
  p_message text,
  p_guest_name text,
  p_previous_intent text,
  p_previous_message text,
  p_ai_analysis jsonb
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  q text := lower(regexp_replace(trim(coalesce(p_message,'')),'\s+',' ','g'));
  baseline jsonb;
  baseline_intent text;
  primary_intent text := null;
  secondary_intent text := null;
  semantic_confidence numeric(6,5) := 0;
  primary_score numeric(6,5) := 0;
  secondary_score numeric(6,5) := 0;
  engine text := left(lower(trim(coalesce(p_ai_analysis->>'engine',''))),48);
  model text := left(trim(coalesce(p_ai_analysis->>'model','')),96);
  neural boolean := lower(trim(coalesce(p_ai_analysis->>'neural','false')))='true';
  canonical text;
  decision jsonb;
  response_text text;
  secondary_text text := null;
  monthly_aed text;
  monthly_sar text;
  monthly_pkr text;
  monthly_usd text;
  yearly_aed text;
  yearly_sar text;
  yearly_pkr text;
  yearly_usd text;
  brand_related boolean := false;
begin
  if engine not in ('transformers_js_minilm','grounded_fallback') then
    engine:='grounded_fallback';
    model:='';
    neural:=false;
  elsif engine<>'transformers_js_minilm' then
    model:='';
    neural:=false;
  end if;

  baseline := public.app_live_chat_ai_answer(p_message,p_guest_name,p_previous_intent,p_previous_message);
  baseline_intent := coalesce(baseline->>'intent','');

  -- Preserve all security/privacy/identity/handoff decisions before consulting
  -- any client-supplied semantic hint.
  if coalesce((baseline->>'handoff')::boolean,false)
     or baseline_intent in (
       'human_handoff','protected_handoff','privacy_guard','confidentiality_guard',
       'scope_guard','ai_identity','greeting','unverified_capability'
     ) then
    return baseline || jsonb_build_object(
      'engine','guarded_server_policy','model',null,'semantic_used',false
    );
  end if;

  if jsonb_typeof(coalesce(p_ai_analysis->'intents','[]'::jsonb))='array' then
    select lower(trim(x.value->>'intent')),
           public.app_live_chat_ai_safe_score(x.value->>'score')
      into primary_intent,primary_score
      from jsonb_array_elements(p_ai_analysis->'intents') with ordinality as x(value,ord)
     where public.app_live_chat_ai_semantic_intent_allowed(x.value->>'intent')
     order by x.ord asc
     limit 1;

    select lower(trim(x.value->>'intent')),
           public.app_live_chat_ai_safe_score(x.value->>'score')
      into secondary_intent,secondary_score
      from jsonb_array_elements(p_ai_analysis->'intents') with ordinality as x(value,ord)
     where public.app_live_chat_ai_semantic_intent_allowed(x.value->>'intent')
       and lower(trim(x.value->>'intent')) is distinct from primary_intent
     order by x.ord asc
     limit 1;
  end if;

  semantic_confidence := greatest(
    primary_score,
    public.app_live_chat_ai_safe_score(p_ai_analysis->>'confidence')
  );
  brand_related := q ~ '(triplem|vip|plan|subscription|trial|wallet|expense|income|inventory|stock|sale|customer|loan|installment|asset|bitcoin|btc|invoice|receipt|report|smart pin|team|workspace|dashboard|support|finance|accounting|bookkeeping|currency|backup|theme|note|reminder)';

  if primary_intent is null or semantic_confidence < 0.34 then
    if baseline_intent in ('scope','triplem_clarify') and brand_related then
      return jsonb_build_object(
        'intent','triplem_clarify','secondary_intent',null,'question_kind','clarify',
        'confidence',greatest(0.40,semantic_confidence),'handoff',false,
        'handoff_reason',null,'needs_clarification',true,
        'response','I want to make sure I understand you correctly. Please rephrase that Triplem VIP question in one short sentence, or tell me what you are trying to manage.',
        'engine',case when engine<>'' then engine else 'grounded_fallback' end,
        'model',nullif(model,''),'semantic_used',false
      );
    end if;
    return baseline || jsonb_build_object(
      'engine',case when engine<>'' then engine else 'grounded_fallback' end,
      'model',nullif(model,''),'semantic_used',false
    );
  end if;

  canonical := public.app_live_chat_ai_semantic_prompt(primary_intent,p_message);
  decision := public.app_live_chat_ai_answer(canonical,p_guest_name,p_previous_intent,p_message);
  response_text := trim(coalesce(decision->>'response',''));

  -- High-value common questions are answered directly and tersely from verified
  -- live product functions, so semantic understanding never sacrifices factual
  -- precision merely to sound generative.
  if primary_intent='overview' then
    response_text := 'Triplem VIP is a private accounting and business-operations workspace. It connects wallets, expenses, inventory and sales, loans, installments, assets, invoices/receipts and reports in one structured system.';
  elsif primary_intent='pricing' then
    monthly_aed:=coalesce(public.app_subscription_price('monthly','AED',0)->>'base_amount','49.00');
    monthly_sar:=coalesce(public.app_subscription_price('monthly','SAR',0)->>'base_amount','49.00');
    monthly_pkr:=coalesce(public.app_subscription_price('monthly','PKR',0)->>'base_amount','1799.00');
    monthly_usd:=coalesce(public.app_subscription_price('monthly','USD',0)->>'base_amount','13.99');
    yearly_aed:=coalesce(public.app_subscription_price('yearly','AED',0)->>'base_amount','449.00');
    yearly_sar:=coalesce(public.app_subscription_price('yearly','SAR',0)->>'base_amount','449.00');
    yearly_pkr:=coalesce(public.app_subscription_price('yearly','PKR',0)->>'base_amount','19999.00');
    yearly_usd:=coalesce(public.app_subscription_price('yearly','USD',0)->>'base_amount','149.00');
    if q ~ '(yearly|annual)' and q !~ '(monthly)' then
      response_text:=format('Pro Yearly is AED %s, SAR %s, PKR %s or USD %s. You can test the full workspace free for 14 days first, with no card required.',yearly_aed,yearly_sar,yearly_pkr,yearly_usd);
    elsif q ~ '(monthly)' and q !~ '(yearly|annual)' then
      response_text:=format('Pro Monthly is AED %s, SAR %s, PKR %s or USD %s. You can test the full workspace free for 14 days first, with no card required.',monthly_aed,monthly_sar,monthly_pkr,monthly_usd);
    else
      response_text:=format('Pro Monthly: AED %s, SAR %s, PKR %s or USD %s. Pro Yearly: AED %s, SAR %s, PKR %s or USD %s. A 14-day full-workspace trial is available first with no card.',monthly_aed,monthly_sar,monthly_pkr,monthly_usd,yearly_aed,yearly_sar,yearly_pkr,yearly_usd);
    end if;
  elsif primary_intent='payment_method' then
    response_text := 'After signing in, open Plan & Subscription, choose Pro Monthly or Pro Yearly and your currency, select an available bank account, complete the transfer and upload the receipt. Activation follows payment verification.';
  elsif primary_intent='trial_signup' then
    response_text := 'Start the 14-day free trial from the signup/sign-in flow when offered. Choose an Individual or Company workspace; the full workspace is available during the trial and no card is required.';
  elsif primary_intent='business_value' and response_text='' then
    response_text := 'Triplem VIP is designed for owners, merchants, service businesses, private lenders and individuals who want structured finance and operational records without scattered spreadsheets.';
  end if;

  -- One strong secondary intent is enough for compound questions such as
  -- "What is it for and how do I subscribe?" without turning chat into an essay.
  if secondary_intent is not null and secondary_score >= 0.42 and secondary_score >= primary_score - 0.105 then
    if secondary_intent='payment_method' and primary_intent<>'payment_method' then
      secondary_text := 'To subscribe, open Plan & Subscription, choose Monthly or Yearly, make the listed bank transfer and upload the receipt for verification.';
    elsif secondary_intent='trial_signup' and primary_intent<>'trial_signup' then
      secondary_text := 'You can test the full workspace free for 14 days first, with no card required.';
    elsif secondary_intent='pricing' and primary_intent<>'pricing' then
      secondary_text := 'Pro is available as Monthly or Yearly; I can give the current prices in AED, SAR, PKR or USD.';
    elsif secondary_intent='overview' and primary_intent not in ('overview','business_value') then
      secondary_text := 'Triplem VIP keeps the related finance and operational records connected in one private workspace.';
    end if;
  end if;

  if secondary_text is not null and char_length(trim(response_text||' '||secondary_text))<=680 then
    response_text := trim(response_text)||' '||trim(secondary_text);
  end if;

  if response_text='' then response_text:=coalesce(baseline->>'response','I want to make sure I answer the right Triplem VIP question.'); end if;
  if char_length(response_text)>720 then response_text:=left(response_text,717)||'...'; end if;

  return jsonb_build_object(
    'intent',primary_intent,
    'secondary_intent',case when secondary_text is not null then secondary_intent else null end,
    'question_kind',coalesce(nullif(trim(p_ai_analysis->>'question_kind'),''),decision->>'question_kind','direct'),
    'confidence',least(0.9950,greatest(0.6500,semantic_confidence)),
    'handoff',false,'handoff_reason',null,'needs_clarification',false,
    'response',response_text,
    'engine',case when engine<>'' then engine else case when neural then 'transformers_js_minilm' else 'grounded_fallback' end end,
    'model',nullif(model,''),'semantic_used',true
  );
end
$fn$;
revoke all on function public.app_live_chat_ai_semantic_answer(text,text,text,text,jsonb) from public, anon, authenticated;

create or replace function public.app_live_chat_ai_process_semantic(
  p_inquiry_id uuid,
  p_message text,
  p_guest_name text default null,
  p_ai_analysis jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  decision jsonb;
  ai_msg public.app_inquiry_messages;
  next_mode text;
  notices int := 0;
  h_reason text;
  intent text;
  confidence numeric(5,4);
  response_text text;
  inquiry_row public.app_inquiries;
  route_row public.app_live_chat_routes;
  current_ai public.app_live_chat_ai_state;
  recent_guest_context text := null;
  availability jsonb;
  support_open boolean := false;
  needs_clarification boolean := false;
  next_uncertainty integer := 0;
  ai_engine text := 'grounded_fallback';
  ai_model text := null;
begin
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;
  if inquiry_row is null or coalesce(inquiry_row.source,'')<>'landing' or lower(coalesce(inquiry_row.subject,''))<>'live chat support' then
    raise exception 'Live chat session is unavailable';
  end if;

  select * into route_row from public.app_live_chat_routes where inquiry_id=p_inquiry_id for update;
  if route_row.status='accepted' and route_row.assigned_user_id is not null then
    return jsonb_build_object('ok',true,'mode','human','handoff',false,'support_queue',0,'message',null);
  end if;
  if route_row.status='closed' or inquiry_row.status='archived' then
    return jsonb_build_object('ok',true,'mode','closed','handoff',false,'support_queue',0,'message',null);
  end if;

  select * into current_ai from public.app_live_chat_ai_state where inquiry_id=p_inquiry_id for update;
  if current_ai.inquiry_id is not null and current_ai.mode<>'ai' then
    return jsonb_build_object('ok',true,'mode',current_ai.mode,'handoff',(current_ai.mode='human_pending'),'support_queue',0,'message',null);
  end if;

  select string_agg(x.body,' | ' order by x.created_at) into recent_guest_context
  from (
    select m.body,m.created_at
      from public.app_inquiry_messages m
     where m.inquiry_id=p_inquiry_id and m.sender_role='guest'
     order by m.created_at desc
     offset 1 limit 3
  ) x;

  decision:=public.app_live_chat_ai_semantic_answer(
    p_message,
    p_guest_name,
    case when current_ai.inquiry_id is not null then current_ai.last_intent else null end,
    recent_guest_context,
    p_ai_analysis
  );

  h_reason:=nullif(decision->>'handoff_reason','');
  intent:=coalesce(nullif(decision->>'intent',''),'scope');
  confidence:=coalesce((decision->>'confidence')::numeric,0.5000);
  response_text:=trim(coalesce(decision->>'response',''));
  needs_clarification:=coalesce((decision->>'needs_clarification')::boolean,false);
  ai_engine:=left(coalesce(nullif(decision->>'engine',''),'grounded_fallback'),48);
  ai_model:=left(nullif(decision->>'model',''),96);

  availability:=public.app_live_chat_availability();
  support_open:=coalesce((availability->>'is_open')::boolean,false);
  next_uncertainty:=case
    when needs_clarification then least(9,coalesce(current_ai.uncertainty_streak,0)+1)
    else 0
  end;

  if coalesce((decision->>'handoff')::boolean,false) then
    next_mode:='human_pending';
  elsif needs_clarification and next_uncertainty>=2 and support_open then
    next_mode:='human_pending';
    h_reason:='ai_uncertain_repeated';
    response_text:='I am not fully understanding your request, and I do not want to keep giving you irrelevant answers. I have transferred this chat to a real Triplem VIP support agent.';
  else
    next_mode:='ai';
    if needs_clarification and next_uncertainty>=2 and not support_open then
      response_text:=trim(response_text)||' Human Live Support is currently offline and resumes at 10:00 AM GST.';
    end if;
  end if;

  if current_ai.inquiry_id is null then
    response_text:='I am Triplem VIP''s AI Assistant. I use AI to understand your question, but I am still learning and may occasionally make mistakes. '||response_text;
  end if;

  insert into public.app_live_chat_ai_state(
    inquiry_id,mode,last_intent,last_confidence,last_ai_message_at,
    human_requested_at,human_reason,uncertainty_streak,last_ai_engine,last_ai_model,
    created_at,updated_at
  ) values(
    p_inquiry_id,next_mode,intent,confidence,now(),
    case when next_mode='human_pending' then now() else null end,
    case when next_mode='human_pending' then coalesce(h_reason,'visitor_requested') else null end,
    next_uncertainty,ai_engine,ai_model,now(),now()
  )
  on conflict(inquiry_id) do update set
    mode=excluded.mode,
    last_intent=excluded.last_intent,
    last_confidence=excluded.last_confidence,
    last_ai_message_at=excluded.last_ai_message_at,
    human_requested_at=case when excluded.mode='human_pending' then coalesce(app_live_chat_ai_state.human_requested_at,excluded.human_requested_at) else app_live_chat_ai_state.human_requested_at end,
    human_reason=case when excluded.mode='human_pending' then excluded.human_reason else app_live_chat_ai_state.human_reason end,
    uncertainty_streak=excluded.uncertainty_streak,
    last_ai_engine=excluded.last_ai_engine,
    last_ai_model=excluded.last_ai_model,
    updated_at=now();

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,support_actor,created_at)
  values(p_inquiry_id,'admin',null,response_text,'ai',clock_timestamp()+interval '1 millisecond')
  returning * into ai_msg;

  update public.app_inquiries
     set last_message_at=now(),updated_at=now(),
         status=case when next_mode='human_pending' then 'open' else status end
   where id=p_inquiry_id;

  if next_mode='human_pending' then
    notices:=public.app_live_chat_notify_available_agents(p_inquiry_id);
  end if;

  return jsonb_build_object(
    'ok',true,'mode',next_mode,'intent',intent,
    'secondary_intent',decision->>'secondary_intent',
    'question_kind',decision->>'question_kind','confidence',confidence,
    'needs_clarification',needs_clarification,'uncertainty_streak',next_uncertainty,
    'handoff',(next_mode='human_pending'),
    'handoff_reason',case when next_mode='human_pending' then coalesce(h_reason,'visitor_requested') else null end,
    'support_queue',notices,'ai_engine',ai_engine,'ai_model',ai_model,
    'message',public.app_message_public_row(ai_msg)
  );
end
$fn$;
revoke all on function public.app_live_chat_ai_process_semantic(uuid,text,text,jsonb) from public, anon, authenticated;

-- New semantic RPCs keep the 108-111 public RPCs intact as deployment-order and
-- browser-compatibility fallbacks. No old signature is dropped or altered.
create or replace function public.app_public_live_chat_start_semantic(
  p_name text,
  p_mobile text,
  p_email text,
  p_message text,
  p_ai_analysis jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  v_name text:=trim(coalesce(p_name,''));
  v_mobile text:=trim(coalesce(p_mobile,''));
  v_email text:=lower(trim(coalesce(p_email,'')));
  v_msg text:=trim(coalesce(p_message,''));
  inquiry_row public.app_inquiries;
  raw_token text;
  expires timestamptz:=now()+interval '2 hours';
  availability jsonb:=public.app_live_chat_availability();
  ai_result jsonb;
  messages jsonb:='[]'::jsonb;
begin
  if char_length(v_name)<2 then raise exception 'Please enter your full name'; end if;
  if char_length(v_mobile)<6 then raise exception 'Please enter a valid contact number'; end if;
  if v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email address'; end if;
  if char_length(v_msg)<1 then raise exception 'Please write a message'; end if;
  if char_length(v_msg)>4000 then raise exception 'Message is too long (max 4000 characters)'; end if;

  perform public.app_live_chat_assert_start_limit(v_email);

  insert into public.app_inquiries(
    sender_id,subject,body,status,source,guest_name,guest_email,guest_phone,last_message_at,user_last_read_at
  ) values(
    null,'Live Chat Support',v_msg,'open','landing',v_name,v_email,v_mobile,now(),now()
  ) returning * into inquiry_row;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(inquiry_row.id,'guest',null,v_msg);

  raw_token:=encode(extensions.gen_random_bytes(32),'hex');
  insert into public.app_live_chat_guest_access(
    inquiry_id,token_hash,expires_at,last_guest_message_at,guest_message_count
  ) values(
    inquiry_row.id,public.app_hash_token(raw_token),expires,now(),1
  );

  insert into public.app_live_chat_routes(inquiry_id,status,created_at,updated_at)
  values(inquiry_row.id,'pending',now(),now())
  on conflict(inquiry_id) do nothing;

  ai_result:=public.app_live_chat_ai_process_semantic(inquiry_row.id,v_msg,v_name,p_ai_analysis);

  select * into inquiry_row from public.app_inquiries where id=inquiry_row.id;
  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb)
    into messages
  from public.app_inquiry_messages m where m.inquiry_id=inquiry_row.id;

  return jsonb_build_object(
    'ok',true,'inquiry_id',inquiry_row.id,'guest_token',raw_token,'expires_at',expires,
    'availability',availability,'inquiry',public.app_inquiry_public_row(inquiry_row),
    'messages',messages,'support_mode',coalesce(ai_result->>'mode','ai'),
    'support_label',case when ai_result->>'mode'='human_pending' then 'Waiting for a human support agent' else 'Triplem VIP AI Assistant' end,
    'ai_available',true,'ai_engine',ai_result->>'ai_engine',
    'support_queue',coalesce((ai_result->>'support_queue')::int,0)
  );
end
$fn$;
revoke all on function public.app_public_live_chat_start_semantic(text,text,text,text,jsonb) from public;
grant execute on function public.app_public_live_chat_start_semantic(text,text,text,text,jsonb) to anon,authenticated,service_role;

create or replace function public.app_public_live_chat_reply_semantic(
  p_inquiry_id uuid,
  p_guest_token text,
  p_body text,
  p_ai_analysis jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access;
  inquiry_row public.app_inquiries;
  route public.app_live_chat_routes;
  ai public.app_live_chat_ai_state;
  msg text:=trim(coalesce(p_body,''));
  new_msg public.app_inquiry_messages;
  ai_result jsonb;
  support_mode text;
  support_label text;
begin
  if char_length(msg)<1 then raise exception 'Please write a message'; end if;
  if char_length(msg)>4000 then raise exception 'Message is too long (max 4000 characters)'; end if;

  access_row:=public.app_live_chat_validate_guest(p_inquiry_id,p_guest_token);

  insert into public.app_live_chat_routes(inquiry_id,status,created_at,updated_at)
  values(p_inquiry_id,'pending',now(),now())
  on conflict(inquiry_id) do nothing;
  if found then perform public.app_live_chat_notify_available_agents(p_inquiry_id); end if;

  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id for update;
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id for update;
  select * into access_row from public.app_live_chat_guest_access where inquiry_id=p_inquiry_id for update;
  if inquiry_row is null or inquiry_row.subject<>'Live Chat Support' then raise exception 'Live chat session is unavailable'; end if;
  if access_row.guest_message_count>=250 then raise exception 'This live chat has reached its message limit'; end if;
  if access_row.last_guest_message_at is not null and access_row.last_guest_message_at>now()-interval '500 milliseconds' then
    raise exception 'Please wait a moment before sending another message';
  end if;
  if inquiry_row.status='archived' or route.status='closed' then
    raise exception 'This live chat has ended. Please start a new chat if you still need help.';
  end if;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(p_inquiry_id,'guest',null,msg) returning * into new_msg;

  update public.app_inquiries
     set body=msg,
         status=case when route.status='accepted' then 'read' else 'open' end,
         last_message_at=now(),user_last_read_at=now(),updated_at=now()
   where id=p_inquiry_id returning * into inquiry_row;

  update public.app_live_chat_guest_access
     set last_guest_message_at=now(),guest_message_count=guest_message_count+1
   where inquiry_id=p_inquiry_id;

  select * into ai from public.app_live_chat_ai_state where inquiry_id=p_inquiry_id;
  if route.status='accepted' and route.assigned_user_id is not null then
    support_mode:='human';
  elsif ai.mode='ai' then
    ai_result:=public.app_live_chat_ai_process_semantic(p_inquiry_id,msg,inquiry_row.guest_name,p_ai_analysis);
    support_mode:=coalesce(ai_result->>'mode','ai');
  elsif ai.mode is not null then
    support_mode:=ai.mode;
  else
    support_mode:='legacy_human';
  end if;

  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;

  support_label:=case support_mode
    when 'ai' then 'Triplem VIP AI Assistant'
    when 'human_pending' then 'Waiting for a human support agent'
    when 'human' then coalesce((select coalesce(nullif(trim(u.display_name),''),u.username) from public.app_users u where u.id=route.assigned_user_id),'Triplem VIP Support Agent')
    else 'Triplem VIP Live Support'
  end;

  return jsonb_build_object(
    'ok',true,'message',public.app_message_public_row(new_msg),
    'ai_message',case when ai_result is null then null else ai_result->'message' end,
    'inquiry',public.app_inquiry_public_row(inquiry_row),'support_mode',support_mode,
    'support_label',support_label,'ai_available',true,
    'ai_engine',case when ai_result is null then null else ai_result->>'ai_engine' end,
    'handoff',coalesce((ai_result->>'handoff')::boolean,false),
    'support_queue',coalesce((ai_result->>'support_queue')::int,0)
  );
end
$fn$;
revoke all on function public.app_public_live_chat_reply_semantic(uuid,text,text,jsonb) from public;
grant execute on function public.app_public_live_chat_reply_semantic(uuid,text,text,jsonb) to anon,authenticated,service_role;

