-- BEGIN migrations/113_live_chat_ai_contextual_neural_agent_refinement.sql
-- ############################################################################

-- ============================================================================
-- 113_live_chat_ai_contextual_neural_agent_refinement.sql
-- Triplem VIP Live Support: contextual neural understanding + AI vs Agent terms.
--
-- PURPOSE
--   * Fix the 112 browser ESM neural-loader path and accept richer semantic hints.
--   * Understand pronouns, short confirmations, subscription actions and payment
--     security as conversational intent instead of matching canned phrases.
--   * Keep server-side verified public facts authoritative and preserve all
--     confidentiality/private-data/security guards.
--   * Visitor-facing terminology is consistently AI vs Agent. Internal mode
--     values such as `human` / `human_pending` are retained for compatibility.
--
-- LIVE-DATABASE SAFETY
--   * Run after 112.
--   * Function replacement only. No installation-time INSERT/UPDATE/DELETE.
--   * No table/column deletion and no existing user/business/financial rewrite.
--   * No paid AI API, metered inference endpoint, API key or external LLM service.
-- ============================================================================

create or replace function public.app_live_chat_ai_human_requested(p_message text)
returns boolean
language plpgsql
immutable
set search_path = public
as $fn$
declare
  q text := lower(regexp_replace(trim(coalesce(p_message,'')),'\s+',' ','g'));
begin
  if q='' then return false; end if;
  return
    q ~ '(^|[^a-z])(transfer|handover|hand over|connect|speak|talk|chat|move)([^a-z].*)?(human|agent|representative|real person|real support|support person|support staff|support team|customer support|administrator|admin|someone|person)'
    or q ~ '(^|[^a-z])(human|agent|representative|real person|real support|support person|support staff|support team|customer support|administrator|admin|someone from support)([^a-z].*)?(please|now|instead|only|wanted|want|need|prefer|connect|transfer|speak|talk|chat)'
    or q ~ '(want|need|prefer|like).{0,30}(talk|speak|chat).{0,30}(person|someone|agent|support)'
    or q ~ '(can|could|would).{0,20}(you )?(transfer|connect).{0,30}(support|person|agent|someone)'
    or q ~ '(do not|don''t|dont|no) (want|need) (ai|bot)'
    or q ~ '(stop|disable) (the )?(ai|bot)'
    or q in ('human','agent','real agent','support agent','support person','real person','customer support','administrator','admin','human please','agent please');
end
$fn$;
revoke all on function public.app_live_chat_ai_human_requested(text) from public, anon, authenticated;

create or replace function public.app_live_chat_ai_semantic_intent_allowed(p_intent text)
returns boolean
language sql
immutable
set search_path = public
as $fn$
  select lower(trim(coalesce(p_intent,''))) = any(array[
    'overview','business_value','setup','dashboard','pricing','payment_method','payment_security','trial_signup',
    'wallets','expenses','income','currency','inventory','sales','customers','invoices',
    'reports','loans','installments','assets','notes','bitcoin','company_team','platforms',
    'personalization','security','continuity','demo','smart_pin','import_backup','support','founder'
  ]::text[])
$fn$;
revoke all on function public.app_live_chat_ai_semantic_intent_allowed(text) from public, anon, authenticated;

create or replace function public.app_live_chat_ai_semantic_prompt(p_intent text,p_original_message text)
returns text
language plpgsql
immutable
set search_path = public
as $fn$
declare i text:=lower(trim(coalesce(p_intent,''))); q text:=lower(trim(coalesce(p_original_message,'')));
begin
  return case i
    when 'overview' then 'What is Triplem VIP for, how does it work and what can it manage?'
    when 'business_value' then 'Who is Triplem VIP for and how can it help a business or individual?'
    when 'setup' then 'How do I get started and set up Triplem VIP?'
    when 'dashboard' then 'What does the Triplem VIP dashboard show?'
    when 'pricing' then case when q~'(yearly|annual)' and q!~'monthly' then 'What is the current Pro Yearly price?' when q~'monthly' and q!~'(yearly|annual)' then 'What is the current Pro Monthly price?' else 'What are the current Pro Monthly and Pro Yearly prices?' end
    when 'payment_method' then 'How do I get, subscribe to, activate or renew a Triplem VIP Pro plan?'
    when 'payment_security' then 'How is the Triplem VIP Pro bank-transfer and receipt-verification payment workflow kept private and safe?'
    when 'trial_signup' then 'How do I start the 14-day free trial?'
    when 'wallets' then 'How do Triplem VIP wallets and balances work?'
    when 'expenses' then 'How do I record and review expenses in Triplem VIP?'
    when 'income' then 'How does Triplem VIP track incoming money?'
    when 'currency' then 'How does Triplem VIP handle multiple currencies?'
    when 'inventory' then 'How does Triplem VIP manage inventory and stock?'
    when 'sales' then 'How do sales work in Triplem VIP?'
    when 'customers' then 'How does Triplem VIP manage customers and balances?'
    when 'invoices' then 'Can Triplem VIP create invoices and receipts?'
    when 'reports' then 'What reports, statements and exports can Triplem VIP produce?'
    when 'loans' then 'How does Triplem VIP manage loans and repayments?'
    when 'installments' then 'How does Triplem VIP manage installment plans?'
    when 'assets' then 'How does Triplem VIP manage assets?'
    when 'notes' then 'How do notes and reminders work in Triplem VIP?'
    when 'bitcoin' then 'What verified Bitcoin tools are available in Triplem VIP?'
    when 'company_team' then 'How do Company workspaces, team members and permissions work?'
    when 'platforms' then 'Does Triplem VIP work on phone, tablet and desktop browsers?'
    when 'personalization' then 'How can Triplem VIP themes, logos and branding be personalized?'
    when 'security' then 'What public security and privacy protections does Triplem VIP use?'
    when 'continuity' then 'What backup, export and reconnect workflows are supported?'
    when 'demo' then 'How can I see the Triplem VIP demo?'
    when 'smart_pin' then 'What is Triplem VIP Smart PIN?'
    when 'import_backup' then 'What import, export and backup workflows are supported?'
    when 'support' then 'When is Triplem VIP Agent Support available and how do I reach an agent?'
    when 'founder' then 'Who created Triplem VIP?'
    else p_original_message end;
end
$fn$;
revoke all on function public.app_live_chat_ai_semantic_prompt(text,text) from public, anon, authenticated;

create or replace function public.app_live_chat_ai_semantic_answer(
  p_message text,
  p_guest_name text,
  p_previous_intent text,
  p_previous_message text,
  p_ai_analysis jsonb
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  q text := lower(regexp_replace(trim(coalesce(p_message,'')),'\s+',' ','g'));
  prev_q text := lower(regexp_replace(trim(coalesce(p_previous_message,'')),'\s+',' ','g'));
  prev_intent text := lower(trim(coalesce(p_previous_intent,'')));
  baseline jsonb;
  baseline_intent text;
  primary_intent text := null;
  secondary_intent text := null;
  semantic_confidence numeric(6,5):=0;
  primary_score numeric(6,5):=0;
  secondary_score numeric(6,5):=0;
  engine text:=left(lower(trim(coalesce(p_ai_analysis->>'engine',''))),48);
  model text:=left(trim(coalesce(p_ai_analysis->>'model','')),96);
  neural boolean:=lower(trim(coalesce(p_ai_analysis->>'neural','false')))='true';
  question_kind text:=lower(trim(coalesce(p_ai_analysis->>'question_kind','')));
  plan_period text:=lower(trim(coalesce(p_ai_analysis->>'plan_period','unknown')));
  currency text:=upper(trim(coalesce(p_ai_analysis->>'currency','unknown')));
  response_text text:='';
  secondary_text text:=null;
  monthly_aed text; monthly_sar text; monthly_pkr text; monthly_usd text;
  yearly_aed text; yearly_sar text; yearly_pkr text; yearly_usd text;
  reason text;
  amount_only boolean:=false;
  confirmation boolean:=false;
  brand_related boolean:=false;
begin
  if engine not in ('browser_language_model','transformers_js_minilm','grounded_fallback') then engine:='grounded_fallback'; model:=''; neural:=false; end if;
  if engine='grounded_fallback' then model:=''; neural:=false; end if;
  if plan_period not in ('monthly','yearly') then plan_period:='unknown'; end if;
  if currency not in ('AED','SAR','PKR','USD') then currency:='unknown'; end if;

  -- Server-side policy always wins over any client-side neural hint.
  if public.app_live_chat_ai_human_requested(q) then
    return jsonb_build_object('intent','human_handoff','question_kind','handoff','confidence',1,'handoff',true,'handoff_reason','visitor_requested','needs_clarification',false,'response','Certainly. AI replies are paused and this chat is now in the Agent queue. A Triplem VIP support agent will continue from here.','engine','guarded_server_policy','model',null,'semantic_used',false);
  end if;
  reason:=public.app_live_chat_ai_sensitive_handoff_reason(q);
  if reason is not null then
    baseline:=public.app_live_chat_ai_answer(p_message,p_guest_name,p_previous_intent,p_previous_message);
    return baseline || jsonb_build_object('engine','guarded_server_policy','model',null,'semantic_used',false);
  end if;
  if public.app_live_chat_ai_private_data_request(q) or public.app_live_chat_ai_confidential_request(q) then
    baseline:=public.app_live_chat_ai_answer(p_message,p_guest_name,p_previous_intent,p_previous_message);
    return baseline || jsonb_build_object('engine','guarded_server_policy','model',null,'semantic_used',false);
  end if;

  amount_only := q ~ '^(aed|sar|pkr|usd)[ ]*[0-9][0-9,.]*[ ?!.]*$';
  confirmation := question_kind='confirmation' or q ~ '^(are you sure|sure|really|is that right|is that correct|correct|right|okay so|ok so)[ ?!.?]*$' or amount_only;

  -- Natural-language repairs for short conversational turns. These are semantic
  -- categories, not exact canned-query matching; neural hints below cover wider paraphrases.
  if q ~ '^(what is|what''s|whats) (this|it) for[ ?!.]*$' or q ~ '^what does (this|it) do[ ?!.]*$' then
    primary_intent:='overview'; primary_score:=0.97; semantic_confidence:=0.97; question_kind:='explain';
  elsif q ~ '(security|safe|secure|protect).{0,35}(payment|bank transfer|receipt)|(payment|bank transfer|receipt).{0,35}(security|safe|secure|protect)' then
    primary_intent:='payment_security'; primary_score:=0.98; semantic_confidence:=0.98; question_kind:='explain';
  elsif q ~ '(how|where).{0,20}(get|buy|take|choose|activate|subscribe).{0,30}(plan|monthly|yearly|pro)|(i|we) (want|need|would like).{0,25}(monthly|yearly|pro|plan)' then
    primary_intent:='payment_method'; primary_score:=0.96; semantic_confidence:=0.96; question_kind:='howto';
    if q~'monthly' then plan_period:='monthly'; elsif q~'(yearly|annual)' then plan_period:='yearly'; end if;
  elsif confirmation and prev_intent<>'' then
    primary_intent:=prev_intent; primary_score:=0.95; semantic_confidence:=0.95; question_kind:='confirmation';
  end if;

  baseline:=public.app_live_chat_ai_answer(p_message,p_guest_name,p_previous_intent,p_previous_message);
  baseline_intent:=coalesce(baseline->>'intent','');
  if coalesce((baseline->>'handoff')::boolean,false) or baseline_intent in ('human_handoff','protected_handoff','privacy_guard','confidentiality_guard','scope_guard','ai_identity','greeting','unverified_capability') then
    return baseline || jsonb_build_object('engine','guarded_server_policy','model',null,'semantic_used',false);
  end if;

  if primary_intent is null and jsonb_typeof(coalesce(p_ai_analysis->'intents','[]'::jsonb))='array' then
    select lower(trim(x.value->>'intent')),public.app_live_chat_ai_safe_score(x.value->>'score')
      into primary_intent,primary_score
      from jsonb_array_elements(p_ai_analysis->'intents') with ordinality x(value,ord)
     where public.app_live_chat_ai_semantic_intent_allowed(x.value->>'intent') order by x.ord limit 1;
    select lower(trim(x.value->>'intent')),public.app_live_chat_ai_safe_score(x.value->>'score')
      into secondary_intent,secondary_score
      from jsonb_array_elements(p_ai_analysis->'intents') with ordinality x(value,ord)
     where public.app_live_chat_ai_semantic_intent_allowed(x.value->>'intent') and lower(trim(x.value->>'intent')) is distinct from primary_intent order by x.ord limit 1;
    semantic_confidence:=greatest(primary_score,public.app_live_chat_ai_safe_score(p_ai_analysis->>'confidence'));
  end if;

  -- Server-side contextual recovery when a device cannot run the neural model.
  if primary_intent is null then
    if baseline_intent not in ('scope','triplem_clarify','') then primary_intent:=baseline_intent; semantic_confidence:=coalesce((baseline->>'confidence')::numeric,0.65); end if;
  end if;
  if primary_intent is null and confirmation then
    if prev_q~'(payment|receipt|bank transfer).*(security|safe|secure)|(security|safe|secure).*(payment|receipt|bank transfer)' then primary_intent:='payment_security';
    elsif prev_q~'(monthly|yearly|annual|price|pricing|aed|sar|pkr|usd|plan)' then primary_intent:=case when prev_q~'(get|buy|subscribe|want|need|activate)' then 'payment_method' else 'pricing' end;
    end if;
    if primary_intent is not null then semantic_confidence:=0.88; end if;
  end if;

  brand_related:=q~'(triplem|vip|plan|subscription|trial|wallet|expense|inventory|stock|sale|loan|installment|asset|invoice|receipt|report|support|finance|accounting|payment|security)';
  if primary_intent is null or semantic_confidence<0.30 then
    if baseline_intent in ('scope','triplem_clarify') and brand_related then
      return jsonb_build_object('intent','triplem_clarify','secondary_intent',null,'question_kind','clarify','confidence',greatest(0.4,semantic_confidence),'handoff',false,'handoff_reason',null,'needs_clarification',true,'response','I may be missing the intent. Tell me the Triplem VIP task you want to do, for example subscribe, manage stock, record expenses, create an invoice, or speak to an Agent.','engine',coalesce(nullif(engine,''),'grounded_fallback'),'model',nullif(model,''),'semantic_used',false);
    end if;
    return baseline || jsonb_build_object('engine',coalesce(nullif(engine,''),'grounded_fallback'),'model',nullif(model,''),'semantic_used',false);
  end if;

  monthly_aed:=coalesce(public.app_subscription_price('monthly','AED',0)->>'base_amount','49.00');
  monthly_sar:=coalesce(public.app_subscription_price('monthly','SAR',0)->>'base_amount','49.00');
  monthly_pkr:=coalesce(public.app_subscription_price('monthly','PKR',0)->>'base_amount','1799.00');
  monthly_usd:=coalesce(public.app_subscription_price('monthly','USD',0)->>'base_amount','13.99');
  yearly_aed:=coalesce(public.app_subscription_price('yearly','AED',0)->>'base_amount','449.00');
  yearly_sar:=coalesce(public.app_subscription_price('yearly','SAR',0)->>'base_amount','449.00');
  yearly_pkr:=coalesce(public.app_subscription_price('yearly','PKR',0)->>'base_amount','19999.00');
  yearly_usd:=coalesce(public.app_subscription_price('yearly','USD',0)->>'base_amount','149.00');

  if primary_intent='overview' then
    response_text:='Triplem VIP is for managing business and personal finance in one private workspace: wallets, expenses, inventory and sales, loans, installments, assets, invoices/receipts and reports stay connected instead of being scattered across separate records.';
  elsif primary_intent='pricing' then
    if question_kind='confirmation' and (amount_only or q~'sure|correct|right|really') then
      if prev_q~'yearly|annual' then response_text:=format('Yes. Pro Yearly is currently AED %s, SAR %s, PKR %s or USD %s.',yearly_aed,yearly_sar,yearly_pkr,yearly_usd);
      else response_text:=format('Yes. Pro Monthly is currently AED %s, SAR %s, PKR %s or USD %s.',monthly_aed,monthly_sar,monthly_pkr,monthly_usd); end if;
    elsif (plan_period='yearly' or q~'(yearly|annual)') and q!~'monthly' then response_text:=format('Pro Yearly is AED %s, SAR %s, PKR %s or USD %s. The 14-day full-workspace trial is available first with no card.',yearly_aed,yearly_sar,yearly_pkr,yearly_usd);
    elsif (plan_period='monthly' or q~'monthly') and q!~'(yearly|annual)' then response_text:=format('Pro Monthly is AED %s, SAR %s, PKR %s or USD %s. The 14-day full-workspace trial is available first with no card.',monthly_aed,monthly_sar,monthly_pkr,monthly_usd);
    else response_text:=format('Pro Monthly is AED %s / SAR %s / PKR %s / USD %s. Pro Yearly is AED %s / SAR %s / PKR %s / USD %s. A 14-day full-workspace trial is available first with no card.',monthly_aed,monthly_sar,monthly_pkr,monthly_usd,yearly_aed,yearly_sar,yearly_pkr,yearly_usd); end if;
  elsif primary_intent='payment_method' then
    if question_kind='confirmation' and (amount_only or q~'sure|correct|right|really') then
      if prev_q~'yearly|annual' then response_text:=format('Yes. If you mean Pro Yearly, the AED base price is %s. To subscribe, sign in, open Plan & Subscription, choose Yearly and your currency, make the listed bank transfer and upload the receipt for verification.',yearly_aed);
      else response_text:=format('Yes. If you mean Pro Monthly, the AED base price is %s. To subscribe, sign in, open Plan & Subscription, choose Monthly and your currency, make the listed bank transfer and upload the receipt for verification.',monthly_aed); end if;
    elsif plan_period='monthly' or q~'monthly' then response_text:='To get Pro Monthly, sign in, open Plan & Subscription, choose Monthly and your currency, select the listed bank account, complete the transfer and upload the receipt. Activation follows payment verification.';
    elsif plan_period='yearly' or q~'(yearly|annual)' then response_text:='To get Pro Yearly, sign in, open Plan & Subscription, choose Yearly and your currency, select the listed bank account, complete the transfer and upload the receipt. Activation follows payment verification.';
    else response_text:='To subscribe, sign in and open Plan & Subscription. Choose Pro Monthly or Pro Yearly and your currency, use the listed bank-transfer account, then upload the receipt. Activation follows payment verification.'; end if;
  elsif primary_intent='payment_security' then
    if question_kind='confirmation' then response_text:='Yes. Pro payment uses the listed bank-transfer workflow and a private receipt-verification step. The AI Assistant cannot see, approve or change your private payment or receipt.';
    else response_text:='Pro payment is handled through the listed bank-transfer workflow, not through AI chat. The receipt is accepted only in supported image/PDF formats, kept private for administrator review, and activation follows verification. The AI Assistant cannot access your receipt or payment status.'; end if;
  elsif primary_intent='security' then
    if question_kind='confirmation' then response_text:='Yes. Triplem VIP keeps workspaces isolated with server-side access controls, while public AI chat is blocked from credentials, private records and implementation-sensitive security details.';
    else response_text:='Triplem VIP uses isolated private workspaces and server-side access controls. The AI Assistant cannot access credentials, private workspace records or implementation-sensitive security details.'; end if;
  elsif primary_intent='trial_signup' then response_text:='You can start with the 14-day full-workspace trial with no card. Create an Individual or Company account, test your real workflow, then choose Pro Monthly or Pro Yearly if it fits.';
  elsif primary_intent='support' then response_text:='AI assistance is available continuously. Agent Support operates 10:00 AM to 5:00 PM GST; ask me to transfer you to an Agent at any time.';
  else
    response_text:=trim(coalesce((public.app_live_chat_ai_answer(public.app_live_chat_ai_semantic_prompt(primary_intent,p_message),p_guest_name,p_previous_intent,p_message))->>'response',''));
    if response_text='' then response_text:=coalesce(baseline->>'response','I understand the Triplem VIP topic, but I need one more detail to answer accurately.'); end if;
  end if;

  if secondary_intent='payment_method' and primary_intent not in ('payment_method','pricing') and secondary_score>=0.45 then secondary_text:='If you want to subscribe, I can also give you the exact Monthly or Yearly steps.';
  elsif secondary_intent='pricing' and primary_intent<>'pricing' and secondary_score>=0.45 then secondary_text:='I can also give the current Monthly or Yearly price in AED, SAR, PKR or USD.';
  elsif secondary_intent='payment_security' and primary_intent<>'payment_security' and secondary_score>=0.45 then secondary_text:='Payment uses the listed bank-transfer and private receipt-verification workflow.';
  end if;
  if secondary_text is not null and char_length(response_text||' '||secondary_text)<=700 then response_text:=trim(response_text)||' '||secondary_text; end if;
  if char_length(response_text)>720 then response_text:=left(response_text,717)||'...'; end if;

  return jsonb_build_object('intent',primary_intent,'secondary_intent',case when secondary_text is null then null else secondary_intent end,'question_kind',coalesce(nullif(question_kind,''),'direct'),'confidence',least(0.995,greatest(0.65,semantic_confidence)),'handoff',false,'handoff_reason',null,'needs_clarification',false,'response',response_text,'engine',coalesce(nullif(engine,''),case when neural then 'transformers_js_minilm' else 'grounded_fallback' end),'model',nullif(model,''),'semantic_used',neural or engine<>'grounded_fallback');
end
$fn$;
revoke all on function public.app_live_chat_ai_semantic_answer(text,text,text,text,jsonb) from public, anon, authenticated;

create or replace function public.app_live_chat_ai_process_semantic(
  p_inquiry_id uuid,
  p_message text,
  p_guest_name text default null,
  p_ai_analysis jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  decision jsonb;
  ai_msg public.app_inquiry_messages;
  next_mode text;
  notices int := 0;
  h_reason text;
  intent text;
  confidence numeric(5,4);
  response_text text;
  inquiry_row public.app_inquiries;
  route_row public.app_live_chat_routes;
  current_ai public.app_live_chat_ai_state;
  recent_guest_context text := null;
  availability jsonb;
  support_open boolean := false;
  needs_clarification boolean := false;
  next_uncertainty integer := 0;
  ai_engine text := 'grounded_fallback';
  ai_model text := null;
begin
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;
  if inquiry_row is null or coalesce(inquiry_row.source,'')<>'landing' or lower(coalesce(inquiry_row.subject,''))<>'live chat support' then
    raise exception 'Live chat session is unavailable';
  end if;

  select * into route_row from public.app_live_chat_routes where inquiry_id=p_inquiry_id for update;
  if route_row.status='accepted' and route_row.assigned_user_id is not null then
    return jsonb_build_object('ok',true,'mode','human','handoff',false,'support_queue',0,'message',null);
  end if;
  if route_row.status='closed' or inquiry_row.status='archived' then
    return jsonb_build_object('ok',true,'mode','closed','handoff',false,'support_queue',0,'message',null);
  end if;

  select * into current_ai from public.app_live_chat_ai_state where inquiry_id=p_inquiry_id for update;
  if current_ai.inquiry_id is not null and current_ai.mode<>'ai' then
    return jsonb_build_object('ok',true,'mode',current_ai.mode,'handoff',(current_ai.mode='human_pending'),'support_queue',0,'message',null);
  end if;

  select string_agg(x.body,' | ' order by x.created_at) into recent_guest_context
  from (
    select m.body,m.created_at
      from public.app_inquiry_messages m
     where m.inquiry_id=p_inquiry_id and m.sender_role='guest'
     order by m.created_at desc
     offset 1 limit 3
  ) x;

  decision:=public.app_live_chat_ai_semantic_answer(
    p_message,
    p_guest_name,
    case when current_ai.inquiry_id is not null then current_ai.last_intent else null end,
    recent_guest_context,
    p_ai_analysis
  );

  h_reason:=nullif(decision->>'handoff_reason','');
  intent:=coalesce(nullif(decision->>'intent',''),'scope');
  confidence:=coalesce((decision->>'confidence')::numeric,0.5000);
  response_text:=trim(coalesce(decision->>'response',''));
  needs_clarification:=coalesce((decision->>'needs_clarification')::boolean,false);
  ai_engine:=left(coalesce(nullif(decision->>'engine',''),'grounded_fallback'),48);
  ai_model:=left(nullif(decision->>'model',''),96);

  availability:=public.app_live_chat_availability();
  support_open:=coalesce((availability->>'is_open')::boolean,false);
  next_uncertainty:=case
    when needs_clarification then least(9,coalesce(current_ai.uncertainty_streak,0)+1)
    else 0
  end;

  if coalesce((decision->>'handoff')::boolean,false) then
    next_mode:='human_pending';
  elsif needs_clarification and next_uncertainty>=2 and support_open then
    next_mode:='human_pending';
    h_reason:='ai_uncertain_repeated';
    response_text:='I am not fully understanding your request, and I do not want to keep giving you irrelevant answers. I have transferred this chat to a Triplem VIP support agent.';
  else
    next_mode:='ai';
    if needs_clarification and next_uncertainty>=2 and not support_open then
      response_text:=trim(response_text)||' Agent Support is currently offline and resumes at 10:00 AM GST.';
    end if;
  end if;

  if current_ai.inquiry_id is null then
    response_text:='I am Triplem VIP''s AI Assistant. I am still learning and may occasionally make mistakes. '||response_text;
  end if;

  insert into public.app_live_chat_ai_state(
    inquiry_id,mode,last_intent,last_confidence,last_ai_message_at,
    human_requested_at,human_reason,uncertainty_streak,last_ai_engine,last_ai_model,
    created_at,updated_at
  ) values(
    p_inquiry_id,next_mode,intent,confidence,now(),
    case when next_mode='human_pending' then now() else null end,
    case when next_mode='human_pending' then coalesce(h_reason,'visitor_requested') else null end,
    next_uncertainty,ai_engine,ai_model,now(),now()
  )
  on conflict(inquiry_id) do update set
    mode=excluded.mode,
    last_intent=excluded.last_intent,
    last_confidence=excluded.last_confidence,
    last_ai_message_at=excluded.last_ai_message_at,
    human_requested_at=case when excluded.mode='human_pending' then coalesce(app_live_chat_ai_state.human_requested_at,excluded.human_requested_at) else app_live_chat_ai_state.human_requested_at end,
    human_reason=case when excluded.mode='human_pending' then excluded.human_reason else app_live_chat_ai_state.human_reason end,
    uncertainty_streak=excluded.uncertainty_streak,
    last_ai_engine=excluded.last_ai_engine,
    last_ai_model=excluded.last_ai_model,
    updated_at=now();

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,support_actor,created_at)
  values(p_inquiry_id,'admin',null,response_text,'ai',clock_timestamp()+interval '1 millisecond')
  returning * into ai_msg;

  update public.app_inquiries
     set last_message_at=now(),updated_at=now(),
         status=case when next_mode='human_pending' then 'open' else status end
   where id=p_inquiry_id;

  if next_mode='human_pending' then
    notices:=public.app_live_chat_notify_available_agents(p_inquiry_id);
  end if;

  return jsonb_build_object(
    'ok',true,'mode',next_mode,'intent',intent,
    'secondary_intent',decision->>'secondary_intent',
    'question_kind',decision->>'question_kind','confidence',confidence,
    'needs_clarification',needs_clarification,'uncertainty_streak',next_uncertainty,
    'handoff',(next_mode='human_pending'),
    'handoff_reason',case when next_mode='human_pending' then coalesce(h_reason,'visitor_requested') else null end,
    'support_queue',notices,'ai_engine',ai_engine,'ai_model',ai_model,
    'message',public.app_message_public_row(ai_msg)
  );
end
$fn$;
revoke all on function public.app_live_chat_ai_process_semantic(uuid,text,text,jsonb) from public, anon, authenticated;

create or replace function public.app_public_live_chat_start_semantic(
  p_name text,
  p_mobile text,
  p_email text,
  p_message text,
  p_ai_analysis jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  v_name text:=trim(coalesce(p_name,''));
  v_mobile text:=trim(coalesce(p_mobile,''));
  v_email text:=lower(trim(coalesce(p_email,'')));
  v_msg text:=trim(coalesce(p_message,''));
  inquiry_row public.app_inquiries;
  raw_token text;
  expires timestamptz:=now()+interval '2 hours';
  availability jsonb:=public.app_live_chat_availability();
  ai_result jsonb;
  messages jsonb:='[]'::jsonb;
begin
  if char_length(v_name)<2 then raise exception 'Please enter your full name'; end if;
  if char_length(v_mobile)<6 then raise exception 'Please enter a valid contact number'; end if;
  if v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email address'; end if;
  if char_length(v_msg)<1 then raise exception 'Please write a message'; end if;
  if char_length(v_msg)>4000 then raise exception 'Message is too long (max 4000 characters)'; end if;

  perform public.app_live_chat_assert_start_limit(v_email);

  insert into public.app_inquiries(
    sender_id,subject,body,status,source,guest_name,guest_email,guest_phone,last_message_at,user_last_read_at
  ) values(
    null,'Live Chat Support',v_msg,'open','landing',v_name,v_email,v_mobile,now(),now()
  ) returning * into inquiry_row;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(inquiry_row.id,'guest',null,v_msg);

  raw_token:=encode(extensions.gen_random_bytes(32),'hex');
  insert into public.app_live_chat_guest_access(
    inquiry_id,token_hash,expires_at,last_guest_message_at,guest_message_count
  ) values(
    inquiry_row.id,public.app_hash_token(raw_token),expires,now(),1
  );

  insert into public.app_live_chat_routes(inquiry_id,status,created_at,updated_at)
  values(inquiry_row.id,'pending',now(),now())
  on conflict(inquiry_id) do nothing;

  ai_result:=public.app_live_chat_ai_process_semantic(inquiry_row.id,v_msg,v_name,p_ai_analysis);

  select * into inquiry_row from public.app_inquiries where id=inquiry_row.id;
  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb)
    into messages
  from public.app_inquiry_messages m where m.inquiry_id=inquiry_row.id;

  return jsonb_build_object(
    'ok',true,'inquiry_id',inquiry_row.id,'guest_token',raw_token,'expires_at',expires,
    'availability',availability,'inquiry',public.app_inquiry_public_row(inquiry_row),
    'messages',messages,'support_mode',coalesce(ai_result->>'mode','ai'),
    'support_label',case when ai_result->>'mode'='human_pending' then 'Waiting for an Agent' else 'Triplem VIP AI Assistant' end,
    'ai_available',true,'ai_engine',ai_result->>'ai_engine',
    'support_queue',coalesce((ai_result->>'support_queue')::int,0)
  );
end
$fn$;
revoke all on function public.app_public_live_chat_start_semantic(text,text,text,text,jsonb) from public;
grant execute on function public.app_public_live_chat_start_semantic(text,text,text,text,jsonb) to anon,authenticated,service_role;

create or replace function public.app_public_live_chat_reply_semantic(
  p_inquiry_id uuid,
  p_guest_token text,
  p_body text,
  p_ai_analysis jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access;
  inquiry_row public.app_inquiries;
  route public.app_live_chat_routes;
  ai public.app_live_chat_ai_state;
  msg text:=trim(coalesce(p_body,''));
  new_msg public.app_inquiry_messages;
  ai_result jsonb;
  support_mode text;
  support_label text;
begin
  if char_length(msg)<1 then raise exception 'Please write a message'; end if;
  if char_length(msg)>4000 then raise exception 'Message is too long (max 4000 characters)'; end if;

  access_row:=public.app_live_chat_validate_guest(p_inquiry_id,p_guest_token);

  insert into public.app_live_chat_routes(inquiry_id,status,created_at,updated_at)
  values(p_inquiry_id,'pending',now(),now())
  on conflict(inquiry_id) do nothing;
  if found then perform public.app_live_chat_notify_available_agents(p_inquiry_id); end if;

  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id for update;
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id for update;
  select * into access_row from public.app_live_chat_guest_access where inquiry_id=p_inquiry_id for update;
  if inquiry_row is null or inquiry_row.subject<>'Live Chat Support' then raise exception 'Live chat session is unavailable'; end if;
  if access_row.guest_message_count>=250 then raise exception 'This live chat has reached its message limit'; end if;
  if access_row.last_guest_message_at is not null and access_row.last_guest_message_at>now()-interval '500 milliseconds' then
    raise exception 'Please wait a moment before sending another message';
  end if;
  if inquiry_row.status='archived' or route.status='closed' then
    raise exception 'This live chat has ended. Please start a new chat if you still need help.';
  end if;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body)
  values(p_inquiry_id,'guest',null,msg) returning * into new_msg;

  update public.app_inquiries
     set body=msg,
         status=case when route.status='accepted' then 'read' else 'open' end,
         last_message_at=now(),user_last_read_at=now(),updated_at=now()
   where id=p_inquiry_id returning * into inquiry_row;

  update public.app_live_chat_guest_access
     set last_guest_message_at=now(),guest_message_count=guest_message_count+1
   where inquiry_id=p_inquiry_id;

  select * into ai from public.app_live_chat_ai_state where inquiry_id=p_inquiry_id;
  if route.status='accepted' and route.assigned_user_id is not null then
    support_mode:='human';
  elsif ai.mode='ai' then
    ai_result:=public.app_live_chat_ai_process_semantic(p_inquiry_id,msg,inquiry_row.guest_name,p_ai_analysis);
    support_mode:=coalesce(ai_result->>'mode','ai');
  elsif ai.mode is not null then
    support_mode:=ai.mode;
  else
    support_mode:='legacy_human';
  end if;

  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;

  support_label:=case support_mode
    when 'ai' then 'Triplem VIP AI Assistant'
    when 'human_pending' then 'Waiting for an Agent'
    when 'human' then coalesce((select coalesce(nullif(trim(u.display_name),''),u.username) from public.app_users u where u.id=route.assigned_user_id),'Triplem VIP Support Agent')
    else 'Triplem VIP Live Support'
  end;

  return jsonb_build_object(
    'ok',true,'message',public.app_message_public_row(new_msg),
    'ai_message',case when ai_result is null then null else ai_result->'message' end,
    'inquiry',public.app_inquiry_public_row(inquiry_row),'support_mode',support_mode,
    'support_label',support_label,'ai_available',true,
    'ai_engine',case when ai_result is null then null else ai_result->>'ai_engine' end,
    'handoff',coalesce((ai_result->>'handoff')::boolean,false),
    'support_queue',coalesce((ai_result->>'support_queue')::int,0)
  );
end
$fn$;
revoke all on function public.app_public_live_chat_reply_semantic(uuid,text,text,jsonb) from public;
grant execute on function public.app_public_live_chat_reply_semantic(uuid,text,text,jsonb) to anon,authenticated,service_role;

create or replace function public.app_public_live_chat_thread(
  p_inquiry_id uuid,
  p_guest_token text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access;
  inquiry_row public.app_inquiries;
  route public.app_live_chat_routes;
  ai public.app_live_chat_ai_state;
  assigned public.app_users;
  messages jsonb:='[]'::jsonb;
  idle jsonb;
  has_unread_support boolean:=false;
  support_mode text;
  support_label text;
begin
  access_row:=public.app_live_chat_validate_guest(p_inquiry_id,p_guest_token);
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;
  if inquiry_row is null or inquiry_row.subject<>'Live Chat Support' then
    raise exception 'Live chat session is unavailable';
  end if;

  insert into public.app_live_chat_routes(inquiry_id,status,created_at,updated_at)
  values(p_inquiry_id,'pending',now(),now())
  on conflict(inquiry_id) do nothing;
  -- A route can be missing only for a legacy/pre-routing chat. Preserve the
  -- established behavior for that historical case; new AI chats already create
  -- their route during app_public_live_chat_start and never enter this branch.
  if found then perform public.app_live_chat_notify_available_agents(p_inquiry_id); end if;

  idle:=public.app_live_chat_maybe_idle_followup(p_inquiry_id);

  select exists(
    select 1 from public.app_inquiry_messages m
    where m.inquiry_id=p_inquiry_id
      and m.sender_role='admin'
      and (inquiry_row.user_last_read_at is null or m.created_at>inquiry_row.user_last_read_at)
  ) into has_unread_support;

  if has_unread_support then
    update public.app_inquiries set user_last_read_at=now()
     where id=p_inquiry_id returning * into inquiry_row;
  end if;

  select * into route from public.app_live_chat_routes where inquiry_id=p_inquiry_id;
  select * into ai from public.app_live_chat_ai_state where inquiry_id=p_inquiry_id;
  if route.assigned_user_id is not null then select * into assigned from public.app_users where id=route.assigned_user_id; end if;

  support_mode:=case
    when route.status='closed' or inquiry_row.status='archived' then 'closed'
    when route.status='accepted' and route.assigned_user_id is not null then 'human'
    when ai.mode is not null then ai.mode
    else 'legacy_human'
  end;
  -- Read/idle handling may advance state; serialize the current inquiry row.
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id;

  support_label:=case support_mode
    when 'ai' then 'Triplem VIP AI Assistant'
    when 'human_pending' then 'Waiting for an Agent'
    when 'human' then coalesce(nullif(trim(coalesce(assigned.display_name,'')),''),assigned.username,'Triplem VIP Support Agent')
    when 'closed' then 'Chat ended'
    else 'Triplem VIP Live Support'
  end;

  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb)
    into messages
  from public.app_inquiry_messages m where m.inquiry_id=p_inquiry_id;

  return jsonb_build_object(
    'ok',true,
    'expires_at',access_row.expires_at,
    'availability',public.app_live_chat_availability(),
    'inquiry',public.app_inquiry_public_row(inquiry_row),
    'messages',messages,
    'chat_closed',(support_mode='closed'),
    'support_mode',support_mode,
    'support_label',support_label,
    'ai_available',true,
    'human_support_active',(support_mode='human')
  );
end
$fn$;
revoke all on function public.app_public_live_chat_thread(uuid,text) from public;
grant execute on function public.app_public_live_chat_thread(uuid,text) to anon,authenticated,service_role;

