-- 114 · Guided AI support + Agent-only free typing
--
-- Purpose
--   Replace free-form visitor-to-AI prompting in the current landing experience
--   with a deterministic, professionally curated guided support flow. Visitors
--   choose short Triplem VIP questions; every AI answer returns relevant next
--   questions plus an Agent handoff option. Free typing is unlocked by the
--   frontend only after an Agent has accepted the existing live-chat route.
--
-- Safety
--   This migration is forward-only and non-destructive. It creates/replaces
--   functions only. It performs no installation-time INSERT/UPDATE/DELETE on
--   existing users, chats, financial records or business data.

create or replace function public.app_live_chat_guided_options(p_context text default 'home')
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  c text := lower(trim(coalesce(p_context,'home')));
begin
  return case c
    when 'overview' then jsonb_build_array(
      jsonb_build_object('id','how_it_works','label','How does it work?'),
      jsonb_build_object('id','features','label','What can I manage?'),
      jsonb_build_object('id','plans','label','What are the plans?'),
      jsonb_build_object('id','security','label','How is it secured?'),
      jsonb_build_object('id','agent','label','Talk to an Agent','kind','agent')
    )
    when 'features' then jsonb_build_array(
      jsonb_build_object('id','wallets_expenses','label','Wallets & expenses?'),
      jsonb_build_object('id','inventory_sales','label','Inventory & sales?'),
      jsonb_build_object('id','loans_assets','label','Loans & assets?'),
      jsonb_build_object('id','reports_invoices','label','Reports & invoices?'),
      jsonb_build_object('id','more_topics','label','More topics'),
      jsonb_build_object('id','agent','label','Talk to an Agent','kind','agent')
    )
    when 'plans' then jsonb_build_array(
      jsonb_build_object('id','monthly','label','Monthly plan?'),
      jsonb_build_object('id','yearly','label','Yearly plan?'),
      jsonb_build_object('id','trial','label','Free trial?'),
      jsonb_build_object('id','subscribe','label','How do I subscribe?'),
      jsonb_build_object('id','agent','label','Talk to an Agent','kind','agent')
    )
    when 'subscription' then jsonb_build_array(
      jsonb_build_object('id','payment_process','label','How do I pay?'),
      jsonb_build_object('id','payment_security','label','Is payment secure?'),
      jsonb_build_object('id','monthly','label','Monthly price?'),
      jsonb_build_object('id','yearly','label','Yearly price?'),
      jsonb_build_object('id','agent','label','Talk to an Agent','kind','agent')
    )
    when 'security' then jsonb_build_array(
      jsonb_build_object('id','payment_security','label','Payment security?'),
      jsonb_build_object('id','data_privacy','label','How is data protected?'),
      jsonb_build_object('id','smart_pin','label','What is Smart PIN?'),
      jsonb_build_object('id','home','label','More questions'),
      jsonb_build_object('id','agent','label','Talk to an Agent','kind','agent')
    )
    when 'operations' then jsonb_build_array(
      jsonb_build_object('id','team_company','label','Team & company setup?'),
      jsonb_build_object('id','notes','label','Notes & reminders?'),
      jsonb_build_object('id','bitcoin','label','Bitcoin tools?'),
      jsonb_build_object('id','demo','label','Can I see the demo?'),
      jsonb_build_object('id','home','label','Main questions'),
      jsonb_build_object('id','agent','label','Talk to an Agent','kind','agent')
    )
    else jsonb_build_array(
      jsonb_build_object('id','overview','label','What is Triplem VIP?'),
      jsonb_build_object('id','how_it_works','label','How does it work?'),
      jsonb_build_object('id','features','label','What can I manage?'),
      jsonb_build_object('id','plans','label','Plans & pricing?'),
      jsonb_build_object('id','subscribe','label','How do I subscribe?'),
      jsonb_build_object('id','agent','label','Talk to an Agent','kind','agent')
    )
  end;
end
$fn$;
revoke all on function public.app_live_chat_guided_options(text) from public, anon, authenticated;

create or replace function public.app_live_chat_guided_choice(p_choice text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $fn$
declare
  c text := lower(trim(coalesce(p_choice,'')));
  label_text text;
  answer_text text;
  next_context text := 'home';
begin
  case c
    when 'overview' then
      label_text := 'What is Triplem VIP?';
      answer_text := 'Triplem VIP is a private accounting and business-operations workspace that brings everyday financial and operational records into one organized system.';
      next_context := 'overview';
    when 'how_it_works' then
      label_text := 'How does it work?';
      answer_text := 'Create your workspace, add the areas you use, then record activity as it happens. Triplem VIP connects those records into dashboards, histories, invoices, receipts and reports.';
      next_context := 'overview';
    when 'features' then
      label_text := 'What can I manage?';
      answer_text := 'You can manage wallets, expenses, inventory and sales, customers, loans, installments, assets, notes, Bitcoin records, invoices, receipts and reports from one workspace.';
      next_context := 'features';
    when 'plans' then
      label_text := 'What are the plans?';
      answer_text := 'Pro Monthly is AED 49, SAR 49, PKR 1,799 or USD 13.99. Pro Yearly is AED 449, SAR 449, PKR 19,999 or USD 149. A 14-day free trial is available first.';
      next_context := 'plans';
    when 'monthly' then
      label_text := 'What is the monthly plan?';
      answer_text := 'Pro Monthly costs AED 49, SAR 49, PKR 1,799 or USD 13.99. You can start with the 14-day free trial before subscribing.';
      next_context := 'plans';
    when 'yearly' then
      label_text := 'What is the yearly plan?';
      answer_text := 'Pro Yearly costs AED 449, SAR 449, PKR 19,999 or USD 149. It provides the same Pro workspace on annual billing.';
      next_context := 'plans';
    when 'trial' then
      label_text := 'Is there a free trial?';
      answer_text := 'Yes. Triplem VIP includes a 14-day free workspace trial with no card required, so you can explore it before choosing a Pro plan.';
      next_context := 'plans';
    when 'subscribe' then
      label_text := 'How do I subscribe?';
      answer_text := 'Sign in, open Plan & Subscription, choose Monthly or Yearly and your currency, select an available bank account, complete the transfer and upload the receipt for verification.';
      next_context := 'subscription';
    when 'payment_process' then
      label_text := 'How do I pay?';
      answer_text := 'Pro subscriptions currently use bank transfer. Triplem VIP shows an available bank account in Plan & Subscription; after transferring, upload the receipt and the subscription is activated after verification.';
      next_context := 'subscription';
    when 'payment_security' then
      label_text := 'Is my payment secure?';
      answer_text := 'The current subscription flow uses bank transfer, so Triplem VIP does not ask you to enter card details into the workspace. Use only the bank details shown inside Plan & Subscription and keep your transfer receipt for verification.';
      next_context := 'security';
    when 'security' then
      label_text := 'How is Triplem VIP secured?';
      answer_text := 'Triplem VIP uses private workspaces and server-side access controls. The public support assistant never exposes passwords, credentials, private records, source code or implementation-sensitive security details.';
      next_context := 'security';
    when 'data_privacy' then
      label_text := 'How is my data protected?';
      answer_text := 'Business records are kept inside authenticated private workspaces with server-side access controls. For account-specific privacy questions, an Agent can review the case without exposing information in public chat.';
      next_context := 'security';
    when 'smart_pin' then
      label_text := 'What is Smart PIN?';
      answer_text := 'Smart PIN is an additional fast-access protection layer for the Triplem VIP workspace. It complements the normal account sign-in rather than replacing account security.';
      next_context := 'security';
    when 'wallets_expenses' then
      label_text := 'How do wallets and expenses work?';
      answer_text := 'Wallets organize balances and money sources, while Expenses records spending and transaction history. Together they give you a clearer view of where money is held and where it goes.';
      next_context := 'features';
    when 'inventory_sales' then
      label_text := 'Can it manage inventory and sales?';
      answer_text := 'Yes. Triplem VIP can organize inventory, products, brands and variants, customers and sales records, helping business activity stay connected with the rest of the workspace.';
      next_context := 'features';
    when 'loans_assets' then
      label_text := 'Can it manage loans and assets?';
      answer_text := 'Yes. Loans and installments can track amounts, repayments and schedules, while Assets can record owned assets, related costs, revenue and disposal history.';
      next_context := 'features';
    when 'reports_invoices' then
      label_text := 'What about reports and invoices?';
      answer_text := 'Triplem VIP can turn recorded business information into structured reports and can create professional invoices and receipts using your workspace details.';
      next_context := 'features';
    when 'team_company' then
      label_text := 'Can I set up my company and team?';
      answer_text := 'Yes. Triplem VIP supports company details, branding and controlled team access, so permitted team members can work inside the same business workspace.';
      next_context := 'operations';
    when 'notes' then
      label_text := 'Does it have notes and reminders?';
      answer_text := 'Yes. Notes can keep operational information inside the workspace, and reminders can help surface time-sensitive items when needed.';
      next_context := 'operations';
    when 'bitcoin' then
      label_text := 'What are the Bitcoin tools?';
      answer_text := 'Triplem VIP includes Bitcoin-related workspace tools for keeping supported Bitcoin wallet and transaction records alongside other financial information. It does not provide investment advice.';
      next_context := 'operations';
    when 'demo' then
      label_text := 'Can I see how Triplem VIP works?';
      answer_text := 'Yes. The website includes a guided Demo that shows key Triplem VIP workflows and interface behavior before you start your own workspace.';
      next_context := 'operations';
    when 'more_topics' then
      label_text := 'Show me more topics';
      answer_text := 'Of course. You can also explore company and team setup, notes and reminders, Bitcoin tools, the product demo, or return to the main questions.';
      next_context := 'operations';
    when 'home' then
      label_text := 'Show me the main questions';
      answer_text := 'Choose any main Triplem VIP topic below and I will keep the answer brief and focused.';
      next_context := 'home';
    else
      return null;
  end case;

  return jsonb_build_object(
    'id',c,
    'label',label_text,
    'answer',answer_text,
    'context',next_context,
    'options',public.app_live_chat_guided_options(next_context)
  );
end
$fn$;
revoke all on function public.app_live_chat_guided_choice(text) from public, anon, authenticated;

create or replace function public.app_public_live_chat_start_guided(
  p_name text,
  p_mobile text,
  p_email text
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $fn$
declare
  v_name text:=trim(coalesce(p_name,''));
  v_mobile text:=trim(coalesce(p_mobile,''));
  v_email text:=lower(trim(coalesce(p_email,'')));
  inquiry_row public.app_inquiries;
  ai_msg public.app_inquiry_messages;
  raw_token text;
  expires timestamptz:=now()+interval '2 hours';
  availability jsonb:=public.app_live_chat_availability();
  messages jsonb:='[]'::jsonb;
  welcome_text text;
begin
  if char_length(v_name)<2 then raise exception 'Please enter your full name'; end if;
  if char_length(v_mobile)<6 then raise exception 'Please enter a valid contact number'; end if;
  if v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then raise exception 'Please enter a valid email address'; end if;

  perform public.app_live_chat_assert_start_limit(v_email);

  insert into public.app_inquiries(
    sender_id,subject,body,status,source,guest_name,guest_email,guest_phone,last_message_at,user_last_read_at
  ) values(
    null,'Live Chat Support','Guided AI support started','open','landing',v_name,v_email,v_mobile,now(),now()
  ) returning * into inquiry_row;

  raw_token:=encode(extensions.gen_random_bytes(32),'hex');
  insert into public.app_live_chat_guest_access(
    inquiry_id,token_hash,expires_at,last_guest_message_at,guest_message_count
  ) values(
    inquiry_row.id,public.app_hash_token(raw_token),expires,null,0
  );

  -- Create the existing routing shell without notifying Agents. An Agent offer
  -- is generated only when the visitor explicitly chooses the Agent option.
  insert into public.app_live_chat_routes(inquiry_id,status,created_at,updated_at)
  values(inquiry_row.id,'pending',now(),now())
  on conflict(inquiry_id) do nothing;

  insert into public.app_live_chat_ai_state(
    inquiry_id,mode,last_intent,last_confidence,last_ai_message_at,
    uncertainty_streak,last_ai_engine,last_ai_model,created_at,updated_at
  ) values(
    inquiry_row.id,'ai','guided_home',1.0000,now(),0,'guided_support','triplem_verified_catalog',now(),now()
  )
  on conflict(inquiry_id) do update set
    mode='ai',last_intent='guided_home',last_confidence=1.0000,last_ai_message_at=now(),
    uncertainty_streak=0,last_ai_engine='guided_support',last_ai_model='triplem_verified_catalog',updated_at=now();

  welcome_text:=format(
    'I am Triplem VIP''s AI Assistant. I am still learning and may occasionally make mistakes. Choose a question below, %s, or request an Agent anytime.',
    split_part(v_name,' ',1)
  );

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,support_actor,created_at)
  values(inquiry_row.id,'admin',null,welcome_text,'ai',clock_timestamp()+interval '1 millisecond')
  returning * into ai_msg;

  select coalesce(jsonb_agg(public.app_message_public_row(m) order by m.created_at asc),'[]'::jsonb)
    into messages
  from public.app_inquiry_messages m where m.inquiry_id=inquiry_row.id;

  return jsonb_build_object(
    'ok',true,
    'inquiry_id',inquiry_row.id,
    'guest_token',raw_token,
    'expires_at',expires,
    'availability',availability,
    'inquiry',public.app_inquiry_public_row(inquiry_row),
    'messages',messages,
    'support_mode','ai',
    'support_label','Triplem VIP AI Assistant',
    'ai_available',true,
    'guided',true,
    'guided_options',public.app_live_chat_guided_options('home')
  );
end
$fn$;
revoke all on function public.app_public_live_chat_start_guided(text,text,text) from public;
grant execute on function public.app_public_live_chat_start_guided(text,text,text) to anon,authenticated,service_role;

create or replace function public.app_public_live_chat_choose(
  p_inquiry_id uuid,
  p_guest_token text,
  p_choice text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $fn$
declare
  access_row public.app_live_chat_guest_access;
  inquiry_row public.app_inquiries;
  route_row public.app_live_chat_routes;
  ai_row public.app_live_chat_ai_state;
  choice_payload jsonb;
  guest_msg public.app_inquiry_messages;
  ai_msg public.app_inquiry_messages;
  choice_id text:=lower(trim(coalesce(p_choice,'')));
  choice_label text;
  answer_text text;
  next_context text;
  availability jsonb:=public.app_live_chat_availability();
  support_open boolean:=false;
  notices int:=0;
begin
  access_row:=public.app_live_chat_validate_guest(p_inquiry_id,p_guest_token);

  select * into route_row from public.app_live_chat_routes where inquiry_id=p_inquiry_id for update;
  select * into inquiry_row from public.app_inquiries where id=p_inquiry_id for update;
  select * into access_row from public.app_live_chat_guest_access where inquiry_id=p_inquiry_id for update;
  select * into ai_row from public.app_live_chat_ai_state where inquiry_id=p_inquiry_id for update;

  if inquiry_row is null or inquiry_row.subject<>'Live Chat Support' then raise exception 'Live chat session is unavailable'; end if;
  if inquiry_row.status='archived' or route_row.status='closed' then raise exception 'This live chat has ended. Please start a new chat if you still need help.'; end if;
  if route_row.status='accepted' and route_row.assigned_user_id is not null then
    raise exception 'An Agent has accepted this chat. You can now type your message in the reply box.';
  end if;
  if ai_row.inquiry_id is null or ai_row.mode not in ('ai','human_pending') then
    raise exception 'Guided AI support is not available for this chat.';
  end if;
  if ai_row.mode='human_pending' then
    raise exception 'Agent support has already been requested. Typing will unlock when an Agent accepts the chat.';
  end if;
  if access_row.guest_message_count>=250 then raise exception 'This live chat has reached its message limit'; end if;

  if choice_id='agent' then
    choice_label:='Talk to an Agent';
  else
    choice_payload:=public.app_live_chat_guided_choice(choice_id);
    if choice_payload is null then raise exception 'Please choose one of the available support questions.'; end if;
    choice_label:=choice_payload->>'label';
    answer_text:=choice_payload->>'answer';
    next_context:=coalesce(choice_payload->>'context','home');
  end if;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,created_at)
  values(p_inquiry_id,'guest',null,choice_label,clock_timestamp())
  returning * into guest_msg;

  update public.app_inquiries
     set body=choice_label,status='open',last_message_at=now(),user_last_read_at=now(),updated_at=now()
   where id=p_inquiry_id returning * into inquiry_row;

  update public.app_live_chat_guest_access
     set last_guest_message_at=now(),guest_message_count=guest_message_count+1
   where inquiry_id=p_inquiry_id;

  if choice_id='agent' then
    support_open:=coalesce((availability->>'is_open')::boolean,false);
    answer_text:=case when support_open then
      'Certainly. AI assistance is paused and this chat is now in the Agent queue. Typing will unlock as soon as an Agent accepts the chat.'
    else
      'Certainly. AI assistance is paused and your Agent request is recorded. Agent support is currently offline; typing will unlock when an Agent accepts the chat during support hours.'
    end;

    update public.app_live_chat_ai_state
       set mode='human_pending',last_intent='guided_agent',last_confidence=1.0000,
           last_ai_message_at=now(),human_requested_at=coalesce(human_requested_at,now()),
           human_reason='guided_agent_request',uncertainty_streak=0,
           last_ai_engine='guided_support',last_ai_model='triplem_verified_catalog',updated_at=now()
     where inquiry_id=p_inquiry_id;

    insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,support_actor,created_at)
    values(p_inquiry_id,'admin',null,answer_text,'ai',clock_timestamp()+interval '1 millisecond')
    returning * into ai_msg;

    notices:=public.app_live_chat_notify_available_agents(p_inquiry_id);

    return jsonb_build_object(
      'ok',true,'message',public.app_message_public_row(guest_msg),'ai_message',public.app_message_public_row(ai_msg),
      'support_mode','human_pending','support_label','Waiting for an Agent','handoff',true,
      'support_queue',notices,'availability',availability,'guided',true,'guided_options','[]'::jsonb
    );
  end if;

  update public.app_live_chat_ai_state
     set mode='ai',last_intent='guided_'||choice_id,last_confidence=1.0000,
         last_ai_message_at=now(),uncertainty_streak=0,last_ai_engine='guided_support',
         last_ai_model='triplem_verified_catalog',updated_at=now()
   where inquiry_id=p_inquiry_id;

  insert into public.app_inquiry_messages(inquiry_id,sender_role,sender_id,body,support_actor,created_at)
  values(p_inquiry_id,'admin',null,answer_text,'ai',clock_timestamp()+interval '1 millisecond')
  returning * into ai_msg;

  update public.app_inquiries set last_message_at=now(),updated_at=now() where id=p_inquiry_id;

  return jsonb_build_object(
    'ok',true,'message',public.app_message_public_row(guest_msg),'ai_message',public.app_message_public_row(ai_msg),
    'support_mode','ai','support_label','Triplem VIP AI Assistant','handoff',false,
    'availability',availability,'guided',true,'guided_context',next_context,
    'guided_options',choice_payload->'options'
  );
end
$fn$;
revoke all on function public.app_public_live_chat_choose(uuid,text,text) from public;
grant execute on function public.app_public_live_chat_choose(uuid,text,text) to anon,authenticated,service_role;

